def _supervised_worker_env(
    extra: dict[str, str] | None = None,
) -> dict[str, str]:
    """Return the secret-free state identity every sessiond worker must inherit."""
    env = {
        key: value
        for key in _SUPERVISED_STATE_ENV_KEYS
        if (value := os.environ.get(key, "").strip())
    }
    if extra:
        env.update(extra)
    return env


def _prime_session_directory(session_root: Path, session: str) -> Path:
    """Return a Prime state directory that cannot escape ``session_root``.

    Preserve readable directory names for ordinary Sophia session identifiers,
    but hash every identifier containing path syntax or unsafe characters.
    Resolving the final candidate also rejects an existing symlink that points
    outside the configured session root.
    """
    root = session_root.expanduser().resolve()
    text = str(session)
    ordinary = (
        0 < len(text) <= MAX_SESSION_CHARS
        and text not in {".", ".."}
        and text[0].isalnum()
        and all(char.isalnum() or char in "._-" for char in text)
    )
    component = (
        text
        if ordinary
        else "session-" + uuid.uuid5(uuid.NAMESPACE_URL, text).hex[:24]
    )
    candidate = (root / component).resolve()
    try:
        candidate.relative_to(root)
    except ValueError as exc:
        raise RuntimeError(
            "Prime session directory escaped the configured session root"
        ) from exc
    return candidate


def _pid_is_alive(pid: int) -> bool:
    """Best-effort liveness check for a recorded owning-process pid.

    ``os.kill(pid, 0)`` sends no signal, it only asks the kernel whether the
    pid is addressable. ProcessLookupError is the one unambiguous "gone"
    answer. PermissionError means a live process owned by another user (still
    alive, just not ours to signal) — and any other OSError is a platform
    quirk, not proof of death. Both are treated as "alive" on purpose: this
    function feeds a crash-reconciliation decision that overwrites another
    process's in-flight state, so an inconclusive check must never be treated
    as a death verdict.
    """
    if pid <= 0:
        return True
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except OSError:
        return True
    return True


