def _normalize_defaults(defaults: dict[str, Any] | None) -> dict[str, Any]:
    data = {**CODE_DEFAULTS, **(defaults or {})}
    return {
        "runtime": _normalize_runtime(data.get("runtime")),
        "model": _normalize_model(data.get("model")),
        "mode": _normalize_mode(data.get("mode")),
        "permission": _normalize_permission(data.get("permission")),
        "logicJudge": str(data.get("logicJudge") or "basic")
        if str(data.get("logicJudge") or "").lower() in {"off", "basic", "strict"} else "basic",
        "deepThink": _normalize_bool(data.get("deepThink")),
        "deepMode": _normalize_bool(data.get("deepMode")),
        "team": _normalize_team(data.get("team")),
        "autoTeam": _normalize_optional_bool(data.get("autoTeam")),
        "a2aAgents": _normalize_a2a_agents(data.get("a2aAgents"), data.get("a2a")),
        "a2aExecution": _normalize_a2a_execution(data.get("a2aExecution")),
        "terminalLayout": _normalize_terminal_layout(data.get("terminalLayout")),
        "workflowMode": _normalize_workflow_mode(data.get("workflowMode")),
        "workflowMaxStages": _normalize_workflow_max_stages(
            data.get("workflowMaxStages")
        ),
        "workflowMaxAgents": _normalize_workflow_max_agents(
            data.get("workflowMaxAgents")
        ),
        "workflowChartPath": _normalize_workflow_chart_path(
            data.get("workflowChartPath")
        ),
        "agiWorkflowMode": _normalize_workflow_mode(
            data.get("agiWorkflowMode")
        ),
        "agiMode": _normalize_bool(data.get("agiMode")),
        "agiProfile": _normalize_agi_profile(data.get("agiProfile")),
        "agiRoute": _normalize_agi_route(data.get("agiRoute")),
        "agiPlannerModel": _normalize_agi_role_model(data.get("agiPlannerModel")),
        "agiWorkerModel": _normalize_agi_role_model(data.get("agiWorkerModel")),
        "agiVerifierModel": _normalize_agi_role_model(data.get("agiVerifierModel")),
        "session": _normalize_session(data.get("session")),
        "maxSteps": max(1, min(256, _safe_int(data.get("maxSteps"), 24))),
        "cwd": str(data.get("cwd") or "").strip(),
        "gateBypass": _normalize_bool(data.get("gateBypass")),
        "conscienceMode": _normalize_conscience_mode(data.get("conscienceMode")),
        "effort": _normalize_effort(data.get("effort")),
        "responseStyle": _normalize_response_style(data.get("responseStyle")),
        "thinkingVisibility": _normalize_thinking_visibility(data.get("thinkingVisibility")),
        "keymap": _normalize_keymap(data.get("keymap")),
        "imageProvider": _normalize_image_provider(data.get("imageProvider")),
        "notifications": _normalize_bool(data.get("notifications")),
        "semanticFallbackModel": _normalize_semantic_fallback_model(
            data.get("semanticFallbackModel")
        ),
        "semanticFallbackPolicy": _normalize_semantic_fallback_policy(
            data.get("semanticFallbackPolicy")
        ),
        "semanticReturnToPrimary": _normalize_bool(
            data.get("semanticReturnToPrimary"), default=True
        ),
        "budget": dict(data.get("budget") or {}) if isinstance(data.get("budget"), dict) else {},
        "drainTimeoutSec": _normalize_drain_timeout(data.get("drainTimeoutSec")),
    }


def _migrate_persisted_defaults(defaults: dict[str, Any] | None) -> dict[str, Any]:
    migrated = dict(defaults or {})
    stored_model = _normalize_model(migrated.get("model"))
    migrated["model"] = _REMOVED_AIPRO_SETTINGS.get(stored_model.casefold(), stored_model)
    return migrated


def _validate_fresh_model(value: Any) -> str:
    from agent import model as model_module

    model = _normalize_model(value)
    if model.casefold() in _REMOVED_AIPRO_SETTINGS:
        raise ValueError(f"removed model setting {model!r}; use aipro or aipro-2")
    provider = _model_spec(model).partition(":")[0].strip().casefold()
    if provider in {"aipro", "aipro-2"}:
        model_module.resolve_config(_model_spec(model))
    return model


def _config_model_override() -> tuple[str | None, str | None]:
    """Read the operator's ``[code].model`` from layered config.toml files.

    Returns ``(model, source_path)`` for the winning layer, or ``(None, None)``
    when no layer sets a model (or none could be read). The source path is the
    provenance key: the layered stack is CWD-dependent, so "has this config
    changed?" is only meaningful per config file, not globally.

    The TUI bridge persists its last-resolved model in code_bridge_state.json,
    which is correct WITHIN a session (so a ``/model`` change survives across
    prompts). But it used to be the ONLY source read on startup, so an
    operator's edit to ``~/.sophia/config.toml`` was silently ignored — the
    stale persisted default kept coming back (e.g. a vLLM preset that hits
    Connection refused because no server is running). config.toml is the
    operator's explicit choice; honor it on every startup as the highest-
    precedence default, matching agent.cli's behavior. Returns None when no
    config.toml is present or it sets no model.
    """
    try:
        import tomllib
    except ModuleNotFoundError:  # pragma: no cover - Python 3.10 fallback
        try:
            import tomli as tomllib  # type: ignore[no-redef]
        except ModuleNotFoundError:
            return None
    candidates: list[Path] = [
        Path.home() / ".sophia" / "config.toml",
    ]
    ws = _workspace_dir_for_config()
    if ws:
        candidates.append(ws / ".sophia" / "config.toml")
    if os.environ.get("SOPHIA_CODE_CONFIG"):
        candidates.append(Path(os.environ["SOPHIA_CODE_CONFIG"]).expanduser())
    merged_model: str | None = None
    merged_source: str | None = None
    for path in candidates:
        if not path.exists():
            continue
        try:
            data = tomllib.loads(path.read_text(encoding="utf-8"))
        except (OSError, tomllib.TOMLDecodeError):
            continue
        table = data.get("code", {})
        if isinstance(table, dict) and isinstance(table.get("model"), str) and table["model"].strip():
            merged_model = table["model"].strip()
            merged_source = str(path)
    return merged_model, merged_source


def _config_auto_team_override() -> tuple[bool | None, str | None]:
    """Read an explicit ``[code].auto_team`` first-use default.

    ``autoTeam`` is also accepted for existing generated configs. The public
    default remains unset/solo; only an operator-authored config value opts a
    machine in before the setting has been persisted by the bridge.
    """
    try:
        import tomllib
    except ModuleNotFoundError:  # pragma: no cover - Python 3.10 fallback
        try:
            import tomli as tomllib  # type: ignore[no-redef]
        except ModuleNotFoundError:
            return None, None
    candidates: list[Path] = [Path.home() / ".sophia" / "config.toml"]
    ws = _workspace_dir_for_config()
    if ws:
        candidates.append(ws / ".sophia" / "config.toml")
    if os.environ.get("SOPHIA_CODE_CONFIG"):
        candidates.append(Path(os.environ["SOPHIA_CODE_CONFIG"]).expanduser())
    merged: bool | None = None
    source: str | None = None
    for path in candidates:
        if not path.exists():
            continue
        try:
            data = tomllib.loads(path.read_text(encoding="utf-8"))
        except (OSError, tomllib.TOMLDecodeError):
            continue
        table = data.get("code", {})
        if not isinstance(table, dict):
            continue
        if "auto_team" in table:
            raw = table.get("auto_team")
        elif "autoTeam" in table:
            raw = table.get("autoTeam")
        else:
            continue
        try:
            normalized = _normalize_optional_bool(raw)
        except ValueError:
            continue
        if normalized is not None:
            merged = normalized
            source = str(path)
    return merged, source


def _config_tui_overrides() -> tuple[dict[str, Any], str | None]:
    """Read explicit, non-secret TUI defaults from layered ``[code]`` config.

    These values are operator-authored policy, not inferred environment state.
    They may therefore satisfy first-run onboarding without the TUI inventing a
    choice. Secret values are never accepted here; providers continue to read
    credentials from their documented environment/auth stores.
    """
    try:
        import tomllib
    except ModuleNotFoundError:  # pragma: no cover - Python 3.10 fallback
        try:
            import tomli as tomllib  # type: ignore[no-redef]
        except ModuleNotFoundError:
            return {}, None
    candidates: list[Path] = [Path.home() / ".sophia" / "config.toml"]
    ws = _workspace_dir_for_config()
    if ws:
        candidates.append(ws / ".sophia" / "config.toml")
    if os.environ.get("SOPHIA_CODE_CONFIG"):
        candidates.append(Path(os.environ["SOPHIA_CODE_CONFIG"]).expanduser())
    merged: dict[str, Any] = {}
    source: str | None = None
    for path in candidates:
        if not path.exists():
            continue
        try:
            data = tomllib.loads(path.read_text(encoding="utf-8"))
        except (OSError, tomllib.TOMLDecodeError):
            continue
        table = data.get("code", {})
        if not isinstance(table, dict):
            continue
        if "permission" in table:
            try:
                merged["permission"] = _normalize_permission(table.get("permission"))
            except ValueError:
                # Ignore only the invalid optional override so the remaining
                # valid config fields can still be loaded from this file.
                pass
        image_raw = table.get("image_provider", table.get("imageProvider"))
        if isinstance(image_raw, str) and image_raw.strip():
            merged["imageProvider"] = _normalize_image_provider(image_raw)
        thinking_raw = table.get("thinking_visibility", table.get("thinkingVisibility"))
        if isinstance(thinking_raw, str):
            merged["thinkingVisibility"] = _normalize_thinking_visibility(thinking_raw)
        keymap_raw = table.get("keymap")
        if isinstance(keymap_raw, str):
            merged["keymap"] = _normalize_keymap(keymap_raw)
        # Optional run-profile defaults (DeepSeek V4 / A2A harness workstations).
        # Invalid values are ignored field-by-field so one typo cannot wipe the rest.
        if "mode" in table:
            try:
                merged["mode"] = _normalize_mode(table.get("mode"))
            except Exception:  # noqa: BLE001
                pass
        effort_raw = table.get("effort")
        if effort_raw is not None and str(effort_raw).strip():
            merged["effort"] = _normalize_effort(effort_raw)
        rs_raw = table.get("response_style", table.get("responseStyle"))
        if isinstance(rs_raw, str) and rs_raw.strip():
            try:
                merged["responseStyle"] = _normalize_response_style(rs_raw)
            except Exception:  # noqa: BLE001
                pass
        if "team" in table:
            try:
                merged["team"] = _normalize_team(table.get("team"))
            except Exception:  # noqa: BLE001
                pass
        if "a2a_agents" in table or "a2aAgents" in table or "a2a" in table:
            try:
                merged["a2aAgents"] = _normalize_a2a_agents(
                    table.get("a2a_agents", table.get("a2aAgents")),
                    table.get("a2a"),
                )
            except Exception:  # noqa: BLE001
                pass
        a2a_execution_raw = table.get("a2a_execution", table.get("a2aExecution"))
        if a2a_execution_raw is not None:
            try:
                merged["a2aExecution"] = _normalize_a2a_execution(a2a_execution_raw)
            except Exception:  # noqa: BLE001
                pass
        terminal_layout_raw = table.get("terminal_layout", table.get("terminalLayout"))
        if terminal_layout_raw is not None:
            try:
                merged["terminalLayout"] = _normalize_terminal_layout(
                    terminal_layout_raw
                )
            except Exception:  # noqa: BLE001
                pass
        workflow_mode_raw = table.get("workflow_mode", table.get("workflowMode"))
        if workflow_mode_raw is not None:
            try:
                merged["workflowMode"] = _normalize_workflow_mode(
                    workflow_mode_raw
                )
            except Exception:  # noqa: BLE001
                pass
        workflow_stages_raw = table.get(
            "workflow_max_stages", table.get("workflowMaxStages")
        )
        if workflow_stages_raw is not None:
            merged["workflowMaxStages"] = _normalize_workflow_max_stages(
                workflow_stages_raw
            )
        workflow_agents_raw = table.get(
            "workflow_max_agents", table.get("workflowMaxAgents")
        )
        if workflow_agents_raw is not None:
            merged["workflowMaxAgents"] = _normalize_workflow_max_agents(
                workflow_agents_raw
            )
        agi_workflow_mode_raw = table.get(
            "agi_workflow_mode", table.get("agiWorkflowMode")
        )
        if agi_workflow_mode_raw is not None:
            try:
                merged["agiWorkflowMode"] = _normalize_workflow_mode(
                    agi_workflow_mode_raw
                )
            except Exception:  # noqa: BLE001
                pass
        if "agi_mode" in table or "agiMode" in table:
            merged["agiMode"] = _normalize_bool(
                table.get("agi_mode", table.get("agiMode"))
            )
        agi_profile_raw = table.get("agi_profile", table.get("agiProfile"))
        if agi_profile_raw is not None:
            merged["agiProfile"] = _normalize_agi_profile(agi_profile_raw)
        agi_route_raw = table.get("agi_route", table.get("agiRoute"))
        if agi_route_raw is not None:
            merged["agiRoute"] = _normalize_agi_route(agi_route_raw)
        for camel, snake in (
            ("agiPlannerModel", "agi_planner_model"),
            ("agiWorkerModel", "agi_worker_model"),
            ("agiVerifierModel", "agi_verifier_model"),
        ):
            if snake in table or camel in table:
                merged[camel] = _normalize_agi_role_model(
                    table.get(snake, table.get(camel))
                )
        max_steps_raw = table.get("max_steps", table.get("maxSteps"))
        if max_steps_raw is not None:
            try:
                merged["maxSteps"] = max(1, min(256, int(max_steps_raw)))
            except (TypeError, ValueError):
                # Ignore only this malformed optional field; preserve every
                # other valid default already merged from the same config.
                pass
        drain_raw = table.get("drain_timeout_sec", table.get("drainTimeoutSec"))
        if drain_raw is not None:
            try:
                merged["drainTimeoutSec"] = _normalize_drain_timeout(drain_raw)
            except Exception:  # noqa: BLE001
                pass
        conscience_raw = table.get("conscience_mode", table.get("conscienceMode"))
        if isinstance(conscience_raw, str) and conscience_raw.strip():
            try:
                merged["conscienceMode"] = _normalize_conscience_mode(conscience_raw)
            except Exception:  # noqa: BLE001
                pass
        if "notifications" in table:
            try:
                merged["notifications"] = _normalize_bool(table.get("notifications"))
            except Exception:  # noqa: BLE001
                pass
        if merged:
            source = str(path)
    return merged, source


def _apply_config_auto_team_default(state: dict[str, Any]) -> None:
    """Apply config auto-team only while the persisted choice is still unset."""
    defaults = state.get("defaults")
    if not isinstance(defaults, dict):
        defaults = {}
        state["defaults"] = defaults
    if _normalize_optional_bool(defaults.get("autoTeam")) is not None:
        return
    value, source = _config_auto_team_override()
    if value is None:
        return
    defaults["autoTeam"] = value
    onboarding = state.get("onboarding")
    if not isinstance(onboarding, dict):
        onboarding = {}
        state["onboarding"] = onboarding
    onboarding["autoTeamConfirmed"] = True
    if source:
        state["autoTeamConfigSource"] = source


def _apply_config_tui_defaults(state: dict[str, Any]) -> None:
    defaults = state.get("defaults")
    if not isinstance(defaults, dict):
        defaults = {}
        state["defaults"] = defaults
    values, source = _config_tui_overrides()
    defaults.update(values)
    if source:
        state["tuiConfigSource"] = source
        onboarding = state.get("onboarding")
        if not isinstance(onboarding, dict):
            onboarding = {}
            state["onboarding"] = onboarding
        if "permission" in values:
            onboarding["permissionConfirmed"] = True
        if "imageProvider" in values:
            onboarding["imageProviderConfirmed"] = True


def _workspace_dir_for_config() -> Path | None:
    """Best-effort workspace dir for layered config (mirrors agent.cli). Returns
    None when CWD can't be resolved so the caller just skips the workspace layer."""
    try:
        return Path.cwd()
    except OSError:
        return None


def _load_state() -> tuple[dict[str, Any], str | None]:
    path = _state_path()
    if not path.exists():
        state = {"version": 1, "defaults": dict(CODE_DEFAULTS), "updatedAt": None}
        warning = _apply_config_model_override(state)
        _apply_config_auto_team_default(state)
        _apply_config_tui_defaults(state)
        return state, warning
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        state = {"version": 1, "defaults": dict(CODE_DEFAULTS),
                 "updatedAt": None}
        config_warning = _apply_config_model_override(state)
        _apply_config_auto_team_default(state)
        _apply_config_tui_defaults(state)
        warning = f"ignored unreadable code state: {type(exc).__name__}"
        return state, f"{warning}; {config_warning}" if config_warning else warning
    if not isinstance(raw, dict):
        state = {"version": 1, "defaults": dict(CODE_DEFAULTS), "updatedAt": None}
        config_warning = _apply_config_model_override(state)
        _apply_config_auto_team_default(state)
        _apply_config_tui_defaults(state)
        warning = "ignored non-object code state"
        return state, f"{warning}; {config_warning}" if config_warning else warning
    raw["version"] = _safe_int(raw.get("version"), 1)
    raw["defaults"] = _normalize_defaults(_migrate_persisted_defaults(
        raw.get("defaults") if isinstance(raw.get("defaults"), dict) else {}
    ))
    if raw.get("selectedSessionID") is not None:
        raw["selectedSessionID"] = _normalize_session(raw.get("selectedSessionID"))
    # Only this path can carry a pre-upgrade state file worth adopting; the three
    # fallbacks above build a fresh state, which has no operator choice to keep.
    warning = _apply_config_model_override(raw, adopt_existing=True)
    _apply_config_auto_team_default(raw)
    _apply_config_tui_defaults(raw)
    return raw, warning


def _config_seen_map(state: dict[str, Any]) -> dict[str, str]:
    """The ``config.toml path -> last-applied model`` provenance map."""
    raw = state.get("configModelSeen")
    if isinstance(raw, dict):
        return {str(k): v.strip() for k, v in raw.items() if isinstance(v, str) and v.strip()}
    return {}


def _config_edited_since_state(source: str, state: dict[str, Any]) -> bool:
    """Was ``source`` modified after this state was last written?

    Used only on the one-time upgrade from a state file that predates the
    provenance map, where "the persisted model differs from config.toml" is
    ambiguous: the operator either picked a model in the UI (state is newer) or
    edited config.toml (config is newer).  Returns True when it cannot tell, so
    an unreadable mtime or a state file with no timestamp keeps the historical
    config-wins behavior rather than inventing a new one.
    """
    stamp = state.get("updatedAt")
    if not isinstance(stamp, str) or not stamp.strip():
        return True
    try:
        written = datetime.fromisoformat(stamp.strip().replace("Z", "+00:00"))
        if written.tzinfo is None:
            written = written.replace(tzinfo=timezone.utc)
        return os.stat(source).st_mtime > written.timestamp()
    except (OSError, ValueError):
        return True


def _apply_config_model_override(
    state: dict[str, Any], *, adopt_existing: bool = False,
) -> str | None:
    """Honor a *changed* ``[code].model`` from config.toml as the default model.

    config.toml is the operator's explicit choice, so an edit to it must not be
    shadowed by a stale persisted default (e.g. a vLLM preset from a prior run
    that now hits Connection refused).  That is why this override exists.

    But applying it on EVERY state read created the opposite defect: a model
    chosen in the TUI picker (or via ``/model``) was silently reverted on the
    next launch, and the app's ready-echo then wrote the reverted value back to
    disk — so the selection was not merely ignored, it was destroyed and could
    never stick.  Picking ``grok`` with a local Qwen in config.toml ran Qwen.

    So the config value wins only when it CHANGED since it was last applied.
    ``configModelSeen`` maps each config.toml PATH to the model last honored
    from it.  It is keyed by path because the candidate stack includes a
    workspace layer: a single scalar made the answer CWD-dependent, so moving
    between a workspace and home re-fired the override every time and the
    user's pick could never survive a directory change.

    ``adopt_existing`` handles the one-time upgrade from a state file written
    before the map existed: that file already holds the operator's last
    effective model, so it is adopted rather than overridden — unless
    config.toml is genuinely newer, which means an operator edit that has not
    been applied yet.
    """
    model, source = _config_model_override()
    if not model or not source:
        # No [code].model anywhere, or no layer could be read/parsed. Leave both
        # the default AND the provenance untouched: a half-written or briefly
        # unreadable config.toml must not read as an edit once it comes back.
        return None
    seen = _config_seen_map(state)
    migrating = (
        adopt_existing
        and "configModelSeen" not in state
        and not _config_edited_since_state(source, state)
    )
    if not migrating and seen.get(source) != model:
        try:
            validated_model = _validate_fresh_model(model)
        except ValueError as exc:
            return f"ignored invalid config model: {exc}"
        defaults = state.get("defaults")
        if not isinstance(defaults, dict):
            defaults = {}
            state["defaults"] = defaults
        defaults["model"] = validated_model
        onboarding = state.get("onboarding")
        if not isinstance(onboarding, dict):
            onboarding = {}
            state["onboarding"] = onboarding
        onboarding["providerConfirmed"] = True
        # Marking it seen HERE is only provisional: callers routinely apply the
        # override to a state whose defaults["model"] they then replace (the run
        # writeback keeps the UI's model; _handle_settings applies the client's
        # patch). Persisting "applied" for a value that never reached disk would
        # consume the operator's config.toml edit without ever honoring it, and
        # every later launch would then see config == seen and skip it — the
        # precedence bug this override exists for, made permanent. _save_state
        # drops the claim unless the applied value is the one being written.
        state[_CONFIG_APPLIED_KEY] = {"source": source, "model": model}
    seen.pop(source, None)  # re-insert last so the trim below drops the oldest
    seen[source] = model
    if len(seen) > _CONFIG_SEEN_LIMIT:
        seen = dict(list(seen.items())[-_CONFIG_SEEN_LIMIT:])
    state["configModelSeen"] = seen
    return None


def _reconcile_config_seen(state: dict[str, Any], saved_model: str) -> dict[str, str]:
    """Provenance for the model actually being persisted.

    ``_apply_config_model_override`` marks a config value as applied while the
    state is still in memory. If the caller then persists a DIFFERENT model, the
    override did not really take effect, so the claim is withdrawn and the edit
    stays pending for the next load.
    """
    seen = _config_seen_map(state)
    applied = state.get(_CONFIG_APPLIED_KEY)
    if isinstance(applied, dict):
        source = applied.get("source")
        model = applied.get("model")
        if isinstance(source, str) and isinstance(model, str) \
                and saved_model != _normalize_model(model) and seen.get(source) == model:
            seen.pop(source, None)
    return seen


def _save_state(state: dict[str, Any]) -> dict[str, Any]:
    saved_defaults = _normalize_defaults(
        state.get("defaults") if isinstance(state.get("defaults"), dict) else {})
    normalized = {
        "version": 1,
        "defaults": saved_defaults,
        "selectedSessionID": (
            _normalize_session(state.get("selectedSessionID"))
            if state.get("selectedSessionID") is not None else None
        ),
        "lastRun": state.get("lastRun") if isinstance(state.get("lastRun"), dict) else None,
        "onboarding": (
            {
                key: bool(value)
                for key, value in state.get("onboarding", {}).items()
                if key in {
                    "providerConfirmed",
                    "permissionConfirmed",
                    "autoTeamConfirmed",
                    "imageProviderConfirmed",
                }
            }
            if isinstance(state.get("onboarding"), dict)
            else {}
        ),
        # Provenance for the config.toml default, not a user-facing setting: it is
        # what lets _apply_config_model_override tell an operator's edit from an
        # unchanged file. Dropping it here would re-arm the override on every save
        # and bring the "picked model reverts on relaunch" bug straight back.
        # Always written (even empty) so its ABSENCE reliably marks a pre-upgrade
        # state file, which is what selects the adopt-don't-override path.
        "configModelSeen": _reconcile_config_seen(state, saved_defaults["model"]),
        "updatedAt": _now_iso(),
    }
    path = _state_path()
    parent = path.parent
    parent.mkdir(parents=True, exist_ok=True)
    if parent == Path.home() / ".sophia":
        try:
            parent.chmod(0o700)
        except OSError:
            # Best-effort hardening; the atomic write below still reports failures.
            pass
    tmp_name: str | None = None
    try:
        with tempfile.NamedTemporaryFile(
            "w", encoding="utf-8", dir=parent,
            prefix=f".{path.name}.", suffix=".tmp", delete=False,
        ) as handle:
            tmp_name = handle.name
            os.chmod(tmp_name, 0o600)
            json.dump(normalized, handle, ensure_ascii=False, indent=2)
            handle.write("\n")
        os.replace(tmp_name, path)
        try:
            path.chmod(0o600)
        except OSError:
            # Some filesystems do not support chmod; the state write itself succeeded.
            pass
    except Exception:
        if tmp_name:
            try:
                Path(tmp_name).unlink(missing_ok=True)
            except OSError:
                # Preserve the original save failure; cleanup is best-effort.
                pass
        raise
    return normalized


def _public_state(state: dict[str, Any], warning: str | None = None) -> dict[str, Any]:
    defaults = _normalize_defaults(
        state.get("defaults") if isinstance(state.get("defaults"), dict) else {})
    payload = {
        "version": _safe_int(state.get("version"), 1),
        "defaults": defaults,
        "autoTeamState": _auto_team_state(defaults.get("autoTeam")),
        "selectedSessionID": state.get("selectedSessionID"),
        "updatedAt": state.get("updatedAt"),
        "settingsPath": str(_state_path()),
        "onboarding": (
            dict(state.get("onboarding"))
            if isinstance(state.get("onboarding"), dict)
            else {}
        ),
    }
    if isinstance(state.get("lastRun"), dict):
        payload["lastRun"] = state["lastRun"]
    if warning:
        payload["warning"] = warning
    return payload


# --------------------------------------------------------------------------- #
# Client proxy: token streaming + cancellation without touching the kernel
# --------------------------------------------------------------------------- #
class _RunCancelled(Exception):
    """Raised inside the model client to abort a run the operator cancelled."""


@dataclass
class _TokenTelemetry:
    """Shared observations for tees that belong to one logical run."""

    last_model_error: str | None = None
    last_provider: str | None = None
    last_model: str | None = None
    fallback_used: bool = False
    total_generation_sec: float = 0.0
    first_time_to_first_token_sec: float | None = None
    malformed_tool_call_seen: bool = False
    prompt_tokens: int = 0
    completion_tokens: int = 0
    cost_usd: float = 0.0
    usage_observed: bool = False
    model_calls: int = 0
    lock: threading.Lock = field(default_factory=threading.Lock, repr=False)


class _TokenTee:
    """Wrap a ModelClient to add token/thinking/provider-progress taps and a
    cancel check.

    The kernel loop never passes streaming callbacks itself; injecting them here
    keeps ``agent/agent_loop.py`` untouched while giving the app live token and
    thinking streams on transports that honor them (OpenAI-compatible + mock)."""

    def __init__(self, inner: Any, on_token: Callable[[str], None], cancel: threading.Event,
                 on_thinking_token: Callable[[str], None] | None = None,
                 on_provider_progress: Callable[[dict[str, Any]], None] | None = None,
                 on_wait: "Callable[[int, float, float], None] | None" = None,
                 telemetry: _TokenTelemetry | None = None):
        self._inner = inner
        self._on_token = on_token
        self._on_thinking_token = on_thinking_token
        self._on_provider_progress = on_provider_progress
        self._cancel = cancel
        self._on_wait = on_wait
        self._telemetry = telemetry or _TokenTelemetry()

    @property
    def telemetry(self) -> _TokenTelemetry:
        return self._telemetry

    @property
    def last_model_error(self) -> str | None:
        return self._telemetry.last_model_error

    @last_model_error.setter
    def last_model_error(self, value: str | None) -> None:
        with self._telemetry.lock:
            self._telemetry.last_model_error = (
                str(value) if value is not None else None
            )

    @property
    def last_provider(self) -> str | None:
        return self._telemetry.last_provider

    @last_provider.setter
    def last_provider(self, value: str | None) -> None:
        with self._telemetry.lock:
            self._telemetry.last_provider = (
                str(value).strip() or None if value is not None else None
            )

    @property
    def last_model(self) -> str | None:
        return self._telemetry.last_model

    @last_model.setter
    def last_model(self, value: str | None) -> None:
        with self._telemetry.lock:
            self._telemetry.last_model = (
                str(value).strip() or None if value is not None else None
            )

    @property
    def fallback_used(self) -> bool:
        return self._telemetry.fallback_used

    @fallback_used.setter
    def fallback_used(self, value: bool) -> None:
        with self._telemetry.lock:
            self._telemetry.fallback_used = bool(value)

    @property
    def total_generation_sec(self) -> float:
        return self._telemetry.total_generation_sec

    @property
    def first_time_to_first_token_sec(self) -> float | None:
        return self._telemetry.first_time_to_first_token_sec

    @property
    def malformed_tool_call_seen(self) -> bool:
        return self._telemetry.malformed_tool_call_seen

    @property
    def prompt_tokens(self) -> int | None:
        return self._telemetry.prompt_tokens if self._telemetry.usage_observed else None

    @property
    def completion_tokens(self) -> int | None:
        return (
            self._telemetry.completion_tokens
            if self._telemetry.usage_observed
            else None
        )

    @property
    def cost_usd(self) -> float | None:
        return self._telemetry.cost_usd if self._telemetry.usage_observed else None

    @property
    def model_calls(self) -> int:
        return self._telemetry.model_calls

    def _check(self) -> None:
        if self._cancel.is_set():
            raise _RunCancelled()

    def _tap(self, existing: Any) -> Callable[[str], None]:
        def cb(token: str) -> None:
            self._check()
            if callable(existing):
                existing(token)
            self._on_token(token)
        return cb

    def _tap_thinking(self, existing: Any) -> Any:
        if self._on_thinking_token is None:
            return existing
        def cb(token: str) -> None:
            self._check()
            if callable(existing):
                existing(token)
            self._on_thinking_token(token)
        return cb

    def _tap_provider_progress(self, existing: Any) -> Any:
        if self._on_provider_progress is None:
            return existing

        def cb(progress: dict[str, Any]) -> None:
            self._check()
            if callable(existing):
                existing(progress)
            self._on_provider_progress(progress)

        return cb

    def _call_with_wait(self, call: Callable[[], Any]) -> Any:
        """Run one blocking provider call with a finite, secret-free notifier."""
        if self._on_wait is None or PROVIDER_WAIT_MAX_EVENTS <= 0 \
                or PROVIDER_WAIT_INTERVAL_SEC <= 0:
            return call()
        done = threading.Event()
        started = time.monotonic()
        max_wait_sec = PROVIDER_WAIT_INTERVAL_SEC * PROVIDER_WAIT_MAX_EVENTS

        def notify() -> None:
            next_at = PROVIDER_WAIT_INTERVAL_SEC
            for sequence in range(1, PROVIDER_WAIT_MAX_EVENTS + 1):
                while True:
                    # Wait on cancellation itself so ``cancel.set()`` wakes the
                    # notifier immediately.  Polling only ``done`` and checking
                    # cancellation afterwards made shutdown depend on thread
                    # scheduling and intermittently missed the macOS CI's
                    # prompt-cancellation deadline under load.
                    if self._cancel.wait(PROVIDER_WAIT_POLL_SEC):
                        return
                    if done.is_set():
                        return
                    elapsed = time.monotonic() - started
                    if elapsed < next_at:
                        continue
                    try:
                        self._on_wait(sequence, elapsed, max_wait_sec)
                    except Exception:  # liveness reporting must not break a model call
                        pass
                    next_at += PROVIDER_WAIT_INTERVAL_SEC
                    break
                if done.is_set() or self._cancel.is_set():
                    return

        notifier = threading.Thread(
            target=notify,
            name="code-bridge-provider-wait",
            daemon=True,
        )
        notifier.start()
        try:
            return call()
        finally:
            done.set()
            notifier.join(timeout=max(PROVIDER_WAIT_POLL_SEC * 2, 0.1))

    def generate(self, *args: Any, **kw: Any) -> Any:
        self._check()
        kw["on_token"] = self._tap(kw.get("on_token"))
        kw["on_thinking_token"] = self._tap_thinking(kw.get("on_thinking_token"))
        kw["on_provider_progress"] = self._tap_provider_progress(
            kw.get("on_provider_progress")
        )
        # Blocking CLI transports (notably the ChatGPT-authenticated Codex
        # subprocess) need the same cancellation signal as streaming providers.
        # Without it the TUI acknowledged cancellation immediately but the
        # bridge remained inside subprocess.run until the provider's 600-second
        # timeout, preventing A2A from returning a resumable failure promptly.
        kw.setdefault("should_cancel", self._cancel.is_set)
        res = self._call_with_wait(lambda: self._inner.generate(*args, **kw))
        # Providers may be non-streaming and return only after cancellation.
        # Do not let that stale answer cross the cancellation boundary.
        self._check()
        self._record(res)
        return res

    def generate_messages(self, messages: list, **kw: Any) -> Any:
        self._check()
        kw["on_token"] = self._tap(kw.get("on_token"))
        kw["on_thinking_token"] = self._tap_thinking(kw.get("on_thinking_token"))
        kw["on_provider_progress"] = self._tap_provider_progress(
            kw.get("on_provider_progress")
        )
        kw.setdefault("should_cancel", self._cancel.is_set)
        res = self._call_with_wait(lambda: self._inner.generate_messages(messages, **kw))
        # The callback check above cannot observe cancellation when a transport
        # does not stream. Check again before exposing its response.
        self._check()
        self._record(res)
        return res

    def _record(self, res: Any) -> None:
        provider = str(getattr(res, "provider", "") or "").strip()
        prompt_tokens = getattr(res, "prompt_tokens", None)
        completion_tokens = getattr(res, "completion_tokens", None)
        cost_usd = getattr(res, "cost_usd", None)
        with self._telemetry.lock:
            self._telemetry.model_calls += 1
            if provider:
                self._telemetry.last_provider = provider
                self._telemetry.last_model = (
                    str(getattr(res, "model", "") or "").strip() or None
                )
            if getattr(res, "ok", True) is False and getattr(res, "error", None):
                self._telemetry.last_model_error = str(res.error)
            # Latch: one substitution anywhere in a multi-step run is worth
            # reporting, even if later steps hit the primary again.
            if getattr(res, "fallback_used", False):
                self._telemetry.fallback_used = True
            self._telemetry.total_generation_sec += float(
                getattr(res, "latency_sec", 0.0) or 0.0
            )
            if self._telemetry.first_time_to_first_token_sec is None:
                ttft = getattr(res, "time_to_first_token_sec", None)
                if ttft is not None:
                    self._telemetry.first_time_to_first_token_sec = float(ttft)
            if getattr(res, "malformed_tool_call", False):
                self._telemetry.malformed_tool_call_seen = True
            if any(
                value is not None
                for value in (prompt_tokens, completion_tokens, cost_usd)
            ):
                self._telemetry.usage_observed = True
                self._telemetry.prompt_tokens += max(
                    0, int(prompt_tokens or 0)
                )
                self._telemetry.completion_tokens += max(
                    0, int(completion_tokens or 0)
                )
                self._telemetry.cost_usd += max(0.0, float(cost_usd or 0.0))

    def __getattr__(self, name: str) -> Any:
        return getattr(self._inner, name)

    @property
    def raw_client(self) -> Any:
        """Underlying callable client for non-streamed internal model calls."""
        return self._inner

    def fork(
        self,
        *,
        on_token: Callable[[str], None] | None = None,
        on_thinking_token: Callable[[str], None] | None = None,
        on_provider_progress: Callable[[dict[str, Any]], None] | None = None,
        share_telemetry: bool = False,
    ) -> "_TokenTee":
        """Share transport authority; optionally aggregate one logical run."""
        return _TokenTee(
            self._inner,
            on_token or self._on_token,
            self._cancel,
            on_thinking_token=(
                self._on_thinking_token
                if on_thinking_token is None
                else on_thinking_token
            ),
            on_provider_progress=(
                self._on_provider_progress
                if on_provider_progress is None
                else on_provider_progress
            ),
            on_wait=self._on_wait,
            telemetry=self._telemetry if share_telemetry else None,
        )


# --------------------------------------------------------------------------- #
# Event bus: pairs tool_call/tool_result nodes, tracks lane/subagent paths
# --------------------------------------------------------------------------- #
class _EventBus:
    def __init__(self, emit: Callable[[dict], dict]):
        self._emit = emit
        self._local = threading.local()
        self._counter = 0
        self._lock = threading.Lock()

    def _next(self, prefix: str) -> str:
        with self._lock:
            self._counter += 1
            return f"{prefix}-{self._counter}"

    def _stack(self) -> list[dict[str, str]]:
        stack = getattr(self._local, "stack", None)
        if stack is None:
            stack = []
            self._local.stack = stack
        return stack

    def reserve(self, kind: str) -> str:
        """Reserve a globally unique frame id before concurrent work starts."""
        return self._next(kind)

    def push(self, kind: str, label: str, *, frame_id: str | None = None) -> str:
        frame_id = frame_id or self._next(kind)
        self._stack().append({"id": frame_id, "kind": kind, "label": label})
        return frame_id

    def pop(self, kind: str) -> None:
        stack = self._stack()
        for idx in range(len(stack) - 1, -1, -1):
            if stack[idx]["kind"] == kind:
                del stack[idx]
                return

    def path(self) -> list[str]:
        return [frame["id"] for frame in self._stack()]

    def lane(self) -> str | None:
        for frame in self._stack():
            if frame["kind"] == "lane":
                return frame["id"]
        return None

    def bridge_event(self, run_id: str, payload: dict) -> None:
        self._emit({
            "type": "bridge_event",
            "runId": run_id,
            "path": self.path(),
            "lane": self.lane(),
            "ts": _now_iso(),
            "event": payload,
        })

    def kernel_sink(self, run_id: str) -> Callable[[dict], None]:
        """on_event sink for run_agent_loop; enriches + pairs tool nodes."""
        def sink(ev: dict) -> None:
            enriched = dict(ev)
            etype = enriched.get("type")
            if etype == "tool_call":
                node_id = self._next("node")
                call_id = str(enriched.get("callId") or self._next("tool-call"))
                self._local.last_tool_node = node_id
                self._local.last_tool_call = call_id
                enriched["node"] = node_id
                enriched["callId"] = call_id
                event_lane = str(enriched.get("lane") or self.lane() or "").strip() or None
                event_path = self.path()
                if not event_path and event_lane:
                    event_path = [event_lane]
                enriched["path"] = event_path
                enriched["lane"] = event_lane
                emitted = self._emit({"type": "event", "runId": run_id, "ts": _now_iso(),
                                      "path": enriched["path"], "lane": enriched["lane"],
                                      "event": enriched})
                self._local.last_tool_event = emitted.get("eventId")
                if enriched.get("tool") == "delegate":
                    goal = str((enriched.get("args") or {}).get("goal", ""))[:120]
                    sub_id = self.push("sub", goal or "subagent")
                    self.bridge_event(run_id, {"type": "subprocess_start", "sub": sub_id,
                                               "goal": goal, "node": node_id})
                return
            if etype == "tool_result":
                node_id = getattr(self._local, "last_tool_node", None)
                call_id = getattr(self._local, "last_tool_call", None)
                parent_event_id = getattr(self._local, "last_tool_event", None)
                if node_id:
                    enriched["node"] = node_id
                if call_id:
                    enriched["callId"] = call_id
                if parent_event_id:
                    enriched["parentEventId"] = parent_event_id
                if enriched.get("tool") == "delegate":
                    self.bridge_event(run_id, {"type": "subprocess_end",
                                               "ok": bool(enriched.get("ok"))})
                    self.pop("sub")
            # Provider-wait callbacks run on a notifier thread, outside the
            # worker's thread-local event-bus stack. Preserve an explicitly
            # supplied lane instead of replacing it with ``None``; otherwise
            # the right panel shows a generic wait while the real lane looks
            # inactive and may be abandoned despite a live provider call.
            event_lane = str(enriched.get("lane") or self.lane() or "").strip() or None
            event_path = self.path()
            if not event_path and event_lane:
                event_path = [event_lane]
            enriched["path"] = event_path
            enriched["lane"] = event_lane
            self._emit({"type": "event", "runId": run_id, "ts": _now_iso(),
                        "path": enriched["path"], "lane": enriched["lane"], "event": enriched})
        return sink


# --------------------------------------------------------------------------- #
# GUI approver: approval_request → wait for the app's {"cmd": "approve"}
# --------------------------------------------------------------------------- #
class _GuiApprover:
    def __init__(self, bridge: "CodeBridge", run_id: str, cancel: threading.Event):
        self._bridge = bridge
        self._run_id = run_id
        self._cancel = cancel

    def __call__(self, name: str, preview: str) -> bool:
        # PreToolUse hook enforcement happens earlier now, inside
        # agent_tools.execute_tool() itself — before this approver is ever
        # invoked, and for every permission mode, not only the manual-approval
        # calls that reach a dialog. A hook denial short-circuits execute_tool
        # with its own ToolResult, so this call site only ever runs for a
        # call a hook has already allowed (or where no hook is configured).
        approval_id = f"ap-{uuid.uuid4().hex[:8]}"
        box: dict[str, Any] = {"event": threading.Event(), "allow": False}
        with self._bridge.approvals_lock:
            self._bridge.approvals[approval_id] = box
        # ``preview`` is a plain str for the fallback-confirmation call sites
        # (cross-provider / semantic local-model fallback) and a ToolPreview
        # (str subclass) for a real tool call — getattr defaults make both
        # shapes safe here without a type check, and every field below stays
        # optional so a peer that predates them keeps working unchanged.
        diff = _safe_text(getattr(preview, "diff", "") or "", limit=4000)
        risk = str(getattr(preview, "risk", "") or "")
        destructive = bool(getattr(preview, "destructive", False))
        request_payload: dict[str, Any] = {
            "type": "approval_request",
            "runId": self._run_id,
            "id": approval_id,
            "tool": name,
            "preview": _safe_text(preview, limit=1200),
            "ts": _now_iso(),
            "canClaimAGI": False,
        }
        if diff:
            request_payload["diff"] = diff
        if risk:
            request_payload["risk"] = risk
        if destructive:
            request_payload["destructive"] = True
        self._bridge.emit(request_payload)
        # Wait in small slices so cancel wakes a pending approval promptly.
        while not box["event"].wait(0.2):
            if self._cancel.is_set():
                break
        with self._bridge.approvals_lock:
            self._bridge.approvals.pop(approval_id, None)
        if self._cancel.is_set():
            return False
        allow = bool(box["allow"])
        decision_payload: dict[str, Any] = {
            "type": "approval_decision",
            "runId": self._run_id,
            "id": approval_id,
            "tool": name,
            "allow": allow,
            "ts": _now_iso(),
            "canClaimAGI": False,
        }
        if risk:
            # Lets the transcript row the app builds from this event alone
            # show risk without correlating back to the (transient) request.
            decision_payload["risk"] = risk
        self._bridge.emit(decision_payload)
        return allow


# --------------------------------------------------------------------------- #
# The bridge
# --------------------------------------------------------------------------- #
def _durable_chart_ids(
    value: Any,
    *,
    limit: int = 128,
) -> list[str] | None:
    """Return a bounded string-id list for the durable chart projection."""
    if not isinstance(value, list) or len(value) > limit:
        return None
    result: list[str] = []
    for item in value:
        if not isinstance(item, str):
            return None
        text = item.strip()
        if not text or len(text) > 160 or text in result:
            return None
        result.append(text)
    return result


def _durable_workflow_chart(value: Any) -> dict[str, Any] | None:
    """Project only the validated, task-free flowchart topology.

    The live bridge event already carries the compiled chart, but the TUI can
    reconnect through the durable run journal. Keep that journal projection
    deliberately smaller than the compiler object: no task prose, roles,
    criteria, tools, provider names, or executable instructions are allowed.
    """
    if not isinstance(value, Mapping):
        return None

    def text(key: str, limit: int) -> str:
        raw = value.get(key)
        return raw.strip()[:limit] if isinstance(raw, str) else ""

    chart: dict[str, Any] = {}
    for key, limit in (
        ("schema", 100),
        ("id", 160),
        ("sourcePath", 512),
        ("sourceDigest", 64),
        ("topologyDigest", 64),
        ("error", 800),
    ):
        item = text(key, limit)
        if item:
            chart[key] = item

    raw_nodes = value.get("nodes")
    raw_edges = value.get("edges")
    if raw_nodes is None or raw_edges is None:
        return chart or None
    if (
        not isinstance(raw_nodes, list)
        or not isinstance(raw_edges, list)
        or len(raw_nodes) > 64
        or len(raw_edges) > 128
    ):
        return None

    nodes: list[dict[str, Any]] = []
    for raw in raw_nodes:
        if not isinstance(raw, Mapping):
            return None
        node_id = raw.get("id")
        if not isinstance(node_id, str) or not node_id.strip():
            return None
        predecessor_ids = _durable_chart_ids(raw.get("predecessorIds"))
        successor_ids = _durable_chart_ids(raw.get("successorIds"))
        if predecessor_ids is None or successor_ids is None:
            return None
        kind = raw.get("kind", "task")
        join = raw.get("join", "")
        if not isinstance(kind, str) or not isinstance(join, str):
            return None
        stage = raw.get("stage")
        if stage is not None and (
            not isinstance(stage, int) or isinstance(stage, bool) or stage < 1
        ):
            return None
        label = raw.get("label")
        if not isinstance(label, str) or not label.strip():
            label = node_id
        nodes.append(
            {
                "id": node_id.strip()[:160],
                "label": label.strip()[:180],
                "kind": kind.strip()[:40],
                "stage": stage,
                "join": join.strip()[:40],
                "predecessorIds": predecessor_ids,
                "successorIds": successor_ids,
            }
        )

    edges: list[dict[str, str]] = []
    for raw in raw_edges:
        if not isinstance(raw, Mapping):
            return None
        edge_id = raw.get("id")
        source = raw.get("from")
        target = raw.get("to")
        kind = raw.get("kind", "control")
        if not all(
            isinstance(item, str) and item.strip()
            for item in (edge_id, source, target, kind)
        ):
            return None
        edges.append(
            {
                "id": edge_id.strip()[:240],
                "from": source.strip()[:160],
                "to": target.strip()[:160],
                "kind": kind.strip()[:40],
            }
        )

    chart["nodes"] = nodes
    chart["edges"] = edges
    return chart


def _durable_workflow_agents(value: Any) -> list[dict[str, Any]] | None:
    """Project chart/status identity without persisting worker report bodies."""
    if not isinstance(value, list) or len(value) > 64:
        return None
    agents: list[dict[str, Any]] = []
    for raw in value:
        if not isinstance(raw, Mapping):
            return None
        name = raw.get("name") or raw.get("agentId") or raw.get("taskId")
        status = raw.get("status", "queued")
        if not isinstance(name, str) or not name.strip():
            return None
        if not isinstance(status, str) or not status.strip():
            return None
        index = raw.get("index", len(agents))
        if not isinstance(index, int) or isinstance(index, bool) or index < 0:
            return None
        row: dict[str, Any] = {
            "name": name.strip()[:240],
            "index": index,
            "status": status.strip()[:80],
        }
        for key in ("active", "started"):
            if isinstance(raw.get(key), bool):
                row[key] = raw[key]
        for key, limit in (
            ("role", 120),
            ("chartNodeId", 160),
            ("chartNodeKind", 40),
        ):
            item = raw.get(key)
            if isinstance(item, str) and item.strip():
                row[key] = item.strip()[:limit]
        for key in ("chartDependencies", "chartSuccessors"):
            ids = _durable_chart_ids(raw.get(key), limit=128)
            if ids is not None and ids:
                row[key] = ids
        failure = raw.get("failureReason")
        if isinstance(failure, str) and failure.strip():
            row["failureReason"] = _safe_diagnostic_text(
                failure,
                limit=400,
            )
        agents.append(row)
    return agents


class CodeBridge:
    def __init__(self, out: TextIO, *, sync: bool = False):
        self.out = out
        self.sync = sync            # tests: execute runs inline instead of a thread
        self.write_lock = threading.Lock()
        self.protocol_lock = threading.Lock()
        self.protocol_sequence = 0
        self.instance_id = f"bridge-{uuid.uuid4().hex[:12]}"
        self.run_finished_publisher = RunFinishedPublisher()
        self.run_finished_lock = threading.Lock()
        self.run_finished_ids: set[tuple[str, str]] = set()
        self.command_local = threading.local()
        self.bus = _EventBus(self.emit)
        self.approvals: dict[str, dict[str, Any]] = {}
        # Supervised terminal workers have their own embedded CodeBridge
        # approval IDs. This map lets the app use the normal approve command
        # while the durable supervisor relays the decision to the correct PTY.
        self.supervisor_approvals: dict[str, dict[str, Any]] = {}
        self.approvals_lock = threading.Lock()
        self.run_lock = threading.Lock()
        self.active: dict[str, Any] | None = None   # {"id", "cancel", "thread", "session", "steers"}
        self.drain_timeout = DRAIN_TIMEOUT_DEFAULT_SEC
        self.active_lock = threading.Lock()
        self.shutdown = threading.Event()
        self.receipts_lock = threading.RLock()
        self.receipts: dict[str, TaskReceiptStore] = {}
        self.model_connection_lock = threading.RLock()
        # Last typed probe result per custom profile. This is deliberately
        # process-local and secret-free; it lets an explicitly approved repair
        # preview reason over the actual failed checks without persisting
        # provider response bodies or credentials.
        self.model_connection_reports: dict[str, dict[str, Any]] = {}
        self.queue_next_lock = threading.Lock()
        self.queue_next: list[dict[str, Any]] = []
        self.request_acks: dict[tuple[str, str], dict[str, Any]] = {}
        self.prime_lock = threading.RLock()
        # session -> (workspace root, persistent owned Prime RPC runtime)
        self.prime_sessions: dict[str, tuple[str, Any]] = {}
        self.plugin_host_lock = threading.RLock()
        # Resolved workspace root -> persistent owned plugin command host.
        # Ordinary persisted selections still use a fresh run host. An
        # explicitly approved process-local /plugin use lease reuses this
        # owned host so its exact authority and sidecars can be retired at the
        # task/session boundary.
        self.plugin_hosts: dict[str, Any] = {}
        # Transient plugin settings are client-wide even though authority and
        # sidecars are cached per workspace. Track the single lease whose
        # patch was most recently published so an older host cannot restore
        # stale settings after a newer workspace lease wins.
        self.plugin_lease_publication_lock = threading.RLock()
        self.plugin_active_lease_binding: tuple[Any, int] | None = None
        # Hook dispatch history for a `/hooks`-status request (recent PreToolUse/
        # PostToolUse/Stop decisions), so the operator can see what a hook did —
        # not just that hooks.toml parsed. Bounded (HOOK_DISPATCH_LOG_MAX): a
        # long session should not leak memory one dispatch record at a time.
        self.hook_log_lock = threading.Lock()
        self.hook_dispatch_log: list[dict[str, Any]] = []
        # Every ToolContext built for a run's checkpoint store outlives the run
        # itself (files stay checkpointed after the run's handle is discarded),
        # so `/undo` and `/checkpoints` need somewhere durable to find the ctx
        # a since-finished run used. Keyed by session (the natural "which
        # conversation was this" unit); `last_ctx` is the same thing unscoped,
        # for a caller that never bothers to pass a session name.
        self.ctx_registry_lock = threading.Lock()
        self.last_ctx_by_session: dict[str, Any] = {}
        self.last_ctx: Any | None = None
        self.mcp_timeouts = {
            "connectMs": _normalize_timeout_ms(
                os.environ.get("SOPHIA_MCP_CONNECT_TIMEOUT_MS"),
                MCP_CONNECT_TIMEOUT_MS,
            ),
            "requestMs": _normalize_timeout_ms(
                os.environ.get("SOPHIA_MCP_REQUEST_TIMEOUT_MS"),
                MCP_REQUEST_TIMEOUT_MS,
            ),
        }

    def _receipt_dir(self) -> Path:
        from agent import harness as _h
        override = os.environ.get("SOPHIA_RECEIPTS_DIR")
        return Path(override).expanduser() if override else Path(_h.RUNS_DIR) / "code_bridge" / "receipts"

    @staticmethod
    def _write_run_provenance(handle: dict, payload: dict[str, Any], suffix: str) -> None:
        """Atomically append one secret-free execution identity record."""
        from agent import cli as terminal_cli

        session = str(handle.get("session") or CODE_DEFAULTS["session"])
        conversation = terminal_cli._conversation_path(session)
        root = conversation.parent / ".provenance" / conversation.stem
        stem = str(handle.get("provenanceStem") or "")
        if not stem:
            stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
            stem = f"{stamp}-{handle['id']}"
            handle["provenanceStem"] = stem
        body = {
            "schema": "sophia.execution-provenance.v1",
            **payload,
            "runId": handle["id"],
            "session": session,
            "canClaimAGI": False,
        }
        terminal_cli._atomic_write_text(
            root / f"{stem}.{suffix}.json",
            json.dumps(body, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        )

    def _emit_goal_update(
        self,
        handle: dict[str, Any],
        *,
        goal: Any,
        source: str,
        reason: Any = "",
        current_stage: int | None = None,
        planned_stages: int | None = None,
        max_stages: int | None = None,
        dedupe_semantic: bool = False,
    ) -> dict[str, Any]:
        """Publish one authoritative, revisable right-panel goal receipt."""

        summary = _goal_panel_summary(goal)
        existing = handle.get("goalPanel")
        if dedupe_semantic and isinstance(existing, dict):
            same_stage = (
                current_stage is None
                or _safe_int(existing.get("currentStage"), 0)
                == max(0, _safe_int(current_stage, 0))
            )
            same_planned = (
                planned_stages is None
                or _safe_int(existing.get("plannedStages"), 0)
                == max(1, _safe_int(planned_stages, 1))
            )
            same_max = (
                max_stages is None
                or _safe_int(existing.get("maxStages"), 0)
                == max(1, _safe_int(max_stages, 1))
            )
            if (
                str(existing.get("goal") or "") == summary
                and same_stage
                and same_planned
                and same_max
            ):
                return dict(existing)

        revision = max(0, _safe_int(handle.get("_goalRevision"), 0)) + 1
        handle["_goalRevision"] = revision
        payload: dict[str, Any] = {
            "type": "goal_update",
            "goal": summary,
            "revision": revision,
            "source": _safe_text(source or "harness", limit=80),
            "reason": _safe_text(reason, limit=600),
            "updatedAt": _now_iso(),
            "candidateOnly": True,
            "canClaimAGI": False,
        }
        if current_stage is not None:
            payload["currentStage"] = max(0, _safe_int(current_stage, 0))
        if max_stages is not None:
            payload["maxStages"] = max(1, _safe_int(max_stages, 1))
        if planned_stages is not None:
            current = max(0, _safe_int(current_stage, 0))
            maximum = max(
                max(1, current),
                _safe_int(max_stages, planned_stages),
            )
            payload["plannedStages"] = max(
                max(1, current),
                min(maximum, _safe_int(planned_stages, max(1, current))),
            )
        handle["goalPanel"] = dict(payload)
        self.bus.bridge_event(str(handle["id"]), payload)
        return payload

    def _emit_workflow_todo_board(
        self,
        handle: dict[str, Any],
        stage_ledger: list[dict[str, Any]],
        *,
        pending_contracts: list[dict[str, Any]] | None = None,
    ) -> None:
        """Publish the shared contract/receipt To-do list. Not a workflow node."""

        from agent.dynamic_workflow import workflow_board_todo_items

        items = workflow_board_todo_items(
            stage_ledger,
            pending_contracts=pending_contracts,
        )
        self.bus.bridge_event(
            str(handle["id"]),
            {
                "type": "todo_update",
                "items": items,
                "source": "workflow-board",
                "candidateOnly": True,
                "canClaimAGI": False,
            },
        )

    def _emit_run_eta(
        self,
        handle: dict[str, Any],
        *,
        mode: str,
        phase: str,
        refresh: bool = False,
    ) -> dict[str, Any] | None:
        """Publish a history-backed estimate of the full root-run duration."""

        eta_lock = handle.setdefault("_runEtaLock", threading.Lock())
        with eta_lock:
            normalized_mode = normalize_run_mode(mode)
            if (
                not refresh
                and handle.get("_runEtaPublishedMode") == normalized_mode
            ):
                return None

            now = time.monotonic()
            started_value = handle.get("startedMonotonic")
            started = (
                float(started_value)
                if isinstance(started_value, (int, float))
                and not isinstance(started_value, bool)
                else now
            )
            elapsed = max(0.0, now - started)
            if refresh:
                last_refresh = handle.get("_runEtaLastRefreshMonotonic")
                if (
                    isinstance(last_refresh, (int, float))
                    and not isinstance(last_refresh, bool)
                    and now - float(last_refresh) < RUN_ETA_REFRESH_INTERVAL_SEC
                ):
                    return None
                handle["_runEtaLastRefreshMonotonic"] = now

            estimate = estimate_run_duration(
                normalized_mode,
                exclude_run_id=str(handle.get("id") or ""),
                minimum_total_sec=elapsed if refresh else None,
            )
            if estimate is None:
                # Initial activation already leaves the TUI in its honest
                # estimating state.  A refresh is different: a prior numeric
                # ETA may now be stale, so publish explicit nulls to clear it.
                handle["_runEtaPublishedMode"] = normalized_mode
                if not refresh:
                    return None

            revision = max(0, _safe_int(handle.get("_runEtaRevision"), 0)) + 1
            handle["_runEtaRevision"] = revision
            payload = {
                "type": "run_eta",
                "mode": estimate.mode if estimate is not None else normalized_mode,
                "phase": _safe_text(phase or "run", limit=80),
                "revision": revision,
                "elapsedSec": round(elapsed, 3),
                "estimatedTotalSec": (
                    round(estimate.total_sec, 3)
                    if estimate is not None
                    else None
                ),
                "estimatedRemainingSec": (
                    round(max(0.0, estimate.total_sec - elapsed), 3)
                    if estimate is not None
                    else None
                ),
                "sampleCount": estimate.sample_count if estimate is not None else 0,
                "confidence": estimate.confidence if estimate is not None else None,
                "etaBasis": (
                    estimate.basis
                    if estimate is not None
                    else (
                        "recalibrating · no successful comparable completed run "
                        "exceeds current elapsed time"
                    )
                ),
                "updatedAt": _now_iso(),
                "candidateOnly": True,
                "canClaimAGI": False,
            }
            handle["_runEtaPublishedMode"] = normalized_mode
            self.bus.bridge_event(str(handle["id"]), payload)
            return payload

    def _refresh_run_eta_on_provider_wait(
        self,
        handle: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Recalibrate the full-run ETA from overall, not per-call, elapsed."""

        return self._emit_run_eta(
            handle,
            mode=str(handle.get("runMode") or "solo"),
            phase="provider wait recalibration",
            refresh=True,
        )

    def _activate_run_mode(
        self,
        handle: dict[str, Any],
        mode: str,
        *,
        phase: str,
    ) -> None:
        """Set the authoritative run mode and announce its full-run ETA."""

        handle["runMode"] = mode
        self._emit_run_eta(handle, mode=mode, phase=phase)

    def _receipt_store(self, run_id: str) -> TaskReceiptStore:
        with self.receipts_lock:
            store = self.receipts.get(run_id)
            if store is None:
                store = TaskReceiptStore(self._receipt_dir() / f"{run_id}.jsonl", run_id=run_id)
                self.receipts[run_id] = store
            return store

    def _load_receipts(self) -> list[TaskReceiptStore]:
        with self.receipts_lock:
            root = self._receipt_dir()
            if root.is_dir():
                self._prune_receipt_dir(root)
                for path in sorted(root.glob("run-*.jsonl")):
                    run_id = path.stem
                    if run_id not in self.receipts:
                        try:
                            store = TaskReceiptStore(path, run_id=run_id)
                        except (OSError, ValueError):
                            continue
                        self.receipts[run_id] = store
                        # `run_id not in self.receipts` above is exactly "this
                        # store was not already tracked by this live process" —
                        # the only stores this process tracks directly are the
                        # run it is currently executing (added in
                        # _run_guarded) and runs it executed earlier in its own
                        # lifetime. Anything discovered by the disk glob was
                        # written by some OTHER process invocation, so it is
                        # the right (and only) population to check for a dead
                        # owner; a store this process already knows about is
                        # never reconciled here, since this process may still
                        # be actively writing to it.
                        self._reconcile_dead_run(store)
            return list(self.receipts.values())

    def _reconcile_dead_run(self, store: TaskReceiptStore) -> None:
        """Resolve a foreign run's stuck-non-terminal nodes to INTERRUPTED if
        its owning process is gone (see TaskReceiptStore.reconcile_orphaned).

        Confirmed on a real install: the bridge replayed every run-*.jsonl it
        found and reported whatever state was last written, so a session
        killed with Ctrl-C or a crash left its in-flight nodes RUNNING
        forever — 7 of 74 parsed receipts stuck that way. This call makes
        every subsequent `tasks`/`workflows` listing report the truth instead
        of replaying a state nobody is advancing anymore.
        """
        try:
            store.reconcile_orphaned(is_alive=_pid_is_alive)
        except (OSError, ValueError):
            # A corrupt or concurrently-truncated journal must not break the
            # listing; it is simply reported as-is (whatever replay recovered).
            pass

    def _prune_receipt_dir(self, root: Path) -> None:
        """Bound the receipts directory so it stops growing forever.

        Deletes a run's full file set (journal + .head/.txn/.lock sidecars)
        once it is older than RECEIPT_MAX_AGE_SEC *and*/or falls beyond the
        newest RECEIPT_MAX_COUNT files by mtime. The currently active run's
        file is always excluded, even if it happens to be the oldest on disk
        (a long-running task must never lose its own receipt mid-flight).
        Sibling bridge processes' own active runs are not visible to this
        process, but a genuinely live run keeps updating its file's mtime, so
        it only risks pruning if it has been silent for the entire age
        window — by then it is effectively indistinguishable from abandoned.
        """
        with self.active_lock:
            active_id = self.active.get("id") if self.active else None
        try:
            candidates = sorted(
                (p for p in root.glob("run-*.jsonl") if p.stem != active_id),
                key=lambda p: p.stat().st_mtime,
            )
        except OSError:
            return
        now = time.time()
        keep_from = max(0, len(candidates) - RECEIPT_MAX_COUNT)
        for index, path in enumerate(candidates):
            try:
                age = now - path.stat().st_mtime
            except OSError:
                continue
            if age > RECEIPT_MAX_AGE_SEC or index < keep_from:
                self._delete_receipt_files(path)

    def _delete_receipt_files(self, jsonl_path: Path) -> None:
        with self.receipts_lock:
            self.receipts.pop(jsonl_path.stem, None)
        for suffix in ("", ".head", ".head.tmp", ".txn", ".lock"):
            try:
                (jsonl_path.parent / (jsonl_path.name + suffix)).unlink(missing_ok=True)
            except OSError:
                # Best-effort cleanup; a file another process still has open
                # stays a live inode until that process closes it regardless.
                pass

    def _receipt_emit(self, kind: str, payload: Any, *, run_id: str, request_id: str | None = None,
                      session_id: str | None = None, task_id: str | None = None) -> None:
        body = receipt_envelope(kind, payload, runId=run_id, requestId=request_id,
                                sessionId=session_id, taskId=task_id)
        self.emit({"type": "receipt", **body})

    def _receipt_task(self, store: TaskReceiptStore, name: str, kind: TaskKind, *, parent_id: str | None = None,
                      request_id: str | None = None, session: str | None = None, can_cancel: bool = False,
                      can_retry: bool = False, detail: dict[str, Any] | None = None):
        node = store.create(name, kind, parent_id=parent_id, request_id=request_id, session=session,
                            can_cancel=can_cancel, can_retry=can_retry, detail=detail or {})
        self._receipt_emit(f"task.{kind.value}.created", node.to_dict(), run_id=store.run_id,
                          request_id=request_id, session_id=session, task_id=node.task_id)
        return node

    # -- output ------------------------------------------------------------ #
    def _next_protocol_sequence(self) -> int:
        with self.protocol_lock:
            self.protocol_sequence += 1
            return self.protocol_sequence

    @staticmethod
    def _event_qos(payload: dict) -> tuple[str, str | None]:
        event = payload.get("event") if isinstance(payload.get("event"), dict) else payload
        etype = str(event.get("type") or payload.get("type") or "")
        if etype in {
            "ready", "bye", "error", "result", "run_finished", "receipt", "approval_request",
            "approval_decision", "cancel_ack", "steer_ack", "steer_applied",
            "steer_rejected", "queue_next_ack", "diagnostic_snapshot",
            "mcp_health", "mcp_timeouts",
        }:
            return "critical", None
        if etype in {
            "token", "thinking_token", "bench_progress", "tbench_progress",
            "gaia_progress", "taubench_progress", "update_progress",
        }:
            run_id = str(payload.get("runId") or event.get("runId") or "")
            lane = str(payload.get("lane") or event.get("lane") or "")
            return "ephemeral", f"{run_id}:{lane}:{etype}"
        return "standard", None

    def _protocol_context(self, payload: dict) -> dict[str, Any]:
        context = getattr(self.command_local, "value", None)
        context = context if isinstance(context, dict) else {}
        run_id = str(payload.get("runId") or "")
        if run_id:
            with self.active_lock:
                active = self.active
            if active and active.get("id") == run_id:
                return {
                    **context,
                    "callId": active.get("callId") or context.get("callId"),
                    "attempt": active.get("attempt") or context.get("attempt"),
                    "parentEventId": active.get("rootEventId") or context.get("parentEventId"),
                }
        return context

    def _apply_protocol_metadata(self, payload: dict) -> dict:
        event = payload.get("event") if isinstance(payload.get("event"), dict) else payload
        context = self._protocol_context(payload)
        protocol_sequence = self._next_protocol_sequence()
        run_id = str(payload.get("runId") or event.get("runId") or "")
        event_id = str(
            payload.get("eventId")
            or event.get("eventId")
            or f"{run_id or self.instance_id}:event:{protocol_sequence}"
        )
        call_id = str(
            payload.get("callId")
            or event.get("callId")
            or context.get("callId")
            or payload.get("requestId")
            or event.get("requestId")
            or f"call:{event_id}"
        )
        try:
            protocol_attempt = max(
                1,
                int(payload.get("protocolAttempt")
                    or event.get("protocolAttempt")
                    or context.get("attempt")
                    or 1),
            )
        except (TypeError, ValueError):
            protocol_attempt = 1
        parent_event_id = (
            payload.get("parentEventId")
            or event.get("parentEventId")
            or context.get("parentEventId")
        )
        logical_type = str(event.get("type") or payload.get("type") or "")
        if logical_type == "run_start":
            parent_event_id = None
        qos, coalesce_key = self._event_qos(payload)
        shared: dict[str, Any] = {
            "protocol": PROTOCOL_VERSION,
            "bridgeInstanceId": self.instance_id,
            "protocolSequence": protocol_sequence,
            "eventId": event_id,
            "callId": call_id,
            "parentEventId": parent_event_id,
            "protocolAttempt": protocol_attempt,
            "qos": qos,
        }
        if context.get("requestId"):
            shared["requestId"] = context["requestId"]
        if coalesce_key:
            shared["coalesceKey"] = coalesce_key
        for target in (payload, event):
            for key, value in shared.items():
                target.setdefault(key, value)
            # Preserve pre-v2 semantic sequence/attempt fields (graph snapshots,
            # goal-loop attempts) while ensuring ordinary events expose the
            # v2 names directly.
            target.setdefault("sequence", protocol_sequence)
            target.setdefault("attempt", protocol_attempt)
        if logical_type == "run_start" and run_id:
            with self.active_lock:
                active = self.active
                if active and active.get("id") == run_id:
                    active["rootEventId"] = event_id
        return payload

    def _durable_run_event(self, payload: dict) -> dict[str, Any] | None:
        event = (
            payload.get("event")
            if isinstance(payload.get("event"), dict)
            else payload
        )
        logical_type = str(event.get("type") or payload.get("type") or "")
        if logical_type not in _DURABLE_RUN_EVENT_TYPES:
            return None
        run_id = str(payload.get("runId") or event.get("runId") or "")
        if not run_id:
            return None
        session = str(event.get("session") or payload.get("session") or "")
        if not session:
            with self.active_lock:
                active = self.active
            if active and str(active.get("id") or "") == run_id:
                session = str(active.get("session") or "")
        if not session:
            return None

        durable: dict[str, Any] = {
            "schema": "sophia.run-event.v1",
            "type": "run_event",
            "eventType": logical_type,
            "session": session,
            "runId": run_id,
            "eventId": str(
                event.get("eventId")
                or payload.get("eventId")
                or f"{run_id}:{logical_type}:{payload.get('protocolSequence') or 0}"
            ),
            "protocolSequence": _safe_int(
                payload.get("protocolSequence")
                or event.get("protocolSequence"),
                0,
            ),
        }
        for key in _DURABLE_RUN_EVENT_FIELDS:
            value = event.get(key)
            if value is None:
                value = payload.get(key)
            if key == "workflowChart":
                chart = _durable_workflow_chart(value)
                if chart is not None:
                    durable[key] = chart
                continue
            if key == "agents":
                agents = _durable_workflow_agents(value)
                if agents is not None:
                    durable[key] = agents
                continue
            if isinstance(value, (bool, int, float)):
                durable[key] = value
            elif isinstance(value, str) and value:
                durable[key] = (
                    _safe_diagnostic_text(value, limit=512)
                    if key in {"goal", "reason"}
                    else value[:512]
                )
        return durable

    def _publish_durable_run_event(self, payload: dict) -> None:
        durable = self._durable_run_event(payload)
        if durable is None:
            return
        try:
            self.run_finished_publisher.publish_event(durable)
        except (OSError, ValueError):
            # The live protocol is authoritative. A filesystem telemetry
            # failure must not prevent a run from making forward progress.
            return

    def _write_prepared_payload(self, payload: dict) -> dict:
        """Write a payload that already carries protocol and claim metadata."""
        if payload.get("type") in {"bridge_event", "event"}:
            self._record_lifecycle(payload)
        self._publish_durable_run_event(payload)
        try:
            from agent.thinking_trace import record_lifecycle
            record_lifecycle(event=str(payload.get("type") or "event"),
                             run_id=str(payload.get("runId") or ""),
                             session=str(payload.get("session") or ""),
                             request_id=str(payload.get("requestId") or ""),
                             status=str(payload.get("status") or ""),
                             metadata={"provider": payload.get("provider"), "model": payload.get("model"),
                                       "attempt": payload.get("attempt"), "ok": payload.get("ok"),
                                       "cancelReason": payload.get("cancelReason"),
                                       "errorType": (payload.get("errorPayload") or {}).get("type")})
        except Exception:
            # Thinking-trace lifecycle logging is best-effort telemetry; it
            # must never block emitting the actual event to the client below.
            pass
        line = json.dumps(payload, ensure_ascii=False)
        with self.write_lock:
            self.out.write(line + "\n")
            self.out.flush()
        return payload

    def emit(self, payload: dict) -> dict:
        run_id = payload.get("runId")
        if run_id and payload.get("type") in {"event", "bridge_event"}:
            with self.active_lock:
                active = self.active
                if active and active.get("id") == run_id and active.get("terminal"):
                    return payload
        self._apply_protocol_metadata(payload)
        _force_can_claim_false(payload)
        return self._write_prepared_payload(payload)

    @staticmethod
    def _run_finished_subs(handle: dict, result: dict) -> list[dict[str, Any]]:
        mode = str(handle.get("runMode") or "solo")
        subs: list[dict[str, Any]] = []
        if mode == "a2a":
            for raw in handle.get("a2aAgents") or []:
                if not isinstance(raw, dict):
                    continue
                name = str(raw.get("name") or "")
                slot = str(raw.get("role") or "")
                if slot != "sub" or not name:
                    continue
                status = str(raw.get("status") or "failed")
                subs.append({
                    "name": name,
                    "role": str(raw.get("persona") or slot),
                    "skills": [
                        str(skill) for skill in (raw.get("skills") or [])
                        if str(skill)
                    ],
                    "status": status,
                    **(
                        {"provider": str(raw.get("provider"))}
                        if raw.get("provider")
                        else {}
                    ),
                    **(
                        {"resolvedModel": str(raw.get("resolvedModel"))}
                        if raw.get("resolvedModel")
                        else {}
                    ),
                    **(
                        {"fallbackUsed": bool(raw.get("fallbackUsed"))}
                        if raw.get("fallbackUsed") is not None
                        else {}
                    ),
                })
        elif mode == "team":
            for index, raw in enumerate(result.get("laneResults") or []):
                if not isinstance(raw, dict):
                    continue
                status = "succeeded" if raw.get("ok") is True else "failed"
                error = str(raw.get("error") or "")
                if "abandoned" in error.lower():
                    status = "abandoned"
                subs.append({
                    "name": str(raw.get("name") or f"Lane {index + 1}"),
                    "role": str(raw.get("role") or "worker"),
                    "skills": [
                        str(skill) for skill in (raw.get("skills") or [])
                        if str(skill)
                    ],
                    "status": status,
                })
        elif mode == "workflow":
            for raw in handle.get("dynamicWorkflowAgents") or []:
                if not isinstance(raw, dict):
                    continue
                name = str(raw.get("name") or "")
                if not name:
                    continue
                subs.append({
                    "name": name,
                    "role": str(raw.get("persona") or raw.get("role") or "sub"),
                    "skills": [
                        str(skill) for skill in (raw.get("skills") or [])
                        if str(skill)
                    ],
                    "status": str(raw.get("status") or "failed"),
                    "stage": max(1, _safe_int(raw.get("stage"), 1)),
                    **(
                        {"reasonCode": str(raw.get("reasonCode"))}
                        if raw.get("reasonCode")
                        else {}
                    ),
                    **(
                        {"started": bool(raw.get("started"))}
                        if raw.get("started") is not None
                        else {}
                    ),
                    **(
                        {"pattern": str(raw.get("pattern"))}
                        if raw.get("pattern")
                        else {}
                    ),
                    **(
                        {
                            "error": _safe_diagnostic_text(
                                raw.get("error"),
                                limit=800,
                            )
                        }
                        if raw.get("error")
                        else {}
                    ),
                    **(
                        {"provider": str(raw.get("provider"))}
                        if raw.get("provider")
                        else {}
                    ),
                    **(
                        {"resolvedModel": str(raw.get("resolvedModel"))}
                        if raw.get("resolvedModel")
                        else {}
                    ),
                    **(
                        {"fallbackUsed": bool(raw.get("fallbackUsed"))}
                        if raw.get("fallbackUsed") is not None
                        else {}
                    ),
                })
        return subs

    @staticmethod
    def _build_run_finished_payload(
        handle: dict,
        result: dict,
    ) -> dict[str, Any] | None:
        """Build the fail-closed terminal receipt, or none for a paused run."""
        mode = str(handle.get("runMode") or "solo")
        receipt_mode = "agi" if mode.startswith("agi") else mode
        agi_status = str(
            (handle.get("agiResult") or {}).get("status")
            or result.get("agiStatus")
            or ""
        ).lower()
        awaiting_input = (
            result.get("awaitingInput") is True
            or str(result.get("goalStatus") or "").lower() == "awaiting_input"
            or agi_status in {"paused", "awaiting_input", "interrupted"}
        )
        if awaiting_input:
            return None
        if receipt_mode == "agi" and agi_status in {
            "", "running"
        }:
            return None

        workflow_result = dict(handle.get("dynamicWorkflowResult") or {})
        workflow_reason_code = str(workflow_result.get("reasonCode") or "")
        if result.get("cancelled") or agi_status == "cancelled":
            reason = "cancel"
        elif receipt_mode == "agi" and agi_status in {"bound_hit", "unachievable"}:
            reason = "bound"
        elif bool(result.get("ok")):
            reason = "verified"
        else:
            reason = "error"

        error_text = _safe_diagnostic_text(result.get("error"), limit=800)

        cancellation_code = ""
        if mode == "workflow" and reason == "cancel":
            cancel_reason = str(
                result.get("cancelReason")
                or handle.get("cancelReason")
                or "user_cancel"
            ).strip()
            cancellation_code = {
                "user_cancel": "operator_cancelled",
                "operator_cancel": "operator_cancelled",
                "budget_cancel": "budget_cancelled",
                "budget": "budget_cancelled",
                "backend_exit": "backend_exit",
            }.get(cancel_reason, "workflow_cancelled")
            workflow_reason_code = cancellation_code

        payload = {
            "type": "run_finished",
            "session": str(handle.get("session") or ""),
            "runId": str(handle.get("id") or result.get("runId") or ""),
            "ok": bool(result.get("ok")) and reason == "verified",
            "mode": (
                receipt_mode
                if receipt_mode in {"solo", "a2a", "team", "agi", "workflow"}
                else "solo"
            ),
            "reason": reason,
            **(
                {"error": error_text}
                if error_text
                else {}
            ),
            **(
                {
                    "reasonCode": (
                        workflow_reason_code
                        or (
                            "verified"
                            if reason == "verified"
                            else "workflow_failed"
                        )
                    )
                }
                if mode == "workflow"
                else {}
            ),
            "subs": CodeBridge._run_finished_subs(handle, result),
            "startedAt": str(handle.get("startedAt") or ""),
            "endedAt": _now_iso(),
            "durationSec": round(
                max(
                    0.0,
                    time.monotonic()
                    - float(handle.get("startedMonotonic") or time.monotonic()),
                ),
                3,
            ),
            **(
                {"requestId": str(handle["requestId"])}
                if handle.get("requestId") is not None
                else {}
            ),
            **(
                {"callId": str(handle["callId"])}
                if handle.get("callId")
                else {}
            ),
            **(
                {"parentEventId": str(handle["rootEventId"])}
                if handle.get("rootEventId")
                else {}
            ),
            **(
                {
                    "dispatchManifestPath": str(
                        handle["dispatchManifestPath"]
                    ),
                    "dispatchManifestSchema": (
                        "sophia.dispatch-manifest.v1"
                    ),
                }
                if handle.get("dispatchManifestPath")
                else {}
            ),
            "candidateOnly": True,
            "canClaimAGI": False,
        }
        if mode == "workflow":
            stages = [
                stage
                for stage in (handle.get("dynamicWorkflowStages") or [])
                if isinstance(stage, dict)
            ]
            derived_requested_agents = sum(
                _safe_int(
                    stage.get("requestedAgentCount"),
                    len(stage.get("agents") or []),
                )
                for stage in stages
            )
            derived_started_agents = sum(
                _safe_int(
                    stage.get("startedAgentCount"),
                    len(stage.get("agents") or []),
                )
                for stage in stages
            )
            derived_unstarted_agents = sum(
                _safe_int(stage.get("unstartedAgentCount"), 0)
                for stage in stages
            )
            recorded_requested_agents = _safe_int(
                workflow_result.get("requestedAgents"),
                0,
            )
            recorded_started_agents = _safe_int(
                workflow_result.get("totalAgents"),
                0,
            )
            recorded_unstarted_agents = _safe_int(
                workflow_result.get("unstartedAgents"),
                0,
            )
            last_pattern = next(
                (
                    str(stage.get("pattern") or "")
                    for stage in reversed(stages)
                    if str(stage.get("pattern") or "")
                ),
                "",
            )
            controller_status = str(workflow_result.get("status") or "")
            controller_pattern = str(workflow_result.get("pattern") or "")
            controller_reason = str(workflow_result.get("reason") or "")
            if reason == "cancel":
                controller_status = "cancelled"
                controller_pattern = controller_pattern or last_pattern
                cancel_phase = str(
                    handle.get("dynamicWorkflowPhase")
                    or (
                        f"stage {stages[-1].get('stage')} review"
                        if stages
                        else "workflow execution"
                    )
                )
                controller_reason = (
                    f"operator cancelled during {cancel_phase}"
                    if cancellation_code == "operator_cancelled"
                    else f"workflow cancelled during {cancel_phase}"
                )
            existing_critic = dict(
                workflow_result.get("criticBarrier") or {}
            )
            critic_stages = [
                stage
                for stage in stages
                if str(stage.get("kind") or "") == "critic"
            ]
            critic_required = bool(existing_critic.get("required")) or bool(
                critic_stages
            )
            critic_satisfied = bool(existing_critic.get("satisfied")) or any(
                str(stage.get("status") or "") == "succeeded"
                and _safe_int(
                    stage.get("requestedAgentCount"),
                    len(stage.get("agents") or []),
                )
                > 0
                and (
                    not isinstance(stage.get("results"), list)
                    or len(stage.get("results") or [])
                    >= _safe_int(
                        stage.get("requestedAgentCount"),
                        len(stage.get("agents") or []),
                    )
                )
                for stage in critic_stages
            )
            payload["workflowReceipt"] = {
                "controller": {
                    "status": controller_status,
                    "pattern": controller_pattern,
                    "reason": _safe_diagnostic_text(
                        controller_reason,
                        limit=800,
                    ),
                    "reasonCode": str(
                        cancellation_code
                        or workflow_result.get("reasonCode")
                        or workflow_reason_code
                        or reason
                    ),
                },
                "scheduler": {
                    "stages": len(stages),
                    "requestedAgents": max(
                        recorded_requested_agents,
                        derived_requested_agents,
                    ),
                    "startedAgents": max(
                        recorded_started_agents,
                        derived_started_agents,
                    ),
                    "unstartedAgents": max(
                        recorded_unstarted_agents,
                        derived_unstarted_agents,
                    ),
                    "stageReceipts": [
                        {
                            "stage": _safe_int(stage.get("stage"), 0),
                            "kind": str(stage.get("kind") or "general"),
                            "status": str(stage.get("status") or ""),
                            "requestedAgents": _safe_int(
                                stage.get("requestedAgentCount"),
                                len(stage.get("agents") or []),
                            ),
                            "startedAgents": _safe_int(
                                stage.get("startedAgentCount"),
                                len(stage.get("agents") or []),
                            ),
                            "unstartedAgents": _safe_int(
                                stage.get("unstartedAgentCount"),
                                0,
                            ),
                            "failureCodes": [
                                str(code)
                                for code in (stage.get("failureCodes") or [])
                                if str(code)
                            ],
                            "failures": [
                                {
                                    "name": str(
                                        item.get("name")
                                        or item.get("taskId")
                                        or "worker"
                                    ),
                                    "taskId": str(item.get("taskId") or ""),
                                    "started": bool(item.get("started")),
                                    "reasonCode": str(
                                        item.get("reasonCode")
                                        or "worker_failed"
                                    ),
                                    "error": _safe_diagnostic_text(
                                        item.get("error")
                                        or item.get("modelError")
                                        or "",
                                        limit=800,
                                    ),
                                }
                                for item in (stage.get("results") or [])
                                if isinstance(item, dict) and not item.get("ok")
                            ],
                        }
                        for stage in stages
                    ],
                },
                "criticBarrier": {
                    **existing_critic,
                    "required": critic_required,
                    "satisfied": critic_satisfied,
                },
                "deliveryGate": {
                    "gated": bool(result.get("gated")),
                    "epistemic": dict(result.get("epistemic") or {}),
                },
                "candidateOnly": True,
                "canClaimAGI": False,
            }
        return payload

    def _emit_run_finished(self, handle: dict, result: dict) -> None:
        payload = self._build_run_finished_payload(handle, result)
        if payload is None:
            return
        key = (str(payload["session"]), str(payload["runId"]))
        with self.run_finished_lock:
            if key in self.run_finished_ids:
                return
            self._apply_protocol_metadata(payload)
            _force_can_claim_false(payload)
            try:
                published = self.run_finished_publisher.publish(payload)
            except OSError as exc:
                # The live protocol must still terminate if a state directory
                # becomes unwritable.  Keep a diagnostic on the handle while
                # preserving the secret-free payload on stdout.
                handle.setdefault("diagnostics", []).append({
                    "type": "run_finished_persistence_error",
                    "error": f"{type(exc).__name__}: {exc}",
                })
                published = True
            self.run_finished_ids.add(key)
        if published:
            self._write_prepared_payload(payload)
            try:
                from agent.tui_failure_memory import record_from_run_finished

                workspace = Path(
                    str(handle.get("root") or handle.get("workspace") or Path.cwd())
                )
                memory = record_from_run_finished(payload, workspace=workspace)
                if memory.get("recorded"):
                    handle.setdefault("diagnostics", []).append(
                        {
                            "type": "tui_failure_memory",
                            "proposalId": memory.get("proposalId"),
                            "okfPath": memory.get("okfPath"),
                            "applied": False,
                            "candidateOnly": True,
                            "canClaimAGI": False,
                        }
                    )
                    self.bus.bridge_event(
                        str(payload.get("runId") or handle.get("id") or ""),
                        {
                            "type": "tui_failure_memory",
                            "proposalId": memory.get("proposalId"),
                            "okfPath": memory.get("okfPath"),
                            "applied": False,
                            "candidateOnly": True,
                            "canClaimAGI": False,
                        },
                    )
            except Exception:  # noqa: BLE001 - memory must not sink run_finished
                pass

    def _finalize_run_finished(self, handle: dict, result: dict) -> None:
        """Emit only after any cancelled-but-in-flight provider lanes return."""
        threads = [
            thread for thread in (handle.get("completionThreads") or [])
            if isinstance(thread, threading.Thread) and thread.is_alive()
        ]
        if not threads:
            self._emit_run_finished(handle, result)
            return

        def wait_and_emit() -> None:
            for thread in threads:
                thread.join()
            self._emit_run_finished(handle, result)

        threading.Thread(
            target=wait_and_emit,
            name=f"run-finished-{handle.get('id', 'unknown')}",
            daemon=True,
        ).start()

    def _record_lifecycle(self, payload: dict) -> None:
        run_id = payload.get("runId")
        if not run_id:
            return
        event = payload.get("event") if isinstance(payload.get("event"), dict) else {}
        etype = str(event.get("type") or "")
        kind_map = {"run_start": TaskKind.WORKFLOW, "lane_start": TaskKind.AGENT,
                    "tool_call": TaskKind.TOOL, "tool_result": TaskKind.TOOL,
                    "validation": TaskKind.VALIDATION}
        try:
            store = self._receipt_store(str(run_id))
            # A team lane finishing: advance the lane's durable AGENT node (minted
            # on lane_start) to its verdict so the TUI's panel/tree shows the
            # member crossing out (✓ succeeded / ✗ failed) instead of staying
            # perpetually "queued" — the bug where every lane row spun forever.
            # lane_end carries no node (only lane+ok+error), so the lane->taskId
            # map recorded on lane_start is the lookup key.
            if etype == "lane_end":
                self._finish_lane(store, event)
                return
            if etype not in kind_map:
                return
            if etype.endswith("_start") or etype == "run_start":
                # The workflow receipt is created authoritatively at run setup.
                # The UI run_start event is descriptive and must not mint a second
                # durable workflow node.
                if etype == "run_start" and self.active and self.active.get("workflowTaskId"):
                    return
                parent = self.active.get("workflowTaskId") if self.active else None
                detail: dict[str, Any] = {"event": etype}
                if etype == "lane_start":
                    for key in ("lane", "role", "title", "division", "source"):
                        if event.get(key):
                            detail[key] = str(event.get(key))
                    if isinstance(event.get("skills"), list):
                        detail["skills"] = [
                            str(skill) for skill in event["skills"] if str(skill).strip()
                        ]
                display_name = (
                    event.get("role")
                    or event.get("title")
                    or event.get("tool")
                    or etype
                )
                node = self._receipt_task(store, str(display_name), kind_map[etype],
                                   parent_id=parent, request_id=self.active.get("requestId") if self.active else None,
                                   session=self.active.get("session") if self.active else None,
                                   can_cancel=etype == "run_start", detail=detail)
                # A lane is WORKING the moment it starts (not queued): record its
                # lane->taskId so lane_end can find it, and advance QUEUED->RUNNING
                # so the panel shows it active immediately.
                if etype == "lane_start" and event.get("lane") and self.active is not None:
                    self.active.setdefault("laneTaskIds", {})[str(event.get("lane"))] = node.task_id
                    store.transition(node.task_id, TaskState.RUNNING)
        except Exception:
            # Receipt/lifecycle bookkeeping is best-effort; a failure here must
            # never break the kernel event stream this method wraps.
            pass

    def _finish_lane(self, store: "TaskReceiptStore", event: dict) -> None:
        """Transition a team lane's AGENT node to its verdict on lane_end and tell
        the TUI. The journal transition alone never reaches the UI, so this emits
        a receipt with the updated node — mirroring workflow.finished's pattern."""
        if self.active is None:
            return
        task_id = (self.active.get("laneTaskIds") or {}).get(str(event.get("lane") or ""))
        if not task_id:
            return
        ok = bool(event.get("ok"))
        state = TaskState.SUCCEEDED if ok else TaskState.FAILED
        detail: dict[str, Any] = {"ok": ok}
        if not ok and event.get("error"):
            detail["error"] = _safe_text(event.get("error"), limit=300)
        for key in (
            "toolCallCount",
            "toolsUsed",
            "nativeToolCallCount",
            "nativeToolsUsed",
            "readBatchToolsUsed",
        ):
            if key in event:
                detail[key] = event[key]
        try:
            node = store.transition(task_id, state, detail=detail)
        except Exception:  # noqa: BLE001 - already terminal/unknown: nothing to update
            return
        self._receipt_emit(f"task.agent.{state.value}", node.to_dict(),
                           run_id=store.run_id,
                           request_id=self.active.get("requestId"),
                           session_id=self.active.get("session"),
                           task_id=node.task_id)

    def error(self, message: str, *, error_type: str = "BridgeError", cmd: str | None = None,
              retryable: bool | None = None) -> None:
        if retryable is None:
            retryable = error_type in {
                "BridgeUnavailable", "MCPHealthTimeout", "RunBusy",
                "ChildExited", "BridgeRestartTimeout",
            }
        error_payload = _safe_error_payload(
            message=message,
            error_type=error_type,
        )
        error_payload.update({
            "category": (
                "protocol" if error_type.startswith(("Command", "Unknown"))
                else "availability" if retryable
                else "runtime"
            ),
            "retryable": bool(retryable),
            "command": cmd,
        })
        self.emit({
            "type": "error",
            "error": _safe_text(message, limit=800),
            "errorPayload": error_payload,
            "cmd": cmd,
            "ts": _now_iso(),
            "canClaimAGI": False,
        })

    # -- commands ---------------------------------------------------------- #
    def handle(self, cmd: dict) -> None:
        if not isinstance(cmd, dict):
            self.error("command must be a JSON object", error_type="CommandShapeError")
            return
        name = str(cmd.get("cmd") or "").strip().lower()
        request_id = cmd.get("requestId", cmd.get("requestID"))
        if request_id is not None:
            request_id = _safe_text(request_id, limit=128)
        call_id = _safe_text(
            cmd.get("callId") or request_id or f"call-{uuid.uuid4().hex[:12]}",
            limit=128,
        )
        try:
            attempt = max(1, int(cmd.get("attempt", 1)))
        except (TypeError, ValueError):
            attempt = 1
        previous_context = getattr(self.command_local, "value", None)
        self.command_local.value = {
            "requestId": request_id,
            "callId": call_id,
            "attempt": attempt,
            "parentEventId": (
                _safe_text(cmd.get("parentEventId"), limit=160)
                if cmd.get("parentEventId") else None
            ),
        }
        try:
            try:
                if name == "config":
                    self.emit({
                        "type": "config",
                        **self.config_payload(cmd.get("cwd")),
                    })
                elif name == "state":
                    state, warning = _load_state()
                    self.emit({"type": "state", "ok": True, "state": _public_state(state, warning),
                               "canClaimAGI": False})
                elif name == "settings":
                    self._handle_settings(cmd)
                elif name in {"plugin", "plugins"}:
                    self._handle_plugin(cmd)
                elif name == "sessions":
                    self.emit({"type": "sessions", **self.sessions_payload(limit=_safe_int(cmd.get("limit"), 50))})
                elif name in {"session_supervisor", "sessiond"}:
                    self._handle_session_supervisor(cmd)
                elif name in {"tasks", "workflows"}:
                    self._handle_tasks(cmd)
                elif name in {"snapshot", "diagnostic_snapshot", "receipt_snapshot"}:
                    self._handle_diagnostic_snapshot(cmd)
                elif name in {"task_action", "task_log"}:
                    self._handle_task_command(name, cmd)
                elif name in {"session_load", "load_session"}:
                    self._handle_session_load(cmd)
                elif name == "steer":
                    self._handle_steer(cmd)
                elif name in {"queue_next", "queue-next"}:
                    self._handle_queue_next(cmd)
                elif name == "compound_workflow":
                    self._handle_compound_workflow(cmd)
                elif name == "run":
                    self._handle_run(cmd)
                elif name == "goal":
                    self._handle_goal(cmd)
                elif name == "agi":
                    self._handle_agi(cmd)
                elif name == "approve":
                    self._handle_approve(cmd)
                elif name == "cancel":
                    self._handle_cancel(cmd)
                elif name == "mcp_health":
                    self._handle_mcp_health(cmd)
                elif name == "mcp_timeouts":
                    self._handle_mcp_timeouts(cmd)
                elif name == "provider_health":
                    self._handle_provider_health(cmd)
                elif name in {"provider_login", "login"}:
                    self._handle_provider_login(cmd)
                elif name == "model_connection":
                    self._handle_model_connection(cmd)
                elif name == "hooks":
                    self._handle_hooks(cmd)
                elif name in {"shell", "bash"}:
                    self._handle_shell(cmd)
                elif name in {"checkpoints", "checkpoint_list"}:
                    self._handle_checkpoints(cmd)
                elif name == "checkpoint_undo":
                    self._handle_checkpoint_undo(cmd)
                elif name == "checkpoint_restore":
                    self._handle_checkpoint_restore(cmd)
                elif name in {"local_engine_report", "engine_report"}:
                    self._handle_local_engine_report(cmd)
                elif name == "adapter_status":
                    self._handle_adapter_status(cmd)
                elif name == "model_preflight":
                    self._handle_model_preflight(cmd)
                elif name == "image":
                    self._handle_image(cmd)
                elif name == "compact":
                    self._handle_compact(cmd)
                elif name == "bench":
                    self._handle_bench(cmd)
                elif name == "tbench":
                    self._handle_tbench(cmd)
                elif name == "gaia":
                    self._handle_gaia(cmd)
                elif name == "taubench":
                    self._handle_taubench(cmd)
                elif name == "graph":
                    self._handle_graph(cmd)
                elif name == "update":
                    self._handle_update(cmd)
                elif name == "shutdown":
                    self.shutdown.set()
                    self._clear_queue_next(reason="bridge shutdown")
                    self._handle_cancel({"reason": "backend_exit"})
                    self._wait_active()
                    self.close()
                    self.emit({"type": "bye", "ts": _now_iso(), "canClaimAGI": False})
                else:
                    self.error(f"unknown cmd {name!r}", error_type="UnknownCommand", cmd=name or None)
            except ModuleNotFoundError as exc:
                missing = str(getattr(exc, "name", "") or "")
                from agent.edition import (
                    edition_unavailable_message,
                    is_full_only_module,
                )

                qualified = missing if missing.startswith("agent.") else f"agent.{missing}"
                if missing and (
                    is_full_only_module(missing) or is_full_only_module(qualified)
                ):
                    self.error(
                        edition_unavailable_message(
                            missing.rsplit(".", 1)[-1].replace("_", "-")
                        ),
                        error_type="OpenEdition",
                        cmd=name or None,
                    )
                else:
                    self.error(
                        f"{type(exc).__name__}: {exc}",
                        error_type=type(exc).__name__,
                        cmd=name or None,
                    )
            except Exception as exc:  # noqa: BLE001 - the app must always get JSON back
                self.error(f"{type(exc).__name__}: {exc}", error_type=type(exc).__name__, cmd=name or None)
        finally:
            if previous_context is None:
                try:
                    del self.command_local.value
                except AttributeError:
                    pass
            else:
                self.command_local.value = previous_context

    def _handle_session_supervisor(self, cmd: dict) -> None:
        """Start or probe the per-user terminal supervisor without failing the bridge.

        The native app connects to sessiond directly for durable terminal state,
        but the Python bridge owns the packaged runtime needed to launch it.
        Startup failures therefore use a dedicated non-fatal status envelope:
        chat/AGI progress remains usable while the UI reports terminal services
        as unavailable.
        """
        action = str(cmd.get("action") or "ensure").strip().lower()
        if action not in {"ensure", "status"}:
            self.error(
                f"unsupported session supervisor action {action!r}",
                error_type="CommandValueError",
                cmd="session_supervisor",
            )
            return
        try:
            from agent.session_supervisor import SessionSupervisorClient

            client = SessionSupervisorClient()
            hello = (
                client.ensure_running()
                if action == "ensure"
                else dict(client.request("hello", timeout=0.5))
            )
            self.emit(
                {
                    "type": "session_supervisor_status",
                    "ok": True,
                    "connected": True,
                    "action": action,
                    "schema": hello.get("schema"),
                    "bootId": hello.get("bootId"),
                    "canClaimAGI": False,
                }
            )
        except Exception as exc:  # noqa: BLE001 - non-fatal app service status
            self.emit(
                {
                    "type": "session_supervisor_status",
                    "ok": False,
                    "connected": False,
                    "action": action,
                    "error": _safe_text(f"{type(exc).__name__}: {exc}", limit=800),
                    "canClaimAGI": False,
                }
            )

    def _handle_settings(self, cmd: dict) -> None:
        next_session_raw = (
            cmd.get("selectedSessionID")
            if cmd.get("selectedSessionID") is not None
            else cmd.get("session")
        )
        if next_session_raw is not None:
            self._end_plugin_leases_for_session_change(
                _normalize_session(next_session_raw)
            )
        state, _ = _load_state()
        defaults = _normalize_defaults(state.get("defaults") if isinstance(state.get("defaults"), dict) else {})
        updated = False
        if cmd.get("gateBypass") is not None:
            self.error("frontend gateBypass is not permitted", error_type="GateBypassRejected", cmd="settings")
            return
        requested_model = (
            _validate_fresh_model(cmd.get("model"))
            if cmd.get("model") is not None
            else None
        )
        for key in (
            "runtime", "model", "mode", "permission", "logicJudge", "deepThink", "deepMode",
            "team", "session", "maxSteps", "cwd", "effort", "responseStyle",
            "thinkingVisibility", "keymap", "imageProvider",
            "notifications", "semanticReturnToPrimary", "conscienceMode",
            "agiMode", "agiProfile", "agiPlannerModel", "agiWorkerModel",
            "agiVerifierModel", "agiRoute", "a2aExecution", "terminalLayout",
            "workflowMode", "workflowMaxStages", "workflowMaxAgents",
            "workflowChartPath",
            "agiWorkflowMode",
        ):
            if cmd.get(key) is not None:
                defaults[key] = requested_model if key == "model" else cmd.get(key)
                updated = True
        if "semanticFallbackModel" in cmd:
            defaults["semanticFallbackModel"] = _normalize_semantic_fallback_model(
                cmd.get("semanticFallbackModel")
            )
            # Setting a model is an explicit opt-in to confirm mode unless the
            # same command explicitly says otherwise. Clearing it disables the
            # feature and prevents a stale hidden model from remaining armed.
            if "semanticFallbackPolicy" not in cmd:
                defaults["semanticFallbackPolicy"] = (
                    "confirm" if defaults["semanticFallbackModel"] else "off"
                )
            updated = True
        if "semanticFallbackPolicy" in cmd:
            defaults["semanticFallbackPolicy"] = _normalize_semantic_fallback_policy(
                cmd.get("semanticFallbackPolicy")
            )
            updated = True
        if "autoTeam" in cmd:
            defaults["autoTeam"] = _normalize_optional_bool(cmd.get("autoTeam"))
            updated = True
        if "a2aAgents" in cmd or "a2a" in cmd:
            defaults["a2aAgents"] = _normalize_a2a_agents(
                cmd.get("a2aAgents"), cmd.get("a2a"),
            )
            updated = True
        if "a2aExecution" in cmd:
            defaults["a2aExecution"] = _normalize_a2a_execution(
                cmd.get("a2aExecution")
            )
            updated = True
        if "terminalLayout" in cmd:
            defaults["terminalLayout"] = _normalize_terminal_layout(
                cmd.get("terminalLayout")
            )
            updated = True
        if "workflowMode" in cmd:
            defaults["workflowMode"] = _normalize_workflow_mode(
                cmd.get("workflowMode")
            )
            updated = True
        if "workflowMaxStages" in cmd:
            defaults["workflowMaxStages"] = _normalize_workflow_max_stages(
                cmd.get("workflowMaxStages")
            )
            updated = True
        if "workflowMaxAgents" in cmd:
            defaults["workflowMaxAgents"] = _normalize_workflow_max_agents(
                cmd.get("workflowMaxAgents")
            )
            updated = True
        if "workflowChartPath" in cmd:
            defaults["workflowChartPath"] = _normalize_workflow_chart_path(
                cmd.get("workflowChartPath")
            )
            updated = True
        if "agiWorkflowMode" in cmd:
            defaults["agiWorkflowMode"] = _normalize_workflow_mode(
                cmd.get("agiWorkflowMode")
            )
            updated = True
        if cmd.get("selectedSessionID") is not None:
            state["selectedSessionID"] = _normalize_session(cmd.get("selectedSessionID"))
            updated = True
        if isinstance(cmd.get("onboarding"), dict):
            onboarding = state.get("onboarding")
            if not isinstance(onboarding, dict):
                onboarding = {}
            for key in (
                "providerConfirmed",
                "permissionConfirmed",
                "autoTeamConfirmed",
                "imageProviderConfirmed",
            ):
                if key in cmd["onboarding"]:
                    onboarding[key] = bool(cmd["onboarding"][key])
            state["onboarding"] = onboarding
            updated = True
        if updated:
            defaults = _normalize_defaults(defaults)
            state["defaults"] = defaults
            try:
                state = _save_state(state)
            except OSError as exc:
                self.error(f"could not save code state: {type(exc).__name__}", error_type=type(exc).__name__)
                return
        payload: dict[str, Any] = {"type": "state", "ok": True, "state": _public_state(state), "canClaimAGI": False}
        if requested_model:
            # An explicit model change IS the "/model switch" moment
            # resolve_config_with_live_context_window is designed for — report
            # the real window immediately instead of waiting for the next
            # `config` fetch to notice the default changed.
            try:
                from agent.model import resolve_config_with_live_context_window
                payload["modelContextWindow"] = resolve_config_with_live_context_window(
                    _model_spec(requested_model)
                ).context_window
            except Exception:  # noqa: BLE001 - an unresolvable model just means "unknown window"
                payload["modelContextWindow"] = None
        self.emit(payload)

    def _persist_plugin_settings_patch(
        self, patch: dict[str, Any]
    ) -> dict[str, Any]:
        """Persist a policy-validated plugin proposal without widening it.

        PluginHost has already rejected unknown/protected keys.  Re-normalize
        at the CodeBridge authority boundary so a future host regression still
        cannot smuggle an invalid workflow value into durable TUI state.
        """
        allowed = {
            "workflowMode",
            "workflowMaxStages",
            "workflowMaxAgents",
            "workflowChartPath",
            "a2aAgents",
            "a2aExecution",
            "terminalLayout",
            "autoTeam",
            "team",
            "deepThink",
            "deepMode",
            "responseStyle",
            "agiMode",
        }
        unknown = sorted(set(patch) - allowed)
        if unknown:
            raise ValueError(
                "plugin settings patch has unsupported key(s): "
                + ", ".join(unknown)
            )
        state, _ = _load_state()
        defaults = _normalize_defaults(
            state.get("defaults")
            if isinstance(state.get("defaults"), dict)
            else {}
        )
        normalized: dict[str, Any] = {}
        for key, value in patch.items():
            if key == "workflowMode":
                normalized[key] = _normalize_workflow_mode(value)
            elif key == "workflowMaxStages":
                normalized[key] = _normalize_workflow_max_stages(value)
            elif key == "workflowMaxAgents":
                normalized[key] = _normalize_workflow_max_agents(value)
            elif key == "workflowChartPath":
                normalized[key] = _normalize_workflow_chart_path(value)
            elif key == "a2aAgents":
                normalized[key] = _normalize_a2a_agents(value)
            elif key == "a2aExecution":
                normalized[key] = _normalize_a2a_execution(value)
            elif key == "terminalLayout":
                normalized[key] = _normalize_terminal_layout(value)
            elif key == "autoTeam":
                normalized[key] = _normalize_optional_bool(value)
            elif key == "team":
                normalized[key] = _normalize_team(value)
            elif key in {"deepThink", "deepMode"}:
                normalized[key] = _normalize_bool(value)
            elif key == "responseStyle":
                normalized[key] = _normalize_response_style(value)
            elif key == "agiMode":
                if value is not False:
                    raise ValueError(
                        "plugin runtime safety patch may only disable agiMode"
                    )
                normalized[key] = False
        state["defaults"] = _normalize_defaults({**defaults, **normalized})
        return _save_state(state)

    @staticmethod
    def _plugin_lease_binding(
        host: Any,
        lease: Any,
    ) -> tuple[Any, int] | None:
        if not isinstance(lease, Mapping):
            return None
        generation = lease.get("generation")
        if not isinstance(generation, int) or isinstance(generation, bool):
            return None
        return host, generation

    @staticmethod
    def _same_plugin_lease_binding(
        left: tuple[Any, int] | None,
        right: tuple[Any, int] | None,
    ) -> bool:
        return (
            left is not None
            and right is not None
            and left[0] is right[0]
            and left[1] == right[1]
        )

    def _plugin_lease_publication_snapshot(
        self,
    ) -> tuple[Any, int] | None:
        with self.plugin_lease_publication_lock:
            return self.plugin_active_lease_binding

    def _publish_plugin_host_event(
        self,
        host: Any,
        payload: Mapping[str, Any],
        *,
        expected_binding: tuple[Any, int] | None = None,
    ) -> dict:
        """Serialize client-wide lease patches across workspace hosts."""
        event = payload if isinstance(payload, dict) else dict(payload)
        activated_binding = (
            self._plugin_lease_binding(host, event.get("activeLease"))
            if event.get("activated") is True
            else None
        )
        lease_ended = event.get("leaseEnded") is True
        if activated_binding is None and not lease_ended:
            return self.emit(event)

        with self.plugin_lease_publication_lock:
            if activated_binding is not None:
                emitted = self.emit(event)
                self.plugin_active_lease_binding = activated_binding
                return emitted

            ended_binding = self._plugin_lease_binding(
                host,
                event.get("endedLease"),
            )
            if ended_binding is None and (
                expected_binding is not None
                and expected_binding[0] is host
            ):
                # Disable/safe-mode command envelopes retain the restoration
                # patch but summarize the ended lease instead of embedding it.
                ended_binding = expected_binding
            if not self._same_plugin_lease_binding(
                self.plugin_active_lease_binding,
                ended_binding,
            ):
                raise PermissionError(
                    "plugin lease changed before bridge result publication"
                )
            emitted = self.emit(event)
            self.plugin_active_lease_binding = None
            return emitted

    def _plugin_lease_end_publisher(
        self,
        host: Any,
    ) -> Callable[[dict[str, Any]], None]:
        expected_binding = self._plugin_lease_publication_snapshot()

        def publish(result: dict[str, Any]) -> None:
            self._publish_plugin_host_event(
                host,
                result,
                expected_binding=expected_binding,
            )

        return publish

    @staticmethod
    def _is_stale_plugin_lease_publication(exc: PermissionError) -> bool:
        return str(exc) in {
            "plugin lease changed before lease-end result publication",
            "plugin lease changed before bridge result publication",
        }

    def _handle_plugin(self, cmd: dict) -> None:
        """Handle explicit operator actions against the plugin host.

        Discovery is read-only. Enable/disable/selection writes are owned by
        PluginRegistry and workflow profile patches are persisted only after
        PluginPolicy validation plus this bridge-side second normalization.
        """
        action = str(cmd.get("action") or "list").strip().casefold()
        root = _normalize_workspace_root(cmd.get("cwd"))
        try:
            with self.plugin_host_lock:
                host = self._plugin_host(root)
            safe_mode_enabled = cmd.get("enabled")
            if action.replace("-", "_") == "safe_mode" and not isinstance(
                safe_mode_enabled,
                bool,
            ):
                raise ValueError(
                    "plugin safe_mode requires an explicit boolean enabled value"
                )
            state, _ = _load_state()
            defaults = (
                state.get("defaults")
                if isinstance(state.get("defaults"), dict)
                else {}
            )
            expected_binding = self._plugin_lease_publication_snapshot()

            def publish(result: dict[str, Any]) -> None:
                patch = result.get("settingsPatch")
                if (
                    isinstance(patch, dict)
                    and patch
                    and result.get("transientSettings") is not True
                ):
                    persisted = self._persist_plugin_settings_patch(patch)
                    result["state"] = _public_state(persisted)
                self._publish_plugin_host_event(
                    host,
                    result,
                    expected_binding=expected_binding,
                )

            host.command_and_publish(
                action,
                publish=publish,
                plugin_id=cmd.get("pluginId") or cmd.get("plugin"),
                reference=cmd.get("reference"),
                source=cmd.get("source"),
                path=cmd.get("path"),
                compatibility_id=cmd.get("compatibilityId"),
                tool=cmd.get("tool"),
                input=cmd.get("input"),
                query=cmd.get("query"),
                contribution=cmd.get("contribution"),
                capability=cmd.get("capability"),
                protocol=cmd.get("protocol"),
                host_protocol=cmd.get("hostProtocols"),
                platform=cmd.get("platform"),
                architecture=cmd.get("architecture"),
                version=cmd.get("version"),
                eligible_only=_normalize_bool(
                    cmd.get("eligibleOnly"), default=False
                ),
                allow_stale=_normalize_bool(
                    cmd.get("allowStale"), default=False
                ),
                allow_prerelease=_normalize_bool(
                    cmd.get("allowPrerelease"), default=False
                ),
                approve_permissions=_normalize_bool(
                    cmd.get("approvePermissions"), default=False
                ),
                approve_settings=_normalize_bool(
                    cmd.get("approveSettings"), default=False
                ),
                approval_token=cmd.get("approvalToken"),
                approve_install=_normalize_bool(
                    cmd.get("approveInstall"), default=False
                ),
                lease_scope=cmd.get("lease") or "task",
                session_id=cmd.get("session"),
                enabled=safe_mode_enabled,
                current_settings=defaults,
            )
        except PermissionError as exc:
            self.emit(
                {
                    "type": "plugin_result",
                    "ok": False,
                    "action": action,
                    "error": _safe_text(str(exc), limit=800),
                    "needsApproval": "--approve" in str(exc),
                    "candidateOnly": True,
                    "canClaimAGI": False,
                }
            )
        except (KeyError, ValueError, OSError, RuntimeError) as exc:
            self.emit(
                {
                    "type": "plugin_result",
                    "ok": False,
                    "action": action,
                    "error": _safe_text(
                        f"{type(exc).__name__}: {exc}", limit=800
                    ),
                    "candidateOnly": True,
                    "canClaimAGI": False,
                }
            )

    def _plugin_host(self, root: Path) -> Any:
        """Return the owned command host for one resolved workspace.

        ``PluginRegistry`` refresh is the authority-reconciliation boundary:
        a cached host must re-read state/manifests and retire stale sidecars
        before every later command, matching the fresh-host behavior this
        cache replaces.
        """
        from agent.plugin_host import PluginHost

        resolved = root.expanduser().resolve()
        key = str(resolved)
        host = self.plugin_hosts.get(key)
        if host is None:
            host_ref: dict[str, Any] = {}

            def on_event(payload: Mapping[str, Any]) -> None:
                self._publish_plugin_host_event(
                    host_ref["host"],
                    payload,
                )

            host = PluginHost(resolved, on_event=on_event)
            host_ref["host"] = host
            self.plugin_hosts[key] = host
            return host
        host._refresh_registry()
        return host

    def _plugin_lease_host_for_run(
        self,
        root: Path,
        *,
        session_id: str,
        run_id: str,
        expected_generation: int | None = None,
    ) -> Any | None:
        resolved = root.expanduser().resolve()
        key = str(resolved)
        with self.plugin_host_lock:
            host = self.plugin_hosts.get(key)
        if host is None:
            return None
        host._refresh_registry()
        snapshot = host.lease_snapshot()
        if not isinstance(snapshot, Mapping):
            return None
        if (
            expected_generation is not None
            and snapshot.get("generation") != expected_generation
        ):
            return None
        binding = self._plugin_lease_binding(host, snapshot)
        with self.plugin_lease_publication_lock:
            if not self._same_plugin_lease_binding(
                self.plugin_active_lease_binding,
                binding,
            ):
                return None
        host.begin_run(
            session_id=session_id,
            run_id=run_id,
            expected_generation=expected_generation,
        )
        with self.plugin_lease_publication_lock:
            still_globally_authorized = self._same_plugin_lease_binding(
                self.plugin_active_lease_binding,
                binding,
            )
        if not still_globally_authorized:
            # A different workspace lease won after begin_run bound this
            # task. Retire the exact just-bound generation without publishing
            # its now-stale restore patch; the caller will also strip its
            # transient settings before execution.
            if binding is not None:
                host.end_lease(
                    reason="bridge_lease_superseded",
                    expected_generation=binding[1],
                )
            return None
        return host

    def _bind_queued_plugin_lease_for_run(
        self,
        root: Path,
        *,
        session_id: str,
        run_id: str,
        cmd: Mapping[str, Any],
        snapshot: Mapping[str, Any],
    ) -> tuple[Any | None, dict[str, Any]]:
        sanitized = dict(cmd)
        raw_generation = snapshot.get("generation")
        expected_generation = (
            raw_generation
            if isinstance(raw_generation, int)
            and not isinstance(raw_generation, bool)
            else None
        )
        if expected_generation is None:
            return None, self._sanitize_queued_plugin_settings(
                sanitized,
                snapshot,
            )
        try:
            host = self._plugin_lease_host_for_run(
                root,
                session_id=session_id,
                run_id=run_id,
                expected_generation=expected_generation,
            )
        except Exception:  # noqa: BLE001 - queued authority fails closed
            host = None
        if host is not None:
            return host, sanitized
        raw_patch = snapshot.get("settingsPatch")
        if isinstance(raw_patch, Mapping):
            for key, value in raw_patch.items():
                normalized_key = str(key)
                if sanitized.get(normalized_key) == value:
                    sanitized.pop(normalized_key, None)
        return None, sanitized

    def _expire_unbound_plugin_task_leases(
        self,
        root: Path,
        *,
        session_id: str,
    ) -> list[dict[str, Any]]:
        results: list[dict[str, Any]] = []
        with self.plugin_host_lock:
            hosts = list(self.plugin_hosts.values())
        for host in hosts:
            try:
                result = host.end_unbound_task_if_context_changed(
                    session_id=session_id,
                    workspace=root,
                    publish=self._plugin_lease_end_publisher(host),
                )
            except PermissionError as exc:
                if not self._is_stale_plugin_lease_publication(exc):
                    raise
                continue
            if result is not None:
                results.append(result)
        return results

    @staticmethod
    def _sanitize_expired_plugin_settings(
        cmd: Mapping[str, Any],
        ended_leases: list[Mapping[str, Any]],
    ) -> dict[str, Any]:
        sanitized = dict(cmd)
        for result in ended_leases:
            ended = result.get("endedLease")
            if not isinstance(ended, Mapping):
                continue
            patch = ended.get("settingsPatch")
            if not isinstance(patch, Mapping):
                continue
            for key, value in patch.items():
                normalized_key = str(key)
                if sanitized.get(normalized_key) == value:
                    sanitized.pop(normalized_key, None)
        return sanitized

    def _plugin_lease_snapshot_for_queue(
        self,
        root: Path,
    ) -> dict[str, Any] | None:
        resolved = root.expanduser().resolve()
        with self.plugin_host_lock:
            host = self.plugin_hosts.get(str(resolved))
            if host is None:
                return None
            snapshot = host.lease_snapshot()
        if not isinstance(snapshot, dict):
            return None
        binding = self._plugin_lease_binding(host, snapshot)
        with self.plugin_lease_publication_lock:
            if not self._same_plugin_lease_binding(
                self.plugin_active_lease_binding,
                binding,
            ):
                return None
        return {
            **snapshot,
            "workspace": str(resolved),
        }

    def _sanitize_queued_plugin_settings(
        self,
        cmd: Mapping[str, Any],
        snapshot: Mapping[str, Any] | None,
    ) -> dict[str, Any]:
        sanitized = dict(cmd)
        if not isinstance(snapshot, Mapping):
            return sanitized
        raw_patch = snapshot.get("settingsPatch")
        if not isinstance(raw_patch, Mapping):
            return sanitized
        workspace = str(snapshot.get("workspace") or "")
        current: Mapping[str, Any] | None = None
        current_host: Any | None = None
        if workspace:
            with self.plugin_host_lock:
                host = self.plugin_hosts.get(workspace)
                if host is not None:
                    value = host.lease_snapshot()
                    if isinstance(value, Mapping):
                        current = value
                        current_host = host
        current_binding = (
            self._plugin_lease_binding(current_host, current)
            if current_host is not None
            else None
        )
        with self.plugin_lease_publication_lock:
            globally_authorized = self._same_plugin_lease_binding(
                self.plugin_active_lease_binding,
                current_binding,
            )
        still_authorized = (
            globally_authorized
            and current is not None
            and current.get("generation") == snapshot.get("generation")
            and current.get("scope") == snapshot.get("scope")
            and current.get("session") == snapshot.get("session")
            and current.get("settingsPatch") == raw_patch
        )
        if still_authorized:
            return sanitized
        for key in raw_patch:
            normalized_key = str(key)
            if sanitized.get(normalized_key) == raw_patch[key]:
                sanitized.pop(normalized_key, None)
        return sanitized

    def _end_plugin_task_lease(self, handle: Mapping[str, Any]) -> None:
        workspace = str(handle.get("pluginLeaseWorkspace") or "")
        run_id = str(handle.get("id") or "")
        if not workspace or not run_id:
            return
        with self.plugin_host_lock:
            host = self.plugin_hosts.get(workspace)
        if host is not None:
            host.end_task(
                run_id=run_id,
                publish=self._plugin_lease_end_publisher(host),
            )

    def _end_plugin_leases_for_session_change(self, session_id: str) -> None:
        with self.plugin_host_lock:
            hosts = list(self.plugin_hosts.values())
        for host in hosts:
            try:
                host.end_session_if_changed(
                    session_id=session_id,
                    publish=self._plugin_lease_end_publisher(host),
                )
            except PermissionError as exc:
                if not self._is_stale_plugin_lease_publication(exc):
                    raise

    def _tasks_payload(self, cmd: dict) -> dict[str, Any]:
        stores = self._load_receipts()
        run_id = _safe_text(cmd.get("runId"), limit=128) if cmd.get("runId") else None
        session = _normalize_session(cmd.get("session")) if cmd.get("session") else None
        # A caller naming a specific runId or session is asking to look
        # something up (task_log/task_action, "load session S") and rightly
        # expects to find that target's completed nodes too. A caller
        # supplying NEITHER filter is asking "what's happening right now" —
        # defaulting that unscoped call to full history was the other half of
        # the reported bug: a brand-new session listing tasks with no filters
        # got every run this machine ever recorded, not just current work.
        # retainCompleted stays an explicit override either way.
        retain = _normalize_bool(cmd.get("retainCompleted"), default=bool(run_id or session))
        nodes: list[dict[str, Any]] = []
        trees: list[dict[str, Any]] = []
        for store in stores:
            if run_id and store.run_id != run_id:
                continue
            store.replay()
            selected = [n for n in store.nodes.values() if (retain or n.state not in TERMINAL_STATES)
                        and (session is None or n.session == session)]
            nodes.extend(n.to_dict() for n in selected)
            trees.extend(store.tree(retain_completed=retain))
        # Echo the caller's correlation id so a client can distinguish a snapshot
        # it explicitly requested from a background/reconnect restore.
        request_id = cmd.get("requestId", cmd.get("requestID"))
        payload: dict[str, Any] = {"type": "workflows", "ok": True, "runId": run_id, "session": session,
                                   "nodes": nodes, "trees": trees,
                                   "capabilities": {"cancel": True, "retry": False, "logs": True},
                                   "canClaimAGI": False}
        if request_id is not None:
            payload["requestId"] = _safe_text(request_id, limit=128)
        return payload

    def _handle_tasks(self, cmd: dict) -> None:
        self.emit(self._tasks_payload(cmd))

    @staticmethod
    def _safe_diagnostics(value: Any) -> Any:
        if isinstance(value, dict):
            return {
                _safe_text(key, limit=80): CodeBridge._safe_diagnostics(child)
                for key, child in list(value.items())[:64]
                if str(key).lower() not in {"prompt", "rawprompt", "token", "secret", "password"}
            }
        if isinstance(value, list):
            return [CodeBridge._safe_diagnostics(child) for child in value[:64]]
        if isinstance(value, str):
            return _safe_text(value, limit=400)
        if isinstance(value, (bool, int, float)) or value is None:
            return value
        return _safe_text(value, limit=200)

    def _mcp_health_payload(self, *, status: str = "not_probed",
                            ok: bool = True, error: str | None = None) -> dict[str, Any]:
        endpoint = str(os.environ.get("SOPHIA_MCP_URL") or "").strip()
        try:
            tools_available = importlib.util.find_spec("sophia_mcp.tools_impl") is not None
        except (ImportError, AttributeError, ValueError):
            tools_available = False
        try:
            # MCP SDK >= 2.0 renamed mcp.server.fastmcp.FastMCP to
            # mcp.server.mcpserver.MCPServer; check both module paths so this
            # reports honestly across SDK generations instead of always False
            # once fastmcp is gone (see requirements-mcp.txt / PR fix/mcp-2-migration).
            transport_available = (
                importlib.util.find_spec("mcp.server.mcpserver") is not None
                or importlib.util.find_spec("mcp.server.fastmcp") is not None
            )
        except (ImportError, AttributeError, ValueError):
            transport_available = False
        payload: dict[str, Any] = {
            "type": "mcp_health",
            "ok": ok,
            "status": status,
            "mode": "remote" if endpoint else "in_process",
            "configured": bool(endpoint) or tools_available,
            "endpointConfigured": bool(endpoint),
            "toolsAvailable": tools_available,
            "transportAvailable": transport_available,
            "timeouts": dict(self.mcp_timeouts),
            "startupProbe": False,
            "canClaimAGI": False,
        }
        if error:
            payload["error"] = _safe_text(error, limit=500)
            payload["errorPayload"] = {
                **_safe_error_payload(message=error, error_type="MCPHealthFailed"),
                "category": "availability",
                "retryable": True,
                "command": "mcp_health",
            }
        return payload

    def _handle_diagnostic_snapshot(self, cmd: dict) -> None:
        workflows = self._tasks_payload(cmd)
        with self.active_lock:
            active = self.active
            active_snapshot = None
            diagnostics: list[Any] = []
            if active is not None:
                active_snapshot = {
                    "runId": active.get("id"),
                    "session": active.get("session"),
                    "requestId": active.get("requestId"),
                    "callId": active.get("callId"),
                    "attempt": active.get("attempt", 1),
                    "terminal": bool(active.get("terminal")),
                    "cancelRequested": bool(active.get("cancel") and active["cancel"].is_set()),
                    "queuedSteers": len(active.get("steers") or []),
                }
                diagnostics = list(active.get("diagnostics") or [])
        with self.queue_next_lock:
            queued = [
                {
                    "queueId": entry.get("queueId"),
                    "requestId": entry.get("requestId"),
                    "session": entry.get("session"),
                    "attempt": entry.get("attempt", 1),
                    "position": index + 1,
                }
                for index, entry in enumerate(self.queue_next)
            ]
        self.emit({
            "type": "diagnostic_snapshot",
            "ok": True,
            "active": active_snapshot,
            "queueNext": queued,
            "workflows": {
                key: workflows.get(key)
                for key in ("runId", "session", "nodes", "trees", "capabilities")
            },
            "diagnostics": self._safe_diagnostics(diagnostics),
            "mcp": self._mcp_health_payload(),
            "protocolInfo": {
                "version": PROTOCOL_VERSION,
                "minimum": PROTOCOL_MIN_VERSION,
                "bridgeInstanceId": self.instance_id,
                "lastSequence": self.protocol_sequence,
            },
            "canClaimAGI": False,
        })

    def _handle_mcp_timeouts(self, cmd: dict) -> None:
        if "connectMs" in cmd:
            self.mcp_timeouts["connectMs"] = _normalize_timeout_ms(
                cmd.get("connectMs"),
                self.mcp_timeouts["connectMs"],
            )
        if "requestMs" in cmd:
            self.mcp_timeouts["requestMs"] = _normalize_timeout_ms(
                cmd.get("requestMs"),
                self.mcp_timeouts["requestMs"],
            )
        self.emit({
            "type": "mcp_timeouts",
            "ok": True,
            "timeouts": dict(self.mcp_timeouts),
            "scope": "bridge_process",
            "canClaimAGI": False,
        })

    def _handle_mcp_health(self, cmd: dict) -> None:
        if not _normalize_bool(cmd.get("probe"), default=False):
            self.emit(self._mcp_health_payload())
            return
        endpoint = str(os.environ.get("SOPHIA_MCP_URL") or "").strip()
        if not endpoint:
            self.emit(self._mcp_health_payload(
                status="in_process",
                ok=importlib.util.find_spec("sophia_mcp.tools_impl") is not None,
            ))
            return
        request_id = cmd.get("requestId", cmd.get("requestID"))
        call_id = cmd.get("callId")
        attempt = cmd.get("attempt", 1)
        timeout_ms = _normalize_timeout_ms(
            cmd.get("timeoutMs"),
            self.mcp_timeouts["requestMs"],
        )
        self.emit({
            **self._mcp_health_payload(status="probing"),
            "requestId": request_id,
            "callId": call_id,
            "attempt": attempt,
        })

        def probe() -> None:
            started = time.monotonic()
            try:
                request = urllib.request.Request(endpoint, method="GET")
                with urllib.request.urlopen(request, timeout=timeout_ms / 1000.0) as response:
                    status_code = int(getattr(response, "status", 200))
                ok = 200 <= status_code < 500
                payload = self._mcp_health_payload(
                    status="reachable" if ok else "unhealthy",
                    ok=ok,
                    error=None if ok else f"MCP endpoint returned HTTP {status_code}",
                )
                payload["statusCode"] = status_code
            except (OSError, urllib.error.URLError, ValueError) as exc:
                payload = self._mcp_health_payload(
                    status="unreachable",
                    ok=False,
                    error=f"{type(exc).__name__}: {exc}",
                )
            payload.update({
                "requestId": request_id,
                "callId": call_id,
                "attempt": attempt,
                "latencyMs": max(0, round((time.monotonic() - started) * 1000)),
            })
            self.emit(payload)

        threading.Thread(
            target=probe,
            name="code-bridge-mcp-health",
            daemon=True,
        ).start()

    def _handle_provider_health(self, cmd: dict) -> None:
        """Emit no-spend health for explicitly requested provider specs.

        Remote metadata is off unless the caller opts in. The default doctor
        path therefore checks credentials/binaries and loopback ``GET /models``
        only; it never sends a generation request or spends provider credit.
        """
        from agent.provider_health import probe_providers

        raw_specs = cmd.get("providers", cmd.get("models"))
        if isinstance(raw_specs, str):
            specs = [part.strip() for part in raw_specs.split(",") if part.strip()]
        elif isinstance(raw_specs, list):
            specs = [str(part).strip() for part in raw_specs if str(part).strip()]
        else:
            state, _ = _load_state()
            defaults = _normalize_defaults(
                state.get("defaults") if isinstance(state.get("defaults"), dict) else {}
            )
            specs = [str(defaults["model"])]
        specs = specs[:16]
        request_id = cmd.get("requestId", cmd.get("requestID"))
        self.emit({
            "type": "provider_health",
            "ok": True,
            "status": "probing",
            "providers": specs,
            "requestId": request_id,
            "paidProbeMade": False,
            "canClaimAGI": False,
        })

        def probe() -> None:
            try:
                # Health probes already understand the public provider aliases.
                # Avoid importing the full interactive CLI just to resolve
                # those aliases: on a cold process that import can take several
                # seconds and make the asynchronous health node look stuck.
                # Custom profiles still require the profile resolver, while
                # ``grok-cli`` is the sole picker-only spelling not accepted by
                # ``agent.model.resolve_config``.
                resolved_specs = [
                    (
                        _model_spec(spec)
                        if spec.startswith("profile:")
                        else "grok"
                        if spec == "grok-cli"
                        else spec
                    )
                    for spec in specs
                ]
                reports = probe_providers(
                    resolved_specs,
                    allow_remote_metadata=_normalize_bool(
                        cmd.get("allowRemoteMetadata"), default=False
                    ),
                    include_models=_normalize_bool(cmd.get("includeModels"), default=True),
                    timeout=max(
                        0.1,
                        min(
                            10.0,
                            float(
                                cmd.get(
                                    "timeoutSec",
                                    PROVIDER_HEALTH_TIMEOUT_SEC,
                                )
                            ),
                        ),
                    ),
                )
                self.emit({
                    "type": "provider_health",
                    "ok": all(report.ok for report in reports),
                    "status": "complete",
                    "providers": [report.to_dict() for report in reports],
                    "requestId": request_id,
                    "paidProbeMade": False,
                    "canClaimAGI": False,
                })
            except Exception as exc:  # noqa: BLE001 - health must not kill the TUI
                self.emit({
                    "type": "provider_health",
                    "ok": False,
                    "status": "error",
                    "providers": [],
                    "error": _safe_text(f"{type(exc).__name__}: {exc}", limit=500),
                    "requestId": request_id,
                    "paidProbeMade": False,
                    "canClaimAGI": False,
                })

        threading.Thread(
            target=probe,
            name="code-bridge-provider-health",
            daemon=True,
        ).start()

    def _handle_provider_login(self, cmd: dict) -> None:
        """Launch official CLI browser login (grok/codex). Never emit secrets."""
        from agent.provider_auth import list_login_providers, run_provider_login

        action = str(cmd.get("action") or cmd.get("provider") or "status").strip().casefold()
        request_id = cmd.get("requestId", cmd.get("requestID"))
        if action in {"", "status", "list"}:
            self.emit({
                "type": "provider_login",
                "ok": True,
                "status": "status",
                "providers": list_login_providers(),
                "requestId": request_id,
                "canClaimAGI": False,
            })
            return
        self.emit({
            "type": "provider_login",
            "ok": True,
            "status": "starting",
            "provider": action,
            "detail": "opening the official provider sign-in page in your browser",
            "requestId": request_id,
            "canClaimAGI": False,
        })

        def login() -> None:
            try:
                result = run_provider_login(action)
                self.emit({
                    "type": "provider_login",
                    "status": "complete" if result.get("ready") else "error",
                    "requestId": request_id,
                    **result,
                })
            except Exception as exc:  # noqa: BLE001 - login must not kill the TUI
                self.emit({
                    "type": "provider_login",
                    "ok": False,
                    "status": "error",
                    "provider": action,
                    "ready": False,
                    "detail": f"{type(exc).__name__}: login did not finish",
                    "requestId": request_id,
                    "canClaimAGI": False,
                })

        threading.Thread(
            target=login,
            name="code-bridge-provider-login",
            daemon=True,
        ).start()

    def _handle_model_connection(self, cmd: dict) -> None:
        """Manage and verify one secret-reference-only custom model endpoint."""
        from agent import provider_profiles

        action = str(cmd.get("action") or "").strip().casefold()
        request_id = _safe_text(
            cmd.get("requestId", cmd.get("requestID")) or f"model-connection-{uuid.uuid4().hex[:8]}",
            limit=128,
        )
        if action not in {
            "list", "save", "remove", "store_credential", "check",
            "format_probe", "repair_plan",
        }:
            raise ValueError("model_connection action is not supported")

        def emit_result(*, ok: bool, **payload: Any) -> None:
            self.emit({
                "type": "model_connection",
                "action": action,
                "requestId": request_id,
                "ok": ok,
                "canClaimAGI": False,
                **payload,
            })

        if action == "list":
            records = [
                _model_connection_record(profile)
                for profile in provider_profiles.list_profiles()
            ]
            emit_result(ok=True, connections=records)
            return

        if action == "remove":
            connection_id = str(cmd.get("connectionId") or "").strip()
            if not connection_id:
                raise ValueError("model_connection remove requires connectionId")
            existing = provider_profiles.get_profile(connection_id)
            removed = provider_profiles.remove_profile(connection_id)
            if existing is not None and existing.credential.kind == "keyring":
                os.environ.pop(
                    provider_profiles.credential_environment_name(existing),
                    None,
                )
            with self.model_connection_lock:
                self.model_connection_reports.pop(
                    provider_profiles.normalize_profile_name(connection_id),
                    None,
                )
            emit_result(
                ok=removed,
                connectionId=provider_profiles.normalize_profile_name(connection_id),
                detail="Endpoint removed." if removed else "Endpoint was not found.",
            )
            return

        if action == "store_credential":
            credential_ref = provider_profiles.CredentialReference.parse(
                cmd.get("credentialRef")
            )
            credential_value = cmd.get("credentialValue")
            try:
                provider_profiles.store_credential_value(
                    credential_ref,
                    credential_value if isinstance(credential_value, str) else "",
                )
            finally:
                # Drop the only raw-value reference held by this stack frame as
                # early as Python allows. Nothing is echoed into the event.
                credential_value = None
            emit_result(
                ok=True,
                detail="Credential stored in the OS keyring. No value was persisted in Sophia config.",
            )
            return

        profile = _model_connection_profile(cmd.get("connection"))
        connection_id = profile.name
        if action == "save":
            saved = provider_profiles.upsert_profile(profile)
            with self.model_connection_lock:
                self.model_connection_reports.pop(saved.name, None)
            emit_result(
                ok=True,
                connectionId=saved.name,
                connection=_model_connection_record(saved),
                detail="Endpoint profile saved. Credential values were not persisted.",
            )
            return

        if action in {"format_probe", "repair_plan"} and cmd.get("consent") is not True:
            emit_result(
                ok=False,
                connectionId=connection_id,
                detail=f"{action.replace('_', ' ')} requires explicit consent.",
            )
            return

        def probe() -> None:
            try:
                if action == "repair_plan":
                    with self.model_connection_lock:
                        report = dict(
                            self.model_connection_reports.get(connection_id)
                            or {
                                "ok": False,
                                "checks": [],
                                "candidateOnly": True,
                                "canClaimAGI": False,
                            }
                        )
                else:
                    report = self._run_model_connection_probe(profile, action=action)
                    with self.model_connection_lock:
                        self.model_connection_reports[connection_id] = dict(report)
                checks = report.get("checks") if isinstance(report, dict) else None
                failures = [
                    check for check in (checks or [])
                    if isinstance(check, dict) and check.get("status") == "fail"
                ]
                ok = bool(report.get("ok")) and not failures
                detail = self._model_connection_report_detail(report)
                if action == "repair_plan":
                    suggestion = self._model_connection_repair_suggestion(
                        profile,
                        report=report,
                    )
                    emit_result(
                        ok=bool(suggestion),
                        connectionId=connection_id,
                        detail=detail,
                        suggestion=suggestion,
                    )
                else:
                    emit_result(
                        ok=ok,
                        connectionId=connection_id,
                        detail=detail,
                    )
            except Exception as exc:  # noqa: BLE001 - diagnostics stay typed and redacted
                emit_result(
                    ok=False,
                    connectionId=connection_id,
                    detail=_safe_text(f"{type(exc).__name__}: {exc}", limit=500),
                )

        threading.Thread(
            target=probe,
            name=f"code-bridge-model-connection-{action}",
            daemon=True,
        ).start()

    @staticmethod
    def _model_connection_report_detail(report: dict[str, Any]) -> str:
        checks = report.get("checks") if isinstance(report, dict) else []
        parts: list[str] = []
        for check in checks or []:
            if not isinstance(check, dict):
                continue
            name = str(check.get("name") or "check")
            status = str(check.get("status") or "unknown")
            detail = str(
                check.get("message")
                or check.get("diagnostic_code")
                or status
            )
            parts.append(f"{name}: {status} ({detail})")
        return _safe_text(
            "; ".join(parts) or "Endpoint probe returned no check details.",
            limit=700,
        )

    @staticmethod
    def _run_model_connection_probe(profile: Any, *, action: str) -> dict[str, Any]:
        """Run the public smoke helper under the profile's exact authority."""
        from agent.custom_endpoint_smoke import run_smoke

        if profile.protocol == "mlx-native":
            # Native MLX is not an HTTP endpoint. Resolve the configured model
            # without loading/generating from it during a no-spend check.
            from agent.provider_profiles import resolve_model_spec

            spec = resolve_model_spec(profile)
            return {
                "ok": True,
                "checks": [{
                    "name": "local_model_spec",
                    "status": "pass",
                    "message": f"resolved {spec}",
                }],
                "candidateOnly": True,
                "canClaimAGI": False,
            }

        protocol = profile.protocol
        if protocol == "ollama-native":
            # The public smoke's common compatibility contract is OpenAI Chat.
            # Native Ollama profiles are exercised through its OpenAI surface.
            protocol = "openai-chat"
        if protocol not in {"openai-chat", "openai-responses", "anthropic-messages"}:
            raise ValueError(f"unsupported endpoint probe protocol {protocol!r}")

        credential_env: str | None = None
        temporary_env: str | None = None
        if profile.credential.kind == "env":
            credential_env = profile.credential.name
        elif profile.credential.kind == "keyring":
            from agent.provider_profiles import resolve_credential_value

            temporary_env = f"SOPHIA_KEYRING_PROBE_{uuid.uuid4().hex.upper()}"
            os.environ[temporary_env] = resolve_credential_value(profile.credential)
            credential_env = temporary_env
        probes = ("discovery",) if action == "check" else ("text", "tools", "response_format", "stream")
        try:
            return run_smoke(
                base_url=profile.endpoint_url,
                protocol=protocol,
                model=profile.model,
                credential_env=credential_env,
                probes=probes,
                timeout_sec=min(float(profile.timeout_sec or 5), 30.0),
                confirm_public_remote=profile.endpoint_scope == "remote",
                confirm_private_network=profile.endpoint_scope == "private",
            )
        finally:
            if temporary_env:
                os.environ.pop(temporary_env, None)

    @staticmethod
    def _model_connection_repair_suggestion(
        profile: Any,
        *,
        report: dict[str, Any],
    ) -> dict[str, Any]:
        """Ask the selected endpoint for a bounded, allow-listed preview only."""
        from agent import model as model_module
        from agent.agent_loop import _iter_json_objects
        from agent.provider_profiles import resolve_model_spec

        checks = report.get("checks") if isinstance(report, dict) else []
        codes = {
            str(check.get("diagnostic_code") or "")
            for check in checks or []
            if isinstance(check, dict)
        }
        changes: dict[str, str] = {}
        summary = "No safe deterministic configuration change was identified."
        base = str(profile.endpoint_url or "")
        if (
            profile.protocol == "openai-chat"
            and base
            and not urlsplit(base).path.rstrip("/").endswith("/v1")
            and codes.intersection({"http_error", "model_not_discovered"})
        ):
            changes["baseUrl"] = base.rstrip("/") + "/v1"
            summary = "Preview adding the conventional OpenAI-compatible /v1 API prefix."
        elif "model_not_discovered" in codes:
            summary = "The endpoint was reachable, but the selected model ID was not advertised. Review the model field."
        elif "transport_error" in codes:
            summary = "The endpoint could not be reached. Review its host, port, TLS, and server process."
        deterministic = {"summary": summary, "changes": changes}

        # This is explicitly consent-gated by _handle_model_connection. Send no
        # source, conversation, API key, headers, or arbitrary error body.
        safe_input = {
            "protocol": profile.protocol,
            "baseUrl": profile.endpoint_url,
            "model": profile.model,
            "diagnosticCodes": sorted(code for code in codes if code),
        }
        try:
            spec = resolve_model_spec(profile)
            client = model_module.default_client(spec)
            response = client.generate(
                (
                    "You diagnose a model endpoint profile. Return one JSON object only. "
                    "Allowed change keys are baseUrl, model, protocol. Never request or "
                    "emit an API key, credential value, shell command, source-code edit, "
                    "or unrelated endpoint."
                ),
                (
                    f"Profile diagnostics: {json.dumps(safe_input, sort_keys=True)}\n"
                    'Return {"summary":"...", "changes":{}}. Keep changes empty unless '
                    "the diagnostic evidence supports a conservative correction."
                ),
                response_format={
                    "type": "json_schema",
                    "json_schema": {
                        "name": "endpoint_repair_preview",
                        "strict": True,
                        "schema": {
                            "type": "object",
                            "additionalProperties": False,
                            "required": ["summary", "changes"],
                            "properties": {
                                "summary": {"type": "string"},
                                "changes": {
                                    "type": "object",
                                    "additionalProperties": False,
                                    "properties": {
                                        "baseUrl": {"type": "string"},
                                        "model": {"type": "string"},
                                        "protocol": {
                                            "type": "string",
                                            "enum": [
                                                "openai-compatible",
                                                "openai-responses",
                                                "anthropic-messages",
                                            ],
                                        },
                                    },
                                },
                            },
                        },
                    },
                },
            )
            if not response.ok:
                return deterministic
            parsed: dict[str, Any] | None = None
            for candidate in _iter_json_objects(response.text):
                try:
                    value = json.loads(candidate)
                except json.JSONDecodeError:
                    continue
                if isinstance(value, dict):
                    parsed = value
                    break
            if parsed is None:
                return deterministic
            allowed: dict[str, str] = {}
            raw_changes = parsed.get("changes")
            if isinstance(raw_changes, dict):
                if isinstance(raw_changes.get("model"), str):
                    allowed["model"] = raw_changes["model"].strip()[:512]
                if raw_changes.get("protocol") in {
                    "openai-compatible",
                    "openai-responses",
                    "anthropic-messages",
                }:
                    allowed["protocol"] = raw_changes["protocol"]
                if isinstance(raw_changes.get("baseUrl"), str):
                    proposed_url = raw_changes["baseUrl"].strip()
                    # Re-validate through the same authority policy. A model may
                    # refine a path, never redirect credentials to another host.
                    proposed = _model_connection_profile({
                        "templateId": dict(profile.metadata).get(
                            "template_id", "openai-compatible"
                        ),
                        "displayName": profile.name,
                        "protocol": allowed.get(
                            "protocol",
                            "anthropic-messages"
                            if profile.protocol == "anthropic-messages"
                            else "openai-responses"
                            if profile.protocol == "openai-responses"
                            else "openai-compatible",
                        ),
                        "baseUrl": proposed_url,
                        "model": allowed.get("model", profile.model),
                        "credentialRef": profile.credential.to_uri().replace(
                            "keyring:", "keychain:", 1
                        ),
                        "allowPrivateNetwork": profile.endpoint_scope == "private",
                    })
                    old = urlsplit(str(profile.endpoint_url or ""))
                    new = urlsplit(str(proposed.endpoint_url or ""))
                    if (
                        old.scheme,
                        old.hostname,
                        old.port,
                    ) == (
                        new.scheme,
                        new.hostname,
                        new.port,
                    ):
                        allowed["baseUrl"] = str(proposed.endpoint_url)
            model_summary = _safe_text(parsed.get("summary"), limit=300).strip()
            return {
                "summary": model_summary or deterministic["summary"],
                "changes": allowed or deterministic["changes"],
            }
        except Exception:
            return deterministic

    # -- user hooks (PreToolUse / PostToolUse / Stop) ----------------------- #
    def _load_run_hook_config(self, root: Path) -> Any:
        """Load ``.sophia/hooks.toml`` scoped to the run's own workspace.

        ``load_user_hooks()``'s own workspace layer reads
        ``agent.runtime_paths.workspace_dir()``, which resolves from the
        bridge PROCESS's cwd — not from ``root`` (the per-run folder the
        operator actually picked, passed explicitly on every ``run`` command).
        Those two are routinely different for a long-lived bridge, so a
        project-local hooks.toml would silently never be found. Checking
        ``root`` first (falling back to the normal home/env precedence when
        the run's own workspace has no file) gets the common case — an
        operator's hooks.toml living in the project they are editing — right
        without reimplementing ``load_user_hooks``'s full layering.
        """
        from agent import hooks as user_hooks
        try:
            workspace_hooks = Path(root) / ".sophia" / "hooks.toml"
            if workspace_hooks.is_file():
                return user_hooks.load_user_hooks(str(workspace_hooks))
            return user_hooks.load_user_hooks()
        except Exception:  # noqa: BLE001 - a broken hook config must disable hooks, not the run
            return user_hooks.UserHookConfig()

    def _record_hook_dispatch(self, run_id: str, dispatch: Any) -> dict[str, Any]:
        record = {
            "runId": run_id,
            "event": str(getattr(dispatch.event, "value", dispatch.event)),
            "tool": dispatch.tool_id,
            "allowed": bool(dispatch.allowed),
            "blockedBy": dispatch.blocked_by,
            "reason": dispatch.reason,
            "outcomes": [
                {
                    "command": " ".join(outcome.rule.command),
                    "matcher": outcome.rule.matcher,
                    "ok": outcome.ok,
                    "returncode": outcome.returncode,
                    "timedOut": outcome.timed_out,
                    "reason": outcome.reason,
                }
                for outcome in dispatch.outcomes
            ],
            "ts": _now_iso(),
        }
        with self.hook_log_lock:
            self.hook_dispatch_log.append(record)
            overflow = len(self.hook_dispatch_log) - HOOK_DISPATCH_LOG_MAX
            if overflow > 0:
                del self.hook_dispatch_log[:overflow]
        return record

    def _record_and_emit_hook_dispatch(self, run_id: str, dispatch: Any) -> dict[str, Any]:
        """Record an already-computed dispatch and make it visible when it matters.

        Always records to the bounded ``/hooks``-status history. Only EMITS a
        live ``hook_dispatch`` bridge event when something actually happened
        (a rule matched, or one blocked) — a disabled config or a no-match
        dispatch fires on every single tool call, and forwarding that as a
        visible event would flood the transcript with "nothing happened" noise
        for every operator who has never written a hooks.toml. Shared by the
        Stop dispatch below and by the ToolContext ``hook_sink`` callback that
        agent_tools.execute_tool() invokes for every Pre/PostToolUse decision.
        """
        record = self._record_hook_dispatch(run_id, dispatch)
        if dispatch.outcomes or not dispatch.allowed:
            self.bus.bridge_event(run_id, {"type": "hook_dispatch", **record})
        return record

    def _dispatch_hook(self, run_id: str, hook_config: Any, event: Any,
                       tool_id: str | None = None, *, payload: dict[str, Any] | None = None) -> Any:
        """Run every hook matching ``(event, tool_id)`` and make the outcome visible.

        The one remaining direct caller is the Stop dispatch at run end — Pre
        and PostToolUse now dispatch from inside agent_tools.execute_tool()
        itself (see the ``hook_sink``/``hook_config`` wiring on the run's
        ToolContext) so enforcement holds in every permission mode, not only
        for calls that reach this bridge's tool-execution path.
        """
        from agent import hooks as user_hooks
        try:
            dispatch = user_hooks.dispatch_user_hooks(hook_config, event, tool_id, payload=payload)
        except Exception as exc:  # noqa: BLE001 - a broken dispatcher must never crash a live run
            # Stop cannot retroactively fail a finished answer, so this must
            # not raise. Record allowed=False so /hooks status does not look
            # like the hook ran cleanly.
            dispatch = user_hooks.UserHookDispatch(
                event=event, tool_id=tool_id, allowed=False,
                reason=f"hook dispatch error: {type(exc).__name__}: {exc}",
            )
        self._record_and_emit_hook_dispatch(run_id, dispatch)
        return dispatch

    def _handle_shell(self, cmd: dict) -> None:
        """Run one operator-typed shell command through execute_tool('bash').

        This is the TUI ``!cmd`` / ``/shell`` path. It does not start a model
        run. Permission, PreToolUse, and destructive confirmation stay in the
        kernel; the TUI only sends the command and renders the result.
        """
        from agent.agent_tools import ToolContext, execute_tool

        command = str(cmd.get("command") or "").strip()
        if not command:
            self.error(
                "shell command is required",
                error_type="ShellCommandRequired",
                cmd="shell",
            )
            return
        workspace = _normalize_workspace_root(cmd.get("cwd"))
        state, _warning = _load_state()
        defaults = _normalize_defaults(
            state.get("defaults") if isinstance(state.get("defaults"), dict) else {}
        )
        try:
            permission = _normalize_permission(
                cmd.get("permission")
                if cmd.get("permission") is not None
                else defaults.get("permission")
            )
        except ValueError as exc:
            self.error(str(exc), error_type="CommandValueError", cmd="shell")
            return
        request_id = _safe_text(
            cmd.get("requestId") or cmd.get("requestID") or "",
            limit=128,
        )
        run_id = f"shell-{uuid.uuid4().hex[:10]}"
        cancel = threading.Event()
        started = {
            "type": "shell_start",
            "ok": True,
            "command": command,
            "cwd": str(workspace),
            "permission": permission,
            "runId": run_id,
            "requestId": request_id,
            "candidateOnly": True,
            "canClaimAGI": False,
        }
        self.emit(started)

        def execute() -> None:
            try:
                approver = (
                    _GuiApprover(self, run_id, cancel)
                    if permission == "approve"
                    else None
                )
                ctx = ToolContext(
                    root=workspace,
                    permission=permission,
                    approver=approver,
                    cancel_check=cancel.is_set,
                )
                result = execute_tool("bash", {"command": command}, ctx)
                self.emit({
                    "type": "shell_result",
                    "ok": bool(result.ok),
                    "command": command,
                    "output": _safe_text(result.output or "", limit=8000),
                    "error": _safe_text(result.error or "", limit=800),
                    "errorType": result.error_type or "",
                    "exitCode": result.exit_code,
                    "cwd": str(workspace),
                    "permission": permission,
                    "runId": run_id,
                    "requestId": request_id,
                    "candidateOnly": True,
                    "canClaimAGI": False,
                })
            except Exception as exc:  # noqa: BLE001 - UI must always get a result
                self.emit({
                    "type": "shell_result",
                    "ok": False,
                    "command": command,
                    "output": "",
                    "error": _safe_text(f"{type(exc).__name__}: {exc}", limit=800),
                    "errorType": type(exc).__name__,
                    "cwd": str(workspace),
                    "permission": permission,
                    "runId": run_id,
                    "requestId": request_id,
                    "candidateOnly": True,
                    "canClaimAGI": False,
                })

        if self.sync:
            execute()
        else:
            threading.Thread(
                target=execute,
                name="code-bridge-shell",
                daemon=True,
            ).start()

    def _handle_hooks(self, cmd: dict) -> None:
        """``/hooks``-status: the real loaded config plus recent dispatch outcomes.

        Replaces a client-side echo of the slash catalog's own description
        with what actually loaded and what it actually did — the two things an
        operator debugging "did my hook run" needs and the old stub had no way
        to answer.
        """
        root = _normalize_workspace_root(cmd.get("cwd"))
        config = self._load_run_hook_config(root)
        with self.hook_log_lock:
            recent = list(self.hook_dispatch_log[-20:])
        self.emit({
            "type": "hooks",
            "ok": True,
            "config": {
                "enabled": bool(config.enabled),
                "source": config.source,
                "error": config.error,
                "rules": [
                    {"event": str(getattr(rule.event, "value", rule.event)),
                     "matcher": rule.matcher, "command": list(rule.command),
                     "timeoutSec": rule.timeout_sec}
                    for rule in config.rules
                ],
            },
            # execute_tool() (agent/agent_tools.py) dispatches PreToolUse before
            # any tool runs — read-only, auto, or manual-approval alike — for
            # every ToolContext this bridge builds, including team lanes.
            # Reported explicitly so an operator can see the real scope rather
            # than assume it from the config alone.
            "preToolUseScope": "every tool call in every permission mode (readonly/approve/auto)",
            "recent": recent,
            "canClaimAGI": False,
        })

    # -- file checkpoints (list / undo / restore) --------------------------- #
    def _lookup_checkpoint_ctx(self, cmd: dict) -> tuple[Any | None, str]:
        session_raw = cmd.get("session")
        session = _normalize_session(session_raw) if session_raw is not None else ""
        with self.ctx_registry_lock:
            if session and session in self.last_ctx_by_session:
                return self.last_ctx_by_session[session], session
            return self.last_ctx, session

    def _handle_checkpoints(self, cmd: dict) -> None:
        from agent.agent_tools import list_checkpoints

        ctx, session = self._lookup_checkpoint_ctx(cmd)
        if ctx is None:
            self.emit({"type": "checkpoints", "ok": True, "session": session,
                       "items": [], "canClaimAGI": False})
            return
        try:
            items = list_checkpoints(ctx)
        except Exception as exc:  # noqa: BLE001 - a status read must not crash the bridge
            self.error(f"{type(exc).__name__}: {exc}", error_type="CheckpointListFailed", cmd="checkpoints")
            return
        self.emit({"type": "checkpoints", "ok": True, "session": session,
                   "items": items, "canClaimAGI": False})

    def _handle_checkpoint_mutation(self, cmd: dict, *, action: str) -> None:
        from agent.agent_tools import restore_checkpoint, undo_last_checkpoint

        with self.active_lock:
            active = self.active
        if active is not None:
            self.error("cannot restore a checkpoint while a run is active — cancel or wait",
                       error_type="RunBusy", cmd=f"checkpoint_{action}")
            return
        ctx, session = self._lookup_checkpoint_ctx(cmd)
        if ctx is None:
            self.error("no checkpoints recorded for this session",
                       error_type="NoCheckpoints", cmd=f"checkpoint_{action}")
            return
        if action == "undo":
            result = undo_last_checkpoint(ctx)
        else:
            checkpoint_id = str(cmd.get("id") or "").strip()
            if not checkpoint_id:
                self.error("checkpoint id is required", error_type="CheckpointIdRequired",
                           cmd="checkpoint_restore")
                return
            result = restore_checkpoint(ctx, checkpoint_id)
        self.emit({
            "type": "checkpoint_result",
            "ok": result.ok,
            "action": action,
            "session": session,
            # `output`/`error` both already name the exact path + checkpoint id
            # (see agent_tools._apply_checkpoint_restore) — surfaced as one
            # `detail` field so the transcript can render a single row either way.
            "detail": result.output if result.ok else result.error,
            "errorType": result.error_type or None,
            "canClaimAGI": False,
        })

    def _handle_checkpoint_undo(self, cmd: dict) -> None:
        self._handle_checkpoint_mutation(cmd, action="undo")

    def _handle_checkpoint_restore(self, cmd: dict) -> None:
        self._handle_checkpoint_mutation(cmd, action="restore")

    # -- local-engine operations --------------------------------------------- #
    def _handle_local_engine_report(self, cmd: dict) -> None:
        """Machine-wide local-runtime report (what's installed, what's running).

        Backed by ``runtime_config.local_runtime_report`` — the same discovery
        `config_payload()` already runs for ``localEngines``/``runtimeRecommendation``,
        exposed as its own on-demand command for a dedicated `/config recommend`
        style view that does not want to pay for (or wait on) the full config
        payload's model list / skills / tools catalogue.
        """
        request_id = cmd.get("requestId", cmd.get("requestID"))

        def probe() -> None:
            from agent import runtime_config
            try:
                report = runtime_config.local_runtime_report()
            except Exception as exc:  # noqa: BLE001 - a status screen must not crash the bridge
                report = {"error": f"{type(exc).__name__}: {exc}"}
            self.emit({
                "type": "local_engine_report", "ok": "error" not in report,
                "requestId": request_id, "canClaimAGI": False, **report,
            })

        threading.Thread(target=probe, name="code-bridge-local-engine-report", daemon=True).start()

    def _handle_adapter_status(self, cmd: dict) -> None:
        from agent import runtime_config
        try:
            status = runtime_config.adapter_status()
        except Exception as exc:  # noqa: BLE001 - a status read must not crash the bridge
            self.error(f"{type(exc).__name__}: {exc}", error_type="AdapterStatusFailed", cmd="adapter_status")
            return
        self.emit({"type": "adapter_status", "ok": True, "canClaimAGI": False, **status})

    def _handle_model_preflight(self, cmd: dict) -> None:
        """On-demand readiness check for a model spec (no run required).

        The same check ``_run_guarded`` runs automatically before a run — see
        the ``model_preflight`` bridge event emitted there — exposed as a
        direct request/response for a `/model` picker to show readiness before
        the operator commits to switching.
        """
        state, _ = _load_state()
        defaults = _normalize_defaults(state.get("defaults") if isinstance(state.get("defaults"), dict) else {})
        alias = str(cmd.get("model") or defaults.get("model") or "mock")
        request_id = cmd.get("requestId", cmd.get("requestID"))

        def probe() -> None:
            from agent import runtime_config
            try:
                report = runtime_config.preflight_spec(_model_spec(alias), alias=alias)
            except Exception as exc:  # noqa: BLE001 - a status screen must not crash the bridge
                report = {"spec": alias, "ready": False,
                          "reason": f"preflight failed: {type(exc).__name__}: {exc}",
                          "transport": "unknown", "endpoint": None, "fix": "unknown"}
            self.emit({
                "type": "model_preflight", "ok": True, "model": alias,
                "requestId": request_id, "canClaimAGI": False, **report,
            })

        threading.Thread(target=probe, name="code-bridge-model-preflight", daemon=True).start()

    def _handle_image(self, cmd: dict) -> None:
        """Execute one explicitly confirmed image request inside the workspace."""
        from agent.image_provider import (
            build_image_request,
            execute_image_request,
            resolve_image_provider,
        )

        prompt = str(cmd.get("prompt") or "").strip()
        if not prompt:
            self.error("image prompt is required", error_type="ImagePromptRequired", cmd="image")
            return
        workspace = _normalize_workspace_root(cmd.get("cwd"))
        raw_output = str(cmd.get("output") or "").strip()
        if not raw_output:
            stamp = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")
            raw_output = f"sophia-image-{stamp}.png"
        output = Path(raw_output).expanduser()
        if not output.is_absolute():
            output = workspace / output
        output = output.resolve()
        try:
            output.relative_to(workspace)
        except ValueError:
            self.error(
                "image output must stay inside the selected workspace",
                error_type="ImageOutputOutsideWorkspace",
                cmd="image",
            )
            return
        state, _ = _load_state()
        defaults = _normalize_defaults(
            state.get("defaults") if isinstance(state.get("defaults"), dict) else {}
        )
        permission = _normalize_permission(
            cmd.get("permission")
            if cmd.get("permission") is not None
            else defaults.get("permission")
        )
        provider_spec = str(cmd.get("provider") or defaults.get("imageProvider") or "none")
        try:
            provider = resolve_image_provider(provider_spec)
            request = build_image_request(prompt, output, spec=provider)
        except Exception as exc:  # noqa: BLE001 - typed UI failure
            self.emit({
                "type": "image_result",
                "ok": False,
                "status": "rejected",
                "provider": provider_spec,
                "outputPath": str(output),
                "detail": _safe_text(f"{type(exc).__name__}: {exc}", limit=500),
                "executed": False,
                "confirmed": bool(cmd.get("confirm") is True),
                "canClaimAGI": False,
            })
            return
        if permission == "readonly":
            self.emit({
                "type": "image_result",
                "ok": False,
                "status": "rejected",
                "provider": provider.name,
                "outputPath": str(output),
                "detail": (
                    "readonly permission blocks image execution because every "
                    "image provider writes an output file"
                ),
                "executed": False,
                "confirmed": bool(cmd.get("confirm") is True),
                "delegated": request.delegated,
                "canClaimAGI": False,
            })
            return
        self.emit({
            "type": "image_start",
            "ok": True,
            "provider": provider.name,
            "outputPath": str(output),
            "delegated": request.delegated,
            "confirmed": bool(cmd.get("confirm") is True),
            "canClaimAGI": False,
        })

        def execute() -> None:
            result = execute_image_request(
                request,
                confirm=cmd.get("confirm") is True,
                timeout=max(1.0, min(300.0, float(cmd.get("timeoutSec", 120.0)))),
                allowed_root=workspace,
                api_key_env=provider.api_key_env,
                permission=permission,
            )
            self.emit({"type": "image_result", **result.to_dict()})

        threading.Thread(
            target=execute,
            name="code-bridge-image",
            daemon=True,
        ).start()

    def _handle_task_command(self, name: str, cmd: dict) -> None:
        run_id = _safe_text(cmd.get("runId"), limit=128) if cmd.get("runId") else ""
        task_id = _safe_text(cmd.get("taskId"), limit=128) if cmd.get("taskId") else ""
        store = self._receipt_store(run_id) if run_id else None
        if store is None or not task_id or task_id not in store.nodes:
            self.error("runId and taskId identify no durable task", error_type="UnknownTask", cmd=name)
            return
        if name == "task_log":
            node = store.nodes[task_id]
            self.emit({"type": "task_log", "ok": True, "runId": run_id, "taskId": task_id,
                       "artifacts": list(node.artifacts), "detail": dict(node.detail),
                       "timings": dict(node.timings), "canClaimAGI": False})
            return
        action = str(cmd.get("action") or "").strip().lower()
        # Retry cannot safely replay a run from a receipt alone: prompt, model,
        # workspace, permissions, and provider state are not durable inputs.
        # Reject rather than marking a queued node as a false-success replay.
        if action == "retry":
            self.error("retry is unsupported without a durable replay manifest",
                       error_type="TaskRetryUnsupported", cmd=name)
            return
        try:
            if action == "cancel":
                with self.active_lock:
                    active = self.active
                if active and active.get("id") == run_id and active.get("workflowTaskId") == task_id:
                    active["cancelReason"] = "user_cancel"
                    active["cancel"].set()
                    budget = active.get("budget")
                    if budget is not None:
                        budget.cancel()
                    node = store.nodes[task_id]
                    self.emit({"type": "task_action", "ok": True, "action": action,
                               "status": "cancelling", "runId": run_id, "taskId": task_id,
                               "task": node.to_dict(), "canClaimAGI": False})
                    return
                node = store.cancel(task_id)
            else:
                node = None
            if node is None:
                raise ValueError("supported actions are cancel and retry")
        except (KeyError, ValueError) as exc:
            self.error(str(exc), error_type="TaskActionRejected", cmd=name)
            return
        self.emit({"type": "task_action", "ok": True, "action": action,
                   "runId": run_id, "taskId": task_id, "task": node.to_dict(), "canClaimAGI": False})

    def _context_usage(self, handle: dict) -> dict:
        """How full the model's window is after this run.

        Compaction already reported its own before/after, but only at the moment
        it fired — so between compactions the operator had no idea whether the
        conversation was at 5% or 79% of the window. That is the number that
        tells you whether to `/compact` now or keep going, and it was invisible.

        Best-effort by construction: a client that cannot compute it renders
        nothing, so every failure path here returns {} rather than a zero. A
        fabricated 0% would read as "plenty of room" — the opposite of the
        truth if the estimate failed on a huge history.
        """
        try:
            from agent import cli as terminal_cli
            from agent.agent_loop import _auto_compact_budget, _estimate_messages_tokens

            session = handle.get("session") or ""
            if not session:
                return {}
            turns = terminal_cli._load_conversation(terminal_cli._conversation_path(session)) or []
            used = _estimate_messages_tokens(turns)
        except Exception:  # noqa: BLE001 - telemetry must never fail a delivered run
            return {}

        # A real prompt_tokens count from this run's last model call is the
        # provider's OWN tokenizer output for the exact context it just sent —
        # strictly more accurate than the char/4 heuristic above, which
        # agent_loop.py itself only ever falls back to for transports that
        # never report usage. Prefer it whenever this run actually saw one;
        # `contextTokensSource` is additive so an older client that only reads
        # `contextTokens` sees no shape change either way.
        real_tokens = handle.get("lastPromptTokens")
        if isinstance(real_tokens, int) and real_tokens > 0:
            usage: dict = {"contextTokens": real_tokens, "contextTokensSource": "reported"}
        else:
            usage = {"contextTokens": used, "contextTokensSource": "estimated"}
        try:
            from agent import model as _model
            window = handle.get("resolvedContextWindow")
            if window is None:
                window = _model.resolve_config(str(handle.get("model") or "")).context_window
        except Exception:  # noqa: BLE001 - an unknown alias just means "no percentage"
            window = None
        if window:
            usage["contextWindow"] = window
            # The threshold the auto-compactor will act on, so the UI can warn
            # BEFORE it fires rather than only reporting it afterwards.
            try:
                usage["contextBudget"] = _auto_compact_budget(window)
            except Exception:  # noqa: BLE001
                pass
        return usage

    def _handle_compact(self, cmd: dict) -> None:
        """Compact a session's stored history on demand.

        `/compact` was in the slash catalog as `info` and did nothing. The
        machinery already existed — agent_loop compacts automatically before a
        model call once history passes the model's budget — but there was no way
        to ask for it, so the only options were "wait until it happens" or
        "/clear and lose the conversation".

        This is the SAME reduction the automatic path uses (deterministic
        head+tail elision, no model call), applied to the file the next run
        loads as `history=`, so the effect persists rather than lasting one turn.
        The reply carries before/after tokens and the model's window, so the
        client can say "now 19% of 500k" rather than a bare token count.
        """
        from agent import cli as terminal_cli
        from agent.agent_loop import _compact_messages, _estimate_messages_tokens

        session = _normalize_session(cmd.get("session"))
        path = terminal_cli._conversation_path(session)
        try:
            turns = terminal_cli._load_conversation(path) or []
        except (OSError, ValueError) as exc:
            self.error(f"could not read session {session!r}: {type(exc).__name__}",
                       error_type="CompactReadFailed", cmd="compact")
            return

        if not turns:
            # Not an error: an empty session is a legitimate state, and failing
            # here would make /compact look broken on a fresh conversation.
            self.emit({"type": "compact", "ok": True, "session": session, "compacted": False,
                       "reason": "nothing to compact", "beforeTokens": 0, "afterTokens": 0,
                       "canClaimAGI": False})
            return

        # Resolve the ACTIVE model's window so a manual compaction targets the
        # same budget the automatic one would, rather than a constant.
        window = None
        try:
            from agent import model as _model
            defaults, _ = _load_state()
            alias = str(cmd.get("model") or defaults.get("defaults", {}).get("model") or "") or None
            if alias:
                window = _model.resolve_config(alias).context_window
        except Exception:  # noqa: BLE001 - an unknown alias must not fail the compaction
            window = None

        before = _estimate_messages_tokens(turns)
        # budget_tokens=1 forces the reduction unconditionally: the operator
        # asked for it, so "already under budget" must not silently no-op.
        compacted, audit = _compact_messages(list(turns), budget_tokens=1, context_window=window)
        after = _estimate_messages_tokens(compacted)

        if not audit.get("compacted"):
            self.emit({"type": "compact", "ok": True, "session": session, "compacted": False,
                       "reason": "already minimal", "beforeTokens": before, "afterTokens": before,
                       "contextWindow": window, "canClaimAGI": False})
            return
        try:
            terminal_cli._save_conversation(path, compacted)
        except OSError as exc:
            self.error(f"compacted in memory but could not save: {type(exc).__name__}",
                       error_type="CompactWriteFailed", cmd="compact")
            return
        self.emit({"type": "compact", "ok": True, "session": session, "compacted": True,
                   "mode": audit.get("mode"), "beforeTokens": before, "afterTokens": after,
                   "contextWindow": window, "foldedTurns": audit.get("foldedTurns"),
                   "keptRecent": audit.get("keptRecent"), "canClaimAGI": False})

    def _handle_bench(self, cmd: dict) -> None:
        """Run ``agent.model_bench`` head-to-head, streaming per-case progress.

        Mirrors ``_handle_compact``'s shape: a synchronous handler that emits
        custom *top-level* events the TUI renders as chat bubbles —
        ``bench_start`` -> one ``bench_progress`` per (model, case) ->
        ``bench_result`` carrying the markdown comparison table. The per-case
        stream is threaded through ``model_bench.run_model``'s ``progress_cb``.

        Methodology / integrity tooling only: every event is
        ``canClaimAGI: false`` and the result is ``candidateOnly``. The
        comparability caveat (CLI transports vs API/local) rides on the result
        so the client can render it — it must never read as a capability claim.
        """
        import agent.model_bench as mb

        # De-dupe model specs (preserve order): the same model twice produces
        # duplicate scorecard rows and a confusing report. The TUI already
        # guards its picker, but any client could send a repeat.
        specs = list(dict.fromkeys(
            s.strip() for s in str(cmd.get("models") or "").split(",") if s.strip()
        ))
        corpus = str(cmd.get("corpus") or "knowledge")
        max_cases = _safe_int(cmd.get("maxCases"), 20)
        warmup = bool(cmd.get("warmup", True))
        if not specs:
            self.error("bench requires at least one model", error_type="BenchEmpty", cmd="bench")
            return
        # Tool-use mode is a distinct benchmark: it drives each model through the
        # REAL Sophia tool loop and scores the S1-S6 tool-use skills + speed. It has
        # its own runner/report (tools.bench_tool_use); delegate and return.
        if str(cmd.get("mode") or corpus).strip().lower() in ("tool-use", "tooluse", "tools"):
            self._handle_bench_tool_use(specs, max_cases, warmup)
            return
        # Trigger benchmark: does the model auto-trigger the RIGHT tool/skill given
        # an intent? Measures recognition (trigger_rate), selection accuracy, over-
        # trigger. The MCP+skill-surfacing diagnostic. Delegate and return.
        if str(cmd.get("mode") or corpus).strip().lower() in ("trigger", "triggers"):
            self._handle_bench_trigger(specs, max_cases)
            return
        try:
            domains = (
                sorted(mb.DOMAIN_BENCH) if corpus == "knowledge"
                else [d.strip() for d in corpus.split(",") if d.strip()]
            )
            cases = mb.select_cases(domains, max_cases)
        except ValueError as exc:
            self.error(str(exc), error_type="BenchConfig", cmd="bench")
            return
        if not cases:
            self.error(f"no cases for corpus {corpus!r}", error_type="BenchConfig", cmd="bench")
            return
        traditions = mb.load_traditions()

        self.emit({"type": "bench_start", "models": specs, "totalCases": len(cases),
                   "corpus": corpus, "canClaimAGI": False})

        # Smoke probe: fail-closed per backend, but proceed with the ready ones
        # (case_idx == -1 marks a smoke failure rather than a scored case).
        smokes = mb.smoke_probe(specs)
        ready = [s for s, ok, _ in smokes if ok]
        for spec, ok, msg in smokes:
            if not ok:
                self.emit({"type": "bench_progress", "model": spec, "case_idx": -1,
                           "total": 0, "passed": False, "error": msg, "canClaimAGI": False})
        if not ready:
            self.emit({"type": "bench_result", "ok": False,
                       "error": "no models are configured/ready — check backend setup",
                       "canClaimAGI": False})
            return

        # One callback for every model: the payload already carries the model
        # name, so there is no loop-variable to close over.
        def _emit_progress(payload: dict) -> None:
            self.emit({"type": "bench_progress", **payload, "canClaimAGI": False})

        model_rows: list[dict[str, Any]] = []
        for spec in ready:
            row = mb.run_model(spec, cases, traditions, warmup=warmup, progress_cb=_emit_progress)
            model_rows.append(row)

        with_throughput = any(
            r.get("mean_tok_s") is not None or r.get("cold_start_s") is not None
            for r in model_rows
        )
        table = mb.render_table(model_rows, with_throughput=with_throughput)
        out_dir = mb.BENCH_OUT_DIR
        try:
            report_path: str = str(mb.write_report(
                model_rows, corpus=corpus, domains=domains, max_cases=max_cases,
                models=ready, warmup=warmup, out_dir=out_dir,
            ))
        except OSError as exc:
            report_path = f"(report not written: {type(exc).__name__})"
        self.emit({"type": "bench_result", "ok": True, "table": table, "results": model_rows,
                   "report": report_path, "comparability": "prose Q&A · candidateOnly",
                   "candidateOnly": True, "canClaimAGI": False})

    def _handle_bench_tool_use(self, specs: list[str], max_cases: int, warmup: bool) -> None:
        """Run the S1-S6 tool-use benchmark head-to-head, streaming per-case progress.

        The tool-use twin of ``_handle_bench``: same ``bench_start`` ->
        ``bench_progress`` -> ``bench_result`` event shape (so the TUI renders it
        with the same bubbles), but each model is driven through the REAL Sophia
        tool loop and scored on the six tool-use skills + speed via
        ``tools.bench_tool_use`` (which reuses the sealed verifiers). Same
        candidateOnly / canClaimAGI:false discipline.
        """
        import agent.model_bench as mb
        from provenance_bench.tool_use_benchmark import load_cases, verify_manifest
        from tools import bench_tool_use as btu

        version = "heldout_v1"
        try:
            cases = btu.select_cases(load_cases(version=version), max_cases)
        except (OSError, ValueError) as exc:
            self.error(str(exc), error_type="BenchConfig", cmd="bench")
            return
        if not cases:
            self.error("no tool-use cases available", error_type="BenchConfig", cmd="bench")
            return

        self.emit({"type": "bench_start", "models": specs, "totalCases": len(cases),
                   "corpus": "tool-use", "mode": "tool-use", "canClaimAGI": False})

        # Smoke probe (shared with the knowledge path): proceed with ready models,
        # mark the rest with case_idx == -1 so the TUI shows them as skipped.
        smokes = mb.smoke_probe(specs)
        ready = [s for s, ok, _ in smokes if ok]
        for spec, ok, msg in smokes:
            if not ok:
                self.emit({"type": "bench_progress", "model": spec, "case_idx": -1,
                           "total": 0, "passed": False, "error": msg, "canClaimAGI": False})
        if not ready:
            self.emit({"type": "bench_result", "ok": False,
                       "error": "no models are configured/ready — check backend setup",
                       "canClaimAGI": False})
            return

        def _emit_progress(payload: dict) -> None:
            self.emit({"type": "bench_progress", **payload, "canClaimAGI": False})

        model_rows: list[dict[str, Any]] = []
        for spec in ready:
            model_rows.append(btu.run_model(spec, cases, warmup=warmup, progress_cb=_emit_progress))

        table = btu.render_table(model_rows)
        # Harness-weakness diagnosis: interpret the S1-S6 pattern as named, fixable
        # harness gaps. This is the diagnostic surface that makes /bench tool-use
        # serve harness improvement (vs a capability headline) — the flagged skills
        # are exactly what should flow into OKF anti-repeat memory.
        diagnosis = btu.diagnose_weaknesses(model_rows)
        try:
            seal = verify_manifest(root=mb.ROOT, version=version)
        except Exception:  # noqa: BLE001 - seal is advisory here; report proceeds
            seal = None
        report = btu.build_report(model_rows, version=version, models=ready,
                                  n_cases=len(cases), warmup=warmup, seal=seal)
        out_dir = mb.BENCH_OUT_DIR
        try:
            report_path: str = str(btu.write_report(report, out_dir))
        except OSError as exc:
            report_path = f"(report not written: {type(exc).__name__})"
        self.emit({"type": "bench_result", "ok": True,
                   "table": table + "\n\n" + diagnosis, "results": model_rows,
                   "diagnosis": diagnosis,
                   "report": report_path, "comparability": "tool-use S1-S6 · candidateOnly",
                   "mode": "tool-use", "candidateOnly": True, "canClaimAGI": False})

        # Write OKF process log for this tool-use benchmark run
        try:
            from agent.benchmark_failure_store import write_okf_process_log
            run_id = f"tooluse-{time.strftime('%Y%m%dT%H%M%S')}"
            n_fail = sum(1 for mr in model_rows for r in mr.get("rows", []) if not r.get("passed"))
            write_okf_process_log(run_id, "tool_use", ",".join(specs), table, n_fail)
        except Exception:  # noqa: BLE001
            pass

    def _handle_bench_trigger(self, specs: list[str], max_cases: int) -> None:
        """Run the trigger benchmark: does the model auto-trigger the right tool/skill?

        The diagnostic the other benchmarks miss: tool-USE measures whether a call
        succeeds once made; this measures whether the model RECOGNIZES when to call
        in the first place (and the right one). Drives the model one short turn per
        sealed intent with the MCP + skill surface exposed, scores trigger_rate /
        selection_accuracy / over_trigger / skill_recall, and emits the scorecard +
        a harness-weakness diagnosis. candidateOnly; canClaimAGI:false.
        """
        import tools.bench_trigger as bt
        actual_cases = len(bt.load_cases(include_skills=True))
        self.emit({"type": "bench_start", "models": specs,
                   "totalCases": min(max_cases, actual_cases) if max_cases else actual_cases,
                   "corpus": "trigger", "canClaimAGI": False})

        def _emit_progress(payload: dict) -> None:
            self.emit({"type": "bench_progress", **payload, "canClaimAGI": False})

        rows = []
        for spec in specs:
            row = bt.run_model(spec, surface_skills=True, max_cases=max_cases,
                               progress_cb=_emit_progress)
            rows.append(row)

        # Render: one table per model (single-model is the norm; the loop supports N).
        tables = [bt.render_table(r) for r in rows]
        table = "\n\n".join(tables)
        self.emit({"type": "bench_result", "ok": True, "table": table, "results": rows,
                   "comparability": bt.COMPARABILITY, "mode": "trigger",
                   "candidateOnly": True, "canClaimAGI": False})

        # Write OKF process log for this benchmark run
        try:
            from agent.benchmark_failure_store import write_okf_process_log
            for r in rows:
                run_id = f"trigger-{time.strftime('%Y%m%dT%H%M%S')}-{r.get('model', 'unknown')}"
                n_fail = r.get("failures_recorded", 0)
                write_okf_process_log(run_id, "trigger", r.get("model", ""), table, n_fail)
        except Exception:  # noqa: BLE001
            pass

    # ------------------------------------------------------------------ #
    # /tbench — run terminal-bench 2.1 tasks through the agent loop (oMLX)
    # ------------------------------------------------------------------ #
    def _handle_tbench(self, cmd: dict) -> None:
        """Run terminal-bench 2.1 tasks through the REAL Sophia agent loop.

        The Sophia harness loop is already inside ``run_agent_loop``: every task
        is auto-recorded as an OKF ``run_*.md`` page + ``FAILURES.md`` row, and
        the NEXT run injects those failures as ``## Anti-repeat memory``. The
        implementation remains in the legacy-named compatibility module.

        This handler adds the two pieces the bare loop lacks:

          1. Per-task isolation — a fresh ``ToolContext(root=mkdtemp)`` so each
             task's file writes cannot leak into another. The agent loop's OKF
             recording keys off ``ctx.root``, so each task gets its own page.
          2. Fix-capture — on failure, ONE bounded reflection call (oMLX) writes
             a structured ``Why / How to apply`` lesson back onto the page and
             its ``FAILURES.md`` row, so anti-repeat recall is high-signal.

        Scoring is HOST-BEST-EFFORT, not Docker-faithful (see
        ``tbench_loader.COMPARABILITY``): tasks needing their Docker image are
        scored ``None`` (deferred), never coerced to pass/fail. The comparability
        caveat rides on every emitted score.

        Event shape mirrors ``_handle_bench``: ``tbench_start`` ->
        one ``tbench_progress`` per task -> ``tbench_result`` with the table.
        Runs synchronously (the kernel is single-threaded for command dispatch);
        each task is a short bounded ``run_agent_loop`` invocation.
        """
        import shutil
        import tempfile

        import agent.tbench_loader as tbench
        import agent.tbench_reflect as treflect
        from agent import model as _m
        from agent.agent_loop import run_agent_loop
        from agent.agent_tools import ToolContext

        mode = str(cmd.get("mode") or "smoke").strip().lower() or "smoke"
        n = max(1, _safe_int(cmd.get("n"), 5 if mode == "smoke" else 20))
        model_alias = _normalize_model(cmd.get("model") if cmd.get("model") is not None else
                                       CODE_DEFAULTS.get("model", "omlx"))
        # terminal-bench is an agentic, tool-use benchmark: oMLX is the target,
        # but any function-calling provider (openai/vllm/ollama) works. The model
        # is resolved per-run so a smoke failure to reach oMLX is reported, not a crash.
        explicit_names = []
        if isinstance(cmd.get("names"), list):
            explicit_names = [str(x).strip() for x in cmd["names"] if str(x).strip()]
        max_steps = max(1, min(256, _safe_int(cmd.get("maxSteps"),
                                              CODE_DEFAULTS.get("maxSteps", 24))))

        # 1. Locate/clone the task set, then select the task list for this mode.
        try:
            cache = cmd.get("cache") or os.environ.get("SOPHIA_TBENCH_CACHE")
            clone = tbench.clone_or_locate(cache)
        except Exception as exc:  # noqa: BLE001 — network/clone fault -> clean error
            self.error(f"tbench: could not locate terminal-bench clone: {type(exc).__name__}: {exc}",
                       error_type="TBenchNoClone", cmd="tbench")
            return
        names = tbench.select(clone, mode=mode, n=n, names=explicit_names or None)
        if not names:
            hint = (" (no smoke tasks matched — the task set may have moved)"
                    if mode == "smoke" else "")
            self.error(f"tbench: no tasks selected for mode {mode!r}{hint}",
                       error_type="TBenchEmpty", cmd="tbench")
            return

        # 2. Resolve the model client once (shared across tasks; oMLX serves one
        # request at a time so we run tasks strictly sequentially).
        try:
            client = _m.default_client(model_alias)
        except Exception as exc:  # noqa: BLE001
            self.emit({"type": "tbench_result", "ok": False,
                       "error": f"model {model_alias!r} not reachable: {type(exc).__name__}: {exc}",
                       "candidateOnly": True, "canClaimAGI": False})
            return

        rows: list[dict[str, Any]] = []
        # Docker-faithful mode: the agent works INSIDE the task image. The task
        # image is what terminal-bench ships per task (task.toml [environment]
        # docker_image); running inside it is the only way both to solve tasks
        # that need pinned deps AND to score faithfully (tests/test.sh → reward.txt).
        use_docker = bool(cmd.get("docker")) or mode == "docker"
        self.emit({"type": "tbench_start", "model": model_alias, "mode": mode,
                   "totalTasks": len(names), "maxSteps": max_steps,
                   "scoring": "container" if use_docker else "host",
                   "comparability": (tbench.COMPARABILITY_CONTAINER if use_docker else tbench.COMPARABILITY),
                   "canClaimAGI": False})
        for idx, name in enumerate(names):
            t0 = time.time()
            workdir = None
            backend = None  # AppleContainerBackend when use_docker
            try:
                task = tbench.load_task(clone, name)
                workdir = tempfile.mkdtemp(prefix=f"sophia-tbench-{name}-")
                if use_docker:
                    # Faithful path: launch the task image, run the agent inside it.
                    from agent.sandbox.apple_container_backend import AppleContainerBackend
                    if not task.docker_image:
                        raise RuntimeError(f"task {name!r} has no docker_image in task.toml")
                    backend = AppleContainerBackend(
                        image=task.docker_image,
                        workdir="/app",
                        env={"TBENCH_TASK": name},
                        # terminal-bench task images are published linux/amd64; on
                        # Apple Silicon we run them under Rosetta (x86 emulation).
                        platform="linux/amd64",
                        rosetta=True,
                    )
                    backend.start(workdir="/app")  # pull + run -d + keepalive
                    # ctx.sandbox routes bash → container exec; the file tools'
                    # _container_file_backend() routes read/write_file → the same
                    # container. root is a host scratch dir (OKF pages land there).
                    ctx = ToolContext(root=Path(workdir), permission="auto", sandbox=backend)
                else:
                    ctx = ToolContext(root=Path(workdir), permission="auto")
                # A neutral system-extra: the task prompt is self-contained and
                # tool-use is the point, so we add only the anti-repeat memory the
                # loop already builds (failure_recall) — no leading instructions.
                # The loop calls failure_recall_system_extra internally via the
                # harness prompt; here we pass an empty extra to avoid double-injecting.
                result = run_agent_loop(
                    task.prompt,
                    client=client,
                    ctx=ctx,
                    max_steps=max_steps,
                )
                latency = time.time() - t0
                # Score: faithful (container) when use_docker, else host-best-effort.
                if use_docker:
                    scored = tbench.score_task_in_container(task, backend)
                else:
                    scored = tbench.score_task(task, workdir)
                # A loop-level failure (model_error or no final answer) counts as
                # a task fail regardless of the scorer; the scorer's None (deferred)
                # is preserved as "not yet scored".
                loop_ok = bool(result.ok) and not result.model_error
                if not loop_ok:
                    passed: bool | None = False
                    reason = (f"agent loop did not complete: {result.model_error}"
                              if result.model_error else "reached step ceiling / no final answer")
                else:
                    passed = scored.passed
                    reason = scored.reason if scored.deferred else (
                        "passed" if scored.passed else
                        ("verifier: assertion failed" if use_docker else "host scorer: assertion failed"))

                # Fix-capture: on any non-pass, reflect once and write the
                # structured lesson back onto the OKF page + FAILURES.md row so
                # the next run's anti-repeat memory carries the fix, not a stub.
                if passed is not True:
                    self._tbench_reflect_and_writeback(
                        task, result, client, model_alias, ctx,
                        treflect=treflect,
                    )

                rows.append({
                    "name": name, "category": task.category, "difficulty": task.difficulty,
                    "passed": passed, "deferred": scored.deferred if loop_ok else False,
                    "reason": reason, "latency_s": round(latency, 1),
                    "steps": len(result.steps), "scoring": "container" if use_docker else "host",
                })
                self.emit({"type": "tbench_progress", "task": name, "case_idx": idx,
                           "total": len(names), "passed": passed,
                           "deferred": scored.deferred if loop_ok else False,
                           "latency_s": round(latency, 1), "error": reason if passed is not True else "",
                           "scoring": "container" if use_docker else "host",
                           "canClaimAGI": False})
            except Exception as exc:  # noqa: BLE001 — one bad task never aborts the sweep
                latency = time.time() - t0
                rows.append({"name": name, "category": "?", "difficulty": "?",
                             "passed": None, "deferred": True,
                             "reason": f"harness error: {type(exc).__name__}: {exc}",
                             "latency_s": round(latency, 1), "steps": 0,
                             "scoring": "container" if use_docker else "host"})
                self.emit({"type": "tbench_progress", "task": name, "case_idx": idx,
                           "total": len(names), "passed": None, "deferred": True,
                           "latency_s": round(latency, 1),
                           "error": f"harness error: {type(exc).__name__}", "canClaimAGI": False})
            finally:
                if backend is not None:
                    backend.stop()  # tear down the per-task container (best-effort)
                if workdir and os.path.isdir(workdir):
                    shutil.rmtree(workdir, ignore_errors=True)

        # 5. Result + candidate report.
        table = _tbench_render_table(rows)
        report_path = _tbench_write_report(rows, model_alias=model_alias, mode=mode,
                                           comparability=tbench.COMPARABILITY)
        self.emit({"type": "tbench_result", "ok": True, "table": table, "results": rows,
                   "report": report_path, "comparability": tbench.COMPARABILITY,
                   "candidateOnly": True, "canClaimAGI": False})

        # Ingest tbench failures into the durable store + OKF process log
        try:
            from agent.benchmark_failure_store import ingest_tbench_results, write_okf_process_log
            run_id = f"tbench-{time.strftime('%Y%m%dT%H%M%S')}-{model_alias}"
            n_fail = ingest_tbench_results(run_id, model_alias, rows)
            write_okf_process_log(run_id, "tbench", model_alias, table, n_fail)
        except Exception:  # noqa: BLE001
            pass

    @staticmethod
    def _tbench_reflect_and_writeback(task, result, client, model_alias, ctx, *, treflect) -> None:
        """One bounded reflection call + write-back onto the OKF page/FAILURES row.

        Extracted so it is easy to unit-test the wiring without a real model: the
        reflection + write-back logic lives in ``agent.tbench_reflect`` (already
        covered by tests); this just pulls the failing tool steps off the result,
        finds the page the loop just wrote, and patches it.
        """
        from agent.sophia_harness import process_log_id, resolve_process_log_dir

        failing_tools = [s for s in result.steps if not s.get("ok")]
        errors = []
        if result.model_error:
            errors.append({"type": "model_error", "tool": "model", "error": result.model_error[:1200]})
        for s in failing_tools[:6]:
            errors.append({"type": "tool_error", "tool": str(s.get("tool")),
                           "error": str(s.get("error") or "")[:400]})
        refl = treflect.reflect_on_failure(
            task.prompt, errors, failing_tools, client,
            timeout_note=f"model={model_alias}, steps={len(result.steps)}",
        )
        # The loop wrote the OKF page under the run's ctx.root. process_log_id is
        # non-deterministic (time_ns+pid+uuid nonce), so locate the page by its
        # stable slug prefix rather than re-deriving the id. Write-back is
        # best-effort: it must never break the sweep, so all faults are swallowed.
        from agent.sophia_harness import resolve_process_log_dir

        try:
            # ctx.root was the per-task workdir; the page lives under its
            # .sophia/okf-process-log/ (resolve_process_log_dir's default branch).
            log_dir = resolve_process_log_dir(Path(ctx.root))
            page = treflect.find_page_for_goal(log_dir, task.prompt)
            if page is not None:
                treflect.write_back_lesson(page, refl)
                treflect.patch_failures_lesson(log_dir / "FAILURES.md", page.stem, refl)
        except Exception:  # noqa: BLE001 — fix-capture is advisory, never fatal
            return



    @staticmethod
    def _find_repo(explicit: str | None = None) -> Path | None:
        """Locate the sophia-agi git checkout for a rebuild-and-install cycle."""
        if explicit:
            p = Path(explicit).expanduser().resolve()
            return p if (p / ".git").exists() or (p / "VERSION").exists() else None
        env = os.environ.get("SOPHIA_REPO")
        if env:
            p = Path(env).expanduser().resolve()
            if (p / ".git").exists() or (p / "VERSION").exists():
                return p
        res = os.environ.get("SOPHIA_RESOURCE_ROOT")
        if res:
            p = Path(res).resolve()
            if (p / ".git").exists():
                return p
        home = Path.home()
        for candidate in (
            home / "Documents" / "GitHub" / "sophia-agi",
            home / "sophia-agi",
            home / "projects" / "sophia-agi",
            home / "src" / "sophia-agi",
        ):
            if (candidate / ".git").exists():
                return candidate.resolve()
        return None

    # ------------------------------------------------------------------ #
    # /gaia — GAIA benchmark per-level harness diagnostic (oMLX)
    # ------------------------------------------------------------------ #
    def _handle_gaia(self, cmd: dict) -> None:
        """Run GAIA validation questions through the agent loop; score with the
        official scorer; aggregate PER-LEVEL (the harness diagnostic).

        GAIA's 3 levels form a gradient (single-step → multi-step chaining →
        long-horizon autonomy). A collapse from L1 to L2/L3 isolates WHERE the
        harness breaks — actionable harness work, not a model IQ verdict. That
        gradient is what a flat pass@1 hides, and it is the point of /gaia.

        Anti-contamination: GAIA questions are PUBLIC but must never enter
        training corpora. We load them at run time only, never persist question
        or answer text, and write only aggregate per-level rates to the report.
        candidateOnly; canClaimAGI:false.
        """
        import tempfile

        from agent import gaia_runner as gaia
        from agent import model as _m
        from agent.agent_loop import run_agent_loop
        from agent.agent_tools import ToolContext

        model_alias = _normalize_model(cmd.get("model") if cmd.get("model") is not None else
                                       CODE_DEFAULTS.get("model", "omlx"))
        # level filter: None = all, else 1/2/3. n caps the per-level sample for a
        # fast read (the full validation set is 165 questions — slow on local 35B).
        level = cmd.get("level")
        try:
            level = int(level) if level not in (None, "") else None
        except (TypeError, ValueError):
            level = None
        max_per_level = max(1, _safe_int(cmd.get("n"), 5))
        max_steps = max(1, min(256, _safe_int(cmd.get("maxSteps"),
                                              CODE_DEFAULTS.get("maxSteps", 24))))

        try:
            client = _m.default_client(model_alias)
        except Exception as exc:  # noqa: BLE001
            self.emit({"type": "gaia_result", "ok": False,
                       "error": f"model {model_alias!r} not reachable: {type(exc).__name__}: {exc}",
                       "candidateOnly": True, "canClaimAGI": False})
            return

        # Load the validation split (gated; needs huggingface-cli login + accepted terms).
        try:
            rows, files_dir = gaia.load_dataset_rows(level=level)
        except Exception as exc:  # noqa: BLE001 — clear error, not a crash
            self.emit({"type": "gaia_result", "ok": False,
                       "error": f"GAIA load failed: {type(exc).__name__}: {exc}",
                       "candidateOnly": True, "canClaimAGI": False})
            return

        # cap per-level sample (deterministic order) for a fast diagnostic read
        if level is None:
            by_level: dict[int, list[dict]] = {}
            for r in rows:
                by_level.setdefault(r["level"], []).append(r)
            capped = []
            for lvl in sorted(by_level):
                capped.extend(by_level[lvl][:max_per_level])
            rows = capped

        self.emit({"type": "gaia_start", "model": model_alias, "level": level,
                   "totalQuestions": len(rows), "maxSteps": max_steps,
                   "comparability": gaia.COMPARABILITY, "canClaimAGI": False})

        scored_rows: list[dict] = []
        for idx, row in enumerate(rows):
            t0 = time.time()
            workdir = None
            try:
                workdir = tempfile.mkdtemp(prefix=f"sophia-gaia-{row['task_id'][:8]}-")
                ctx = ToolContext(root=Path(workdir), permission="auto")
                prompt = gaia.build_prompt(row, files_dir)
                result = run_agent_loop(prompt, client=client, ctx=ctx, max_steps=max_steps)
                latency = time.time() - t0
                answer = gaia.extract_final_answer(result.final_text)
                passed = gaia.score_row(answer, row)
                scored_rows.append({"level": row["level"], "passed": passed,
                                    "task_id": row["task_id"]})
                self.emit({"type": "gaia_progress", "task_id": row["task_id"],
                           "level": row["level"], "case_idx": idx, "total": len(rows),
                           "passed": passed, "latency_s": round(latency, 1),
                           "canClaimAGI": False})
            except Exception as exc:  # noqa: BLE001 — one bad question never aborts
                scored_rows.append({"level": row["level"], "passed": False,
                                    "task_id": row["task_id"]})
                self.emit({"type": "gaia_progress", "task_id": row["task_id"],
                           "level": row["level"], "case_idx": idx, "total": len(rows),
                           "passed": False, "error": f"{type(exc).__name__}",
                           "canClaimAGI": False})
            finally:
                if workdir and os.path.isdir(workdir):
                    shutil.rmtree(workdir, ignore_errors=True)

        from agent import gaia_scorer as _gs  # noqa: E402
        diag = _gs.diagnose_by_level(scored_rows)
        self.emit({"type": "gaia_result", "ok": True, "diagnosis": diag,
                   "n": len(scored_rows), "comparability": gaia.COMPARABILITY,
                   "candidateOnly": True, "canClaimAGI": False})

    # ------------------------------------------------------------------ #
    # /taubench — τ-bench reliability (pass^k) harness diagnostic (oMLX)
    # ------------------------------------------------------------------ #
    def _handle_taubench(self, cmd: dict) -> None:
        """Run τ-bench tasks through the agent loop; score reliability with pass^k.

        pass^k = p^k decays with per-trial flakiness, so it measures HARNESS
        reliability — "does my loop flake?" — exactly the harness-weakness signal
        a flat pass@1 hides. A steep pass@1→pass^N decay flags non-determinism
        (tool-call parsing on local Qwen batches, jittery stops).

        Drives τ-bench's in-process Env with our agent loop (not tau-bench's own
        agent), so the measurement is of OUR harness. Each turn's observation is
        fed into run_agent_loop's tool-calling path; tool_calls map back to τ-bench
        Action objects. candidateOnly; canClaimAGI:false.
        """
        from agent import taubench_runner as tb
        from agent import model as _m

        model_alias = _normalize_model(cmd.get("model") if cmd.get("model") is not None else
                                       CODE_DEFAULTS.get("model", "omlx"))
        domain = str(cmd.get("domain") or "retail").strip().lower()
        num_trials = max(1, _safe_int(cmd.get("numTrials") or cmd.get("k") or cmd.get("n"), 3))
        # the user-simulator is a SEPARATE model; default to the same local model so
        # the run is fully local. A frontier user-sim would isolate agent-side flakiness.
        user_model = str(cmd.get("userModel") or model_alias)
        task_ids = cmd.get("taskIds") if isinstance(cmd.get("taskIds"), list) else None
        max_steps = max(1, min(256, _safe_int(cmd.get("maxSteps") or tb.DEFAULT_MAX_STEPS,
                                              tb.DEFAULT_MAX_STEPS)))

        self.emit({"type": "taubench_start", "model": model_alias, "domain": domain,
                   "numTrials": num_trials, "userModel": user_model,
                   "taskIds": task_ids, "comparability": tb.COMPARABILITY,
                   "canClaimAGI": False})
        try:
            rewards_per_task = tb.run_sweep(
                domain=domain, model_alias=model_alias, client=_m.default_client(model_alias),
                user_model=user_model, num_trials=num_trials, task_ids=task_ids,
                max_steps=max_steps,
                progress_cb=lambda payload: self.emit({"type": "taubench_progress",
                    "canClaimAGI": False, **payload}),
            )
        except Exception as exc:  # noqa: BLE001
            self.emit({"type": "taubench_result", "ok": False,
                       "error": f"τ-bench failed: {type(exc).__name__}: {exc}",
                       "candidateOnly": True, "canClaimAGI": False})
            return

        passk = tb.pass_hat_k(rewards_per_task, num_trials=num_trials)
        diag = tb.diagnose_reliability(passk, num_trials=num_trials)
        self.emit({"type": "taubench_result", "ok": True, "passk": passk,
                   "passAt1": tb.pass_at_1(rewards_per_task), "diagnosis": diag,
                   "numTrials": num_trials, "nTasks": len(rewards_per_task),
                   "comparability": tb.COMPARABILITY,
                   "candidateOnly": True, "canClaimAGI": False})

    def _handle_graph(self, cmd: dict) -> None:
        """Emit a read-only OKF belief-graph projection for the TUI /graph panel.

        Same source of truth as the ``sophia_dump_graph`` MCP tool
        (``sophia_mcp.tools_impl.mcp_dump_graph``): the page-derived belief graph
        projected into ``sophia.graph_projection.v1``. The TUI sends
        ``{cmd:"graph", root?, domain?, depth?}`` and we reply with ONE
        ``graph_projection`` event carrying the projection document plus a
        monotonic ``sequence`` so the client reducer (``isStaleSnapshot``) can
        drop a late/out-of-order read.

        Fail-closed: a build/import fault surfaces as ``ok:false`` with the
        structured error — the panel then keeps its prior/empty state and a
        system line explains why; we never emit a partial graph. ``canClaimAGI``
        is also forced false globally by ``emit()``. Offline, non-destructive.
        """
        _root = cmd.get("root")
        root = (_safe_text(_root, limit=256) or None) if _root not in (None, "") else None
        _dom = cmd.get("domain")
        domain = (_safe_text(_dom, limit=128) or None) if _dom not in (None, "") else None
        raw_depth = cmd.get("depth")
        if raw_depth in (None, ""):
            # Root-scoped lookups default to a 2-hop neighbourhood (matches the
            # /graph entity UX); an unscoped request stays unbounded (audit view).
            depth: int | None = 2 if root else None
        else:
            depth = max(1, min(_safe_int(raw_depth, 2), 8))
        seq = getattr(self, "_graph_seq", 0) + 1
        self._graph_seq = seq
        try:
            from sophia_mcp.tools_impl import mcp_dump_graph
            result = mcp_dump_graph(domain=domain, root=root, depth=depth, fmt="json")
        except Exception as exc:  # noqa: BLE001 - import/build fault -> honest error
            result = {"error": f"{type(exc).__name__}: {exc}"}
        if isinstance(result, dict) and result.get("error"):
            self.emit({"type": "graph_projection", "ok": False, "sequence": seq,
                       "error": str(result.get("error")), "canClaimAGI": False})
            return
        self.emit({"type": "graph_projection", "ok": True, "sequence": seq,
                   "projection": result, "canClaimAGI": False})

    def _handle_update(self, cmd: dict) -> None:
        """Pull latest origin/main, rebuild the TUI, and reinstall source mode.

        Uses ``git archive`` to extract origin/main into a temp directory so
        the user's working branch is never touched and git-crypt smudge
        filters are bypassed (archive does not run filters).  The public source
        updater is intentionally separate from the signed commercial release
        builder, whose native-binary and licensing inputs are not available to
        an ordinary checkout update.
        Emits ``update_start`` -> ``update_progress`` per step ->
        ``update_result``.
        """
        import shutil as _shutil

        repo_arg = _safe_text(cmd.get("repo"), limit=512) or None
        repo = self._find_repo(repo_arg)
        if repo is None:
            self.error(
                "cannot locate the sophia-agi git checkout — pass the path: "
                "/update /path/to/sophia-agi, or set SOPHIA_REPO",
                error_type="UpdateNoRepo", cmd="update",
            )
            return

        self.emit({"type": "update_start", "repo": str(repo), "canClaimAGI": False})

        build_dir = tempfile.mkdtemp(prefix="sophia-update-")
        try:
            def run_step(
                label: str,
                argv: list[str],
                cwd: str | None,
            ) -> subprocess.CompletedProcess[str] | None:
                self.emit({"type": "update_progress", "step": label,
                           "canClaimAGI": False})
                try:
                    proc = subprocess.run(
                        argv, cwd=cwd, capture_output=True, text=True,
                        timeout=300,
                    )
                except subprocess.TimeoutExpired:
                    self.emit({"type": "update_result", "ok": False,
                               "error": f"timed out during: {label}",
                               "canClaimAGI": False})
                    return
                except FileNotFoundError as exc:
                    self.emit({"type": "update_result", "ok": False,
                               "error": f"{label}: {exc}",
                               "canClaimAGI": False})
                    return None
                if proc.returncode != 0:
                    detail = (proc.stderr or proc.stdout or "").strip()
                    if len(detail) > 500:
                        detail = "…" + detail[-500:]
                    self.emit({"type": "update_result", "ok": False,
                               "error": f"{label} failed (exit {proc.returncode}): {detail}",
                               "canClaimAGI": False})
                    return None
                return proc

            if run_step(
                "fetching origin/main",
                ["git", "fetch", "origin", "main"],
                str(repo),
            ) is None:
                return
            resolved = run_step(
                "resolving origin/main",
                ["git", "rev-parse", "origin/main"],
                str(repo),
            )
            if resolved is None:
                return
            commit = resolved.stdout.strip().lower()
            if len(commit) != 40 or any(c not in "0123456789abcdef" for c in commit):
                self.emit({
                    "type": "update_result",
                    "ok": False,
                    "error": "resolving origin/main returned an invalid commit id",
                    "canClaimAGI": False,
                })
                return

            # Pin the archive to the resolved commit rather than reading the
            # moving origin/main ref again after the fetch.
            if run_step(
                "extracting source tree",
                [
                    "bash",
                    "-c",
                    'git archive "$1" | tar -x -C "$2"',
                    "sophia-update",
                    commit,
                    build_dir,
                ],
                str(repo),
            ) is None:
                return
            if run_step(
                "installing TUI dependencies",
                ["npm", "ci", "--silent"],
                str(Path(build_dir) / "apps" / "sophia-tui"),
            ) is None:
                return
            if run_step(
                "building TUI",
                ["npm", "run", "build"],
                str(Path(build_dir) / "apps" / "sophia-tui"),
            ) is None:
                return

            version = (Path(build_dir) / "VERSION").read_text().strip()
            installer = Path(build_dir) / "tools" / "install_sophia_source_checkout.py"
            if run_step(
                "installing source update",
                [
                    "python3",
                    str(installer),
                    "--source-root",
                    build_dir,
                    "--commit",
                    commit,
                ],
                str(repo),
            ) is None:
                return
            self.emit({
                "type": "update_result",
                "ok": True,
                "version": version,
                "commit": commit,
                "canClaimAGI": False,
            })
        finally:
            _shutil.rmtree(build_dir, ignore_errors=True)

    def _handle_approve(self, cmd: dict) -> None:
        approval_id = str(cmd.get("id") or "")
        with self.approvals_lock:
            box = self.approvals.get(approval_id)
            supervised = self.supervisor_approvals.pop(approval_id, None)
        if supervised is not None:
            client = supervised["client"]
            client.write_input(
                supervised["runId"],
                supervised["taskId"],
                json.dumps(
                    {
                        "cmd": "approve",
                        "id": supervised["workerApprovalId"],
                        "allow": _normalize_bool(cmd.get("allow")),
                    },
                    sort_keys=True,
                ),
            )
            return
        if box is None:
            self.error(f"no pending approval {approval_id!r}", error_type="UnknownApproval")
            return
        box["allow"] = _normalize_bool(cmd.get("allow"))
        box["event"].set()

    def _compound_workflow_service(self):
        from agent import harness as _h
        from agent.compound_workflow_bridge import CompoundWorkflowBridgeService

        # Resolve RUNS_DIR at command time. Tests and embedded deployments may
        # deliberately override it after the long-lived bridge was constructed.
        return CompoundWorkflowBridgeService(_h.RUNS_DIR)

    def _emit_compound_workflow_event(
        self, session: str, event: dict[str, Any]
    ) -> None:
        run_id = str(event.get("runId") or "")
        inner_event = dict(event)
        inner_event.setdefault("session", session)
        self.emit(
            {
                "type": "bridge_event",
                "runId": run_id,
                "session": session,
                "path": [],
                "lane": None,
                "ts": _now_iso(),
                # Keep engine event IDs, sequences, artifact references, and
                # digests exact. Protocol decoration uses setdefault and cannot
                # replace these durable identities.
                "event": inner_event,
                "canClaimAGI": False,
            }
        )

    def _emit_compound_workflow_failure(
        self,
        *,
        action: str,
        session: str,
        workflow_run_key: str | None,
        error: Any,
        replay: bool = False,
        storage_id: str | None = None,
    ) -> None:
        from agent.compound_workflow_bridge import failure_status_payload

        # Both records contain only the bridge-owned fixed message/code. Never
        # serialize the underlying exception: plans and durable files may hold
        # private initial input or provider diagnostics.
        self.error(
            error.message,
            error_type=error.code,
            cmd="compound_workflow",
            retryable=error.retryable,
        )
        status = failure_status_payload(
            action=action,
            session=session,
            workflow_run_key=workflow_run_key,
            error=error,
            replay=replay,
        )
        if storage_id:
            status["workflowStorageId"] = storage_id
        self.emit(status)

    def _handle_compound_workflow(self, cmd: dict) -> None:
        from agent.edition import edition_unavailable_message, is_oss_edition

        if is_oss_edition():
            action_value = str(cmd.get("action") or "replay").strip().lower()
            # Bridge-ready replay is a read of durable receipts. Failing it as
            # a user-visible OpenEdition error made every OSS boot show
            # `Error · /workflow is not part of Sophia Code`.
            if action_value in {"replay", "status", "events"}:
                self.emit({
                    "type": "compound_workflow_status",
                    "ok": True,
                    "action": action_value,
                    "workflows": [],
                    "canClaimAGI": False,
                })
                return
            self.error(
                edition_unavailable_message("workflow"),
                error_type="OpenEdition",
                cmd="compound_workflow",
                retryable=False,
            )
            return
        from agent.compound_workflow_bridge import (
            CompoundWorkflowCommandError,
            validate_compound_command,
        )

        session = _normalize_session(
            cmd.get("session") if cmd.get("session") is not None
            else CODE_DEFAULTS["session"]
        )
        action_value = cmd.get("action")
        action = (
            str(action_value)
            if action_value in {"run", "resume", "status", "events", "replay"}
            else "unknown"
        )
        request = None
        try:
            request = validate_compound_command(cmd, normalized_session=session)
            action = request.action
        except CompoundWorkflowCommandError as error:
            self._emit_compound_workflow_failure(
                action=action,
                session=session,
                workflow_run_key=None,
                error=error,
            )
            return
        except Exception:
            error = CompoundWorkflowCommandError(
                "CompoundWorkflowInternalError",
                "compound workflow command failed",
            )
            self._emit_compound_workflow_failure(
                action=action,
                session=session,
                workflow_run_key=None,
                error=error,
            )
            return

        # Holding run_lock for this bounded synchronous operation prevents a
        # normal agent run from starting midway through its event stream. The
        # fixed pure local registry is the v1 boundary; arbitrary/blocking work
        # would require a first-class async handle and cancellation protocol.
        with self.run_lock:
            with self.active_lock:
                active = self.active
            if active is not None:
                error = CompoundWorkflowCommandError(
                    "RunBusy",
                    "a run is already active — cancel it or wait",
                    retryable=True,
                )
                self._emit_compound_workflow_failure(
                    action=request.action,
                    session=request.session,
                    workflow_run_key=request.workflow_run_key,
                    error=error,
                )
                return
            if request.action == "replay":
                self._replay_compound_workflow_session(request.session)
                return
            try:
                outcome = self._compound_workflow_service().execute(
                    request,
                    emit_event=lambda event: self._emit_compound_workflow_event(
                        request.session, event
                    ),
                )
            except CompoundWorkflowCommandError as error:
                self._emit_compound_workflow_failure(
                    action=request.action,
                    session=request.session,
                    workflow_run_key=request.workflow_run_key,
                    error=error,
                )
                return
            except Exception:
                error = CompoundWorkflowCommandError(
                    "CompoundWorkflowInternalError",
                    "compound workflow command failed",
                )
                self._emit_compound_workflow_failure(
                    action=request.action,
                    session=request.session,
                    workflow_run_key=request.workflow_run_key,
                    error=error,
                )
                return
        self.emit(outcome.status_payload())

    def _replay_compound_workflow_session(self, session: str) -> None:
        from agent.compound_workflow_bridge import CompoundWorkflowCommandError

        try:
            report = self._compound_workflow_service().replay_session(
                session,
                emit_event=lambda event: self._emit_compound_workflow_event(
                    session, event
                ),
            )
        except CompoundWorkflowCommandError as error:
            self._emit_compound_workflow_failure(
                action="replay",
                session=session,
                workflow_run_key=None,
                error=error,
                replay=True,
            )
            return
        except Exception:
            error = CompoundWorkflowCommandError(
                "CompoundWorkflowInternalError",
                "compound workflow replay failed",
            )
            self._emit_compound_workflow_failure(
                action="replay",
                session=session,
                workflow_run_key=None,
                error=error,
                replay=True,
            )
            return
        for failure in report.failures:
            self._emit_compound_workflow_failure(
                action="replay",
                session=session,
                workflow_run_key=None,
                error=failure.error,
                replay=True,
                storage_id=failure.storage_id,
            )
        self.emit(
            {
                "type": "compound_workflow_status",
                "workflowCommandVersion": 1,
                "action": "replay",
                "session": session,
                "ok": not report.failures,
                "state": "replayed" if not report.failures else "partial",
                "replayedRunCount": report.run_count,
                "replayedEventCount": report.event_count,
                "failedRunCount": len(report.failures),
                "eventDeliveryFailures": report.delivery_failures,
                "candidateOnly": True,
                "canClaimAGI": False,
            }
        )

    def _handle_session_load(self, cmd: dict) -> None:
        from agent import cli as terminal_cli
        from agent.a2a_orchestration import load_latest_orchestration

        session = _normalize_session(cmd.get("session"))
        path = terminal_cli._conversation_path(session)
        try:
            turns = terminal_cli._load_conversation(path) or []
            # IMPORTANT: do NOT ship full tool dumps over NDJSON. A 50–100KB single
            # line stalled the TUI (flash then blank). Clients should read ``path``
            # from disk for the UI; the kernel already loads the same file for
            # history= on the next run. Emit a tiny scannable preview only.
            preview: list[dict[str, str]] = []
            for item in turns:
                role = str(item.get("role") or "")
                content = str(item.get("content") or "")
                if role == "user" and not content.startswith("[tool"):
                    preview.append({"role": "user", "content": content[:500]})
                elif role == "assistant" and content.strip() and not content.startswith("["):
                    preview.append({"role": "assistant", "content": content[:800]})
            preview = preview[-12:]
            orchestration = load_latest_orchestration(session)
            self.emit({
                "type": "session",
                "ok": True,
                "session": session,
                "path": str(path),
                "turns": len(turns),
                "transcript": preview,  # preview only — full file is at path
                "loadFromPath": True,
                "a2aOrchestration": orchestration,
                "canClaimAGI": False,
            })
        except Exception as exc:  # noqa: BLE001 - resume must never crash the bridge
            self.emit({
                "type": "session",
                "ok": False,
                "session": session,
                "path": str(path),
                "turns": 0,
                "transcript": [],
                "error": f"{type(exc).__name__}: {exc}",
                "canClaimAGI": False,
            })
    def _handle_steer(self, cmd: dict) -> None:
        prompt = str(cmd.get("prompt") or "").strip()
        session = _normalize_session(cmd.get("session"))
        run_id = str(cmd.get("runId") or "")
        request_id = cmd.get("requestId", cmd.get("requestID"))
        request_id = _safe_text(request_id, limit=128) if request_id is not None else None
        base = {"runId": run_id, "session": session, "canClaimAGI": False}
        if request_id is not None:
            base["requestId"] = request_id
            previous = self.request_acks.get(("steer", request_id))
            if previous is not None:
                self.emit({**previous, "duplicate": True})
                return
        with self.active_lock:
            active = self.active
        if not prompt or len(prompt) > MAX_PROMPT_CHARS:
            self.emit({"type": "steer_rejected", **base, "reason": "invalid prompt"})
            return
        if active is None:
            self.emit({"type": "steer_rejected", **base, "reason": "no active run"})
            return
        if active.get("id") != run_id or active.get("session") != session:
            self.emit({"type": "steer_rejected", **base, "reason": "run/session mismatch"})
            return
        with active["steer_lock"]:
            if len(active["steers"]) >= 32:
                self.emit({"type": "steer_rejected", **base, "reason": "steer queue full"})
                return
            active["steer_seq"] += 1
            seq = active["steer_seq"]
            active["steers"].append((seq, prompt, request_id))
        ack = {"type": "steer_ack", **base, "sequence": seq,
               "status": "queued", "command": "steer"}
        self._remember_request_ack("steer", request_id, ack)
        self.emit(ack)

    def _remember_request_ack(self, command: str, request_id: str | None,
                              payload: dict[str, Any]) -> None:
        if not request_id:
            return
        key = (command, request_id)
        self.request_acks[key] = dict(payload)
        while len(self.request_acks) > 256:
            self.request_acks.pop(next(iter(self.request_acks)))

    def _handle_queue_next(self, cmd: dict) -> None:
        prompt = str(cmd.get("prompt") or "").strip()
        request_id = cmd.get("requestId", cmd.get("requestID"))
        request_id = _safe_text(request_id, limit=128) if request_id is not None else None
        if request_id:
            previous = self.request_acks.get(("queue_next", request_id))
            if previous is not None:
                self.emit({**previous, "duplicate": True})
                return
        queue_id = _safe_text(
            cmd.get("queueId") or request_id or f"queue-{uuid.uuid4().hex[:10]}",
            limit=128,
        )
        session = _normalize_session(cmd.get("session"))
        base = {
            "type": "queue_next_ack",
            "command": "queue_next",
            "queueId": queue_id,
            "requestId": request_id,
            "session": session,
            "canClaimAGI": False,
        }
        if not prompt or len(prompt) > MAX_PROMPT_CHARS:
            ack = {**base, "ok": False, "status": "rejected", "reason": "invalid prompt"}
            self._remember_request_ack("queue_next", request_id, ack)
            self.emit(ack)
            return
        run_cmd = dict(cmd)
        run_cmd["cmd"] = "run"
        run_cmd["session"] = session
        run_cmd["prompt"] = prompt
        run_cmd.pop("queueId", None)
        root = _normalize_workspace_root(run_cmd.get("cwd"))
        plugin_lease_snapshot = self._plugin_lease_snapshot_for_queue(root)
        with self.queue_next_lock:
            if len(self.queue_next) >= MAX_QUEUE_NEXT:
                ack = {**base, "ok": False, "status": "rejected", "reason": "queue-next full"}
                self._remember_request_ack("queue_next", request_id, ack)
                self.emit(ack)
                return
            entry = {
                "queueId": queue_id,
                "requestId": request_id,
                "session": session,
                "callId": cmd.get("callId"),
                "attempt": cmd.get("attempt", 1),
                "cmd": run_cmd,
                "pluginLeaseSnapshot": plugin_lease_snapshot,
            }
            self.queue_next.append(entry)
            position = len(self.queue_next)
        ack = {**base, "ok": True, "status": "queued", "position": position}
        self._remember_request_ack("queue_next", request_id, ack)
        self.emit(ack)
        with self.active_lock:
            idle = self.active is None
        if idle:
            self._dispatch_next()

    def _dispatch_next(self) -> None:
        if self.shutdown.is_set():
            return
        with self.active_lock:
            if self.active is not None:
                return
        with self.queue_next_lock:
            if not self.queue_next:
                return
            entry = self.queue_next.pop(0)
        ack = {
            "type": "queue_next_ack",
            "ok": True,
            "status": "starting",
            "command": "queue_next",
            "queueId": entry.get("queueId"),
            "requestId": entry.get("requestId"),
            "callId": entry.get("callId"),
            "attempt": entry.get("attempt", 1),
            "session": entry.get("session"),
            "position": 0,
            "canClaimAGI": False,
        }
        self._remember_request_ack("queue_next", entry.get("requestId"), ack)
        self.emit(ack)
        plugin_lease_snapshot = entry.get("pluginLeaseSnapshot")
        run_cmd = self._sanitize_queued_plugin_settings(
            entry["cmd"],
            plugin_lease_snapshot,
        )
        if isinstance(plugin_lease_snapshot, Mapping):
            run_cmd["_pluginLeaseSnapshot"] = dict(
                plugin_lease_snapshot
            )
        run_id = self._handle_run(run_cmd)
        if run_id:
            return
        # A concurrent direct run won the race. Put the queued command back at
        # the front instead of losing it; its existing requestId keeps retries
        # idempotent within this bridge instance.
        with self.queue_next_lock:
            self.queue_next.insert(0, entry)
        deferred = {**ack, "status": "queued", "position": 1, "deferred": True}
        self._remember_request_ack("queue_next", entry.get("requestId"), deferred)
        self.emit(deferred)

    def _clear_queue_next(self, *, reason: str) -> None:
        with self.queue_next_lock:
            pending = self.queue_next[:]
            self.queue_next.clear()
        for entry in pending:
            ack = {
                "type": "queue_next_ack",
                "ok": False,
                "status": "rejected",
                "command": "queue_next",
                "queueId": entry.get("queueId"),
                "requestId": entry.get("requestId"),
                "session": entry.get("session"),
                "reason": reason,
                "canClaimAGI": False,
            }
            self._remember_request_ack("queue_next", entry.get("requestId"), ack)
            self.emit(ack)

    def _persist_partial_conversation(self, handle: dict) -> None:
        """Persist the transcript accumulated so far after a cancelled run.

        run_agent_loop keeps a live reference to its ``messages`` on the context
        (``ctx._live_messages``), re-pointed after auto-compaction. Saving it here
        means a mid-stream cancel leaves the session exactly where it got to, so
        the operator can resume immediately rather than losing every turn the run
        had already completed. Best-effort: a persistence failure must never mask
        the cancellation result. Only the top-level interactive run is tracked
        (the bridge sets ``ctx.session_name`` solely there), so subagent loops
        never overwrite the parent conversation.
        """
        try:
            from agent import cli as terminal_cli
            ctx = handle.get("_ctx")
            session = handle.get("session")
            messages = getattr(ctx, "_live_messages", None) if ctx is not None else None
            if not session or not messages:
                return
            terminal_cli._save_conversation(
                terminal_cli._conversation_path(session), list(messages))
        except Exception:  # noqa: BLE001 - persistence is best-effort
            pass

    def _handle_cancel(self, cmd: dict | None = None, *,
                       ack: bool | None = None) -> None:
        """Cancel the active run, optionally acknowledging it to the client.

        ``ack`` defaults to "acknowledge whenever this came from a real
        command" (``cmd is not None``). The stdin-EOF path must override it to
        ``False``: it still needs to record WHY the run ended, but the app is
        already gone, so writing a ``cancel_ack`` down a closed pipe would
        raise instead of letting the process exit cleanly.
        """
        reason = str((cmd or {}).get("reason") or "user_cancel").strip()
        if reason not in _CANCEL_MESSAGES:
            self.error(f"unsupported cancellation reason {reason!r}",
                       error_type="CancelReasonInvalid", cmd="cancel")
            return
        with self.active_lock:
            active = self.active
        if active is not None:
            active["cancelReason"] = reason
            active["cancel"].set()
            budget = active.get("budget")
            if budget is not None:
                budget.cancel()
        if ack if ack is not None else cmd is not None:
            self.emit({
                "type": "cancel_ack",
                "ok": True,
                "status": "cancelling" if active is not None else "idle",
                "stage": "requested",
                "runId": active.get("id") if active is not None else None,
                "session": active.get("session") if active is not None else None,
                "canClaimAGI": False,
            })

    def _wait_active(self, timeout: float = 30.0) -> None:
        """Block until the active run finishes (used for graceful shutdown/EOF)."""
        deadline = time.time() + timeout
        while time.time() < deadline:
            with self.active_lock:
                active = self.active
            if active is None:
                return
            thread = active.get("thread")
            if thread is None or not thread.is_alive():
                return
            thread.join(timeout=0.2)

    def _prime_runtime_for(self, session: str, root: Path) -> Any:
        """Return the persistent, policy-loaded Prime child for one session."""
        from agent.prime_agent_runtime import PrimeAgentRuntime

        root_text = str(root)
        with self.prime_lock:
            current = self.prime_sessions.get(session)
            if current is not None:
                current_root, runtime = current
                if current_root == root_text:
                    return runtime
                runtime.close()
                self.prime_sessions.pop(session, None)

            session_root = Path(
                os.environ.get("SOPHIA_PRIME_SESSION_ROOT")
                or (Path.home() / ".sophia" / "prime-agent" / "sessions")
            )
            session_dir = _prime_session_directory(session_root, session)
            extension = _repo_root() / "extensions" / "sophia-pi-gate" / "index.js"
            try:
                timeout_sec = float(
                    os.environ.get("SOPHIA_PRIME_AGENT_TIMEOUT_SEC") or 300.0
                )
            except ValueError:
                timeout_sec = 300.0
            runtime = PrimeAgentRuntime(
                cwd=root,
                session_dir=session_dir,
                extension_path=extension,
                timeout_sec=timeout_sec,
                policy_mode=os.environ.get("SOPHIA_PRIME_POLICY") or "advisory",
            )
            self.prime_sessions[session] = (root_text, runtime)
            return runtime

    def _close_prime_runtimes(self) -> None:
        """Stop only Prime children created by this bridge."""
        with self.prime_lock:
            runtimes = [runtime for _, runtime in self.prime_sessions.values()]
            self.prime_sessions.clear()
        for runtime in runtimes:
            try:
                runtime.close()
            except Exception:
                # Bridge shutdown is best-effort; each runtime owns only its
                # child, and one close failure must not strand later children.
                continue

    def _close_plugin_hosts(self) -> None:
        """Stop only plugin command hosts created and cached by this bridge."""
        with self.plugin_host_lock:
            hosts = list(self.plugin_hosts.values())
            self.plugin_hosts.clear()
        for host in hosts:
            try:
                has_active_lease = getattr(host, "has_active_lease", None)
                end_lease_and_publish = getattr(
                    host,
                    "end_lease_and_publish",
                    None,
                )
                if (
                    callable(has_active_lease)
                    and has_active_lease()
                    and callable(end_lease_and_publish)
                ):
                    end_lease_and_publish(
                        reason="bridge_closed",
                        publish=self._plugin_lease_end_publisher(host),
                    )
            except Exception:
                # Lease cleanup is best-effort during process shutdown. Still
                # close the owned host so its children cannot be stranded.
                pass
            try:
                host.close()
            except Exception:
                # Each host owns only its supervised children. Keep closing the
                # remaining hosts if one child refuses a best-effort shutdown.
                continue

    def close(self) -> None:
        """Deterministically close all process-local runtimes owned by the bridge."""
        self._close_plugin_hosts()
        self._close_prime_runtimes()

    def _run_plugin_external(
        self,
        handle: dict,
        *,
        host: Any,
        record: Any,
        runtime: dict[str, Any],
        prompt: str,
        root: Path,
        session: str,
        requested_model: str,
        mode: str,
        permission: str,
        response_style: str,
        conscience_mode: str,
        close_host: bool = True,
    ) -> dict[str, Any]:
        """Run one selected plugin runtime and quarantine all text until gated."""
        from agent import cli as terminal_cli
        from agent.epistemic_status import describe as describe_epistemic
        from extensions.sophia_pi_gate_compat import evaluate_prime_floor

        run_id = handle["id"]
        cancel: threading.Event = handle["cancel"]
        plugin_id = str(record.manifest.plugin_id)
        runtime_id = str(runtime.get("id") or "runtime")
        runtime_ref = f"{plugin_id}/{runtime_id}"
        provider = f"plugin:{runtime_ref}"
        self.bus.bridge_event(
            run_id,
            {
                "type": "run_start",
                "goal": prompt,
                "session": session,
                "model": provider,
                "requestedSophiaModel": requested_model,
                "mode": mode,
                "permission": "external-read-only-requested",
                "responseStyle": response_style,
                "team": 1,
                "deepThink": False,
                "executionRuntime": "plugin",
                "pluginRuntime": runtime_ref,
                "executionAuthority": "external-user-process",
                "streamingQuarantined": True,
                "candidateOnly": True,
                "canClaimAGI": False,
                **dict(handle.get("runtimeSource") or {}),
            },
        )
        self.bus.bridge_event(
            run_id,
            {
                "type": "external_runtime_notice",
                "runtime": "plugin",
                "pluginRuntime": runtime_ref,
                "detail": (
                    "The plugin runtime is an external process under the current "
                    "OS user. Sophia requests read-only operation, exposes no "
                    "plugin autonomy APIs, and buffers final text until the "
                    "mandatory delivery floor checks it. This is not an OS-level "
                    "sandbox guarantee."
                ),
                "candidateOnly": True,
                "canClaimAGI": False,
            },
        )
        started = time.time()
        from agent.deepseek_harness_adapter import ExternalRuntimeResult

        def consume_runtime_result(
            result: ExternalRuntimeResult,
        ) -> ExternalRuntimeResult:
            # execute_runtime invokes this bounded ownership transfer under
            # the plugin host's authority lock, after adapter cleanup and full
            # result construction.  A revocation therefore linearizes either
            # before this copy (and strips the result) or after the bridge has
            # consumed the quarantined output.
            return ExternalRuntimeResult(
                ok=bool(result.ok),
                text=str(result.text),
                error=str(result.error),
                meta=dict(result.meta),
            )

        try:
            external = host.execute_runtime(
                record,
                runtime,
                prompt=prompt,
                cancel_event=cancel,
                consume=consume_runtime_result,
            )
        finally:
            if close_host:
                host.close()
        elapsed = time.time() - started
        if cancel.is_set() or external.meta.get("cancelled"):
            raise _RunCancelled()
        if not external.ok:
            epistemic = describe_epistemic(
                verdict="",
                gated=False,
                strict=False,
                empty=True,
                floor_checked=False,
                runner=provider,
                reason=external.error,
                checks={
                    "executionAuthority": "external-user-process",
                    "requestedPermissionMode": "read-only",
                    "toolPolicyChecked": False,
                },
            ).to_dict()
            return {
                "ok": False,
                "error": external.error or "external plugin runtime failed",
                "goal": prompt,
                "finalText": "",
                "summary": "",
                "gated": False,
                "epistemic": epistemic,
                "permission": "external-read-only-requested",
                "requestedSophiaPermission": permission,
                "root": str(root),
                "steps": [],
                "filesTouched": [],
                "fileChanges": {},
                "certificate": {
                    "kind": "sophia-plugin-runtime-certificate",
                    "pluginRuntime": runtime_ref,
                    "executionAuthority": "external-user-process",
                    "requestedPermissionMode": "read-only",
                    "toolPolicyChecked": False,
                    "toolActionsApprovedBySophia": False,
                    "outputFloorChecked": False,
                    "streamingQuarantined": True,
                    "deliveryGatePassed": False,
                    "candidateOnly": True,
                    "canClaimAGI": False,
                },
                "session": {"id": session, "name": session},
                "model": provider,
                "requestedSophiaModel": requested_model,
                "provider": provider,
                "resolvedModel": "",
                "fallbackUsed": False,
                "mode": mode,
                "team": 1,
                "deepThink": False,
                "responseStyle": response_style,
                "conscienceMode": conscience_mode,
                "executionRuntime": "plugin",
                "pluginRuntime": runtime_ref,
                "executionAuthority": "external-user-process",
                "requestedPermissionMode": "read-only",
                "toolPolicyChecked": False,
                "toolActionsApprovedBySophia": False,
                "outputFloorChecked": False,
                "streamingQuarantined": True,
                "runtimeMeta": dict(external.meta),
                "elapsedSec": round(elapsed, 2),
                "candidateOnly": True,
                "canClaimAGI": False,
            }

        floor = evaluate_prime_floor(external.text)
        allowed = bool(floor.allow and floor.floorChecked)
        final_text = (
            external.text
            if allowed
            else "Sophia delivery floor withheld the external plugin answer. "
            "The text was not delivered unchecked."
        )
        gated = not allowed
        epistemic = describe_epistemic(
            verdict=floor.verdict,
            gated=gated,
            strict=False,
            empty=not final_text.strip(),
            floor_checked=floor.floorChecked,
            runner=provider,
            reason=floor.reason,
            checks={
                "executionRuntime": "plugin",
                "pluginRuntime": runtime_ref,
                "executionAuthority": "external-user-process",
                "requestedPermissionMode": "read-only",
                "toolPolicyChecked": False,
                "toolActionsApprovedBySophia": False,
                "outputFloorChecked": bool(floor.floorChecked),
            },
        ).to_dict()
        try:
            conversation_path = terminal_cli._conversation_path(session)
            history = terminal_cli._load_conversation(conversation_path) or []
            history.extend(
                [
                    {"role": "user", "content": prompt},
                    {"role": "assistant", "content": final_text},
                ]
            )
            terminal_cli._save_conversation(conversation_path, history)
        except Exception as exc:
            self.bus.bridge_event(
                run_id,
                {
                    "type": "transcript_warning",
                    "warning": (
                        "Sophia transcript mirror was not saved after the plugin "
                        f"runtime: {type(exc).__name__}"
                    ),
                    "candidateOnly": True,
                    "canClaimAGI": False,
                },
            )
        certificate = {
            "kind": "sophia-plugin-runtime-certificate",
            "deliveryGatePassed": allowed,
            "deliveryGated": gated,
            "executionRuntime": "plugin",
            "pluginRuntime": runtime_ref,
            "pluginVersion": record.manifest.version,
            "pluginDigest": record.manifest.digest,
            "executionAuthority": "external-user-process",
            "requestedPermissionMode": "read-only",
            "toolPolicyChecked": False,
            "toolActionsApprovedBySophia": False,
            "outputFloorChecked": bool(floor.floorChecked),
            "strictUncertaintyChecked": False,
            "streamingQuarantined": True,
            "permission": "external-read-only-requested",
            "requestedSophiaPermission": permission,
            "session": session,
            "team": 1,
            "deepThink": False,
            "candidateOnly": True,
            "canClaimAGI": False,
        }
        payload: dict[str, Any] = {
            "ok": allowed,
            "goal": prompt,
            "finalText": final_text,
            "summary": _summary(final_text),
            "confidence": "n/a",
            "gated": gated,
            "epistemic": epistemic,
            "tracePath": None,
            "permission": "external-read-only-requested",
            "requestedSophiaPermission": permission,
            "root": str(root),
            "steps": [],
            "filesTouched": [],
            "fileChanges": {},
            "logicJudge": {
                "verdict": "not_run",
                "reason": "external plugin runtime",
            },
            "certificate": certificate,
            "acceptanceReceipt": {},
            "session": {"id": session, "name": session},
            "model": provider,
            "requestedSophiaModel": requested_model,
            "provider": provider,
            "resolvedModel": "",
            "fallbackUsed": False,
            "mode": mode,
            "team": 1,
            "deepThink": False,
            "responseStyle": response_style,
            "conscienceMode": conscience_mode,
            "exactOutput": False,
            "gateBypass": False,
            "elapsedSec": round(elapsed, 2),
            "executionRuntime": "plugin",
            "pluginRuntime": runtime_ref,
            "executionAuthority": "external-user-process",
            "requestedPermissionMode": "read-only",
            "toolPolicyChecked": False,
            "toolActionsApprovedBySophia": False,
            "outputFloorChecked": bool(floor.floorChecked),
            "streamingQuarantined": True,
            "runtimeMeta": dict(external.meta),
            "display": {
                "summary": _summary(final_text),
                "confidence": "n/a",
                "statusLabel": (
                    "External plugin output checked" if allowed else "Held / failed"
                ),
                "toolCount": 0,
                "fileCount": 0,
                "executionRuntime": "plugin",
                "canClaimAGI": False,
            },
            "candidateOnly": True,
            "canClaimAGI": False,
        }
        fresh_state, _ = _load_state()
        fresh_defaults = _normalize_defaults(
            fresh_state.get("defaults")
            if isinstance(fresh_state.get("defaults"), dict)
            else {}
        )
        fresh_state["defaults"] = _normalize_defaults(
            {**fresh_defaults, "session": session, "cwd": str(root)}
        )
        fresh_state["selectedSessionID"] = session
        fresh_state["lastRun"] = {
            "command": "run",
            "ok": allowed,
            "runtime": "plugin",
            "pluginRuntime": runtime_ref,
            "provider": provider,
            "permission": permission,
            "session": session,
            "outputFloorChecked": bool(floor.floorChecked),
            "toolPolicyChecked": False,
            "updatedAt": _now_iso(),
            "canClaimAGI": False,
        }
        try:
            _save_state(fresh_state)
        except OSError as exc:
            self.bus.bridge_event(
                run_id,
                {
                    "type": "state_warning",
                    "warning": (
                        "plugin runtime result state was not saved: "
                        f"{type(exc).__name__}"
                    ),
                    "candidateOnly": True,
                    "canClaimAGI": False,
                },
            )
        return payload

    def _run_prime_external(
        self,
        handle: dict,
        cmd: dict,
        *,
        prompt: str,
        root: Path,
        session: str,
        requested_model: str,
        mode: str,
        permission: str,
        response_style: str,
        conscience_mode: str,
        defaults: dict[str, Any],
    ) -> dict[str, Any]:
        """Run Prime as a quarantined external backend, then floor-check text.

        Text deltas stay buffered inside :mod:`agent.prime_agent_runtime`.
        Streaming them to the transcript before the final floor runs would make
        a later veto cosmetic rather than preventive.
        """
        from agent import cli as terminal_cli
        from agent.epistemic_status import describe as describe_epistemic
        from extensions.sophia_pi_gate_compat import evaluate_prime_floor

        run_id = handle["id"]
        cancel: threading.Event = handle["cancel"]
        runtime = self._prime_runtime_for(session, root)
        if not runtime.policy_configured:
            return {
                "ok": False,
                "error": (
                    "Prime Agent policy extension is not configured in the launch "
                    "command; refusing external execution fail-closed."
                ),
                "executionRuntime": "prime",
                "executionAuthority": "external-user-process",
                "toolPolicyMode": runtime.policy_mode,
                "toolPolicyChecked": False,
                "toolActionsApprovedBySophia": False,
                "outputFloorChecked": False,
                "strictUncertaintyChecked": False,
                "streamingQuarantined": True,
                "primeAutonomyExposed": False,
                "candidateOnly": True,
                "canClaimAGI": False,
        }

        # Prime's own schedules/goals/subagents are intentionally not exposed in
        # v1. Sophia is the outer orchestrator and one Prime session is one lane.
        effective_permission = f"external-{runtime.policy_mode}"
        if runtime.policy_mode == "advisory":
            policy_detail = (
                "Advisory policy allows read/grep/find/ls only; final text is "
                "buffered until Sophia's delivery floor checks it."
            )
        else:
            policy_detail = (
                "Full policy leaves Prime's tool surface available under the "
                "current user's OS permissions; final text is buffered until "
                "Sophia's delivery floor checks it."
            )
        self.bus.bridge_event(run_id, {
            "type": "run_start",
            "goal": prompt,
            "session": session,
            "model": "prime-agent",
            "requestedSophiaModel": requested_model,
            "mode": mode,
            "permission": effective_permission,
            "responseStyle": response_style,
            "team": 1,
            "deepThink": False,
            "executionRuntime": "prime",
            "executionAuthority": "external-user-process",
            "toolPolicyMode": runtime.policy_mode,
            "streamingQuarantined": True,
            "primeAutonomyExposed": False,
            "candidateOnly": True,
            "canClaimAGI": False,
            **dict(handle.get("runtimeSource") or {}),
        })
        self.bus.bridge_event(run_id, {
            "type": "external_runtime_notice",
            "runtime": "prime",
            "detail": (
                "Prime runs as a user-level external process. "
                f"{policy_detail}"
            ),
            "candidateOnly": True,
            "canClaimAGI": False,
        })

        sink = self.bus.kernel_sink(run_id)
        buffered_notice_sent = False
        prime_tools: list[dict[str, Any]] = []

        def on_event(event: dict[str, Any]) -> None:
            nonlocal buffered_notice_sent
            if event.get("type") == "token":
                if not buffered_notice_sent:
                    buffered_notice_sent = True
                    self.bus.bridge_event(run_id, {
                        "type": "external_text_buffered",
                        "runtime": "prime",
                        "detail": "Prime text is quarantined pending Sophia floor evaluation.",
                        "candidateOnly": True,
                        "canClaimAGI": False,
                    })
                return
            if event.get("type") == "tool_call":
                prime_tools.append({
                    "tool": _safe_text(event.get("tool"), limit=80),
                    "callId": _safe_text(event.get("callId"), limit=120),
                    "ok": None,
                })
            elif event.get("type") == "tool_result":
                call_id = _safe_text(event.get("callId"), limit=120)
                matching = next(
                    (
                        tool
                        for tool in reversed(prime_tools)
                        if tool.get("callId") == call_id
                    ),
                    None,
                )
                if matching is not None:
                    matching["ok"] = event.get("ok") is not False
            sink(event)

        approver = _GuiApprover(self, run_id, cancel)

        def on_ui_request(event: dict[str, Any]) -> dict[str, Any]:
            method = str(event.get("method") or event.get("kind") or "").casefold()
            if method != "confirm":
                return {"cancelled": True}
            title = _safe_text(event.get("title") or "Prime Agent confirmation", limit=120)
            preview = _safe_text(event.get("message") or event.get("description") or "", limit=1200)
            return {"confirmed": approver(f"Prime: {title}", preview)}

        started = time.time()
        prime_result = runtime.run(
            prompt,
            cancel_event=cancel,
            on_event=on_event,
            on_ui_request=on_ui_request,
        )
        elapsed = time.time() - started
        if cancel.is_set() or prime_result.meta.get("cancelled"):
            raise _RunCancelled()

        if not prime_result.ok:
            epistemic = describe_epistemic(
                verdict="",
                gated=False,
                strict=False,
                empty=True,
                floor_checked=False,
                runner="prime",
                reason=prime_result.error,
                checks={
                    "executionAuthority": "external-user-process",
                    "toolPolicyChecked": bool(prime_result.meta.get("toolPolicyChecked")),
                },
            ).to_dict()
            return {
                "ok": False,
                "error": prime_result.error,
                "goal": prompt,
                "finalText": "",
                "summary": "",
                "gated": False,
                "epistemic": epistemic,
                "permission": effective_permission,
                "requestedSophiaPermission": permission,
                "root": str(root),
                "steps": [],
                "filesTouched": [],
                "fileChanges": {},
                "certificate": {
                    "kind": "sophia-external-runtime-certificate",
                    "executionRuntime": "prime",
                    "externalRuntimeVersion": runtime.runtime_version,
                    "executionAuthority": "external-user-process",
                    "toolPolicyMode": runtime.policy_mode,
                    "toolPolicyChecked": bool(prime_result.meta.get("toolPolicyChecked")),
                    "toolActionsApprovedBySophia": False,
                    "outputFloorChecked": False,
                    "strictUncertaintyChecked": False,
                    "streamingQuarantined": True,
                    "primeAutonomyExposed": False,
                    "deliveryGatePassed": False,
                    "canClaimAGI": False,
                },
                "session": {"id": session, "name": session},
                "model": "prime-agent",
                "requestedSophiaModel": requested_model,
                "provider": "prime-agent-runtime",
                "resolvedModel": "",
                "fallbackUsed": False,
                "mode": mode,
                "team": 1,
                "deepThink": False,
                "responseStyle": response_style,
                "conscienceMode": conscience_mode,
                "executionRuntime": "prime",
                "externalRuntimeVersion": runtime.runtime_version,
                "executionAuthority": "external-user-process",
                "toolPolicyMode": runtime.policy_mode,
                "toolPolicyChecked": bool(prime_result.meta.get("toolPolicyChecked")),
                "toolActionsApprovedBySophia": False,
                "outputFloorChecked": False,
                "strictUncertaintyChecked": False,
                "streamingQuarantined": True,
                "primeAutonomyExposed": False,
                "runtimeMeta": prime_result.meta,
                "elapsedSec": round(elapsed, 2),
                "candidateOnly": True,
                "canClaimAGI": False,
            }

        floor = evaluate_prime_floor(prime_result.text)
        allowed = bool(floor.allow and floor.floorChecked)
        final_text = (
            prime_result.text
            if allowed
            else "Sophia delivery floor withheld the external answer. "
            "The text was not delivered unchecked."
        )
        gated = not allowed
        epistemic = describe_epistemic(
            verdict=floor.verdict,
            gated=gated,
            strict=False,
            empty=not final_text.strip(),
            floor_checked=floor.floorChecked,
            runner="prime",
            reason=floor.reason,
            checks={
                "executionRuntime": "prime",
                "executionAuthority": "external-user-process",
                "toolPolicyChecked": bool(prime_result.meta.get("toolPolicyChecked")),
                "toolActionsApprovedBySophia": False,
                "outputFloorChecked": bool(floor.floorChecked),
            },
        ).to_dict()

        trajectory_receipt: dict[str, Any] = {}
        try:
            from agent.prime_trajectory import (
                append_prime_trajectory,
                make_prime_trajectory,
            )

            capture_content = _normalize_bool(
                os.environ.get("SOPHIA_PRIME_TRAJECTORY_CAPTURE"),
                default=False,
            )
            trajectory = make_prime_trajectory(
                session_id=session,
                run_id=run_id,
                runtime_version=runtime.runtime_version,
                prompt=prompt,
                output=prime_result.text,
                outcome="succeeded" if allowed else "withheld",
                floor_checked=bool(floor.floorChecked),
                floor_verdict=floor.verdict,
                tool_policy_checked=bool(
                    prime_result.meta.get("toolPolicyChecked")
                ),
                tools=prime_tools,
                capture_content=capture_content,
            )
            trajectory_path = append_prime_trajectory(trajectory)
            trajectory_receipt = {
                "trajectoryId": trajectory.trajectoryId,
                "trajectoryPath": str(trajectory_path),
                "trajectoryContentCaptured": capture_content,
                "trajectoryTrainingEligible": False,
            }
        except Exception as exc:
            self.bus.bridge_event(run_id, {
                "type": "trajectory_warning",
                "warning": (
                    "Prime trajectory quarantine record was not saved: "
                    f"{type(exc).__name__}"
                ),
                "candidateOnly": True,
                "canClaimAGI": False,
            })

        # Preserve a Sophia-side session transcript in addition to Prime's own
        # persistent session. A held answer records only the fixed abstention.
        try:
            conversation_path = terminal_cli._conversation_path(session)
            history = terminal_cli._load_conversation(conversation_path) or []
            history.extend([
                {"role": "user", "content": prompt},
                {"role": "assistant", "content": final_text},
            ])
            terminal_cli._save_conversation(conversation_path, history)
        except Exception as exc:
            self.bus.bridge_event(run_id, {
                "type": "transcript_warning",
                "warning": (
                    "Sophia transcript mirror was not saved after the Prime run: "
                    f"{type(exc).__name__}"
                ),
                "candidateOnly": True,
                "canClaimAGI": False,
            })

        certificate = {
            "kind": "sophia-external-runtime-certificate",
            "deliveryGatePassed": allowed,
            "deliveryGated": gated,
            "executionRuntime": "prime",
            "externalRuntimeVersion": runtime.runtime_version,
            "executionAuthority": "external-user-process",
            "toolPolicyMode": runtime.policy_mode,
            "toolPolicyChecked": bool(prime_result.meta.get("toolPolicyChecked")),
            "toolActionsApprovedBySophia": False,
            "outputFloorChecked": bool(floor.floorChecked),
            "strictUncertaintyChecked": False,
            "streamingQuarantined": True,
            "primeAutonomyExposed": False,
            "permission": effective_permission,
            "requestedSophiaPermission": permission,
            "session": session,
            "team": 1,
            "deepThink": False,
            "candidateOnly": True,
            "canClaimAGI": False,
        }
        payload: dict[str, Any] = {
            "ok": allowed,
            "goal": prompt,
            "finalText": final_text,
            "summary": _summary(final_text),
            "confidence": "n/a",
            "gated": gated,
            "epistemic": epistemic,
            "tracePath": None,
            "permission": effective_permission,
            "requestedSophiaPermission": permission,
            "root": str(root),
            "steps": [],
            "filesTouched": [],
            "fileChanges": {},
            "logicJudge": {"verdict": "not_run", "reason": "external runtime"},
            "certificate": certificate,
            # Prime is an external-runtime lane and has no AgentLoopResult.
            # Its floor certificate above is the authoritative acceptance
            # evidence; keep the kernel-only receipt surface explicitly empty.
            "acceptanceReceipt": {},
            "session": {"id": session, "name": session},
            "model": "prime-agent",
            "requestedSophiaModel": requested_model,
            "provider": "prime-agent-runtime",
            "resolvedModel": "",
            "fallbackUsed": False,
            "mode": mode,
            "team": 1,
            "deepThink": False,
            "responseStyle": response_style,
            "conscienceMode": conscience_mode,
            "exactOutput": False,
            "gateBypass": False,
            "elapsedSec": round(elapsed, 2),
            "executionRuntime": "prime",
            "externalRuntimeVersion": runtime.runtime_version,
            "executionAuthority": "external-user-process",
            "toolPolicyMode": runtime.policy_mode,
            "toolPolicyChecked": bool(prime_result.meta.get("toolPolicyChecked")),
            "toolActionsApprovedBySophia": False,
            "outputFloorChecked": bool(floor.floorChecked),
            "streamingQuarantined": True,
            "primeAutonomyExposed": False,
            "runtimeMeta": prime_result.meta,
            **trajectory_receipt,
            "display": {
                "summary": _summary(final_text),
                "confidence": "n/a",
                "statusLabel": "External output checked" if allowed else "Held / failed",
                "toolCount": int(prime_result.meta.get("toolsStarted") or 0),
                "fileCount": 0,
                "executionRuntime": "prime",
                "canClaimAGI": False,
            },
            "candidateOnly": True,
            "canClaimAGI": False,
        }

        fresh_state, _ = _load_state()
        fresh_defaults = _normalize_defaults(
            fresh_state.get("defaults")
            if isinstance(fresh_state.get("defaults"), dict)
            else {}
        )
        merged = {
            **fresh_defaults,
            "runtime": "prime",
            "session": session,
            "cwd": str(root),
        }
        fresh_state["defaults"] = _normalize_defaults(merged)
        fresh_state["selectedSessionID"] = session
        fresh_state["lastRun"] = {
            "command": "run",
            "ok": allowed,
            "runtime": "prime",
            "provider": "prime-agent-runtime",
            "resolvedModel": "",
            "permission": permission,
            "session": session,
            "outputFloorChecked": bool(floor.floorChecked),
            "toolPolicyChecked": bool(prime_result.meta.get("toolPolicyChecked")),
            "updatedAt": _now_iso(),
            "canClaimAGI": False,
        }
        try:
            _save_state(fresh_state)
        except OSError as exc:
            self.bus.bridge_event(run_id, {
                "type": "state_warning",
                "warning": f"run state was not saved: {type(exc).__name__}",
            })
        return payload

    def _handle_goal(self, cmd: dict) -> None:
        # Autonomous goal-continuation mode: reuse the interactive run machinery
        # (threading, cancellation, receipts, delivery gate, conversation memory)
        # but swap the single tool loop for run_goal_loop, which keeps generating
        # continuation prompts (restating the original goal) until the goal is
        # achieved, confidently unachievable, or a safety bound trips. See
        # agent/goal_harness.py and docs/09-Agent/Goal-Continuation-Harness.md.
        cmd = dict(cmd)
        cmd["goalMode"] = True
        self._handle_run(cmd)

    def _handle_agi(self, cmd: dict) -> None:
        """Control the opt-in durable AGI-shaped loop.

        Enabling/disabling changes future routing only.  Pause/stop is written
        to the active run's durable control file and observed at the next safe
        phase boundary; no foreign process or arbitrary PID is signalled.
        """
        from agent.agi_mode import AGIRunStore

        action = str(cmd.get("action") or "status").strip().lower()
        session = _normalize_session(
            cmd.get("session") or CODE_DEFAULTS["session"]
        )
        with self.active_lock:
            active = self.active

        if action in {"on", "off"}:
            self._handle_settings(
                {
                    "cmd": "settings",
                    "agiMode": action == "on",
                    **(
                        {"agiProfile": cmd.get("profile")}
                        if cmd.get("profile") is not None
                        else {}
                    ),
                }
            )
            return
        if action == "profile":
            self._handle_settings(
                {
                    "cmd": "settings",
                    "agiProfile": _normalize_agi_profile(cmd.get("profile")),
                }
            )
            return
        if action == "route":
            self._handle_settings(
                {
                    "cmd": "settings",
                    "agiRoute": _normalize_agi_route(cmd.get("route")),
                }
            )
            return
        if action in {"pause", "stop"}:
            store = active.get("agiStore") if isinstance(active, dict) else None
            if not isinstance(store, AGIRunStore):
                self.error(
                    "no active AGI-mode run",
                    error_type="AGIRunNotActive",
                    cmd="agi",
                )
                return
            control = store.request_control(
                action,
                _safe_text(cmd.get("reason") or "", limit=500),
            )
            self.emit(
                {
                    "type": "agi_control_ack",
                    "ok": True,
                    "action": action,
                    "runId": store.run_id,
                    "session": store.session,
                    "control": control,
                    "canClaimAGI": False,
                }
            )
            return
        if action == "approve":
            if active is not None:
                self.error(
                    "cannot approve and resume while another run is active",
                    error_type="RunBusy",
                    cmd="agi",
                )
                return
            requested = _safe_text(cmd.get("runId"), limit=160)
            store = (
                AGIRunStore(session, requested)
                if requested
                else AGIRunStore.latest(session)
            )
            state = store.read_state() if store else None
            pending = (
                state.get("pendingAction")
                if isinstance(state, dict)
                and isinstance(state.get("pendingAction"), dict)
                else {}
            )
            pending_action_id = _safe_text(pending.get("actionId"), limit=300)
            if (
                not store
                or not state
                or not pending_action_id
                or pending.get("authorizationRequired") is not True
            ):
                self.error(
                    "no pending authorization-gated AGI action was found",
                    error_type="AGIApprovalNotFound",
                    cmd="agi",
                )
                return
            requested_action_id = _safe_text(cmd.get("actionId"), limit=300)
            if requested_action_id and requested_action_id != pending_action_id:
                self.error(
                    (
                        f"approval actionId {requested_action_id!r} does not match "
                        f"pending action {pending_action_id!r}"
                    ),
                    error_type="AGIApprovalMismatch",
                    cmd="agi",
                )
                return
            target_action_id = pending_action_id
            control = store.request_control(
                "approve",
                _safe_text(cmd.get("reason") or "approved by operator", limit=500),
                target_action_id=target_action_id,
            )
            self.emit(
                {
                    "type": "agi_control_ack",
                    "ok": True,
                    "action": "approve",
                    "actionId": target_action_id,
                    "runId": store.run_id,
                    "session": store.session,
                    "control": control,
                    "canClaimAGI": False,
                }
            )
            resume_cmd = dict(cmd)
            resume_cmd.update(
                {
                    "cmd": "run",
                    "prompt": str(state.get("goal") or "").strip(),
                    "session": session,
                    "agiMode": True,
                    "agiResumeRunId": store.run_id,
                    "autoGoal": False,
                }
            )
            self._handle_run(resume_cmd)
            return
        if action == "resume":
            requested = _safe_text(cmd.get("runId"), limit=160)
            store = (
                AGIRunStore(session, requested)
                if requested
                else AGIRunStore.latest(session)
            )
            state = store.read_state() if store else None
            if not store or not state:
                self.error(
                    "no durable AGI-mode run was found for this session",
                    error_type="AGIRunNotFound",
                    cmd="agi",
                )
                return
            resume_cmd = dict(cmd)
            resume_cmd.update(
                {
                    "cmd": "run",
                    "prompt": str(state.get("goal") or "").strip(),
                    "session": session,
                    "agiMode": True,
                    "agiResumeRunId": store.run_id,
                    "autoGoal": False,
                }
            )
            self._handle_run(resume_cmd)
            return
        if action in {"start", "run"}:
            run_cmd = dict(cmd)
            run_cmd.update(
                {
                    "cmd": "run",
                    "agiMode": True,
                    "autoGoal": False,
                }
            )
            self._handle_run(run_cmd)
            return
        if action != "status":
            raise ValueError(
                "agi action must be on, off, status, pause, resume, stop, "
                "approve, profile, route, or start"
            )

        store = None
        if isinstance(active, dict):
            candidate = active.get("agiStore")
            if isinstance(candidate, AGIRunStore):
                store = candidate
        store = store or AGIRunStore.latest(session)
        state = store.read_state() if store else None
        state_view = dict(state) if isinstance(state, dict) else None
        active_store = active.get("agiStore") if isinstance(active, dict) else None
        if (
            state_view
            and str(state_view.get("status") or "") == "running"
            and active_store is not store
        ):
            state_view["status"] = "interrupted"
            state_view["reason"] = (
                "durable state says running, but this bridge does not own an active "
                "controller; inspect or resume the run"
            )
        # The durable state contains full phase transcripts and model messages,
        # which can exceed a megabyte. Status clients only need the controller
        # projection below; sending the entire checkpoint can overflow desktop
        # bridge line limits and leaks implementation detail into every poll.
        status_keys = {
            "runId",
            "session",
            "status",
            "reason",
            "cycle",
            "currentPhase",
            "route",
            "routeReason",
            "config",
            "correction",
            "pendingAction",
            "deterministicEvidence",
            "verifierIndependent",
            "candidateOnly",
            "canClaimAGI",
        }
        if state_view:
            state_view = {
                key: state_view[key]
                for key in status_keys
                if key in state_view
            }
            state_view["statePath"] = str(store.state_path) if store else ""
        persisted, _ = _load_state()
        defaults = _normalize_defaults(
            persisted.get("defaults")
            if isinstance(persisted.get("defaults"), dict)
            else {}
        )
        self.emit(
            {
                "type": "agi_status",
                "ok": True,
                "enabled": bool(defaults.get("agiMode")),
                "workflowMode": defaults.get("agiWorkflowMode") or "off",
                "profile": defaults.get("agiProfile"),
                "route": defaults.get("agiRoute"),
                "plannerModel": defaults.get("agiPlannerModel") or "",
                "workerModel": defaults.get("agiWorkerModel") or "",
                "verifierModel": defaults.get("agiVerifierModel") or "",
                "session": session,
                "run": state_view,
                "statePath": str(store.state_path) if store else "",
                "canClaimAGI": False,
            }
        )

    def _handle_run(self, cmd: dict) -> str | None:
        prompt = str(cmd.get("prompt") or "").strip()
        if len(prompt) > MAX_PROMPT_CHARS:
            self.error(f"prompt exceeds {MAX_PROMPT_CHARS} characters", error_type="CommandTooLarge", cmd="run")
            return None
        if "gateBypass" in cmd:
            self.error("frontend gateBypass is not permitted", error_type="GateBypassRejected", cmd="run")
            return None
        with self.run_lock:
            with self.active_lock:
                active = self.active
            if active is not None:
                self.error("a run is already active — cancel it or wait",
                           error_type="RunBusy", cmd="run")
                return None
            run_id = f"run-{uuid.uuid4().hex[:8]}"
            handle = {"id": run_id, "cancel": threading.Event(), "thread": None,
                      "startedAt": _now_iso(),
                      "startedMonotonic": time.monotonic(),
                      "cancelReason": None,
                      "requestId": cmd.get("requestId", cmd.get("requestID")),
                      "callId": (
                          cmd.get("callId") or cmd.get("requestId")
                          or cmd.get("requestID") or f"call-{uuid.uuid4().hex[:12]}"
                      ),
                      "attempt": max(1, _safe_int(cmd.get("attempt"), 1)),
                      "parentEventId": cmd.get("parentEventId"),
                      "session": _normalize_session(cmd.get("session") or CODE_DEFAULTS["session"]),
                      "steers": [], "steer_seq": 0, "steer_lock": threading.Lock(),
                      "terminal": False, "diagnostics": []}
            with self.active_lock:
                self.active = handle
        if self.sync:
            self._execute_run(handle, cmd)
        else:
            thread = threading.Thread(target=self._execute_run, args=(handle, cmd),
                                      name=f"code-bridge-{run_id}", daemon=True)
            handle["thread"] = thread
            thread.start()
        return run_id

    # -- run execution ----------------------------------------------------- #
    def _execute_run(self, handle: dict, cmd: dict) -> None:
        run_id = handle["id"]
        cancel: threading.Event = handle["cancel"]
        try:
            result = self._run_guarded(handle, cmd)
        except _RunCancelled:
            reason = handle.get("cancelReason") or "user_cancel"
            result = _cancel_result(reason)
        except Exception as exc:  # noqa: BLE001
            result = {"ok": False, "error": f"{type(exc).__name__}: {exc}",
                      "errorPayload": _safe_error_payload(message=f"{type(exc).__name__}: {exc}",
                                                          error_type=type(exc).__name__)}
        budget_cancelled = (handle.get("budget") is not None
                            and handle["budget"].snapshot().cancelled)
        if cancel.is_set() or budget_cancelled:
            reason = handle.get("cancelReason") or ("budget_cancel" if budget_cancelled else "user_cancel")
            result = _cancel_result(reason, diagnostics=handle.get("diagnostics"))
        # A mid-run cancel must not lose the work already done: persist the
        # partial transcript so the session resumes immediately afterwards
        # (the operator can re-run and continue from where they stopped, instead
        # of the conversation file silently reverting to the pre-run state).
        if result.get("cancelled"):
            self._persist_partial_conversation(handle)
            result["cancelStage"] = "completed"
        result.setdefault("runId", run_id)
        if handle.get("provenanceStem"):
            status = (
                "cancelled" if result.get("cancelled")
                else "succeeded" if result.get("ok")
                else "failed"
            )
            terminal = {
                "type": "run_terminal",
                "timestamp": _now_iso(),
                "status": status,
                "provider": str(result.get("provider") or ""),
                "resolvedModel": str(result.get("resolvedModel") or ""),
                "fallbackUsed": bool(result.get("fallbackUsed")),
            }
            if result.get("cancelReason"):
                terminal["cancelReason"] = str(result["cancelReason"])
            try:
                self._write_run_provenance(handle, terminal, "terminal")
            except OSError as exc:
                self.bus.bridge_event(run_id, {
                    "type": "provenance_warning",
                    "warning": f"run provenance was not saved: {type(exc).__name__}",
                })
        workflow_task_id = handle.get("workflowTaskId")
        try:
            store = self._receipt_store(run_id)
            final_state = TaskState.CANCELLED if result.get("cancelled") else (TaskState.SUCCEEDED if result.get("ok") else TaskState.FAILED)
            if workflow_task_id:
                detail = {"ok": bool(result.get("ok"))}
                if result.get("cancelReason"):
                    detail["cancelReason"] = result["cancelReason"]
                if result.get("awaitingInput"):
                    # Receipt schema retains FAILED as the run's terminal state
                    # for backward compatibility, while this explicit detail
                    # lets current clients render the workflow as paused/blocked
                    # instead of an ordinary execution failure.
                    detail["awaitingInput"] = True
                    detail["goalStatus"] = "awaiting_input"
                if result.get("incomplete"):
                    detail["incomplete"] = True
                    detail["resumable"] = bool(result.get("resumable"))
                    if result.get("incompleteReason"):
                        detail["incompleteReason"] = str(result["incompleteReason"])
                node = store.transition(workflow_task_id, final_state, detail=detail)
                self._receipt_emit("workflow.finished", {"state": final_state.value, **detail},
                                   run_id=run_id, request_id=handle.get("requestId"),
                                   session_id=handle.get("session"), task_id=node.task_id)
        except Exception:
            # Receipt/lifecycle bookkeeping is best-effort; a failure here must
            # not prevent the run's actual result from being emitted below.
            pass
        result["type"] = "result"
        if handle.get("requestId") is not None:
            result["requestId"] = _safe_text(handle["requestId"], limit=128)
        result["ts"] = _now_iso()
        result["canClaimAGI"] = False
        if handle.get("dispatchManifestPath"):
            result["dispatchManifestPath"] = str(
                handle["dispatchManifestPath"]
            )
            result["dispatchManifestSchema"] = (
                "sophia.dispatch-manifest.v1"
            )
        dispatch_manifest = handle.get("_dispatchManifest")
        if dispatch_manifest is not None:
            try:
                terminal_status = (
                    "cancelled"
                    if result.get("cancelled")
                    else "succeeded"
                    if result.get("ok")
                    else "failed"
                )
                terminal_snapshot = dispatch_manifest.set_status(
                    terminal_status,
                    phase="output",
                    main_status=terminal_status,
                )
                self._publish_dispatch_manifest(
                    handle,
                    snapshot=terminal_snapshot,
                )
            except Exception as exc:  # noqa: BLE001 - telemetry must not sink result
                self.bus.bridge_event(
                    run_id,
                    {
                        "type": "dispatch_manifest_warning",
                        "warning": f"{type(exc).__name__}: {exc}"[:400],
                        "candidateOnly": True,
                        "canClaimAGI": False,
                    },
                )
        result.update(self._context_usage(handle))
        with handle["steer_lock"]:
            pending = handle["steers"][:]
            handle["steers"].clear()
        for seq, _, request_id in pending:
            self.emit({"type": "steer_rejected", "runId": run_id,
                       "session": handle.get("session", ""),
                       "requestId": request_id, "sequence": seq,
                       "reason": "run reached terminal boundary; no safe steering point",
                       "canClaimAGI": False})
        # Hold the run-state lock from the moment ``result`` becomes visible
        # through active-state cleanup. A client may submit its next run as
        # soon as it reads ``result``; without this lock the command thread can
        # observe the old handle and incorrectly reject the new run as busy.
        # Keep the active handle present while emitting so protocol metadata
        # still inherits the run's call/root identifiers.
        try:
            with self.run_lock:
                with self.active_lock:
                    handle["terminal"] = True
                try:
                    self._end_plugin_task_lease(handle)
                except Exception as exc:  # noqa: BLE001 - terminal cleanup
                    try:
                        self.emit(
                            {
                                "type": "plugin_cleanup_warning",
                                "runId": run_id,
                                "warning": (
                                    "plugin lease cleanup failed: "
                                    f"{type(exc).__name__}: {exc}"
                                )[:800],
                                "candidateOnly": True,
                                "canClaimAGI": False,
                            }
                        )
                    except Exception:
                        pass
                try:
                    self.emit(result)
                    # ``result`` carries the assistant answer and compatibility
                    # metadata. ``run_finished`` is the connector-facing
                    # terminal boundary and may be deferred until an abandoned
                    # provider lane has actually returned.
                    self._finalize_run_finished(handle, result)
                finally:
                    with self.active_lock:
                        if self.active is handle:
                            self.active = None
        finally:
            self._dispatch_next()

    def _run_guarded(self, handle: dict, cmd: dict) -> dict[str, Any]:
        from agent import cli as terminal_cli
        from agent import model as m
        from agent.agent_loop import _prompt_requires_initial_tool, run_agent_loop
        from agent.agent_tools import ToolContext, all_tools
        from agent.orchestration_first import decide_orchestration

        run_id = handle["id"]
        cancel: threading.Event = handle["cancel"]
        request_id = _safe_text(handle.get("requestId"), limit=128) if handle.get("requestId") else None
        session_hint = handle.get("session")
        requested_internal_artifact = _normalize_bool(
            cmd.get("internalArtifact"),
            default=False,
        )
        supervised_task_id = str(
            os.environ.get("SOPHIA_SUPERVISED_TASK_ID") or ""
        ).strip()
        internal_artifact = bool(
            requested_internal_artifact
            and supervised_task_id
            and request_id == supervised_task_id
        )
        if requested_internal_artifact and not internal_artifact:
            raise ValueError(
                "internalArtifact is reserved for the matching supervised "
                "workflow worker"
            )
        handle["internalArtifact"] = internal_artifact
        receipt_store = self._receipt_store(run_id)
        # Recording this process's pid on the root node is what lets a LATER
        # process (this one restarted, or a fresh session) tell "still
        # running" apart from "the process that was running it is gone" —
        # see _reconcile_dead_run / TaskReceiptStore.reconcile_orphaned.
        workflow_task = self._receipt_task(receipt_store, "workflow", TaskKind.WORKFLOW,
                                           request_id=request_id, session=session_hint,
                                           can_cancel=True, can_retry=False,
                                           detail={"pid": os.getpid()})
        handle["workflowTaskId"] = workflow_task.task_id
        receipt_store.transition(workflow_task.task_id, TaskState.RUNNING)
        self._receipt_emit("workflow.started", {"state": "running"}, run_id=run_id,
                           request_id=request_id, session_id=session_hint, task_id=workflow_task.task_id)

        def steering_consumer() -> list[str]:
            with handle["steer_lock"]:
                pending = handle["steers"][:]
                handle["steers"].clear()
            for seq, _, request_id in pending:
                self.emit({"type": "steer_applied", "runId": run_id,
                           "session": handle.get("session", ""),
                           "requestId": request_id, "sequence": seq,
                           "canClaimAGI": False})
            return [prompt for _, prompt, _ in pending]

        state, _ = _load_state()
        defaults = _normalize_defaults(state.get("defaults") if isinstance(state.get("defaults"), dict) else {})
        execution_runtime = _normalize_runtime(
            cmd.get("runtime")
            if cmd.get("runtime") is not None
            else defaults.get("runtime")
        )
        model_alias = _normalize_model(cmd.get("model") if cmd.get("model") is not None else defaults["model"])
        mode = _normalize_mode(cmd.get("mode") if cmd.get("mode") is not None else defaults["mode"])
        permission = _normalize_permission(
            cmd.get("permission") if cmd.get("permission") is not None else defaults["permission"])
        session = _normalize_session(cmd.get("session") if cmd.get("session") is not None else defaults["session"])
        handle["session"] = session
        cwd = str(
            cmd.get("cwd") or defaults.get("cwd") or ""
        ).strip() or None
        root = _normalize_workspace_root(cwd)
        if not root.is_dir():
            # The usual cause is a REMEMBERED workspace, not a bad argument:
            # run state persists the last cwd, so a folder that has since been
            # moved, deleted, or evicted turns every later run into a failure.
            # Never silently fall back to another directory.
            raise ValueError(
                f"workspace folder not found: {root} — this session remembers a "
                "workspace that is no longer there (moved, deleted, or on a "
                "cloud/network mount that is not currently available). Relaunch "
                "from the directory you want (cd <dir> && sophia) or pass "
                "--cwd <dir>."
            )
        ended_leases = self._expire_unbound_plugin_task_leases(
            root,
            session_id=session,
        )
        cmd = self._sanitize_expired_plugin_settings(
            cmd,
            ended_leases,
        )
        queued_lease_snapshot = cmd.pop(
            "_pluginLeaseSnapshot",
            None,
        )
        queued_plugin_host = None
        if isinstance(queued_lease_snapshot, Mapping):
            queued_plugin_host, cmd = (
                self._bind_queued_plugin_lease_for_run(
                    root,
                    session_id=session,
                    run_id=run_id,
                    cmd=cmd,
                    snapshot=queued_lease_snapshot,
                )
            )
        # Carried so the terminal result can report context usage against
        # THIS model's window (see _context_usage).
        handle["model"] = model_alias
        deep_think = _normalize_bool(cmd.get("deepThink"), default=bool(defaults["deepThink"]))
        deep_mode = _normalize_bool(cmd.get("deepMode"), default=bool(defaults.get("deepMode")))
        team = _normalize_team(cmd.get("team") if cmd.get("team") is not None else defaults["team"])
        configured_team = team
        auto_team_setting = _normalize_optional_bool(
            cmd.get("autoTeam") if "autoTeam" in cmd else defaults.get("autoTeam"))
        auto_team_enabled = auto_team_setting is True
        auto_team_capability = _auto_team_capability(model_alias)
        auto_team_capable = bool(auto_team_capability["capable"])
        a2a_agents = _normalize_a2a_agents(
            cmd.get("a2aAgents") if "a2aAgents" in cmd else defaults.get("a2aAgents"),
            cmd.get("a2a") if "a2a" in cmd else None,
        )
        a2a_execution = _normalize_a2a_execution(
            cmd.get("a2aExecution")
            if cmd.get("a2aExecution") is not None
            else defaults.get("a2aExecution")
        )
        terminal_layout = _normalize_terminal_layout(
            cmd.get("terminalLayout")
            if cmd.get("terminalLayout") is not None
            else defaults.get("terminalLayout")
        )
        if terminal_layout == "off":
            a2a_execution = "embedded"
        elif terminal_layout == "headless":
            a2a_execution = "headless"
        workflow_mode = _normalize_workflow_mode(
            cmd.get("workflowMode")
            if cmd.get("workflowMode") is not None
            else defaults.get("workflowMode")
        )
        workflow_max_stages = _normalize_workflow_max_stages(
            cmd.get("workflowMaxStages")
            if cmd.get("workflowMaxStages") is not None
            else defaults.get("workflowMaxStages")
        )
        workflow_max_agents = _normalize_workflow_max_agents(
            cmd.get("workflowMaxAgents")
            if cmd.get("workflowMaxAgents") is not None
            else defaults.get("workflowMaxAgents")
        )
        workflow_chart_path = _normalize_workflow_chart_path(
            cmd.get("workflowChartPath")
            if cmd.get("workflowChartPath") is not None
            else defaults.get("workflowChartPath")
        )
        agi_workflow_mode = _normalize_workflow_mode(
            cmd.get("agiWorkflowMode")
            if cmd.get("agiWorkflowMode") is not None
            else defaults.get("agiWorkflowMode")
        )
        agi_mode = _normalize_bool(
            cmd.get("agiMode")
            if "agiMode" in cmd
            else defaults.get("agiMode")
        )
        if agi_workflow_mode != "off":
            # `/agi-workflow` is one AGI-controller route, not a competing
            # top-level controller.  It owns supervised A2A prerequisites for
            # the current run so stale persisted Team/A2A settings cannot make
            # the requested route inert before the first node.
            agi_mode = True
            team = 1
            auto_team_setting = False
            auto_team_enabled = False
            if a2a_agents == 0:
                a2a_agents = -1
            if a2a_execution not in {"terminal", "headless"}:
                a2a_execution = "terminal"
            if terminal_layout == "off":
                terminal_layout = "auto"
        agi_profile = _normalize_agi_profile(
            cmd.get("agiProfile")
            if cmd.get("agiProfile") is not None
            else defaults.get("agiProfile")
        )
        agi_route = _normalize_agi_route(
            cmd.get("agiRoute")
            if cmd.get("agiRoute") is not None
            else defaults.get("agiRoute")
        )
        completion_mode = str(
            cmd.get("completionMode") or defaults.get("completionMode") or ""
        ).strip().lower()
        if completion_mode not in {"", "contract_solo", "contract_gap_closure"}:
            raise ValueError(
                "completionMode must be contract_solo or contract_gap_closure"
            )
        if completion_mode:
            # Contract modes are deliberately one-worker and cannot silently
            # inherit AGI/A2A/team routing from persisted settings.
            # ``completionMode`` is command-scoped: it is intentionally not
            # included in normalized/persisted defaults, so a one-off harness
            # arm cannot silently become the next launch's default.
            handle["completionMode"] = completion_mode
            agi_mode = False
            agi_workflow_mode = "off"
            team = 1
            a2a_agents = 0
            auto_team_setting = False
            cmd = {
                **cmd,
                "agiMode": False,
                "team": 1,
                "a2aAgents": 0,
                "autoTeam": False,
            }
        chart_route_blocked_reason = ""
        chart_route_forced = False
        if workflow_chart_path:
            # A chart is an explicit workflow route, not a hint for AUTO.  The
            # TUI normally writes these prerequisites atomically, but the
            # kernel must also protect direct bridge callers and stale
            # persisted settings from silently turning the selected chart into
            # a solo run.
            if execution_runtime == "prime":
                raise ValueError(
                    "flowchart workflow is owned by the Sophia kernel and "
                    "cannot run in the Prime backend"
                )
            elif (
                "workflowMode" in cmd
                and workflow_mode == "off"
            ):
                chart_route_blocked_reason = (
                    "operator-owned workflowMode=off declined the selected "
                    "flowchart; clear workflowMode=off or select the chart "
                    "through /workflow use-file"
                )
            elif (
                "completionMode" in cmd
                or completion_mode
            ):
                chart_route_blocked_reason = (
                    "completion mode is incompatible with a selected "
                    "flowchart workflow"
                )
            elif "team" in cmd and team > 1:
                chart_route_blocked_reason = (
                    "operator-owned team routing conflicts with the selected "
                    "flowchart"
                )
            elif "agiMode" in cmd and agi_mode:
                chart_route_blocked_reason = (
                    "operator-owned AGI mode conflicts with the selected "
                    "flowchart"
                )
            elif (
                "agiWorkflowMode" in cmd
                and agi_workflow_mode != "off"
            ):
                chart_route_blocked_reason = (
                    "operator-owned AGI workflow routing conflicts with the "
                    "selected flowchart"
                )
            else:
                # These are routing prerequisites, not execution instructions
                # supplied by the chart.  Force them at the kernel boundary so
                # a stale AUTO/A2A/team snapshot cannot bypass the file graph.
                workflow_mode = "on"
                a2a_agents = -1
                a2a_execution = "terminal"
                terminal_layout = "auto"
                team = 1
                auto_team_setting = False
                auto_team_enabled = False
                agi_mode = False
                agi_workflow_mode = "off"
                chart_route_forced = True
        agi_planner_model = _normalize_agi_role_model(
            cmd.get("agiPlannerModel")
            if cmd.get("agiPlannerModel") is not None
            else defaults.get("agiPlannerModel")
        )
        agi_worker_model = _normalize_agi_role_model(
            cmd.get("agiWorkerModel")
            if cmd.get("agiWorkerModel") is not None
            else defaults.get("agiWorkerModel")
        )
        agi_verifier_model = _normalize_agi_role_model(
            cmd.get("agiVerifierModel")
            if cmd.get("agiVerifierModel") is not None
            else defaults.get("agiVerifierModel")
        )
        # Parallel team and A2A-owned routes are mutually exclusive for one run.
        # a2a_agents: 0=off, -1=auto (Main decides), >=2=fixed legacy total.
        if team > 1 and a2a_agents != 0:
            a2a_agents = 0
        if workflow_chart_path:
            # Keep the selected chart on the workflow branch even when an
            # explicit operator-owned setting declined it.  The branch emits
            # a chart-specific failed result; it must never fall through to
            # ordinary solo execution.
            effective_workflow_mode = "on"
        elif team > 1 or agi_mode:
            # Preserve the persisted preference but make the current run's
            # ownership unambiguous. AGI and Team have their own controllers.
            effective_workflow_mode = "off"
        else:
            effective_workflow_mode = workflow_mode
        max_steps = max(1, min(256, _safe_int(cmd.get("maxSteps"), defaults["maxSteps"])))
        skill_name = str(cmd.get("skill") or "").strip() or None
        gate_bypass = _normalize_bool(cmd.get("gateBypass"), default=bool(defaults.get("gateBypass")))
        conscience_mode = _normalize_conscience_mode(
            cmd.get("conscienceMode")
            if cmd.get("conscienceMode") is not None
            else defaults.get("conscienceMode")
        )
        sophia_contract = _normalize_bool(
            cmd.get("sophiaContract", cmd.get("claudeCode")),
            default=True,
        )
        branch_from = cmd.get("branchFrom") if isinstance(cmd.get("branchFrom"), dict) else None
        prompt = str(cmd.get("prompt") or "").strip()
        if not prompt:
            raise ValueError("prompt is required")
        if len(prompt) > MAX_PROMPT_CHARS:
            raise ValueError(f"prompt exceeds {MAX_PROMPT_CHARS} characters")
        if "gateBypass" in cmd:
            raise ValueError("frontend gateBypass is not permitted")
        effort = _normalize_effort(cmd.get("effort") if cmd.get("effort") is not None else defaults.get("effort"))
        response_style = _normalize_response_style(
            cmd.get("responseStyle") if cmd.get("responseStyle") is not None
            else defaults.get("responseStyle"))
        semantic_fallback_model = _normalize_semantic_fallback_model(
            cmd.get("semanticFallbackModel")
            if "semanticFallbackModel" in cmd
            else defaults.get("semanticFallbackModel")
        )
        semantic_fallback_policy = _normalize_semantic_fallback_policy(
            cmd.get("semanticFallbackPolicy")
            if "semanticFallbackPolicy" in cmd
            else defaults.get("semanticFallbackPolicy")
        )
        semantic_return_to_primary = _normalize_bool(
            cmd.get("semanticReturnToPrimary")
            if "semanticReturnToPrimary" in cmd
            else defaults.get("semanticReturnToPrimary"),
            default=True,
        )
        raw_budget = cmd.get("budget") if isinstance(cmd.get("budget"), dict) else defaults.get("budget", {})
        raw_budget = raw_budget if isinstance(raw_budget, dict) else {}
        limits = Limits(**{k: raw_budget[k] for k in ("usd", "input_tokens", "output_tokens", "cache_tokens", "tool_calls") if k in raw_budget})
        deadline_sec = raw_budget.get("deadlineSec")
        deadline = None if deadline_sec is None else time.monotonic() + max(0.0, float(deadline_sec))
        budget = ExecutionBudget(limits, max_concurrency=raw_budget.get("maxConcurrency"), deadline=deadline, run_id=run_id, request_id=request_id)
        handle["budget"] = budget
        handle["drainTimeoutSec"] = _normalize_drain_timeout(
            raw_budget.get("drainTimeoutSec", defaults.get("drainTimeoutSec", DRAIN_TIMEOUT_DEFAULT_SEC)))
        try:
            workflow_model_is_local = m.is_local_model(
                m.resolve_config(_model_spec(model_alias))
            )
        except Exception:  # noqa: BLE001 - routing classification fails closed
            workflow_model_is_local = True
        if effective_workflow_mode == "auto":
            # AUTO is intentionally opportunistic rather than a new global
            # controller that suppresses the established goal/team/A2A
            # routers.  The TUI and `/workflow auto` atomically enable these
            # supervised-parallel prerequisites.  Direct bridge clients that
            # omit them retain the legacy solo/goal/team behavior instead of
            # losing those routes merely because AUTO is the stored default.
            workflow_auto_ready = (
                not workflow_model_is_local
                and
                a2a_agents != 0
                and a2a_execution in {"terminal", "headless"}
                and terminal_layout != "off"
                and (
                    budget.max_concurrency is None
                    or int(budget.max_concurrency) >= 2
                )
            )
            if not workflow_auto_ready:
                effective_workflow_mode = "off"
        handle["budgetReceipt"] = {"budgetId": budget.snapshot().correlation.budget_id, "limits": {k: v for k, v in vars(limits).items() if v is not None}, "deadline": deadline, "maxConcurrency": budget.max_concurrency}

        # Compare the exact bridge source executing this process with the
        # operator's workspace before any run event is emitted. This makes a
        # packaged-runtime/workspace mismatch visible for solo runs too, rather
        # than only after team_start.
        handle["runtimeSource"] = _runtime_source_provenance(root)
        plugin_host = None
        plugin_host_owned_by_run = True
        plugin_context = None
        try:
            from agent.plugin_host import PluginHost

            if isinstance(queued_lease_snapshot, Mapping):
                plugin_host = queued_plugin_host
            else:
                plugin_host = self._plugin_lease_host_for_run(
                    root,
                    session_id=session,
                    run_id=run_id,
                )
            if plugin_host is not None:
                plugin_host_owned_by_run = False
                handle["pluginLeaseWorkspace"] = str(root.resolve())
            else:
                plugin_host = PluginHost(root)
            plugin_context = plugin_host.runtime_context()
        except Exception as exc:  # noqa: BLE001 - authority discovery fails closed
            if plugin_host is not None and plugin_host_owned_by_run:
                plugin_host.close()
            plugin_host = None
            self.bus.bridge_event(
                run_id,
                {
                    "type": "plugin_warning",
                    "warning": (
                        "plugin context was not activated: "
                        f"{type(exc).__name__}: {_safe_text(exc, limit=400)}"
                    ),
                    "candidateOnly": True,
                    "canClaimAGI": False,
                },
            )
            return {
                "ok": False,
                "error": (
                    "plugin authority could not be established; native execution "
                    "was not started. Inspect /plugin list and reload or repair "
                    f"the plugin state: {type(exc).__name__}: "
                    f"{_safe_text(exc, limit=400)}"
                ),
                "executionRuntime": "plugin-authority",
                "candidateOnly": True,
                "canClaimAGI": False,
            }
        blocked_plugin_selections = (
            plugin_context.blocked_selections
            if plugin_context is not None
            else ()
        )
        if blocked_plugin_selections:
            if plugin_host is not None and plugin_host_owned_by_run:
                plugin_host.close()
            return {
                "ok": False,
                "error": (
                    "selected plugin authority is unavailable; native execution "
                    "was not started. Clear or re-enable the selection: "
                    + "; ".join(blocked_plugin_selections)
                ),
                "executionRuntime": "plugin-authority",
                "blockedPluginSelections": list(blocked_plugin_selections),
                "candidateOnly": True,
                "canClaimAGI": False,
            }
        selected_plugin_runtime = (
            plugin_context.runtime if plugin_context is not None else None
        )
        if selected_plugin_runtime is not None and (
            completion_mode
            or agi_mode
            or team > 1
            or a2a_agents != 0
            or effective_workflow_mode != "off"
        ):
            if plugin_host is not None and plugin_host_owned_by_run:
                plugin_host.close()
            return {
                "ok": False,
                "error": (
                    "selected plugin runtime supports one quarantined external "
                    "lane only; disable AGI/team/A2A/workflow routing first"
                ),
                "executionRuntime": "plugin",
                "pluginRuntime": plugin_context.runtime_ref,
                "candidateOnly": True,
                "canClaimAGI": False,
            }
        # Establish the requested execution identity before any provider
        # preflight or client construction can fail. The paired terminal record
        # is written by _execute_run for every return/exception/cancellation.
        # Fork runs move this record below fork creation so it names the fork,
        # never the parent conversation.
        if not branch_from:
            start_provenance = {
                "type": "run_start",
                "timestamp": _now_iso(),
                "modelAlias": model_alias,
                "workspace": str(root),
                "mode": mode,
            }
            # Preserve the established Sophia provenance-v1 shape byte for
            # byte.  Prime needs an explicit external-runtime discriminator,
            # but adding a redundant "sophia" field breaks existing consumers
            # that deliberately validate the native schema as an exact object.
            if selected_plugin_runtime is not None:
                start_provenance["executionRuntime"] = "plugin"
                start_provenance["pluginRuntime"] = plugin_context.runtime_ref
            elif execution_runtime == "prime":
                start_provenance["executionRuntime"] = "prime"
            self._write_run_provenance(handle, start_provenance, "start")

        if selected_plugin_runtime is not None:
            record, runtime = selected_plugin_runtime
            return self._run_plugin_external(
                handle,
                host=plugin_host,
                record=record,
                runtime=dict(runtime),
                prompt=prompt,
                root=root,
                session=session,
                requested_model=model_alias,
                mode=mode,
                permission=permission,
                response_style=response_style,
                conscience_mode=conscience_mode,
                close_host=plugin_host_owned_by_run,
            )

        if plugin_host is not None and plugin_host_owned_by_run:
            plugin_host.close()

        if execution_runtime == "prime":
            return self._run_prime_external(
                handle,
                cmd,
                prompt=prompt,
                root=root,
                session=session,
                requested_model=model_alias,
                mode=mode,
                permission=permission,
                response_style=response_style,
                conscience_mode=conscience_mode,
                defaults=defaults,
            )

        # Loaded once per run (cheap: at most a few file-existence checks when
        # no hooks.toml exists) so the ToolContext built below (whose
        # execute_tool() calls this config on every Pre/PostToolUse dispatch)
        # and the Stop dispatch at the end of this method share one config
        # instead of re-parsing the file on every tool call.
        hook_config = self._load_run_hook_config(root)
        from agent.hooks import HookEvent as _HookEvent
        if gate_bypass:
            # The repo's documented audit bypass: withheld answers are delivered
            # but every delivery is logged as delivery_gate_bypass in the trace.
            os.environ["SOPHIA_DELIVERY_GATE_BYPASS"] = "i-accept-the-audit"
        else:
            os.environ.pop("SOPHIA_DELIVERY_GATE_BYPASS", None)
        settings = terminal_cli.MODE_PRESETS[mode]

        # Sampling + thinking configuration (same env contract as the terminal CLI).
        os.environ["SOPHIA_TEMPERATURE"] = str(settings["temperature"])
        os.environ["SOPHIA_TOP_P"] = str(settings["top_p"])
        os.environ["SOPHIA_TOP_K"] = str(settings["top_k"])
        logic_judge = str(settings["logic_judge"])
        # Thinking display + reasoning effort stay bound to deepThink (high/ultra):
        # the creative→logical debate stage and visible reasoning live there.
        if deep_think:
            os.environ["SOPHIA_REASONING_EFFORT"] = "high"
            os.environ["SOPHIA_SHOW_THINKING"] = "1"
            os.environ["SOPHIA_CAPTURE_THINKING"] = "1"
            os.environ.setdefault("SOPHIA_THINKING_LOG", "1")
        else:
            for var in ("SOPHIA_REASONING_EFFORT", "SOPHIA_SHOW_THINKING", "SOPHIA_CAPTURE_THINKING"):
                os.environ.pop(var, None)
        # Deep-mode SAMPLING is decoupled from effort: it is switched on by the
        # /deepmode toggle (deep_mode), NOT by high/ultra. It applies the
        # maximum-exploration profile ("divergent": high temperature/top_p/top_k)
        # so creative search is a deliberate operator choice independent of effort.
        if deep_mode:
            deep_sampling = terminal_cli.MODE_PRESETS["divergent"]
            os.environ["SOPHIA_TEMPERATURE"] = str(deep_sampling["temperature"])
            os.environ["SOPHIA_TOP_P"] = str(deep_sampling["top_p"])
            os.environ["SOPHIA_TOP_K"] = str(deep_sampling["top_k"])

        # Cross-provider substitution is always an explicit operator decision in
        # interactive Sophia surfaces, even when tool permission is `auto`.
        # Same-provider retries remain automatic under ModelClient's policy.
        fallback_approver = _GuiApprover(self, run_id, cancel)

        def confirm_fallback(request: Any) -> bool:
            return fallback_approver(
                "cross-provider fallback",
                (
                    f"Primary: {request.primary_provider}/{request.primary_model}\n"
                    "Primary authority: "
                    f"{_fallback_authority_preview(getattr(request, 'primary_authority', None))}\n"
                    f"Fallback: {request.fallback_provider}/{request.fallback_model}\n"
                    "Fallback authority: "
                    f"{_fallback_authority_preview(getattr(request, 'fallback_authority', None))}\n"
                    "Changed authority fields: "
                    f"{', '.join(getattr(request, 'authority_changes', ()) or ('unavailable',))}\n"
                    f"Reason: {_safe_text(getattr(request.reason, 'message', request.reason), limit=400)}\n"
                    "Allow this provider change for the current model call?"
                ),
            )

        # Live-probes a local endpoint's real context window (cached by
        # base_url+model; a no-op for cloud/mock presets and for any preset
        # that already declares one — see resolve_config_with_live_context_
        # window's own scoping). Every run names its model explicitly, so this
        # IS the bridge's model-switch point; the cache keeps repeat runs of
        # the same model from paying a second network round trip.
        primary_cfg = m.resolve_config_with_live_context_window(_model_spec(model_alias))
        handle["resolvedContextWindow"] = primary_cfg.context_window
        try:
            from agent import runtime_config
            preflight = runtime_config.preflight_spec(_model_spec(model_alias), alias=model_alias)
        except Exception:  # noqa: BLE001 - a preflight probe must never block or fail the run
            preflight = None
        if preflight is not None and not preflight.get("ready", True):
            # Deliberately NON-blocking: preflight is a heuristic (binary/auth/
            # reachability checks), and both this repo's own test doubles and a
            # real operator's less-common setup can make a "not ready" verdict
            # wrong. The goal is an early, actionable heads-up before whatever
            # confusing error the actual call would otherwise produce — not a
            # new way for a run to refuse to even try.
            self.bus.bridge_event(run_id, {"type": "model_preflight", **preflight})
        client = _build_model_client(
            m.default_client,
            _model_spec(model_alias),
            fallback_confirmer=confirm_fallback,
            working_dir=root,
        )
        if primary_cfg.allow_fallbacks:
            client.fallback_policy = m.FallbackPolicy.from_value("confirm")
        else:
            client.fallbacks = []
            client.fallback_policy = m.FallbackPolicy.from_value("never")
            client.fallback_confirmer = None
        terminal_cli._set_client_sampling(
            client,
            temperature=float(os.environ["SOPHIA_TEMPERATURE"]),
            top_p=float(os.environ["SOPHIA_TOP_P"]),
            top_k=int(os.environ["SOPHIA_TOP_K"]),
        )

        # The delivery gate only judges the FINAL answer, so raw tokens would
        # otherwise reach a client's screen before any verdict exists. Guard on
        # the server side of the protocol so the property holds for every
        # client rather than depending on one UI to behave.
        stream_guard = StreamFloorGuard()
        withheld_announced: list[bool] = []

        def _emit_stream(text: str) -> None:
            if text:
                self.bus.bridge_event(run_id, {"type": "token", "text": text})
            if stream_guard.withheld and not withheld_announced:
                withheld_announced.append(True)
                self.bus.bridge_event(run_id, {
                    "type": "stream_withheld", "reason": stream_guard.reason,
                })

        def on_token(token: str) -> None:
            _emit_stream(stream_guard.feed(token))

        def flush_stream() -> None:
            """Release the checked tail; a short answer lives entirely in it."""
            _emit_stream(stream_guard.finish())

        def on_thinking_token(token: str) -> None:
            self.bus.bridge_event(run_id, {"type": "thinking_token", "text": token})

        def on_provider_wait(sequence: int, elapsed_sec: float,
                             max_wait_sec: float) -> None:
            # Refresh first so the following wait heartbeat remains the latest
            # lifecycle state consumed by the TUI ("waiting", with the revised
            # estimate) rather than being overwritten as generically active.
            self._refresh_run_eta_on_provider_wait(handle)
            self.bus.bridge_event(run_id, {
                "type": "provider_wait",
                "sequence": sequence,
                "elapsedSec": round(elapsed_sec, 3),
                "maxWaitSec": round(max_wait_sec, 3),
            })

        def on_provider_progress(progress: dict[str, Any]) -> None:
            """Project transport activity into one provider-neutral bridge event.

            The model layer already excludes prompts, hidden reasoning, tool
            inputs, and tool outputs. Keep a second allow-list here because the
            bridge is the durable/public protocol boundary consumed by the TUI,
            session supervisor, connectors, and automation logs.
            """
            safe: dict[str, Any] = {"type": "provider_progress"}
            text_fields = {
                "phase",
                "provider",
                "model",
                "status",
                "detail",
                "tool",
                "toolCallId",
            }
            numeric_fields = {
                "attempt",
                "maxAttempts",
                "elapsedSec",
                "delaySec",
                "planSteps",
                "promptTokens",
                "completionTokens",
                "reasoningTokens",
            }
            for key in text_fields:
                value = progress.get(key)
                if isinstance(value, str) and value.strip():
                    safe[key] = m._redact_error_text(value.strip())[:240]
            for key in numeric_fields:
                value = progress.get(key)
                if isinstance(value, (int, float)) and not isinstance(value, bool):
                    safe[key] = value
            if isinstance(progress.get("fallback"), bool):
                safe["fallback"] = progress["fallback"]
            self.bus.bridge_event(run_id, safe)

        team_worker_tee: _TokenTee | None = None
        team_worker_model: str | None = None
        worker_allowed_tools: set[str] | None = None
        if primary_cfg.worker_model and (
            effort == "ultramode" or primary_cfg.worker_all_efforts
        ):
            worker_client = _build_model_client(
                m.default_worker_client,
                _model_spec(model_alias),
                fallback_confirmer=confirm_fallback,
                working_dir=root,
            )
            worker_client.fallbacks = []
            worker_client.retries = 1
            worker_client.fallback_policy = m.FallbackPolicy.from_value("never")
            worker_client.fallback_confirmer = None
            worker_cfg = getattr(worker_client, "primary", None)
            if worker_cfg is not None and hasattr(worker_cfg, "max_tokens"):
                worker_cfg.max_tokens = min(int(worker_cfg.max_tokens), 2048)
            terminal_cli._set_client_sampling(
                worker_client,
                temperature=float(os.environ["SOPHIA_TEMPERATURE"]),
                top_p=float(os.environ["SOPHIA_TOP_P"]),
                top_k=int(os.environ["SOPHIA_TOP_K"]),
            )
            team_worker_tee = _TokenTee(
                worker_client,
                lambda _token: None,
                cancel,
                on_provider_progress=on_provider_progress,
                on_wait=on_provider_wait,
            )
            team_worker_model = primary_cfg.worker_model
            worker_allowed_tools = {
                "read_file", "read_runtime_file", "write_file", "edit_file",
                "list_dir", "glob", "grep", "grep_runtime",
                "git_status", "git_diff", "git_log",
            }

        tee = _TokenTee(
            client,
            on_token,
            cancel,
            on_thinking_token=on_thinking_token,
            on_provider_progress=on_provider_progress,
            on_wait=on_provider_wait,
        )

        approver = (
            _GuiApprover(self, run_id, cancel)
            if permission == "approve" else None
        )

        def _on_tool_hook_dispatch(dispatch: Any) -> None:
            # execute_tool() dispatches Pre/PostToolUse itself now (every
            # permission mode, not just manual-approval calls); this closure is
            # how that kernel-only call site still reaches the bridge's
            # `/hooks`-status history and live `hook_dispatch` event, without
            # agent_tools.py knowing anything about bridges, run ids, or NDJSON.
            self._record_and_emit_hook_dispatch(run_id, dispatch)

        def _on_native_delegate_dispatch(payload: Mapping[str, Any]) -> None:
            """Project ordinary-mode ``delegate`` lifecycle into SMUX state."""
            event_type = str(payload.get("type") or "")
            assignment_id = _safe_text(
                payload.get("assignmentId"),
                limit=240,
            )
            if (
                event_type not in {"delegate_start", "delegate_end"}
                or not assignment_id
            ):
                return
            dispatch_manifest = self._ensure_dispatch_manifest(
                handle,
                session=str(handle.get("session") or session),
                mode="delegate",
            )
            if event_type == "delegate_start":
                dispatch_manifest.set_status(
                    "running",
                    phase="worker",
                    source="native_delegate",
                    main_status="waiting_for_worker",
                )
                snapshot = dispatch_manifest.register_assignment(
                    assignment_id=assignment_id,
                    agent_id=_safe_text(
                        payload.get("agentId") or assignment_id,
                        limit=240,
                    ),
                    task_id=_safe_text(
                        payload.get("taskId") or assignment_id,
                        limit=240,
                    ),
                    name=_safe_text(
                        payload.get("name") or "Delegated Sub-Agent",
                        limit=240,
                    ),
                    task=_safe_text(payload.get("task"), limit=1600),
                    phase="worker",
                    status="running",
                    persona_id=_safe_text(
                        payload.get("personaId"),
                        limit=160,
                    ),
                    persona_name=_safe_text(
                        payload.get("personaName"),
                        limit=240,
                    ),
                    persona_discipline=_safe_text(
                        payload.get("personaDiscipline"),
                        limit=160,
                    ),
                    persona_via=_safe_text(
                        payload.get("personaVia") or "fallback",
                        limit=80,
                    ),
                    skills=[
                        _safe_text(item, limit=160)
                        for item in list(payload.get("skills") or [])
                        if _safe_text(item, limit=160)
                    ],
                    skill_via=[
                        _safe_text(item, limit=160)
                        for item in list(payload.get("skillVia") or [])
                        if _safe_text(item, limit=160)
                    ],
                    allowed_tools=[
                        _safe_text(item, limit=120)
                        for item in list(payload.get("allowedTools") or [])
                        if _safe_text(item, limit=120)
                    ],
                    tool_scope_via=_safe_text(
                        payload.get("toolScopeVia")
                        or "default_read_only+parent_intersection",
                        limit=100,
                    ),
                    permission=_safe_text(
                        payload.get("permission") or permission,
                        limit=80,
                    ),
                    execution=_safe_text(
                        payload.get("execution") or "embedded",
                        limit=80,
                    ),
                    provider=_safe_text(
                        payload.get("provider")
                        or str(model_alias).split(":", 1)[0],
                        limit=100,
                    ),
                    model=_safe_text(
                        payload.get("model") or model_alias,
                        limit=180,
                    ),
                    source="native_delegate",
                )
                self._publish_dispatch_manifest(
                    handle,
                    snapshot=snapshot,
                )
            else:
                status = str(payload.get("status") or "failed").casefold()
                if status not in {
                    "succeeded",
                    "failed",
                    "cancelled",
                    "timed_out",
                }:
                    status = "failed"
                dispatch_manifest.update_assignment(
                    assignment_id,
                    status=status,
                    phase="worker",
                    summary=_safe_text(
                        payload.get("summary"),
                        limit=600,
                    ),
                    error=(
                        _safe_text(payload.get("error"), limit=800)
                        if status != "succeeded"
                        else None
                    ),
                    provider=(
                        _safe_text(payload.get("provider"), limit=100)
                        or None
                    ),
                    model=(
                        _safe_text(payload.get("model"), limit=180)
                        or None
                    ),
                )
                snapshot = dispatch_manifest.set_status(
                    "verifying",
                    phase="main",
                    main_status="working",
                )
                self._publish_dispatch_manifest(
                    handle,
                    snapshot=snapshot,
                )
            self.bus.bridge_event(
                run_id,
                {
                    "type": "subagent_dispatch",
                    "lifecycle": event_type,
                    "assignmentId": assignment_id,
                    "agentId": _safe_text(
                        payload.get("agentId") or assignment_id,
                        limit=240,
                    ),
                    "taskId": _safe_text(
                        payload.get("taskId") or assignment_id,
                        limit=240,
                    ),
                    "name": _safe_text(
                        payload.get("name") or "Delegated Sub-Agent",
                        limit=240,
                    ),
                    "task": _safe_text(payload.get("task"), limit=600),
                    "status": _safe_text(
                        payload.get("status") or "running",
                        limit=80,
                    ),
                    "personaId": _safe_text(
                        payload.get("personaId"),
                        limit=160,
                    ),
                    "personaName": _safe_text(
                        payload.get("personaName"),
                        limit=240,
                    ),
                    "personaVia": _safe_text(
                        payload.get("personaVia"),
                        limit=80,
                    ),
                    "skills": [
                        _safe_text(item, limit=160)
                        for item in list(payload.get("skills") or [])
                        if _safe_text(item, limit=160)
                    ],
                    "skillVia": [
                        _safe_text(item, limit=160)
                        for item in list(payload.get("skillVia") or [])
                        if _safe_text(item, limit=160)
                    ],
                    "allowedTools": [
                        _safe_text(item, limit=120)
                        for item in list(payload.get("allowedTools") or [])
                        if _safe_text(item, limit=120)
                    ],
                    "toolScopeVia": _safe_text(
                        payload.get("toolScopeVia"),
                        limit=100,
                    ),
                    "candidateOnly": True,
                    "canClaimAGI": False,
                    "validatedUplift": False,
                    "productGo": False,
                },
            )

        ctx = ToolContext(
            root=root,
            permission=permission,
            approver=approver,
            client=tee,
            subagent_client=team_worker_tee,
            subagent_allowed_tools=worker_allowed_tools,
            dispatch_sink=_on_native_delegate_dispatch,
            budget=budget,
            conscience_strict=conscience_mode == "strict",
            conscience_mode=conscience_mode,
            hook_config=hook_config if hook_config.enabled else None,
            hook_sink=_on_tool_hook_dispatch,
            cancel_check=cancel.is_set,
        )
        if plugin_context is not None and plugin_context.allowed_tools is not None:
            # Plugin skills/agents can only narrow the native tool catalog.
            # Unknown tool names disappear from the intersection and no
            # plugin contribution can add a tool or override risk/approval.
            ctx.allowed_tools = set(plugin_context.allowed_tools) & set(all_tools())
        requested_tool_scope = cmd.get("allowedTools")
        if requested_tool_scope is not None:
            # Supervised dispatch specs carry the Main Agent's resolved
            # least-privilege scope.  Treat the field as a narrowing
            # capability, never as a way to widen the parent/plugin policy.
            if isinstance(requested_tool_scope, str):
                requested_values = requested_tool_scope.split(",")
            elif isinstance(requested_tool_scope, (list, tuple, set, frozenset)):
                requested_values = list(requested_tool_scope)
            else:
                requested_values = []
            requested_scope = {
                str(value or "").strip().lower().replace("-", "_")
                for value in requested_values
                if str(value or "").strip()
            }
            requested_scope.intersection_update(set(all_tools()))
            if not _normalize_bool(
                cmd.get("allowSubagents"),
                default=False,
            ):
                requested_scope.discard("delegate")
            if ctx.allowed_tools is None:
                ctx.allowed_tools = requested_scope
            else:
                ctx.allowed_tools.intersection_update(requested_scope)
            if ctx.subagent_allowed_tools is not None:
                ctx.subagent_allowed_tools = (
                    set(ctx.subagent_allowed_tools) & requested_scope
                )
            self.bus.bridge_event(
                run_id,
                {
                    "type": "dispatch_tool_scope",
                    "allowedTools": sorted(ctx.allowed_tools or ()),
                    "scopeVia": "worker_command",
                    "candidateOnly": True,
                    "canClaimAGI": False,
                },
            )
        acceptance_contract = cmd.get("acceptanceContract")
        if isinstance(acceptance_contract, dict):
            tool_policy = acceptance_contract.get("toolPolicy")
            if isinstance(tool_policy, dict):
                ctx.tool_policy = dict(tool_policy)
        ctx.session_name = session  # type: ignore[attr-defined]  # todo plugin namespaces by session
        ctx.manual_skill_name = skill_name  # type: ignore[attr-defined]
        # Aligns the checkpoint store's folder name (.sophia/checkpoints/<run_id>)
        # with this exact bridge run, so a receipt/log correlated by run id can
        # find the same checkpoints /checkpoints or /undo would list. Purely a
        # naming choice — a fresh auto-generated id would isolate undo history
        # identically, just without the human-readable correlation.
        ctx.run_id = run_id
        # Expose the context so _execute_run's cancel handler can persist the
        # partial transcript (run_agent_loop keeps the live messages on ctx).
        handle["_ctx"] = ctx
        # Durable past this run's lifetime: /checkpoints and /undo need to find
        # this ctx (and the checkpoint store its run_id names) after the run
        # has already finished and `self.active` has gone back to None.
        with self.ctx_registry_lock:
            self.last_ctx_by_session[session] = ctx
            self.last_ctx = ctx
        sink = self.bus.kernel_sink(run_id)
        primary_final_events: list[dict[str, Any]] = []

        def primary_sink(event: dict[str, Any]) -> None:
            # Delay the primary terminal preview until semantic-refusal recovery
            # has selected the authoritative stage. Otherwise the TUI renders a
            # refusal bubble, then a second local/continued answer bubble.
            if str(event.get("type") or "") == "final":
                primary_final_events.append(dict(event))
                return
            # todo_write is RISK_SAFE and its args are already carried verbatim
            # on the tool_call event, so the checklist can reach the front end
            # the instant the model calls it rather than waiting a step for the
            # identically-shaped tool_result. Defensive by construction: a
            # malformed/missing items list just means nothing is emitted here,
            # never a broken event or a crashed sink.
            if (str(event.get("type") or "") == "tool_call"
                    and str(event.get("tool") or "") == "todo_write"):
                items = _todo_items_from_args(event.get("args"))
                if items is not None:
                    self.bus.bridge_event(
                        run_id,
                        {
                            "type": "todo_update",
                            "items": items,
                            "source": "todo_write",
                        },
                    )
                    revision = _todo_goal_revision(items)
                    if revision is not None:
                        goal, reason = revision
                        self._emit_goal_update(
                            handle,
                            goal=goal,
                            source="todo-harness",
                            reason=reason,
                            dedupe_semantic=True,
                        )
            sink(event)

        def buffered_sink(buffer: list[dict[str, Any]]) -> Callable[[dict], None]:
            def emit(event: dict[str, Any]) -> None:
                if str(event.get("type") or "") == "final":
                    buffer.append(dict(event))
                    return
                sink(event)

            return emit

        def stage_tee(inner: Any) -> tuple[_TokenTee, Callable[[], None]]:
            """Create an independently gated stream for one recovery stage."""
            guard = StreamFloorGuard()
            announced: list[bool] = []

            def emit_text(text: str) -> None:
                if text:
                    self.bus.bridge_event(run_id, {"type": "token", "text": text})
                if guard.withheld and not announced:
                    announced.append(True)
                    self.bus.bridge_event(
                        run_id,
                        {"type": "stream_withheld", "reason": guard.reason},
                    )

            def stage_token(token: str) -> None:
                emit_text(guard.feed(token))

            def finish() -> None:
                emit_text(guard.finish())

            return (
                _TokenTee(
                    inner,
                    stage_token,
                    cancel,
                    on_thinking_token=on_thinking_token,
                ),
                finish,
            )

        # tools_ext/delegate forwards this sink into subagent loops so subprocess
        # tool calls appear in the same stream (guarded getattr there; no-op otherwise).
        ctx.code_bridge_sink = sink  # type: ignore[attr-defined]

        fork_info = None
        if branch_from:
            # Fork: seed a new session from the parent conversation so the
            # injected idea branches off the original path (which stays intact).
            parent_session = _normalize_session(branch_from.get("session"))
            fork_session = f"{parent_session}-fork-{uuid.uuid4().hex[:6]}"
            parent_turns = terminal_cli._load_conversation(
                terminal_cli._conversation_path(parent_session)) or []
            if parent_turns:
                terminal_cli._save_conversation(
                    terminal_cli._conversation_path(fork_session), parent_turns)
            session = fork_session
            handle["session"] = session
            fork_info = {
                "session": parent_session,
                "fork": fork_session,
                "nodeId": str(branch_from.get("nodeId") or ""),
                "nodeTitle": _safe_text(branch_from.get("nodeTitle") or "", limit=120),
            }

        if branch_from:
            self._write_run_provenance(handle, {
                "type": "run_start",
                "timestamp": _now_iso(),
                "modelAlias": model_alias,
                "workspace": str(root),
                "mode": mode,
            }, "start")
        history = terminal_cli._load_conversation(terminal_cli._conversation_path(session)) or []
        raw_prompt = prompt
        continuation = None
        goal_record = None
        if history:
            try:
                from agent.continuation import resolve_continuation
                from agent.goal_harness import load_session_goal

                goal_record = load_session_goal(session)
                unfinished_goal = None
                if goal_record and str(goal_record.get("status") or "in_progress") in {
                    "in_progress", "awaiting_input", "bound_hit", "cancelled",
                }:
                    unfinished_goal = str(goal_record.get("goal") or "").strip() or None
                continuation = resolve_continuation(
                    raw_prompt, history, unfinished_goal=unfinished_goal)
            except Exception:  # noqa: BLE001 - semantic continuity must fail closed
                continuation = None
        if continuation is not None:
            prompt = continuation.instruction
        resumes_unfinished_goal = bool(
            continuation is not None
            and continuation.source == "unfinished_goal"
        )
        # A request that explicitly requires a native tool must stay on the
        # primary loop.  Team lanes intentionally receive a narrowed tool
        # surface and their answer-only coordinator has tools disabled; routing
        # a terminal/goal/todo request through either automatic fan-out path
        # can therefore turn an available tool protocol into a false
        # "tools unavailable" answer.  An operator-requested team (team > 1)
        # remains authoritative; this only blocks automatic dispatch.
        direct_native_tool_turn = _prompt_requires_initial_tool(prompt)

        # Decide orchestration ONCE before the first provider call. Historically
        # the TUI could spend one call on goal triage, another accumulating a
        # brand-new goal with an empty prior goal, and a third on team triage
        # before any user work began. The deterministic decision below removes
        # that planner-about-planning overhead and also selects a bounded worker
        # count for independent read-only native tool batches.
        orchestration = decide_orchestration(
            prompt,
            auto_goal=bool(cmd.get("autoGoal")),
            auto_team=auto_team_setting,
            requested_parallel_tools=_safe_int(
                raw_budget.get("maxParallelTools", defaults.get("maxParallelTools", 4)),
                4,
            ),
        )
        if bool(cmd.get("autoGoal")) and resumes_unfinished_goal:
            # A plain "continue" resolved against the durable session-goal
            # record. Preserve that outer-loop execution contract even though
            # the resolved goal text may not repeat "until"/"resume" wording.
            orchestration = replace(
                orchestration,
                goal_candidate=True,
                reason="unfinished long-horizon goal",
                substantive_task=True,
            )
        elif (
            bool(cmd.get("autoGoal"))
            and continuation is None
            and goal_record
            and str(goal_record.get("status") or "") == "awaiting_input"
        ):
            # The next operator turn commonly supplies the requested login,
            # approval, declaration, URL, or other missing input instead of the
            # literal word "resume". Route it through accumulation so the
            # durable paused goal can continue (or be superseded if the
            # accumulator judges the new request unrelated).
            orchestration = replace(
                orchestration,
                goal_candidate=True,
                reason="operator reply to an awaiting-input goal",
                substantive_task=True,
            )
        if direct_native_tool_turn:
            orchestration = replace(
                orchestration,
                team_candidate=False,
                team_lanes=1,
                reason=f"{orchestration.reason}; direct native-tool turn stays solo",
            )
        # `/team on` is a capability-aware automatic policy, not a request to
        # shoehorn every selected backend into a native-tool team contract.
        # Preserve explicit `/agents N` as the operator override.  Capture the
        # pre-capability candidate so the TUI can explain a worthy task that was
        # intentionally kept solo rather than looking like the toggle failed.
        team_candidate_before_capability = bool(orchestration.team_candidate)
        if (
            auto_team_enabled
            and team_candidate_before_capability
            and team <= 1
            and not auto_team_capable
        ):
            orchestration = replace(
                orchestration,
                team_candidate=False,
                team_lanes=1,
                reason=(
                    f"{orchestration.reason}; automatic team dispatch skipped: "
                    f"{auto_team_capability['reason']}"
                ),
            )
        max_parallel_tools = orchestration.max_parallel_tools

        self.bus.bridge_event(run_id, {
            "type": "run_start",
            "goal": prompt,
            "rawPrompt": raw_prompt,
            "model": model_alias,
            "mode": mode,
            "permission": permission,
            "session": session,
            "team": team,
            "a2aAgents": a2a_agents,
            "a2aExecution": a2a_execution,
            "terminalLayout": terminal_layout,
            "workflowMode": workflow_mode,
            "workflowEffectiveMode": effective_workflow_mode,
            "workflowMaxStages": workflow_max_stages,
            "workflowMaxAgents": workflow_max_agents,
            "workflowChartPath": workflow_chart_path,
            "workflowChartSelected": bool(workflow_chart_path),
            "workflowChartRouteForced": chart_route_forced,
            "workflowChartRouteBlocked": bool(chart_route_blocked_reason),
            "workflowChartRouteReason": chart_route_blocked_reason,
            "agiWorkflowMode": agi_workflow_mode,
            "agiMode": agi_mode,
            "agiProfile": agi_profile,
            "agiRoute": agi_route,
            "agiPlannerModel": agi_planner_model or model_alias,
            "agiWorkerModel": agi_worker_model or model_alias,
            "agiVerifierModel": agi_verifier_model or model_alias,
            "completionMode": completion_mode,
            "autoTeam": auto_team_setting,
            "goalMode": bool(cmd.get("goalMode")),
            "autoTeamState": _auto_team_state(auto_team_setting),
            "autoTeamCapable": auto_team_capable,
            "autoTeamCapabilityReason": auto_team_capability["reason"],
            "autoTeamResolvedModel": auto_team_capability["model"],
            "autoTeamTransport": auto_team_capability["transport"],
            "directNativeToolTurn": direct_native_tool_turn,
            "effort": effort,
            "maxSteps": max_steps,
            "deepThink": deep_think,
            "sophiaContract": sophia_contract,
            "responseStyle": response_style,
            "gateBypass": gate_bypass,
            "conscienceMode": conscience_mode,
            "skill": skill_name,
            "pluginSkill": (
                plugin_context.skill_ref if plugin_context is not None else None
            ),
            "pluginCompatSkill": (
                plugin_context.compat_skill_ref
                if plugin_context is not None
                else None
            ),
            "pluginAgent": (
                plugin_context.agent_ref if plugin_context is not None else None
            ),
            "pluginSafeMode": (
                plugin_context.safe_mode if plugin_context is not None else False
            ),
            "pluginLease": (
                dict(plugin_context.lease)
                if plugin_context is not None
                and plugin_context.lease is not None
                else None
            ),
            "root": str(root),
            "branchFrom": fork_info,
            **dict(handle.get("runtimeSource") or {}),
        })
        self.bus.bridge_event(run_id, {
            "type": "orchestration_plan",
            "substantiveTask": orchestration.substantive_task,
            "goalCandidate": orchestration.goal_candidate,
            "teamCandidate": orchestration.team_candidate,
            "teamCandidateBeforeCapability": team_candidate_before_capability,
            "teamLanes": orchestration.team_lanes,
            "maxParallelTools": max_parallel_tools,
            "directNativeToolTurn": direct_native_tool_turn,
            "autoTeamCapable": auto_team_capable,
            "autoTeamCapabilityReason": auto_team_capability["reason"],
            "autoTeamResolvedModel": auto_team_capability["model"],
            "autoTeamTransport": auto_team_capability["transport"],
            "reason": orchestration.reason,
            "plannerModelCalls": 0,
        })
        self._emit_goal_update(
            handle,
            goal=prompt,
            source=(
                "continuation"
                if continuation is not None
                else "orchestration"
            ),
            reason=orchestration.reason,
        )
        if continuation is not None:
            self.bus.bridge_event(run_id, {
                "type": "continuation_resolved",
                "rawPrompt": raw_prompt,
                "effectiveRequest": prompt,
                "source": continuation.source,
                "requiresLiveRefresh": continuation.requires_live_refresh,
                "session": session,
            })

        system_extra = ""
        try:
            from agent.tui_failure_memory import next_run_system_extra

            system_extra += next_run_system_extra(Path(root), prompt)
        except Exception:  # noqa: BLE001 - missing harness is not a run failure
            pass
        if continuation is not None:
            from agent.continuation import continuation_system_guidance
            system_extra += continuation_system_guidance(continuation)
        if sophia_contract:
            # Run-specific sharpening of the base Sophia Operating Contract:
            # orchestrate once, minimize round trips, verify before claiming.
            system_extra += (
                "\nSophia Operating Contract:\n"
                "- Before the first tool call, form the dependency-ordered plan from the "
                "whole request. Do not call a tool merely to announce or rediscover it.\n"
                "- Minimize round trips: combine related discovery into the smallest useful "
                "search/read calls; never repeat a successful identical read; batch only "
                "independent read-only native calls and keep writes/dependencies serial.\n"
                "- Prefer tools over prose: ground code answers in files, make surgical "
                "edits, and verify with tests/commands before claiming something works.\n"
                "- Be concise and professional: reference files as path:line, no preamble, "
                "no flattery, state assumptions in one line and keep going."
            )
        if skill_name:
            system_extra += self._skill_brief(run_id, skill_name)
        if plugin_context is not None and plugin_context.system_extra:
            system_extra += plugin_context.system_extra
            self.bus.bridge_event(
                run_id,
                {
                    "type": "plugin_context",
                    "skill": plugin_context.skill_ref,
                    "compatSkill": plugin_context.compat_skill_ref,
                    "agent": plugin_context.agent_ref,
                    "toolScope": (
                        sorted(ctx.allowed_tools)
                        if ctx.allowed_tools is not None
                        else None
                    ),
                    "safeMode": plugin_context.safe_mode,
                    "lease": (
                        dict(plugin_context.lease)
                        if plugin_context.lease is not None
                        else None
                    ),
                    "candidateOnly": True,
                    "canClaimAGI": False,
                },
            )
        if deep_think:
            system_extra += (
                "\nDeep-think profile: reason slowly and explicitly. Decompose the task, "
                "verify each step with tools where possible, and double-check the final "
                "answer before emitting it."
            )

        started = time.time()
        lane_results: list[dict[str, Any]] = []
        # Set when auto-triage accumulates a session goal; the goalMode branch
        # below writes the loop outcome back to it after the run.
        _accumulated_session_goal: str | None = None
        _synthetic_session_recovery = False
        _synthetic_recovery_had_record = False
        # --- Automatic long-horizon goal detection (no /goal needed) ---
        # Substantive bounded tasks stay in the normal inner agent loop, which
        # already orchestrates tool dependencies and continuations. The outer
        # goal loop is reserved for explicit persistence/retry/resume intent
        # because its strict completion judge adds a provider call per attempt.
        # Routing remains deterministic and local.
        if (
            bool(cmd.get("autoGoal"))
            and not agi_mode
            and effective_workflow_mode == "off"
            and not cmd.get("goalMode")
            and team <= 1
            # A team route owns the whole task. Starting goal mode first would
            # return before the team branch and silently discard the plan.
            and not orchestration.team_candidate
        ):
            _will_loop = orchestration.goal_candidate
            _triage = {
                "is_goal": _will_loop,
                "goal": prompt,
                "confidence": 1.0 if _will_loop else 0.0,
                "reason": f"deterministic orchestration: {orchestration.reason}",
            }
            self.bus.bridge_event(run_id, {
                "type": "goal_triage", "prompt": prompt,
                "isGoal": bool(_triage.get("is_goal")),
                "goal": _triage.get("goal", prompt),
                "confidence": float(_triage.get("confidence", 0.0)),
                "reason": _triage.get("reason", ""),
                "willLoop": _will_loop,
            })
            if _will_loop:
                # Accumulate the extracted goal into the SESSION's running goal so
                # it compounds across prompts in this chat (and survives restarts),
                # then engage the autonomous goal loop on the ACCUMULATED goal.
                from agent.goal_harness import accumulate_goal, load_session_goal, save_session_goal
                _prior = load_session_goal(session)
                _prior_goal = _prior.get("goal") if _prior else None
                _prior_status = _prior.get("status") if _prior else None
                _prior_synthetic = bool(_prior and _prior.get("syntheticRecovery"))
                _extracted = (_triage.get("goal") or "").strip() or prompt
                recovery_only = bool(
                    (
                        continuation is not None
                        and continuation.source == "session_context"
                    )
                    or (
                        _prior_synthetic
                        and str(_prior_status or "") == "awaiting_input"
                        and continuation is None
                    )
                )
                if recovery_only:
                    # SESSION_CONTEXT_CONTINUATION is a synthetic recovery
                    # instruction used when compaction removed the explicit
                    # objective. It may drive this run, but persisting it as the
                    # session's goal would let kernel control text permanently
                    # replace the operator's objective.
                    _synthetic_session_recovery = True
                    _synthetic_recovery_had_record = _prior_synthetic
                    recovery_goal = _extracted
                    if _prior_synthetic and continuation is None:
                        from agent.continuation import SESSION_CONTEXT_CONTINUATION
                        recovery_goal = (
                            f"{SESSION_CONTEXT_CONTINUATION}\n\n"
                            f"New operator-supplied input:\n{_extracted}"
                        )
                    _acc = {
                        "goal": recovery_goal,
                        "continues_prior": False,
                        "confidence": 0.0,
                        "reason": "synthetic session recovery; not persisted",
                    }
                elif resumes_unfinished_goal:
                    # ``resolve_continuation`` already selected the unfinished
                    # durable goal as the authoritative request. Merging that
                    # goal with itself would add a provider round trip and could
                    # distort the exact persisted objective.
                    _acc = {
                        "goal": _prior_goal or _extracted,
                        "continues_prior": bool(_prior_goal),
                        "confidence": 1.0,
                        "reason": "resuming unfinished goal; no merge needed",
                    }
                elif _prior_goal and str(_prior_status or "in_progress") in {
                    "in_progress", "awaiting_input", "bound_hit", "cancelled",
                }:
                    try:
                        _acc = accumulate_goal(
                            _prior_goal,
                            _extracted,
                            client=tee.raw_client,
                            prior_status=_prior_status,
                        )
                    except Exception:  # noqa: BLE001 - accumulation must never break a run
                        _acc = {
                            "goal": f"{_prior_goal} | {_extracted}",
                            "continues_prior": True,
                            "confidence": 0.0,
                            "reason": "accumulation error",
                        }
                else:
                    # The common new-task path needs no semantic merge: using a
                    # model to combine "nothing" with the current prompt only
                    # burns a call and can distort the user's exact request.
                    _acc = {
                        "goal": _extracted,
                        "continues_prior": False,
                        "confidence": 1.0,
                        "reason": "new goal; no prior merge needed",
                    }
                goal_for_loop = _acc.get("goal") or _extracted
                if not recovery_only:
                    _accumulated_session_goal = goal_for_loop
                    save_session_goal(session, _accumulated_session_goal,
                                      meta={"status": "in_progress",
                                            "continuesPrior": bool(_acc.get("continues_prior")),
                                            "confidence": float(_acc.get("confidence", 0.0))})
                    self.bus.bridge_event(run_id, {
                        "type": "goal_accumulated",
                        "priorGoal": _prior_goal or "",
                        "newPrompt": _extracted,
                        "accumulatedGoal": _accumulated_session_goal,
                        "continuesPrior": bool(_acc.get("continues_prior")),
                        "confidence": float(_acc.get("confidence", 0.0)),
                    })
                    self._emit_goal_update(
                        handle,
                        goal=_accumulated_session_goal,
                        source="goal-harness",
                        reason=_acc.get("reason", "session goal updated"),
                    )
                prompt = goal_for_loop
                cmd = {**cmd, "goalMode": True}
        if cmd.get("goalMode") and not agi_mode:
            # Autonomous goal-continuation: swap the single tool loop for
            # run_goal_loop (reuses ALL the setup above — client/tee/ctx/budget/
            # delivery gate/history). The standard single-run post-processing
            # below is skipped; _run_goal builds its own terminal payload.
            _goal_payload = self._run_goal(
                handle, cmd, prompt=prompt, tee=tee, ctx=ctx, sink=sink,
                budget=budget, history=history, session=session,
                show_thinking=deep_think, system_extra=system_extra,
                response_style=response_style,
                raw_prompt=raw_prompt,
                continuation_instruction=(
                    continuation.instruction if continuation is not None else None),
                max_steps=max_steps, model_alias=model_alias,
                max_parallel_tools=max_parallel_tools,
                flush_stream=flush_stream, steering_consumer=steering_consumer,
                started=started,
            )
            # Write the outcome back to the session's accumulated goal so the next
            # prompt's accumulation knows what is achieved vs still outstanding.
            if _accumulated_session_goal is not None:
                try:
                    from agent.goal_harness import save_session_goal as _save_sg
                    _save_sg(session, _accumulated_session_goal, meta={
                        "status": _goal_payload.get("goalStatus"),
                        "confidence": _goal_payload.get("confidence"),
                        "continuations": _goal_payload.get("continuations"),
                        "reason": _goal_payload.get("goalReason"),
                    })
                except Exception:  # noqa: BLE001 - persistence is best-effort
                    pass
            elif (
                _synthetic_session_recovery
                and (
                    _synthetic_recovery_had_record
                    or _goal_payload.get("goalStatus") == "awaiting_input"
                )
            ):
                # A compacted legacy session may have no recoverable concrete
                # objective. Preserve only the pause/outcome marker so a later
                # owner reply is routed back into recovery; keep the synthetic
                # instruction explicitly marked and resolver-filtered instead
                # of promoting it to an operator goal. Never persist the
                # operator-supplied input in this fallback record.
                try:
                    from agent.continuation import SESSION_CONTEXT_CONTINUATION
                    from agent.goal_harness import save_session_goal as _save_sg
                    _save_sg(session, SESSION_CONTEXT_CONTINUATION, meta={
                        "status": _goal_payload.get("goalStatus"),
                        "confidence": _goal_payload.get("confidence"),
                        "continuations": _goal_payload.get("continuations"),
                        "reason": _goal_payload.get("goalReason"),
                        "syntheticRecovery": True,
                    })
                except Exception:  # noqa: BLE001 - persistence is best-effort
                    pass
            return _goal_payload
        # Ultra effort auto-dispatches a team ONLY for cloud models, and only when
        # the swarm router judges the task team-worthy (easy tasks stay single-LLM:
        # below DIFFICULTY_SOLO_FLOOR with no hard signal the router returns no
        # assignments). Local models never auto-fan-out here (cloud-only for now);
        # an explicit team>1 from the operator is still honored regardless.
        if (
            not agi_mode
            and effective_workflow_mode == "off"
            and effort == "ultramode"
            and not direct_native_tool_turn
            and team <= 1
        ):
            # Classify from the resolved model spec (not the live client, which
            # may be a test double without `.primary`).
            try:
                _is_cloud = not m.is_local_model(m.resolve_config(_model_spec(model_alias)))
            except Exception:  # noqa: BLE001 - classification must never break the run
                _is_cloud = False
            if _is_cloud:
                from agent.swarm_router import SwarmRouter
                try:
                    _plan = SwarmRouter().decide(prompt)
                    _worthy = bool(getattr(_plan, "assignments", None))
                except Exception:  # noqa: BLE001 - routing must never break the run
                    _plan, _worthy = None, False
                if _worthy:
                    team = max(2, _ultramode_team_size(_plan))
        # Auto-team: the auto-goal analogue for parallelism. When the persisted
        # or per-command tri-state explicitly enables it, a local deterministic
        # classifier decides whether the prompt warrants a PARALLEL TEAM of
        # independent lanes (and how many, 2..4) — so a "compare A, B, and C"
        # task fans out with no /agents command. Conservative + fail-closed:
        # an unsupported transport or unsure triage keeps the run solo.
        # Runs only while still solo (team<=1) so an explicit /agents or the
        # ultramode router above is never overridden; goal mode already returned
        # earlier (goal and team are mutually exclusive). Unset is fail-closed
        # to solo; explicit /agents remains authoritative.
        if (
            not agi_mode
            and
            effective_workflow_mode == "off"
            and
            auto_team_enabled
            and not direct_native_tool_turn
            and not cmd.get("goalMode")
            and team <= 1
        ):
            _will_team = orchestration.team_candidate
            _ttriage = {
                "is_team": _will_team,
                "lanes": orchestration.team_lanes,
                "confidence": 1.0 if _will_team else 0.0,
                "reason": f"deterministic orchestration: {orchestration.reason}",
            }
            if _will_team:
                team = orchestration.team_lanes
            self.bus.bridge_event(run_id, {
                "type": "team_triage", "prompt": prompt,
                "isTeam": bool(_ttriage.get("is_team")),
                "lanes": int(_ttriage.get("lanes", 1) or 1),
                "team": team,
                "confidence": float(_ttriage.get("confidence", 0.0)),
                "reason": _ttriage.get("reason", ""),
                "willTeam": _will_team,
                "candidate": team_candidate_before_capability,
                "modelCapable": auto_team_capable,
                "model": auto_team_capability["model"],
                "transport": auto_team_capability["transport"],
                "capabilityReason": auto_team_capability["reason"],
            })
        # Model-aware tool-call ceiling: both cloud and local models retain a
        # finite 4×max_steps ceiling. See CLOUD_MAX_CONTINUATIONS. Classification
        # fails safe to the same bounded cap.
        _is_local = workflow_model_is_local
        _loop_continuations = None if _is_local else CLOUD_MAX_CONTINUATIONS
        # Runtime licensing is enforced in the execution core rather than only
        # in the native/TUI presentation layer. Source checkouts default to
        # development mode, while commercial builds carry a fail-closed
        # PRODUCT-CONTRACT.json and pinned entitlement verification key.
        from sophia.product_licensing import require_runtime_feature

        if agi_mode:
            self._activate_run_mode(handle, "agi", phase="controller startup")
        if completion_mode:
            require_runtime_feature("agi-mode")
        elif agi_mode:
            require_runtime_feature("agi-mode")
        if team > 1:
            require_runtime_feature("multi-agent")
        if effective_workflow_mode != "off":
            require_runtime_feature("multi-agent")
        dispatch_mode = (
            "agi"
            if agi_mode
            else (
                "team"
                if team > 1
                else (
                    "workflow"
                    if effective_workflow_mode != "off"
                    else "a2a"
                    if a2a_agents != 0
                    else ""
                )
            )
        )
        if dispatch_mode:
            self._ensure_dispatch_manifest(
                handle,
                session=session,
                mode=dispatch_mode,
                source_run_id=(
                    _safe_text(cmd.get("workflowResumeRunId"), limit=160)
                    if dispatch_mode in {"workflow", "agi"}
                    else ""
                ),
            )
        if completion_mode:
            res = self._run_completeness_mode(
                handle,
                {
                    **cmd,
                    "completionMode": completion_mode,
                },
                prompt=prompt,
                tee=tee,
                ctx=ctx,
                sink=primary_sink,
                budget=budget,
                session=session,
                show_thinking=deep_think,
                system_extra=system_extra,
                max_steps=max_steps,
                model_alias=model_alias,
                response_style=response_style,
                root=root,
            )
        elif agi_mode:
            res = self._run_agi_mode(
                handle,
                {
                    **cmd,
                    "agiProfile": agi_profile,
                    "agiRoute": agi_route,
                    "agiPlannerModel": agi_planner_model or model_alias,
                    "agiWorkerModel": agi_worker_model or model_alias,
                    "agiVerifierModel": agi_verifier_model or model_alias,
                    "agiWorkflowMode": agi_workflow_mode,
                    "workflowMaxStages": workflow_max_stages,
                    "workflowMaxAgents": workflow_max_agents,
                    "a2aAgents": a2a_agents,
                    "a2aExecution": a2a_execution,
                    "terminalLayout": terminal_layout,
                },
                prompt=prompt,
                tee=tee,
                ctx=ctx,
                sink=primary_sink,
                budget=budget,
                session=session,
                show_thinking=deep_think,
                system_extra=system_extra,
                max_steps=max_steps,
                model_alias=model_alias,
                response_style=response_style,
                root=root,
                fallback_confirmer=confirm_fallback,
            )
        elif team > 1:
            self._activate_run_mode(handle, "team", phase="parallel lanes")
            res = self._run_team(
                handle, prompt, tee, ctx, primary_sink,
                team=team, max_steps=max_steps, history=history,
                raw_prompt=raw_prompt,
                show_thinking=deep_think, system_extra=system_extra,
                lane_results=lane_results,
                budget=budget,
                max_parallel_tools=max_parallel_tools,
                post_tool_continuity=True,
                max_continuations=_loop_continuations,
                require_live_refresh=bool(
                    continuation is not None
                    and continuation.requires_live_refresh
                ),
                response_style=response_style,
                worker_tee=team_worker_tee,
                worker_model=team_worker_model,
            )
        elif effective_workflow_mode != "off":
            workflow_parallel_ready = (
                not chart_route_blocked_reason
                and a2a_agents != 0
                and a2a_execution in {"terminal", "headless"}
                and terminal_layout != "off"
                and (
                    budget.max_concurrency is None
                    or int(budget.max_concurrency) >= 2
                )
            )
            eligibility_reason = chart_route_blocked_reason
            if not eligibility_reason and _is_local:
                eligibility_reason = (
                    "dynamic workflow is cloud-model only; the selected model "
                    "is local or self-hosted"
                )
            elif not eligibility_reason and a2a_agents == 0:
                eligibility_reason = (
                    "dynamic workflow requires A2A on/auto"
                )
            elif not eligibility_reason and a2a_execution not in {"terminal", "headless"}:
                eligibility_reason = (
                    "dynamic workflow requires supervised parallel A2A "
                    "(use /terminals auto or headless)"
                )
            elif not eligibility_reason and terminal_layout == "off":
                eligibility_reason = (
                    "dynamic workflow requires the A2A terminal supervisor"
                )
            elif (
                not eligibility_reason
                and budget.max_concurrency is not None
                and int(budget.max_concurrency) < 2
            ):
                eligibility_reason = (
                    "dynamic workflow requires a concurrency budget of at least 2"
                )
            route_eligible = bool(
                not _is_local
                and workflow_parallel_ready
                and not chart_route_blocked_reason
            )
            self.bus.bridge_event(run_id, {
                "type": "dynamic_workflow_route",
                "configuredMode": workflow_mode,
                "effectiveMode": effective_workflow_mode,
                "eligible": route_eligible,
                "reason": eligibility_reason or "eligible for Main routing",
                "a2aAgents": a2a_agents,
                "a2aExecution": a2a_execution,
                "terminalLayout": terminal_layout,
                "localModel": _is_local,
                "maxStages": workflow_max_stages,
                "maxAgents": workflow_max_agents,
                "workflowChartPath": workflow_chart_path,
                "workflowChartSelected": bool(workflow_chart_path),
                "workflowChartRouteForced": chart_route_forced,
                "workflowChartRouteBlocked": bool(chart_route_blocked_reason),
                "candidateOnly": True,
                "canClaimAGI": False,
            })
            if _is_local or not workflow_parallel_ready or chart_route_blocked_reason:
                if effective_workflow_mode == "on":
                    self._activate_run_mode(
                        handle,
                        "workflow",
                        phase="workflow prerequisite check",
                    )
                    from agent.agent_loop import AgentLoopResult
                    reason = eligibility_reason or (
                        "dynamic workflow prerequisites were not satisfied"
                    )
                    handle["dynamicWorkflowResult"] = {
                        "status": "failed",
                        "configuredMode": effective_workflow_mode,
                        "reason": reason,
                        "reasonCode": (
                            "flowchart_route_blocked"
                            if chart_route_blocked_reason
                            else "workflow_ineligible"
                        ),
                        "stages": 0,
                        "plannedStages": 0,
                        "maxStages": workflow_max_stages,
                        "totalAgents": 0,
                        "requestedAgents": 0,
                        "unstartedAgents": 0,
                        "workflowChart": (
                            {
                                "sourcePath": workflow_chart_path,
                                "error": reason,
                            }
                            if workflow_chart_path
                            else None
                        ),
                        "criticBarrier": {
                            "required": False,
                            "satisfied": False,
                        },
                        "candidateOnly": True,
                        "canClaimAGI": False,
                    }
                    res = AgentLoopResult(
                        goal=prompt,
                        final_text=(
                            (
                                "Selected flowchart workflow did not start: "
                                if workflow_chart_path
                                else "Dynamic workflow did not start: "
                            )
                            + f"{reason}. "
                            + (
                                "The selected chart was not run and the request "
                                "did not fall back to solo execution. "
                                if workflow_chart_path
                                else (
                                    "Use a cloud model with `/a2a auto` and "
                                    "`/terminals auto` or `/terminals headless`. "
                                )
                            )
                            + "candidateOnly: true; canClaimAGI: false."
                        ),
                        ok=False,
                        messages=list(history or []) + [{
                            "role": "assistant",
                            "content": (
                                (
                                    "Selected flowchart workflow did not start: "
                                    if workflow_chart_path
                                    else "Dynamic workflow did not start: "
                                )
                                + f"{reason}. "
                                + (
                                    "The selected chart was not run and the "
                                    "request did not fall back to solo execution. "
                                    if workflow_chart_path
                                    else (
                                        "Use a cloud model with `/a2a auto` and "
                                        "`/terminals auto` or `/terminals headless`. "
                                    )
                                )
                                + "candidateOnly: true; canClaimAGI: false."
                            ),
                        }],
                        model_error=reason,
                    )
                else:
                    self._activate_run_mode(
                        handle,
                        "solo",
                        phase="workflow skipped",
                    )
                    self.bus.bridge_event(run_id, {
                        "type": "dynamic_workflow_end",
                        "selected": False,
                        "status": "skipped",
                        "reason": eligibility_reason,
                        "workflowChartSelected": bool(workflow_chart_path),
                        "workflowChartRouteBlocked": bool(chart_route_blocked_reason),
                        "stages": 0,
                        "plannedStages": 0,
                        "maxStages": workflow_max_stages,
                        "totalAgents": 0,
                        "candidateOnly": True,
                        "canClaimAGI": False,
                    })
                    res = run_agent_loop(
                        prompt,
                        client=tee,
                        ctx=ctx,
                        history=history,
                        on_event=primary_sink,
                        max_steps=max_steps,
                        system_extra=system_extra,
                        show_thinking=deep_think,
                        steering_consumer=steering_consumer,
                        budget=budget,
                        max_parallel_tools=max_parallel_tools,
                        post_tool_continuity=True,
                        max_continuations=_loop_continuations,
                        raw_user_turn=raw_prompt,
                        current_task=(
                            prompt if continuation is not None else None
                        ),
                        response_style=response_style,
                        require_live_refresh=bool(
                            continuation is not None
                            and continuation.requires_live_refresh
                        ),
                    )
            else:
                self._activate_run_mode(
                    handle,
                    "workflow",
                    phase="workflow routing",
                )
                res = self._run_dynamic_workflow(
                    handle,
                    prompt,
                    tee,
                    ctx,
                    primary_sink,
                    configured_mode=effective_workflow_mode,
                    max_stages=workflow_max_stages,
                    max_agents=workflow_max_agents,
                    max_steps=max_steps,
                    history=history,
                    raw_prompt=raw_prompt,
                    show_thinking=deep_think,
                    system_extra=system_extra,
                    budget=budget,
                    max_parallel_tools=max_parallel_tools,
                    max_continuations=_loop_continuations,
                    response_style=response_style,
                    steering_consumer=steering_consumer,
                    require_live_refresh=bool(
                        continuation is not None
                        and continuation.requires_live_refresh
                    ),
                    execution=a2a_execution,
                    terminal_layout=terminal_layout,
                    model_alias=model_alias,
                    mode=mode,
                    permission=permission,
                    session=session,
                    root=root,
                    workflow_chart_path=workflow_chart_path,
                    resume_workflow_run_id=(
                        _safe_text(
                            cmd.get("workflowResumeRunId"),
                            limit=160,
                        )
                        or None
                    ),
                )
        elif a2a_agents != 0:
            self._activate_run_mode(handle, "a2a", phase="Main planning")
            res = self._run_a2a_chain(
                handle,
                prompt,
                tee,
                ctx,
                primary_sink,
                a2a_agents=a2a_agents,
                max_steps=max_steps,
                history=history,
                raw_prompt=raw_prompt,
                show_thinking=deep_think,
                system_extra=system_extra,
                budget=budget,
                max_parallel_tools=max_parallel_tools,
                max_continuations=_loop_continuations,
                response_style=response_style,
                steering_consumer=steering_consumer,
                require_live_refresh=bool(
                    continuation is not None
                    and continuation.requires_live_refresh
                ),
                execution=a2a_execution,
                terminal_layout=terminal_layout,
                model_alias=model_alias,
                mode=mode,
                permission=permission,
                session=session,
                root=root,
                local_model=_is_local,
            )
        else:
            self._activate_run_mode(handle, "solo", phase="model execution")
            res = run_agent_loop(
                prompt,
                client=tee,
                ctx=ctx,
                history=history,
                on_event=primary_sink,
                max_steps=max_steps,
                system_extra=system_extra,
                show_thinking=deep_think,
                steering_consumer=steering_consumer,
                budget=budget,
                max_parallel_tools=max_parallel_tools,
                # Interactive TUI run: keep the loop alive after each tool so a
                # tool result is never abandoned by an early short final. The
                # bench / gaia / tbench handlers leave this off (default) to
                # preserve their measurement behaviour.
                post_tool_continuity=True,
                allow_continuation_nudges=not internal_artifact,
                max_continuations=_loop_continuations,
                raw_user_turn=raw_prompt,
                current_task=prompt if continuation is not None else None,
                response_style=response_style,
                require_live_refresh=bool(
                    continuation is not None
                    and continuation.requires_live_refresh
                ),
                continue_unfinished_objective=_normalize_bool(
                    cmd.get("continueUnfinishedObjective"),
                    default=True,
                ),
                defer_delivery_gate=internal_artifact,
            )
        # Release the guard's checked tail. A short answer never reaches the
        # release threshold, so without this it would stream nothing at all.
        flush_stream()

        # Semantic recovery is distinct from transport fallback. A provider can
        # return ok=True yet supply only a policy refusal; in that case an
        # explicitly configured LOCAL model may be tried once, after operator
        # confirmation, and its operator-policy-reviewed candidate may be handed back to a
        # fresh instance of the selected primary for verification/continuation.
        #
        # There is exactly one cycle. A resumed primary refusal never recurses.
        from agent.semantic_fallback import (
            build_local_fallback_prompt,
            build_primary_resume_prompt,
            detect_semantic_refusal,
            is_gate_uphold_report,
        )

        semantic_meta: dict[str, Any] = {
            "semanticFallbackDetected": False,
            "semanticFallbackUsed": False,
            "semanticFallbackReason": "",
            "semanticFallbackProvider": "",
            "semanticFallbackModel": "",
            "semanticFallbackApproved": None,
            "primaryResumeAttempted": False,
            "returnedToPrimary": False,
            "primaryResumeProvider": "",
            "primaryResumeModel": "",
            "primaryResumeDeclined": False,
        }
        selected_final_events = primary_final_events
        primary_decision = detect_semantic_refusal(
            res.final_text,
            ok=bool(res.ok),
            gated=bool(res.gated),
            model_error=getattr(res, "model_error", None),
        )
        if (
            primary_decision.triggered
            and not agi_mode
            and str(handle.get("runMode") or "") != "workflow"
            and not internal_artifact
        ):
            semantic_meta["semanticFallbackDetected"] = True
            semantic_meta["semanticFallbackReason"] = primary_decision.reason
            primary_provider = tee.last_provider or getattr(
                getattr(client, "primary", None), "label", ""
            ) or model_alias
            primary_resolved_model = tee.last_model or getattr(
                getattr(client, "primary", None), "model", ""
            )
            self.bus.bridge_event(
                run_id,
                {
                    "type": "semantic_refusal_detected",
                    "reason": primary_decision.reason,
                    "signals": list(primary_decision.signals),
                    "primaryProvider": primary_provider,
                    "primaryModel": primary_resolved_model,
                },
            )

            skip_reason = ""
            try:
                primary_cfg = m.resolve_config(_model_spec(model_alias))
                primary_is_local = m.is_local_model(primary_cfg)
            except Exception:  # noqa: BLE001 - inability to classify fails closed
                primary_is_local = True
            if semantic_fallback_policy != "confirm":
                skip_reason = "semantic fallback policy is off"
            elif not semantic_fallback_model:
                skip_reason = "no semantic fallback model is configured"
            elif primary_is_local:
                skip_reason = (
                    "the selected primary is already local; cloud-to-local semantic "
                    "fallback was not armed"
                )

            local_cfg = None
            local_spec = ""
            if not skip_reason:
                try:
                    local_spec = _model_spec(semantic_fallback_model or "")
                    local_cfg = m.resolve_config(local_spec)
                except Exception as exc:  # noqa: BLE001 - invalid config fails closed
                    skip_reason = f"configured semantic fallback could not be resolved: {type(exc).__name__}"
                else:
                    if not m.is_local_model(local_cfg):
                        skip_reason = (
                            "configured semantic fallback is not a verified local/self-hosted model"
                        )

            if skip_reason:
                self.bus.bridge_event(
                    run_id,
                    {
                        "type": "semantic_fallback_skipped",
                        "reason": skip_reason,
                        "configuredModel": semantic_fallback_model or "",
                    },
                )
            else:
                assert local_cfg is not None  # narrowed above
                local_provider = local_cfg.label or local_cfg.kind
                local_model_name = local_cfg.model
                approved = fallback_approver(
                    "semantic local-model fallback",
                    (
                        "The selected primary returned a non-substantive policy refusal.\n"
                        f"Primary: {primary_provider}/{primary_resolved_model or model_alias}\n"
                        "Authority boundary: cloud/provider authority → local/self-hosted authority\n"
                        f"Local fallback: {local_provider}/{local_model_name}\n"
                        "Local authority: "
                        f"{_fallback_authority_preview(m._fallback_authority_descriptor(local_cfg))}\n"
                        f"Reason: {primary_decision.reason}\n"
                        "Retry this current authorized request once with the local model? "
                        "The same tool permission and the operator-selected final Conscience "
                        f"policy ({conscience_mode}) apply."
                    ),
                )
                semantic_meta["semanticFallbackApproved"] = bool(approved)
                if not approved:
                    self.bus.bridge_event(
                        run_id,
                        {
                            "type": "semantic_fallback_skipped",
                            "reason": "operator denied the cloud-to-local authority crossing",
                            "configuredModel": semantic_fallback_model or "",
                        },
                    )
                else:
                    try:
                        local_client = _build_model_client(
                            m.default_client,
                            local_spec,
                            fallback_confirmer=lambda request: False,
                            working_dir=root,
                        )
                        actual_local_cfg = getattr(local_client, "primary", None)
                        if isinstance(actual_local_cfg, m.ModelConfig) and (
                            not m.is_local_model(actual_local_cfg)
                            or actual_local_cfg.model != local_cfg.model
                        ):
                            raise ValueError(
                                "local fallback factory did not preserve the approved local model"
                            )
                        # Exact local authority only: environment fallback chains
                        # must not substitute a cloud service underneath a model
                        # the operator approved as local.
                        try:
                            local_client.fallbacks = []
                            local_client.fallback_policy = m.FallbackPolicy.from_value("never")
                            local_client.fallback_confirmer = None
                        except (AttributeError, TypeError):
                            # Compatible injected clients may not expose mutable
                            # fallback-config fields; the exact provider boundary
                            # is still enforced by the resolved config check above.
                            pass
                        try:
                            terminal_cli._set_client_sampling(
                                local_client,
                                temperature=float(os.environ["SOPHIA_TEMPERATURE"]),
                                top_p=float(os.environ["SOPHIA_TOP_P"]),
                                top_k=int(os.environ["SOPHIA_TOP_K"]),
                            )
                        except (AttributeError, TypeError, ValueError):
                            # Compatible injected clients may not expose mutable
                            # sampling fields; the exact provider boundary still
                            # remains enforced by the resolved config check.
                            pass
                    except Exception as exc:  # noqa: BLE001
                        self.bus.bridge_event(
                            run_id,
                            {
                                "type": "semantic_fallback_skipped",
                                "reason": f"local fallback client failed to initialize: {type(exc).__name__}",
                                "configuredModel": semantic_fallback_model or "",
                            },
                        )
                    else:
                        semantic_meta["semanticFallbackUsed"] = True
                        semantic_meta["semanticFallbackProvider"] = local_provider
                        semantic_meta["semanticFallbackModel"] = local_model_name
                        self.bus.bridge_event(
                            run_id,
                            {
                                "type": "semantic_fallback_start",
                                "primaryProvider": primary_provider,
                                "primaryModel": primary_resolved_model,
                                "fallbackProvider": local_provider,
                                "fallbackModel": local_model_name,
                                "authorityBoundary": "cloud-to-local",
                            },
                        )
                        local_final_events: list[dict[str, Any]] = []
                        local_tee, flush_local_stream = stage_tee(local_client)
                        _set_context_clients(ctx, local_tee)
                        primary_steps = list(res.steps or [])
                        local_prompt = build_local_fallback_prompt(
                            prompt,
                            res.final_text,
                            completed_steps=primary_steps,
                        )
                        local_res = run_agent_loop(
                            local_prompt,
                            client=local_tee,
                            ctx=ctx,
                            history=history,
                            on_event=buffered_sink(local_final_events),
                            max_steps=max_steps,
                            system_extra=system_extra,
                            show_thinking=deep_think,
                            steering_consumer=steering_consumer,
                            budget=budget,
                            post_tool_continuity=True,
                            # Keep the normal bounded local-model ceiling.
                            max_continuations=None,
                            raw_user_turn=raw_prompt,
                            current_task=local_prompt,
                            response_style=response_style,
                        )
                        flush_local_stream()
                        local_only_steps = list(local_res.steps or [])
                        local_res.steps = [*primary_steps, *local_only_steps]
                        semantic_meta["semanticFallbackProvider"] = (
                            local_tee.last_provider or local_provider
                        )
                        semantic_meta["semanticFallbackModel"] = (
                            local_tee.last_model or local_model_name
                        )
                        local_decision = detect_semantic_refusal(
                            local_res.final_text,
                            ok=bool(local_res.ok),
                            gated=bool(local_res.gated),
                            model_error=getattr(local_res, "model_error", None),
                        )
                        self.bus.bridge_event(
                            run_id,
                            {
                                "type": "semantic_fallback_complete",
                                "ok": bool(local_res.ok),
                                "gated": bool(local_res.gated),
                                "provider": semantic_meta["semanticFallbackProvider"],
                                "model": semantic_meta["semanticFallbackModel"],
                                "answerChars": len(local_res.final_text or ""),
                                "semanticRefusal": bool(local_decision.triggered),
                                "conscienceMode": conscience_mode,
                            },
                        )

                        local_usable_for_resume = (
                            bool(local_res.ok)
                            and bool((local_res.final_text or "").strip())
                            and not bool(getattr(local_res, "model_error", None))
                            and not bool(local_res.gated)
                            and not is_gate_uphold_report(local_res.final_text)
                            and not local_decision.triggered
                        )
                        if not local_usable_for_resume or not semantic_return_to_primary:
                            res = local_res
                            tee = local_tee
                            _set_context_clients(ctx, local_tee)
                            selected_final_events = local_final_events
                        else:
                            semantic_meta["primaryResumeAttempted"] = True
                            semantic_meta["primaryResumeProvider"] = (
                                primary_cfg.label or primary_cfg.kind
                            )
                            semantic_meta["primaryResumeModel"] = primary_cfg.model
                            self.bus.bridge_event(
                                run_id,
                                {
                                    "type": "semantic_primary_resume_start",
                                    "primaryProvider": primary_cfg.label or primary_cfg.kind,
                                    "primaryModel": primary_cfg.model,
                                    "fallbackProvider": semantic_meta["semanticFallbackProvider"],
                                    "fallbackModel": semantic_meta["semanticFallbackModel"],
                                    "conscienceMode": conscience_mode,
                                },
                            )
                            resume_final_events: list[dict[str, Any]] = []
                            try:
                                resume_client = _build_model_client(
                                    m.default_client,
                                    _model_spec(model_alias),
                                    fallback_confirmer=confirm_fallback,
                                    working_dir=root,
                                )
                                actual_resume_cfg = getattr(resume_client, "primary", None)
                                if isinstance(actual_resume_cfg, m.ModelConfig) and (
                                    m.is_local_model(actual_resume_cfg)
                                    or actual_resume_cfg.model != primary_cfg.model
                                ):
                                    raise ValueError(
                                        "primary resume factory did not preserve the selected cloud model"
                                    )
                                try:
                                    resume_client.fallbacks = []
                                    resume_client.fallback_policy = m.FallbackPolicy.from_value("never")
                                except (AttributeError, TypeError):
                                    # Compatible injected clients may not expose mutable
                                    # fallback-config fields; the exact provider boundary
                                    # is still enforced by the resolved config check above.
                                    pass
                                try:
                                    terminal_cli._set_client_sampling(
                                        resume_client,
                                        temperature=float(os.environ["SOPHIA_TEMPERATURE"]),
                                        top_p=float(os.environ["SOPHIA_TOP_P"]),
                                        top_k=int(os.environ["SOPHIA_TOP_K"]),
                                    )
                                except (AttributeError, TypeError, ValueError):
                                    # Compatible injected clients may not expose mutable
                                    # sampling fields; the exact provider boundary still
                                    # remains enforced by the resolved config check.
                                    pass
                                resume_tee, flush_resume_stream = stage_tee(resume_client)
                                _set_context_clients(
                                    ctx,
                                    resume_tee,
                                    subagent_client=team_worker_tee,
                                )
                                resume_prompt = build_primary_resume_prompt(
                                    prompt,
                                    local_res.final_text,
                                    completed_steps=local_res.steps,
                                )
                                resume_res = run_agent_loop(
                                    resume_prompt,
                                    client=resume_tee,
                                    ctx=ctx,
                                    history=history,
                                    on_event=buffered_sink(resume_final_events),
                                    max_steps=max_steps,
                                    system_extra=system_extra,
                                    show_thinking=deep_think,
                                    steering_consumer=steering_consumer,
                                    budget=budget,
                                    post_tool_continuity=True,
                                    max_continuations=_loop_continuations,
                                    raw_user_turn=raw_prompt,
                                    current_task=resume_prompt,
                                    response_style=response_style,
                                )
                                flush_resume_stream()
                            except _RunCancelled:
                                raise
                            except Exception as exc:  # noqa: BLE001
                                semantic_meta["primaryResumeDeclined"] = True
                                local_res.steps = list(local_res.steps or [])
                                res = local_res
                                tee = local_tee
                                _set_context_clients(ctx, local_tee)
                                selected_final_events = local_final_events
                                self.bus.bridge_event(
                                    run_id,
                                    {
                                        "type": "semantic_primary_resume_declined",
                                        "reason": f"primary resume failed to initialize or run: {type(exc).__name__}",
                                        "retained": (
                                            "local-gate-cleared-result"
                                            if conscience_mode in {"floor", "strict"}
                                            else "local-operator-policy-result"
                                        ),
                                        "conscienceMode": conscience_mode,
                                    },
                                )
                            else:
                                resume_only_steps = list(resume_res.steps or [])
                                combined_steps = [
                                    *list(local_res.steps or []),
                                    *resume_only_steps,
                                ]
                                resume_res.steps = combined_steps
                                resume_decision = detect_semantic_refusal(
                                    resume_res.final_text,
                                    ok=bool(resume_res.ok),
                                    gated=bool(resume_res.gated),
                                    model_error=getattr(resume_res, "model_error", None),
                                )
                                resume_failed = (
                                    not bool(resume_res.ok)
                                    or bool(getattr(resume_res, "model_error", None))
                                    or not bool((resume_res.final_text or "").strip())
                                )
                                semantic_meta["primaryResumeProvider"] = (
                                    resume_tee.last_provider or primary_cfg.label or primary_cfg.kind
                                )
                                semantic_meta["primaryResumeModel"] = (
                                    resume_tee.last_model or primary_cfg.model
                                )
                                if (resume_decision.triggered or resume_failed) and not resume_res.gated:
                                    semantic_meta["primaryResumeDeclined"] = True
                                    local_res.steps = combined_steps
                                    res = local_res
                                    tee = local_tee
                                    _set_context_clients(ctx, local_tee)
                                    selected_final_events = local_final_events
                                    self.bus.bridge_event(
                                        run_id,
                                        {
                                            "type": "semantic_primary_resume_declined",
                                            "reason": (
                                                resume_decision.reason
                                                if resume_decision.triggered
                                                else "primary resume returned no usable answer"
                                            ),
                                            "retained": (
                                                "local-gate-cleared-result"
                                                if conscience_mode in {"floor", "strict"}
                                                else "local-operator-policy-result"
                                            ),
                                            "conscienceMode": conscience_mode,
                                        },
                                    )
                                else:
                                    semantic_meta["returnedToPrimary"] = True
                                    res = resume_res
                                    tee = resume_tee
                                    _set_context_clients(
                                        ctx,
                                        resume_tee,
                                        subagent_client=team_worker_tee,
                                    )
                                    selected_final_events = resume_final_events
                                    self.bus.bridge_event(
                                        run_id,
                                        {
                                            "type": "semantic_primary_resume_complete",
                                            "ok": bool(resume_res.ok),
                                            "gated": bool(resume_res.gated),
                                            "provider": semantic_meta["primaryResumeProvider"],
                                            "model": semantic_meta["primaryResumeModel"],
                                            "answerChars": len(resume_res.final_text or ""),
                                        },
                                    )

        # Publish only the terminal preview belonging to the selected result.
        # Every stage already wrote its own trace; this controls presentation,
        # not audit retention.
        for final_event in selected_final_events:
            sink(final_event)
        elapsed = time.time() - started

        # Surface provider failures the kernel loop swallows into empty answers
        # (e.g. HTTP 403/429 with no text): the run did not actually succeed.
        # The kernel may also report the failure explicitly via AgentLoopResult
        # .model_error (it then fills final_text with a "Model call failed: …"
        # notice), so honor that signal too instead of relying on empty text.
        # Computed BEFORE Deep Think so the review stage can be skipped when the
        # main run never produced a real answer (there is nothing to review).
        steps = [
            {"tool": s.get("tool"), "ok": bool(s.get("ok")), "args": s.get("args") or {}}
            for s in (res.steps or [])
        ]
        loop_incomplete = bool(getattr(res, "incomplete", False))
        incomplete_reason = str(
            getattr(res, "incomplete_reason", None) or ""
        ).strip()
        kernel_model_error = getattr(res, "model_error", None)
        model_error = tee.last_model_error or kernel_model_error
        model_failed = bool(kernel_model_error) or (
            bool(tee.last_model_error) and not (res.final_text or "").strip()
        )
        # Same for a nominally-"ok" but empty answer with zero tool steps — a
        # healthy provider never answers a task with nothing, so treat it as a
        # failed call (usually a broken/missing CLI or a dead server).
        empty_answer = not (res.final_text or "").strip() and not steps
        if empty_answer:
            model_failed = True
            if not model_error:
                model_error = ("provider returned an empty answer with no tool steps "
                               "(often a missing CLI, dead server, or region-blocked API — "
                               "see the Debug report)")

        # Deep Think second stage: a creative→logical debate over the run's own
        # transcript. It may improve the final answer, but must preserve the
        # model's natural presentation instead of imposing a harness template.
        # Runs whenever deep_think is on (high/ultra) — always, with no per-effort
        # episode count. SKIP only when the main run failed (no usable transcript).
        review: dict[str, Any] | None = None
        deep_think_empty = False
        deep_think_skipped_reason = ""
        authoritative_text = res.final_text or ""
        if deep_think and agi_mode:
            # AGI mode already has an explicit verifier + delivery-gate phase.
            # Running the generic Deep Think pass afterwards would create a
            # second, tools-free authority layer that can overwrite the
            # controller's evidence-grounded terminal report.
            deep_think_skipped_reason = (
                "AGI mode already completed its verifier and delivery gate; "
                "preserving the controller result"
            )
            review = {
                "schema": "sophia.code_deep_think.v1", "stages": [],
                "conclusion": "", "confidence": "", "partial": False,
                "skipped": True,
                "diagnostics": {"reason": deep_think_skipped_reason},
                "canClaimAGI": False,
            }
            self.bus.bridge_event(handle["id"], {"type": "deep_think_done", **review})
        elif deep_think and str(handle.get("runMode") or "") == "workflow":
            # Dynamic workflow already has a controller review after every
            # parallel barrier plus a separate delivery-gated Main synthesis.
            # A generic tools-free post-pass cannot see the full worker traces
            # and must not replace that evidence-grounded final answer.
            deep_think_skipped_reason = (
                "dynamic workflow already completed staged controller review "
                "and final synthesis; preserving the workflow result"
            )
            review = {
                "schema": "sophia.code_deep_think.v1", "stages": [],
                "conclusion": "", "confidence": "", "partial": False,
                "skipped": True,
                "diagnostics": {"reason": deep_think_skipped_reason},
                "canClaimAGI": False,
            }
            self.bus.bridge_event(handle["id"], {"type": "deep_think_done", **review})
        elif deep_think and is_exact_output_request(prompt):
            # A valid exact response cannot be improved by a creative debate; its
            # three conclusions are categorically ineligible to replace the literal.
            review = {
                "schema": "sophia.code_deep_think.v1", "stages": [],
                "conclusion": "", "confidence": "", "partial": False,
                "skipped": True,
                "diagnostics": {"reason": "exact-output request preserved"},
                "canClaimAGI": False,
            }
            self.bus.bridge_event(handle["id"], {"type": "deep_think_done", **review})
        elif deep_think and lane_results:
            # A completed team run already has an answer-only coordinator that
            # synthesized the workers' native-tool evidence. The later
            # tools-free Deep Think digest only sees ``res.steps`` from that
            # coordinator (normally empty), not the lane transcripts. Running
            # it would therefore erase real evidence by falsely treating the
            # synthesized answer as an unsupported direct response.
            deep_think_skipped_reason = (
                "team coordinator already synthesized teammate evidence; "
                "preserving the coordinator result"
            )
            review = {
                "schema": "sophia.code_deep_think.v1", "stages": [],
                "conclusion": "", "confidence": "", "partial": False,
                "skipped": True,
                "diagnostics": {"reason": deep_think_skipped_reason},
                "canClaimAGI": False,
            }
            self.bus.bridge_event(handle["id"], {"type": "deep_think_done", **review})
        elif deep_think:
            run_usable = (
                not model_failed
                and not loop_incomplete
                and bool(authoritative_text.strip() or steps)
            )
            if not run_usable:
                # Nothing to review: the main run produced no text and no tool
                # steps (provider failure / empty answer). Emit a terminal
                # deep-think event so the app's review node closes cleanly,
                # then carry the primary answer forward as-is.
                deep_think_skipped_reason = (
                    "main run ended incomplete; preserving its resumable checkpoint"
                    if loop_incomplete
                    else "main run produced no usable answer; nothing to review"
                )
                review = {
                    "schema": "sophia.code_deep_think.v1", "episodes": [], "conclusion": "",
                    "confidence": "", "partial": False, "skipped": True,
                    "diagnostics": {"reason": deep_think_skipped_reason}, "canClaimAGI": False,
                }
                self.bus.bridge_event(handle["id"], {"type": "deep_think_done", **review})
            else:
                from agent.continuation import build_continuation_context
                continuation_text = "\n".join(
                    str(item.get("content") or "")
                    for item in build_continuation_context(history, effective_request=prompt)
                )
                review = self._run_deep_think(
                    handle, prompt, tee, ctx, res,
                    continuation_context=continuation_text,
                    response_style=response_style,
                    lane_results=lane_results,
                )
                conclusion = str((review or {}).get("conclusion") or "").strip()
                from agent import code_bridge_deepthink as _dt
                authoritative_text = _dt.choose_final_text(
                    primary_text=authoritative_text,
                    conclusion_text=conclusion,
                    exact_output=is_exact_output_request(prompt),
                    conclusion_ok=not bool((review or {}).get("partial")),
                )
                if not authoritative_text.strip():
                    deep_think_empty = True
                    authoritative_text = "Deep-think review produced no conclusion. The run did not complete a usable answer."
            elapsed = time.time() - started

        res.final_text = authoritative_text
        # The primary loop already appended its pre-review assistant answer. If
        # Deep Think replaced it, update that one canonical turn in place; never
        # append a second assistant conclusion that later continuation can treat
        # as a separate instruction/outcome.
        if res.messages and res.messages[-1].get("role") == "assistant":
            res.messages[-1] = {**res.messages[-1], "content": authoritative_text}

        run_ok = bool(res.ok) and not model_failed and not deep_think_empty
        raw_loop_resumable = getattr(res, "resumable", None)
        loop_resumable = (
            loop_incomplete
            if raw_loop_resumable is None
            else bool(raw_loop_resumable)
        )
        completeness_result = getattr(res, "completeness_result", None)
        if not isinstance(completeness_result, dict):
            completeness_result = dict(handle.get("completenessResult") or {})
        completion_mode_result = str(
            handle.get("completionMode")
            or completeness_result.get("mode")
            or (cmd.get("completionMode") if completeness_result else "")
            or ""
        ).strip().lower()
        if continuation is not None and run_ok:
            from agent.continuation import fulfill_latest_continuation
            res.messages = fulfill_latest_continuation(
                res.messages, instruction=continuation.instruction)
        terminal_cli._save_conversation(terminal_cli._conversation_path(session), res.messages)

        files: list[str] = []
        for step in res.steps or []:
            args = step.get("args") or {}
            if not step.get("ok") or step.get("tool") not in {"write_file", "edit_file"}:
                continue
            try:
                touched = _resolve_under_workspace(root, args.get("path"))
            except (OSError, ValueError):
                # A rejected/invalid tool path must never be reported as touched.
                continue
            files.append(str(touched.relative_to(root)))
        files = sorted(set(files))
        # Per-file added/removed line counts, derived from the SAME checkpoint
        # store every write_file/edit_file call already populates (agent_tools.
        # _capture_checkpoint) — not a fresh mechanism. Diffs each touched
        # file's pre-mutation checkpoint bytes against its current on-disk
        # bytes; a file this cannot honestly diff (checkpoint missing, blob
        # unreadable) is simply left out of fileChanges rather than reported
        # as a fabricated 0/0.
        file_changes: dict[str, dict[str, int]] = {}
        try:
            from agent.agent_tools import list_checkpoints
            checkpoints = list_checkpoints(ctx)
        except Exception:  # noqa: BLE001 - a change-summary miss must never fail the run
            checkpoints = []
        for rel_path in files:
            counts = _file_change_counts(ctx, checkpoints, rel_path)
            if counts is not None:
                file_changes[rel_path] = counts
        logic = terminal_cli._logic_audit(res.final_text, logic_judge)
        try:
            confidence = terminal_cli._extract_confidence(res.final_text) or "n/a"
        except Exception:  # noqa: BLE001 - display metadata is best-effort
            confidence = "n/a"

        certificate = {
            "kind": "sophia-code-app-certificate",
            "deliveryGatePassed": bool(res.ok),
            "deliveryGated": bool(res.gated),
            "deliveryPolicyMode": conscience_mode,
            "deliveryGateEnforced": conscience_mode in {"floor", "strict"},
            "deliveryEvaluationRan": conscience_mode != "off",
            "gateBypass": gate_bypass,
            "tracePath": res.trace_path,
            "toolsRun": [s["tool"] for s in steps],
            "filesTouched": files,
            "permission": permission,
            "session": session,
            "team": team,
            "autoTeam": auto_team_setting,
            "goalMode": bool(cmd.get("goalMode")),
            "a2aAgents": a2a_agents,
            "a2aExecution": a2a_execution,
            "workflowMode": workflow_mode,
            "workflowEffectiveMode": effective_workflow_mode,
            "workflowMaxStages": workflow_max_stages,
            "workflowMaxAgents": workflow_max_agents,
            "workflowResult": dict(handle.get("dynamicWorkflowResult") or {}),
            "agiWorkflowMode": agi_workflow_mode,
            "agiWorkflow": dict(handle.get("agiWorkflowResult") or {}),
            "agiMode": agi_mode,
            "agiProfile": agi_profile,
            "agiRoute": agi_route,
            "agiResult": dict(handle.get("agiResult") or {}),
            "acceptanceReceipt": dict(
                getattr(res, "acceptance_receipt", None) or {}
            ),
            "deepThink": deep_think,
            "conscienceMode": conscience_mode,
            "semanticFallbackUsed": bool(semantic_meta["semanticFallbackUsed"]),
            "semanticFallbackModel": semantic_meta["semanticFallbackModel"],
            "returnedToPrimary": bool(semantic_meta["returnedToPrimary"]),
            "canClaimAGI": False,
        }
        agi_result_status = str(
            (handle.get("agiResult") or {}).get("status") or ""
        ).lower()
        agi_awaiting_input = bool(
            agi_mode
            and agi_result_status in {
                "paused",
                "awaiting_input",
                "interrupted",
            }
        )
        workflow_result = dict(handle.get("dynamicWorkflowResult") or {})
        workflow_result_status = str(
            workflow_result.get("status") or ""
        ).lower()
        workflow_awaiting_input = bool(
            str(handle.get("runMode") or "") == "workflow"
            and workflow_result_status == "awaiting_input"
        )
        payload: dict[str, Any] = {
            "ok": run_ok,
            "incomplete": loop_incomplete or bool(getattr(res, "incomplete", False)),
            "resumable": loop_resumable,
            "completionMode": completion_mode_result,
            "completenessResult": completeness_result,
            "orchestrationStatus": getattr(res, "orchestration_status", None)
            or ("completed" if not (loop_incomplete or getattr(res, "incomplete", False)) else "running"),
            "taskStatus": getattr(res, "task_status", None)
            or ("complete" if run_ok else "incomplete"),
            "verificationStatus": getattr(res, "verification_status", None) or "",
            "observedRoute": handle.get("observedRoute") or "",
            **(
                {"awaitingInput": True}
                if agi_awaiting_input or workflow_awaiting_input
                else {}
            ),
            **({"incompleteReason": incomplete_reason or getattr(res, "incomplete_reason", "")} if (incomplete_reason or getattr(res, "incomplete_reason", None)) else {}),
            "goal": prompt,
            "finalText": res.final_text,
            "summary": _summary(res.final_text),
            "confidence": confidence,
            "gated": bool(res.gated),
            # What the gate actually checked. "gated" alone cannot tell
            # "cleared" from "merely not prohibited" — see agent/epistemic_status.py.
            "epistemic": dict(getattr(res, "epistemic", None) or {}),
            "tracePath": res.trace_path,
            "permission": permission,
            "root": str(root),
            "steps": steps,
            "filesTouched": files,
            "fileChanges": file_changes,
            "logicJudge": logic,
            "certificate": certificate,
            "session": {"id": session, "name": session},
            "model": model_alias,
            # What actually answered. "model" above is the alias the user picked;
            # these say who served it, so a fallback substitution or a CLI
            # transport choosing its own model is visible instead of silent.
            "provider": tee.last_provider or "",
            "resolvedModel": tee.last_model or "",
            "fallbackUsed": bool(tee.fallback_used),
            "mode": mode,
            "team": team,
            "workflowMode": workflow_mode,
            "workflowEffectiveMode": effective_workflow_mode,
            "workflowMaxStages": workflow_max_stages,
            "workflowMaxAgents": workflow_max_agents,
            "workflowResult": workflow_result,
            "agiWorkflowMode": agi_workflow_mode,
            "agiWorkflow": dict(handle.get("agiWorkflowResult") or {}),
            "dynamicWorkflowStages": [
                {
                    "stage": _safe_int(stage.get("stage"), 0),
                    "pattern": str(stage.get("pattern") or ""),
                    "kind": str(stage.get("kind") or "general"),
                    "goal": str(stage.get("goal") or ""),
                    "status": str(stage.get("status") or ""),
                    "requestedAgentCount": _safe_int(
                        stage.get("requestedAgentCount"),
                        len(stage.get("agents") or []),
                    ),
                    "startedAgentCount": _safe_int(
                        stage.get("startedAgentCount"),
                        len(stage.get("agents") or []),
                    ),
                    "unstartedAgentCount": _safe_int(
                        stage.get("unstartedAgentCount"),
                        0,
                    ),
                    "maxConcurrency": _safe_int(
                        stage.get("maxConcurrency"), 0
                    ),
                    "agents": [
                        {
                            "name": str(agent.get("name") or ""),
                            "role": str(
                                agent.get("persona")
                                or agent.get("role")
                                or "sub"
                            ),
                            "skills": [
                                str(skill)
                                for skill in (agent.get("skills") or [])
                                if str(skill)
                            ],
                            "status": str(agent.get("status") or ""),
                            **(
                                {
                                    "reasonCode": str(
                                        agent.get("reasonCode")
                                    )
                                }
                                if agent.get("reasonCode")
                                else {}
                            ),
                            **(
                                {"started": bool(agent.get("started"))}
                                if agent.get("started") is not None
                                else {}
                            ),
                        }
                        for agent in (stage.get("agents") or [])
                        if isinstance(agent, dict)
                    ],
                }
                for stage in (handle.get("dynamicWorkflowStages") or [])
                if isinstance(stage, dict)
            ],
            "agiMode": agi_mode,
            "agiWorkflowMode": agi_workflow_mode,
            "agiProfile": agi_profile,
            "agiRoute": agi_route,
            "agiRunId": handle.get("agiRunId", ""),
            "agiStatus": agi_result_status,
            "effort": effort,
            "maxSteps": max_steps,
            "deepThink": deep_think,
            "sophiaContract": sophia_contract,
            "responseStyle": response_style,
            "conscienceMode": conscience_mode,
            "exactOutput": is_exact_output_request(prompt),
            "gateBypass": gate_bypass,
            "elapsedSec": round(elapsed, 2),
            "budget": dict(handle.get("budgetReceipt", {})),
            "laneResults": lane_results,
            "teamDegraded": bool(handle.get("teamDegraded")),
            "continuationResolved": continuation is not None,
            "continuationSource": continuation.source if continuation is not None else "literal",
            "effectiveRequest": prompt,
            "rawPrompt": raw_prompt,
            "deepThinkReview": review,
            **semantic_meta,
            "display": {
                "summary": _summary(res.final_text),
                "confidence": confidence,
                "statusLabel": (
                    "Model call failed"
                    if model_failed
                    else str((handle.get("agiResult") or {}).get("status") or "")
                    if agi_mode
                    else "Incomplete · resume available"
                    if loop_incomplete
                    else "OK"
                    if run_ok
                    else "Held / failed"
                ),
                "toolCount": len(steps),
                "fileCount": len(files),
                "canClaimAGI": False,
            },
            "canClaimAGI": False,
        }
        if model_failed:
            payload["error"] = model_error
            payload["errorPayload"] = _safe_error_payload(
                message=str(model_error), error_type="ModelCallFailed")

        # Per-turn telemetry: model/provider are already on the payload above.
        # Cost/token totals come from AgentLoopResult (agent_loop.py already
        # sums them across every model call this run made, and reports None —
        # not 0 — when a transport never reported usage at all); throughput and
        # time-to-first-token are NOT on AgentLoopResult (they are properties
        # of an individual streamed ModelResult, not something the tool-use
        # loop tracks), so those two come from this run's own `tee`, which saw
        # every one of the same calls. Every key here is omitted, never
        # guessed, when the underlying number was never reported.
        prompt_tokens = (
            tee.prompt_tokens
            if tee.prompt_tokens is not None
            else getattr(res, "prompt_tokens", None)
        )
        completion_tokens = (
            tee.completion_tokens
            if tee.completion_tokens is not None
            else getattr(res, "completion_tokens", None)
        )
        cost_usd = (
            tee.cost_usd
            if tee.cost_usd is not None
            else getattr(res, "cost_usd", None)
        )
        if prompt_tokens is not None:
            payload["promptTokens"] = prompt_tokens
            handle["lastPromptTokens"] = prompt_tokens
        if completion_tokens is not None:
            payload["completionTokens"] = completion_tokens
        if cost_usd is not None:
            payload["costUsd"] = round(cost_usd, 6)
        payload["modelCalls"] = int(tee.model_calls)
        if tee.first_time_to_first_token_sec is not None:
            payload["ttftMs"] = round(tee.first_time_to_first_token_sec * 1000, 1)
        if isinstance(completion_tokens, int) and completion_tokens > 0 and tee.total_generation_sec > 0:
            payload["tokensPerSec"] = round(completion_tokens / tee.total_generation_sec, 2)
        if tee.malformed_tool_call_seen:
            payload["malformedToolCall"] = True

        # Supervised workflow/A2A workers are internal artifacts. Their child
        # session IDs must never become the operator's selected/default session
        # or replace the parent run in the global UI state. The parent bridge
        # persists its own state after the orchestration barrier completes.
        if bool(handle.get("internalArtifact")):
            if hook_config.enabled:
                self._dispatch_hook(run_id, hook_config, _HookEvent.STOP)
            return payload

        # Persist defaults + lastRun for the next launch.  Reload the current
        # on-disk state first: a setting the operator changed mid-run (e.g.
        # Shift+Tab -> permission auto) was written by _handle_settings while
        # this run was executing.  Writing back the start-of-run snapshot would
        # silently revert it (a lost update), so the concurrent change wins and
        # the run only contributes the values the operator did not re-set.
        fresh_state, _ = _load_state()
        fresh_defaults = _normalize_defaults(
            fresh_state.get("defaults") if isinstance(fresh_state.get("defaults"), dict) else {})
        # What this run RESOLVED becomes the next launch's default. Two keys are
        # deliberately absent, because for them "resolved" does not mean "chosen":
        #
        #   deepThink — the TUI has no Deep Think toggle; it derives the flag from
        #     the effort ladder and sends it on EVERY run. Writing that back flipped
        #     a persisted, cross-client setting (the macOS app restores it and shows
        #     it as a chip) as a side effect of running a prompt at high effort.
        #   logicJudge — never read by a run at all. The audit strength comes from
        #     the mode preset (MODE_PRESETS[mode]["logic_judge"]), so persisting the
        #     preset-derived value silently overwrote the operator's own setting
        #     with one they never chose, while their choice stayed inert.
        #
        # Both remain settable through `settings`, which IS an explicit act; a run
        # simply no longer votes on them.
        run_defaults = {
            "runtime": execution_runtime,
            "model": model_alias, "mode": mode, "permission": permission,
            # Persist the operator's team setting, not an ephemeral auto-team
            # triage result. Otherwise one automatic 3-lane dispatch silently
            # turns every later run into explicit team=3.
            "team": configured_team, "session": session, "maxSteps": max_steps,
            "gateBypass": gate_bypass, "effort": effort,
            "responseStyle": response_style,
            "conscienceMode": conscience_mode,
            "agiMode": agi_mode,
            "agiWorkflowMode": agi_workflow_mode,
            "agiProfile": agi_profile,
            "agiRoute": agi_route,
            "agiPlannerModel": agi_planner_model,
            "agiWorkerModel": agi_worker_model,
            "agiVerifierModel": agi_verifier_model,
        }
        if "autoTeam" in cmd or defaults.get("autoTeam") is not None:
            run_defaults["autoTeam"] = auto_team_setting
        # A key that changed on disk since this run started reflects a later
        # explicit operator action and must survive; otherwise use the run's
        # resolved value.  `defaults` is the start-of-run baseline.
        merged = {**defaults, **run_defaults}
        for key, fresh_value in fresh_defaults.items():
            if fresh_value != defaults.get(key):
                merged[key] = fresh_value
        state = fresh_state
        state["defaults"] = _normalize_defaults(merged)
        state["selectedSessionID"] = session
        state["lastRun"] = {
            "command": "run", "ok": bool(res.ok), "model": model_alias, "mode": mode,
            "provider": tee.last_provider or "", "resolvedModel": tee.last_model or "",
            "fallbackUsed": bool(tee.fallback_used),
            "semanticFallbackUsed": bool(semantic_meta["semanticFallbackUsed"]),
            "semanticFallbackProvider": semantic_meta["semanticFallbackProvider"],
            "semanticFallbackModel": semantic_meta["semanticFallbackModel"],
            "returnedToPrimary": bool(semantic_meta["returnedToPrimary"]),
            "primaryResumeDeclined": bool(semantic_meta["primaryResumeDeclined"]),
            "permission": merged.get("permission", permission), "session": session, "updatedAt": _now_iso(),
            "conscienceMode": conscience_mode,
            "agiMode": agi_mode,
            "agiWorkflowMode": agi_workflow_mode,
            "agiProfile": agi_profile,
            "agiRoute": agi_route,
            "agiRunId": handle.get("agiRunId", ""),
            "agiStatus": (handle.get("agiResult") or {}).get("status", ""),
        }
        try:
            _save_state(state)
        except OSError as exc:
            # Runs remain usable when optional UI state persistence fails.
            self.bus.bridge_event(run_id, {
                "type": "state_warning",
                "warning": f"run state was not saved: {type(exc).__name__}",
            })
        if hook_config.enabled:
            self._dispatch_hook(run_id, hook_config, _HookEvent.STOP)
        return payload

    # -- experimental AGI-shaped mode -------------------------------------- #
    def _run_agi_mode(
        self,
        handle: dict,
        cmd: dict,
        *,
        prompt: str,
        tee: _TokenTee,
        ctx: Any,
        sink: Callable[[dict], None],
        budget: ExecutionBudget,
        session: str,
        show_thinking: bool,
        system_extra: str,
        max_steps: int,
        model_alias: str,
        response_style: ResponseStyle,
        root: Path,
        fallback_confirmer: Callable[[Any], bool],
    ) -> Any:
        """Run the durable perceive→plan→act→verify loop.

        Phase roles run sequentially so one local model can provide every role
        without parallel VRAM pressure.  A configured role model creates an
        exact client with fallbacks disabled; when all roles use the selected
        model the verifier is explicitly marked non-independent. When
        ``agiWorkflowMode`` is enabled, an individual complex cloud-backed node
        may invoke one bounded nested workflow; simple nodes and strict
        acceptance-contract nodes remain single-pass.
        """
        from agent import cli as terminal_cli
        from agent import model as m
        from agent.agent_loop import AgentLoopResult, run_agent_loop
        from agent.agent_tools import all_tools
        from agent.agi_mode import (
            AGIModeConfig,
            AGIPhaseRequest,
            AGIPhaseResult,
            AGIRunStore,
            PHASES,
            READ_ONLY_CONTEXT_TOOLS,
            STATUS_ACHIEVED,
            STATUS_AWAITING_INPUT,
            STATUS_BOUND_HIT,
            STATUS_CANCELLED,
            STATUS_CANDIDATE_COMPLETE,
            STATUS_FAILED,
            STATUS_INTERRUPTED,
            STATUS_PAUSED,
            STATUS_UNACHIEVABLE,
            run_agi_mode,
        )
        from agent.agi_workflow import decide_agi_workflow

        cancel: threading.Event = handle["cancel"]
        agi_run_id = _safe_text(
            cmd.get("agiResumeRunId") or AGIRunStore.new_run_id(),
            limit=160,
        )
        store = AGIRunStore(session, agi_run_id)
        handle["agiStore"] = store
        handle["agiRunId"] = store.run_id

        planner_model = _normalize_agi_role_model(
            cmd.get("agiPlannerModel")
        ) or model_alias
        worker_model = _normalize_agi_role_model(
            cmd.get("agiWorkerModel")
        ) or model_alias
        verifier_model = _normalize_agi_role_model(
            cmd.get("agiVerifierModel")
        ) or model_alias
        profile = _normalize_agi_profile(cmd.get("agiProfile"))
        route = _normalize_agi_route(cmd.get("agiRoute"))
        acceptance_spec = (
            dict(cmd.get("acceptanceContract") or {})
            if isinstance(cmd.get("acceptanceContract"), dict)
            else {}
        )
        acceptance_tool_policy = (
            dict(acceptance_spec.get("toolPolicy") or {})
            if isinstance(acceptance_spec.get("toolPolicy"), dict)
            else {}
        )
        try:
            strict_max_total_calls = int(
                acceptance_tool_policy.get("maxTotalCalls")
            )
        except (TypeError, ValueError):
            strict_max_total_calls = -1
        if strict_max_total_calls < 0:
            strict_max_total_calls = -1
        requested_max_cycles = _safe_int(cmd.get("agiMaxCycles"), 0) or None
        if strict_max_total_calls >= 0:
            requested_max_cycles = 1
        config = AGIModeConfig(
            profile=profile,
            route=route,
            max_cycles=requested_max_cycles,
            max_strategies=_safe_int(cmd.get("agiMaxStrategies"), 0) or None,
            max_subagents_per_cycle=(
                _safe_int(cmd.get("agiMaxSubagentsPerCycle"), 0) or None
            ),
            wall_clock_sec=_safe_int(cmd.get("agiWallClockSec"), 0) or None,
            max_no_progress=_safe_int(cmd.get("agiMaxNoProgress"), 0) or None,
            planner_model=planner_model,
            worker_model=worker_model,
            verifier_model=verifier_model,
        )
        agi_workflow_mode = _normalize_workflow_mode(
            cmd.get("agiWorkflowMode")
        )
        self._activate_run_mode(
            handle,
            "agi-workflow" if agi_workflow_mode != "off" else "agi",
            phase=(
                "AGI workflow controller"
                if agi_workflow_mode != "off"
                else "AGI controller"
            ),
        )
        agi_workflow_max_stages = _normalize_workflow_max_stages(
            cmd.get("workflowMaxStages")
        )
        agi_workflow_max_agents = _normalize_workflow_max_agents(
            cmd.get("workflowMaxAgents")
        )
        agi_a2a_agents = _normalize_a2a_agents(
            cmd.get("a2aAgents"),
            cmd.get("a2a"),
        )
        agi_a2a_execution = _normalize_a2a_execution(
            cmd.get("a2aExecution")
        )
        agi_terminal_layout = _normalize_terminal_layout(
            cmd.get("terminalLayout")
        )
        agi_parallel_a2a = bool(
            agi_a2a_agents != 0
            and agi_a2a_execution in {"terminal", "headless"}
            and agi_terminal_layout != "off"
            and (
                budget.max_concurrency is None
                or int(budget.max_concurrency) >= 2
            )
        )
        agi_workflow_nodes: list[dict[str, Any]] = []
        handle["agiWorkflowResult"] = {
            "mode": agi_workflow_mode,
            "status": "running" if agi_workflow_mode != "off" else "disabled",
            "nodes": agi_workflow_nodes,
            "selectedNodes": 0,
            "soloNodes": 0,
            "candidateOnly": True,
            "canClaimAGI": False,
        }
        if agi_workflow_mode != "off":
            self.bus.bridge_event(handle["id"], {
                "type": "agi_workflow_start",
                "runId": store.run_id,
                "mode": agi_workflow_mode,
                "status": "running",
                "maxStages": agi_workflow_max_stages,
                "maxAgents": agi_workflow_max_agents,
                "parallelA2A": agi_parallel_a2a,
                "a2aExecution": agi_a2a_execution,
                "terminalLayout": agi_terminal_layout,
                "candidateOnly": True,
                "canClaimAGI": False,
            })

        silent_primary = _TokenTee(
            tee.raw_client,
            lambda _token: None,
            cancel,
            telemetry=tee.telemetry,
        )
        role_tees: dict[str, _TokenTee] = {
            model_alias: silent_primary,
        }

        def role_tee(model_name: str, *, operator_final: bool) -> _TokenTee:
            alias = _normalize_model(model_name or model_alias)
            if alias == model_alias:
                return tee if operator_final else silent_primary
            cached = role_tees.get(alias)
            if cached is not None:
                return cached
            role_client = _build_model_client(
                m.default_client,
                _model_spec(alias),
                fallback_confirmer=fallback_confirmer,
                working_dir=root,
            )
            # A role override is an exact authority choice.  Never silently
            # substitute a different provider beneath planner/verifier labels.
            try:
                role_client.fallbacks = []
                role_client.fallback_policy = m.FallbackPolicy.from_value("never")
                role_client.fallback_confirmer = None
            except (AttributeError, TypeError):
                pass
            try:
                terminal_cli._set_client_sampling(
                    role_client,
                    temperature=float(os.environ["SOPHIA_TEMPERATURE"]),
                    top_p=float(os.environ["SOPHIA_TOP_P"]),
                    top_k=int(os.environ["SOPHIA_TOP_K"]),
                )
            except (AttributeError, TypeError, ValueError):
                pass
            cached = _TokenTee(
                role_client,
                lambda _token: None,
                cancel,
                telemetry=tee.telemetry,
            )
            role_tees[alias] = cached
            return cached

        inherited_scope = getattr(ctx, "allowed_tools", None)
        agi_tool_scope = (
            set(all_tools()) if inherited_scope is None else set(inherited_scope)
        )
        # The AGI controller itself owns decomposition.  Nested generic
        # delegation would create an untracked second orchestration hierarchy.
        agi_tool_scope.discard("delegate")
        if str(getattr(ctx, "permission", "") or "").lower() == "readonly":
            # Do not advertise tools that the authoritative permission gate
            # will reject. Besides reducing wasted calls, this keeps a strict
            # one-attempt receipt from being consumed by an impossible action.
            agi_tool_scope.intersection_update(READ_ONLY_CONTEXT_TOOLS)

        def agi_workflow_decision_for(request: AGIPhaseRequest) -> Any:
            phase = str(request.phase or "").strip().lower()
            prompt_text = str(request.prompt or "")
            lowered = prompt_text.lower()
            checklist_items = len(
                re.findall(r"(?m)^\s*(?:[-*]|\d+[.)])\s+\S", prompt_text)
            )
            inherently_complex = phase in {
                "strategize",
                "critique",
                "diagnose",
                "verify",
                "evaluate",
            }
            explicitly_parallel = any(
                marker in lowered
                for marker in {
                    "independent workstream",
                    "independent concern",
                    "compare alternatives",
                    "multiple sources",
                    "adversarial",
                    "specialist",
                    "cross-check",
                }
            )
            high_risk = phase in {"critique", "verify", "evaluate"} or any(
                marker in lowered
                for marker in {
                    "security",
                    "credential",
                    "destructive",
                    "production",
                    "privacy",
                    "irreversible",
                    "contested",
                }
            )
            workstreams = (
                min(8, max(2, checklist_items))
                if inherently_complex or explicitly_parallel or checklist_items >= 3
                else 1
            )
            simple_phase = phase in {"perceive", "retrieve", "observe"}
            simple = bool(
                simple_phase
                and not explicitly_parallel
                and checklist_items < 3
                and not high_risk
            )
            complexity = (
                "simple"
                if simple
                else (
                    "high"
                    if inherently_complex
                    or explicitly_parallel
                    or checklist_items >= 3
                    or len(prompt_text) >= 2400
                    else "medium"
                )
            )
            risk_signals: list[str] = []
            if phase in {"critique", "verify", "evaluate"}:
                risk_signals.append("verification_required")
            if high_risk:
                risk_signals.append("high_impact")
            try:
                phase_cfg = m.resolve_config(_model_spec(request.model))
                phase_local = m.is_local_model(phase_cfg)
                provider: Any = {
                    "name": request.model,
                    "kind": phase_cfg.kind,
                    "local": phase_local,
                    "cloud": not phase_local,
                    "available": True,
                }
            except Exception:  # noqa: BLE001 - unknown provider fails closed
                provider = {
                    "name": request.model,
                    "kind": "unknown",
                    "available": False,
                }
            # Strict acceptance contracts account for a precise number of
            # native tool calls in the parent context. A nested workflow owns
            # separate worker contexts, so selecting it here would make the
            # contract's call ceiling unverifiable. Keep those nodes solo.
            routing_mode = (
                "off" if strict_max_total_calls >= 0 else agi_workflow_mode
            )
            return decide_agi_workflow(
                mode=routing_mode,
                provider=provider,
                parallel_a2a={
                    "available": agi_parallel_a2a,
                    "supervised": agi_a2a_execution
                    in {"terminal", "headless"},
                    "bounded": True,
                    "stageBarriers": True,
                },
                phase=phase,
                node_type=request.role,
                complexity=complexity,
                risk="high" if high_risk else "low",
                risk_signals=risk_signals,
                independent_workstreams=workstreams,
                simple=simple,
                max_stages=agi_workflow_max_stages,
                max_agents=agi_workflow_max_agents,
            )

        def phase_runner(request: AGIPhaseRequest) -> AGIPhaseResult:
            phase_client = role_tee(
                request.model,
                operator_final=not request.internal_artifact,
            )
            prior_scope = getattr(ctx, "allowed_tools", None)
            prior_client = getattr(ctx, "client", None)
            prior_subagent = getattr(ctx, "subagent_client", None)
            reserve_strict_tools_for_action = (
                strict_max_total_calls >= 0
                and request.phase in {"perceive", "retrieve"}
            )
            strict_tool_budget_exhausted = (
                strict_max_total_calls >= 0
                and int(getattr(ctx, "tool_policy_total_attempts", 0))
                >= strict_max_total_calls
            )
            strict_action_tool_turns: int | None = None
            if strict_max_total_calls >= 0 and request.phase == "act":
                strict_action_tool_turns = min(
                    max(1, int(request.max_steps)),
                    max(
                        0,
                        strict_max_total_calls
                        - int(getattr(ctx, "tool_policy_total_attempts", 0)),
                    ),
                )
            strict_action_model_calls = (
                strict_action_tool_turns + 1
                if strict_action_tool_turns is not None
                else None
            )
            effective_tools_enabled = bool(
                request.tools_enabled
                and not reserve_strict_tools_for_action
                and not strict_tool_budget_exhausted
            )
            if effective_tools_enabled:
                phase_scope = set(agi_tool_scope)
                if request.allowed_tools is not None:
                    phase_scope.intersection_update(request.allowed_tools)
                ctx.allowed_tools = phase_scope
            else:
                ctx.allowed_tools = set()
            _set_context_clients(ctx, phase_client)

            def phase_sink(event: dict[str, Any]) -> None:
                if (
                    request.internal_artifact
                    and str(event.get("type") or "") == "final"
                ):
                    return
                sink(event)

            phase_extra = (
                f"{system_extra}\n\n"
                "Experimental AGI-shaped controller contract:\n"
                f"- Current phase: {request.phase}; role: {request.role}.\n"
                "- Follow the phase's structured-output contract exactly.\n"
                "- Never claim that Sophia or this run is AGI.\n"
                "- Treat internal strategies, critiques, and semantic judgments "
                "as candidate evidence until verified.\n"
                "- Current permission policy and every hard delivery/promotion "
                "gate remain authoritative."
            ).strip()
            node_index = len(agi_workflow_nodes) + 1
            node_id = _normalize_session(
                f"{request.phase}-{request.key}-{node_index}"
            )
            workflow_decision = agi_workflow_decision_for(request)
            if agi_workflow_mode != "off":
                self._emit_goal_update(
                    handle,
                    goal=f"{request.phase.title()}: complete the {request.role} node.",
                    source="agi-workflow-node",
                    reason=workflow_decision.reason or "AGI node routing",
                    current_stage=max(1, node_index),
                    planned_stages=max(1, len(PHASES)),
                    max_stages=max(1, len(PHASES)),
                    dedupe_semantic=True,
                )
                self.bus.bridge_event(handle["id"], {
                    "type": "agi_workflow_node_start",
                    "runId": store.run_id,
                    "nodeId": node_id,
                    "index": node_index,
                    "phase": request.phase,
                    "title": f"{request.phase} · {request.role}",
                    "status": "running",
                    "route": "pending",
                    "candidateOnly": True,
                    "canClaimAGI": False,
                })
                route_event = workflow_decision.to_event()
                route_event.update(
                    {
                        "runId": store.run_id,
                        "nodeId": node_id,
                        "index": node_index,
                        "title": f"{request.phase} · {request.role}",
                    }
                )
                self.bus.bridge_event(handle["id"], route_event)
            node_finalized = False

            def finalize_agi_workflow_node(
                node_result: Any | None,
                node_error: BaseException | None = None,
            ) -> None:
                nonlocal node_finalized
                if node_finalized or agi_workflow_mode == "off":
                    return
                node_finalized = True
                nested_stages = (
                    [
                        dict(stage)
                        for stage in (
                            handle.get("dynamicWorkflowStages") or []
                        )
                        if isinstance(stage, dict)
                    ]
                    if workflow_decision.selected
                    else []
                )
                nested_result = (
                    dict(handle.get("dynamicWorkflowResult") or {})
                    if workflow_decision.selected
                    else {}
                )
                node_agents = [
                    dict(agent)
                    for stage in nested_stages
                    for agent in list(stage.get("agents") or [])
                    if isinstance(agent, dict)
                ]
                node_ok = (
                    node_error is None
                    and node_result is not None
                    and bool(getattr(node_result, "ok", False))
                )
                error_text = (
                    f"{type(node_error).__name__}: {node_error}"[:400]
                    if node_error is not None
                    else ""
                )
                if node_error is not None:
                    nested_result = {
                        **nested_result,
                        "status": "failed",
                        "reasonCode": "node_exception",
                        "reason": error_text,
                        "candidateOnly": True,
                        "canClaimAGI": False,
                    }
                node_record = {
                    "nodeId": node_id,
                    "index": node_index,
                    "phase": request.phase,
                    "role": request.role,
                    "route": (
                        "workflow"
                        if workflow_decision.selected
                        else "solo"
                    ),
                    "routeReason": workflow_decision.reason,
                    "reasonCode": (
                        "node_exception"
                        if node_error is not None
                        else workflow_decision.reason_code
                    ),
                    "pattern": (
                        workflow_decision.pattern.name
                        if workflow_decision.pattern is not None
                        else ""
                    ),
                    "status": "succeeded" if node_ok else "failed",
                    "workflow": nested_result,
                    "stages": nested_stages,
                    "agents": node_agents,
                    "error": error_text,
                    "candidateOnly": True,
                    "canClaimAGI": False,
                }
                agi_workflow_nodes.append(node_record)
                selected_nodes = sum(
                    1
                    for item in agi_workflow_nodes
                    if item.get("route") == "workflow"
                )
                handle["agiWorkflowResult"] = {
                    "mode": agi_workflow_mode,
                    "status": "running",
                    "nodes": agi_workflow_nodes,
                    "selectedNodes": selected_nodes,
                    "soloNodes": len(agi_workflow_nodes) - selected_nodes,
                    "warmWorkers": list(
                        nested_stages[-1].get("warmWorkers") or []
                    )
                    if nested_stages
                    else [],
                    "candidateOnly": True,
                    "canClaimAGI": False,
                }
                self.bus.bridge_event(handle["id"], {
                    "type": "agi_workflow_node_end",
                    "runId": store.run_id,
                    "nodeId": node_id,
                    "index": node_index,
                    "phase": request.phase,
                    "title": f"{request.phase} · {request.role}",
                    "route": node_record["route"],
                    "status": node_record["status"],
                    "ok": node_ok,
                    "workflowStatus": str(
                        nested_result.get("status") or ""
                    ),
                    "agents": node_agents,
                    "error": error_text,
                    "evidenceSummary": (
                        str(getattr(node_result, "final_text", "") or "")[:400]
                        if node_result is not None
                        else ""
                    ),
                    "candidateOnly": True,
                    "canClaimAGI": False,
                })
                if workflow_decision.selected:
                    # Preserve the copied node receipt above but always clear
                    # generic nested-workflow slots, including exception paths.
                    handle["dynamicWorkflowResult"] = {}
                    handle["dynamicWorkflowStages"] = []
                    handle["dynamicWorkflowAgents"] = []
                    handle["runMode"] = "agi-workflow"

            try:
                if workflow_decision.selected:
                    pattern_name = (
                        workflow_decision.pattern.name
                        if workflow_decision.pattern is not None
                        else workflow_decision.preferred_pattern
                    )
                    nested_extra = (
                        f"{phase_extra}\n\n"
                        "Nested AGI-workflow contract:\n"
                        f"- This workflow serves only AGI node {node_id} "
                        f"({request.phase}).\n"
                        f"- Prefer the bounded `{pattern_name}` pattern unless "
                        "Main has a better explicitly bounded shape.\n"
                        "- The final Main synthesis is an internal artifact and "
                        "must satisfy the original phase's structured-output "
                        "contract exactly.\n"
                        "- Workers receive self-contained prompts; Main must "
                        "verify rather than rubber-stamp their reports.\n"
                        "- Never dispatch overlapping writes in parallel. "
                        "Research may fan out; dependent writes remain serial."
                    )
                    result = self._run_dynamic_workflow(
                        handle,
                        request.prompt,
                        phase_client,
                        ctx,
                        phase_sink,
                        configured_mode="on",
                        max_stages=workflow_decision.budget.max_stages,
                        max_agents=workflow_decision.budget.max_agents,
                        max_steps=(
                            max(1, strict_action_tool_turns)
                            if strict_action_tool_turns is not None
                            else request.max_steps
                        ),
                        history=None,
                        show_thinking=False,
                        system_extra=nested_extra,
                        budget=budget,
                        raw_prompt=request.prompt,
                        max_parallel_tools=1,
                        max_continuations=0,
                        response_style=response_style,
                        execution=agi_a2a_execution,
                        terminal_layout=agi_terminal_layout,
                        model_alias=request.model,
                        mode="balanced",
                        permission=str(
                            getattr(ctx, "permission", "approve") or "approve"
                        ),
                        session=session,
                        root=root,
                        internal_artifact=True,
                        parent_mode="agi",
                        parent_node_id=node_id,
                        parent_phase=request.phase,
                    )
                else:
                    result = run_agent_loop(
                        request.prompt,
                        client=phase_client,
                        ctx=ctx,
                        history=None,
                        on_event=phase_sink,
                        max_steps=(
                            max(1, strict_action_tool_turns)
                            if strict_action_tool_turns is not None
                            else request.max_steps
                        ),
                        system_extra=phase_extra,
                        show_thinking=show_thinking
                        and not request.internal_artifact,
                        enable_tools=effective_tools_enabled,
                        budget=budget,
                        max_parallel_tools=1,
                        max_model_calls=strict_action_model_calls,
                        reserve_final_model_call=bool(strict_action_tool_turns),
                        post_tool_continuity=(
                            effective_tools_enabled
                            and strict_max_total_calls < 0
                        ),
                        max_continuations=(
                            0 if strict_action_tool_turns is not None else 2
                        ),
                        raw_user_turn=(
                            prompt if request.phase == "act" else None
                        ),
                        current_task=request.prompt,
                        response_style=response_style,
                        defer_delivery_gate=request.internal_artifact,
                    )
            except BaseException as exc:
                finalize_agi_workflow_node(None, exc)
                raise
            finally:
                ctx.allowed_tools = prior_scope
                ctx.client = prior_client
                ctx.subagent_client = prior_subagent
            finalize_agi_workflow_node(result)
            return AGIPhaseResult(
                text=str(getattr(result, "final_text", "") or ""),
                ok=bool(getattr(result, "ok", False)),
                steps=list(getattr(result, "steps", None) or []),
                messages=list(getattr(result, "messages", None) or []),
                model_error=str(getattr(result, "model_error", "") or ""),
                raw=result,
            )

        def agi_event_sink(event: dict[str, Any]) -> None:
            if str(event.get("type") or "") == "agi_phase_start":
                phase = str(event.get("phase") or "").strip().lower()
                try:
                    stage = PHASES.index(phase) + 1
                except ValueError:
                    stage = 1
                role = str(event.get("role") or "controller").strip()
                self._emit_goal_update(
                    handle,
                    goal=f"{phase.title()}: complete the {role} controller stage.",
                    source="agi-controller",
                    reason=f"controller phase {phase or 'unknown'} started",
                    current_stage=stage,
                    planned_stages=len(PHASES),
                    max_stages=len(PHASES),
                    dedupe_semantic=True,
                )
            self.bus.bridge_event(handle["id"], event)

        outcome = run_agi_mode(
            prompt,
            phase_runner=phase_runner,
            active_model=model_alias,
            session=session,
            config=config,
            emit=agi_event_sink,
            cancel_check=cancel.is_set,
            run_id=store.run_id,
            resume=bool(cmd.get("agiResumeRunId")),
            base_system_extra=system_extra,
            max_steps_per_action=max_steps,
        )
        result = outcome.raw_result
        if result is None:
            result = AgentLoopResult(
                goal=prompt,
                final_text=outcome.final_text,
                ok=False,
                steps=outcome.steps,
                messages=outcome.messages
                or [{"role": "assistant", "content": outcome.final_text}],
            )
        result.final_text = outcome.final_text
        result.steps = outcome.steps
        result.messages = outcome.messages or list(
            getattr(result, "messages", None) or []
        )
        if result.messages and result.messages[-1].get("role") == "assistant":
            result.messages[-1] = {
                **result.messages[-1],
                "content": outcome.final_text,
            }
        elif outcome.final_text:
            result.messages.append(
                {"role": "assistant", "content": outcome.final_text}
            )
        from agent.completion_gate import (
            apply_decision_to_result,
            decide_completion,
            evaluate_deterministic_contract,
            finalize_completion_markers,
            remaining_from_mapping,
            render_tool_receipt_failure,
        )

        acceptance_contract = acceptance_spec
        deterministic_receipt = evaluate_deterministic_contract(
            acceptance_contract,
            final_text=outcome.final_text,
            steps=outcome.steps,
            files_touched=(),
            route=outcome.route or "controller",
        )
        receipt_pass = bool(deterministic_receipt.get("passed"))
        receipt_sufficient = bool(deterministic_receipt.get("sufficient"))
        receipt_text = render_tool_receipt_failure(
            deterministic_receipt,
            fallback_text=outcome.final_text,
        )
        predicates: dict[str, bool] = {}
        finalized, predicates = finalize_completion_markers(
            receipt_text,
            prompt=prompt,
            additional_predicates={
                "deterministic_acceptance": receipt_pass
            }
            if acceptance_contract
            else None,
        )
        outcome.final_text = finalized
        result.final_text = finalized
        if result.messages and result.messages[-1].get("role") == "assistant":
            result.messages[-1] = {
                **result.messages[-1],
                "content": finalized,
            }
        deterministic_pass: bool | None
        if acceptance_contract and not receipt_pass:
            deterministic_pass = False
        elif receipt_sufficient:
            deterministic_pass = True
        elif outcome.deterministic_evidence:
            deterministic_pass = True
        else:
            deterministic_pass = None
        decision_reason = (
            "completion-sufficient deterministic acceptance receipt passed"
            if receipt_sufficient
            else outcome.reason
        )
        decision = decide_completion(
            controller_status=outcome.status,
            deterministic_pass=deterministic_pass,
            semantic_status=outcome.status,
            output_predicates_pass=all(predicates.values()) if predicates else True,
            remaining=remaining_from_mapping(getattr(outcome, "reason", "")),
            reason=decision_reason,
            budget_exhausted=outcome.status == STATUS_BOUND_HIT,
            operator_denied=outcome.status == STATUS_CANCELLED,
            unverifiable=outcome.status == STATUS_UNACHIEVABLE,
            contract_complete=True if receipt_sufficient else None,
        )
        apply_decision_to_result(result, decision)
        result.incomplete_reason = (
            decision.verification_status if decision.incomplete else ""
        )
        result.model_error = (
            str(getattr(result, "model_error", "") or outcome.reason)
            if outcome.status == STATUS_FAILED
            else ""
        )
        result.acceptance_receipt = deterministic_receipt
        effective_status = STATUS_ACHIEVED if decision.ok else outcome.status
        agi_payload = outcome.to_dict()
        agi_payload.update(decision.to_dict())
        agi_payload["finalText"] = finalized
        agi_payload["controllerStatus"] = outcome.status
        agi_payload["status"] = effective_status
        agi_payload["deterministicEvidence"] = bool(
            outcome.deterministic_evidence or receipt_sufficient
        )
        agi_payload["deterministicReceipt"] = deterministic_receipt
        durable_state = store.read_state() or {}
        durable_state.update(
            {
                "controllerStatus": outcome.status,
                "status": effective_status,
                "reason": decision.reason,
                "finalText": finalized,
                "taskStatus": decision.task_status,
                "verificationStatus": decision.verification_status,
                "externalDeterministicReceipt": deterministic_receipt,
                "updatedAt": _now_iso(),
                "candidateOnly": True,
                "canClaimAGI": False,
            }
        )
        store.write_state(durable_state)
        store.append_event(
            {
                "type": "agi_external_acceptance",
                "status": effective_status,
                "controllerStatus": outcome.status,
                "passed": receipt_pass,
                "sufficient": receipt_sufficient,
                "verificationStatus": decision.verification_status,
            }
        )
        result.agi_mode_result = agi_payload
        handle["agiResult"] = agi_payload
        if agi_workflow_mode != "off":
            selected_nodes = sum(
                1
                for item in agi_workflow_nodes
                if item.get("route") == "workflow"
            )
            agi_workflow_status = (
                "succeeded"
                if decision.ok
                else (
                    "cancelled"
                    if outcome.status == STATUS_CANCELLED
                    else (
                        "awaiting_input"
                        if outcome.status
                        in {STATUS_AWAITING_INPUT, STATUS_PAUSED}
                        else "failed"
                    )
                )
            )
            handle["agiWorkflowResult"] = {
                **dict(handle.get("agiWorkflowResult") or {}),
                "mode": agi_workflow_mode,
                "status": agi_workflow_status,
                "nodes": agi_workflow_nodes,
                "selectedNodes": selected_nodes,
                "soloNodes": len(agi_workflow_nodes) - selected_nodes,
                "terminalReason": decision.reason,
                "candidateOnly": True,
                "canClaimAGI": False,
            }
            self.bus.bridge_event(handle["id"], {
                "type": "agi_workflow_end",
                "runId": store.run_id,
                "status": agi_workflow_status,
                "ok": bool(decision.ok),
                "reason": decision.reason,
                "selectedNodes": selected_nodes,
                "soloNodes": len(agi_workflow_nodes) - selected_nodes,
                "nodes": agi_workflow_nodes,
                "candidateOnly": True,
                "canClaimAGI": False,
            })
        handle["observedRoute"] = "controller"
        return result

    def _run_completeness_mode(
        self,
        handle: dict,
        cmd: dict,
        *,
        prompt: str,
        tee: _TokenTee,
        ctx: Any,
        sink: Callable[[dict], None],
        budget: ExecutionBudget,
        session: str,
        show_thinking: bool,
        system_extra: str,
        max_steps: int,
        model_alias: str,
        response_style: ResponseStyle,
        root: Path,
    ) -> Any:
        """Run one worker against an acceptance contract, optionally closing gaps."""
        from agent import model as m
        from agent.agent_loop import AgentLoopResult, run_agent_loop
        from agent.acceptance_contract import AcceptanceContract
        from agent.completeness_loop import run_completeness_loop
        from agent.completion_gate import compile_initial_criteria

        mode = str(cmd.get("completionMode") or "contract_solo").strip().lower()
        if mode not in {"contract_solo", "contract_gap_closure"}:
            raise ValueError("completionMode must be contract_solo or contract_gap_closure")
        criteria = compile_initial_criteria(prompt)
        contract = AcceptanceContract(criteria=criteria)
        cancel: threading.Event = handle["cancel"]
        inherited_scope = getattr(ctx, "allowed_tools", None)
        worker_scope = tuple(sorted(set(inherited_scope or set())))
        silent = _TokenTee(
            tee.raw_client,
            lambda _token: None,
            cancel,
            telemetry=tee.telemetry,
        )

        def worker(
            instruction: str,
            allowed_tools: tuple[str, ...],
            worker_max_calls: int,
        ) -> dict[str, Any]:
            prior_scope = getattr(ctx, "allowed_tools", None)
            prior_client = getattr(ctx, "client", None)
            prior_subagent = getattr(ctx, "subagent_client", None)
            try:
                ctx.allowed_tools = (
                    set(worker_scope)
                    if instruction == prompt
                    else set(allowed_tools).intersection(worker_scope)
                )
                ctx.client = tee if instruction == prompt else silent
                ctx.subagent_client = ctx.client
                result = run_agent_loop(
                    instruction,
                    client=ctx.client,
                    ctx=ctx,
                    history=None,
                    on_event=sink,
                    max_steps=max(1, min(max_steps, worker_max_calls)),
                    system_extra=(
                        f"{system_extra}\n\n"
                        "Contract completion mode: report criterion IDs and concrete "
                        "evidence. Do not claim completion without satisfying the "
                        "explicit output contract."
                    ).strip(),
                    show_thinking=show_thinking if instruction == prompt else False,
                    enable_tools=instruction == prompt and bool(ctx.allowed_tools),
                    budget=budget,
                    max_parallel_tools=1,
                    post_tool_continuity=instruction == prompt,
                    max_continuations=1,
                    raw_user_turn=prompt if instruction == prompt else None,
                    current_task=instruction,
                    response_style=response_style,
                    defer_delivery_gate=instruction != prompt,
                )
                text = str(getattr(result, "final_text", "") or "")
                return {
                    "text": text,
                    "finalText": text,
                    "evidence": [
                        str(step.get("output") or "")
                        for step in list(getattr(result, "steps", []) or [])
                        if isinstance(step, dict) and step.get("ok")
                    ],
                    "steps": list(getattr(result, "steps", []) or []),
                    "ok": bool(getattr(result, "ok", False)),
                    "verified": [
                        criterion.criterion_id
                        for criterion in contract.criteria
                        if criterion.verifier_type not in {"test", "deterministic", "source", "output_regex"}
                        and bool(getattr(result, "ok", False))
                    ],
                    "criteriaCovered": (
                        [
                            criterion.criterion_id
                            for criterion in contract.criteria
                            if criterion.verifier_type not in {"test", "deterministic", "source", "output_regex"}
                            and bool(getattr(result, "ok", False))
                        ]
                        if instruction == prompt
                        else []
                    ),
                }
            finally:
                ctx.allowed_tools = prior_scope
                ctx.client = prior_client
                ctx.subagent_client = prior_subagent

        outcome = run_completeness_loop(
            prompt,
            contract=contract,
            worker=worker,
            mode=mode,
            max_gap_waves=_safe_int(cmd.get("completionMaxGapWaves"), 2),
            initial_allowed_tools=worker_scope,
        )
        for event in outcome.events:
            sink(event)
        final_text = outcome.final_text
        result = AgentLoopResult(
            goal=prompt,
            final_text=final_text,
            ok=outcome.ok,
            incomplete=outcome.incomplete,
            resumable=outcome.resumable,
            steps=[],
            messages=[{"role": "assistant", "content": final_text}],
        )
        result.completeness_result = outcome.to_dict()
        result.incomplete_reason = outcome.reason if outcome.incomplete else None
        handle["observedRoute"] = "solo"
        handle["completenessResult"] = outcome.to_dict()
        return result

    # -- autonomous goal-continuation mode --------------------------------- #
    def _run_goal(self, handle: dict, cmd: dict, *, prompt: str, tee: _TokenTee,
                  ctx: Any, sink: Callable[[dict], None], budget: ExecutionBudget,
                  history: "list[dict] | None", session: str, show_thinking: bool,
                  system_extra: str, max_steps: int, model_alias: str,
                  max_parallel_tools: int = 1,
                  response_style: ResponseStyle = "adaptive",
                  raw_prompt: str | None = None,
                  continuation_instruction: str | None = None,
                  flush_stream: Callable[[], None],
                  steering_consumer: Callable[[], list[str]] | None,
                  started: float) -> dict[str, Any]:
        """Drive run_goal_loop and build the terminal goal payload.

        Reuses everything _run_guarded already set up (client/tee/ctx/budget/
        delivery gate/history). The loop self-generates continuation prompts
        (restating the original goal) until the goal is achieved, paused for
        operator input, confidently unachievable, or a safety bound trips.
        Bounded + fail-closed; see agent/goal_harness.py.
        """
        from agent import cli as terminal_cli
        from agent.goal_harness import run_goal_loop

        run_id = handle["id"]
        cancel: threading.Event = handle["cancel"]

        def _int(key: str, default: int) -> int:
            try:
                return max(1, int(cmd.get(key, default)))
            except (TypeError, ValueError):
                return default

        def _float(key: str, default: float) -> float:
            try:
                return float(cmd.get(key, default))
            except (TypeError, ValueError):
                return default

        # Hard ceilings so a frontend can never request an unbounded loop.
        max_continuations = min(32, _int("maxContinuations", 8))
        max_steps_per_run = min(256, _int("maxStepsPerRun", max_steps))
        max_no_progress = min(10, _int("maxNoProgress", 3))
        achieved_threshold = _float("achievedThreshold", 0.8)
        unachievable_threshold = _float("unachievableThreshold", 0.8)

        # The judge is an internal assessment — use the underlying callable
        # client directly so its tokens do not enter the transcript.
        judge_client = tee.raw_client

        self.bus.bridge_event(run_id, {
            "type": "goal_mode_start", "goal": prompt,
            "maxContinuations": max_continuations,
            "achievedThreshold": achieved_threshold,
            "unachievableThreshold": unachievable_threshold,
        })

        gres = run_goal_loop(
            prompt, client=tee, ctx=ctx, judge_client=judge_client,
            on_event=sink, history=history, budget=budget,
            max_continuations=max_continuations,
            max_steps_per_run=max_steps_per_run,
            max_parallel_tools=max_parallel_tools,
            achieved_threshold=achieved_threshold,
            unachievable_threshold=unachievable_threshold,
            max_no_progress=max_no_progress,
            system_extra=system_extra, show_thinking=show_thinking,
            steering_consumer=steering_consumer,
            response_style=response_style,
            raw_user_turn=raw_prompt,
            current_task=continuation_instruction,
            cancel_check=lambda: cancel.is_set(),
            goal_id=run_id,
        )
        flush_stream()
        elapsed = time.time() - started

        # Carry the accumulated conversation memory into the session so a later
        # /run or /goal resumes from where the goal loop left off.
        try:
            if gres.messages:
                if (continuation_instruction is not None
                        and gres.status in {"achieved", "unachievable"}):
                    from agent.continuation import fulfill_latest_continuation
                    gres.messages = fulfill_latest_continuation(
                        gres.messages, instruction=continuation_instruction)
                terminal_cli._save_conversation(
                    terminal_cli._conversation_path(session), gres.messages)
        except Exception:  # noqa: BLE001 - persistence is best-effort
            pass

        achieved = gres.status == "achieved"
        awaiting_input = gres.status == "awaiting_input"
        return {
            "ok": bool(achieved),
            "incomplete": awaiting_input,
            "resumable": awaiting_input,
            "awaitingInput": awaiting_input,
            **({"incompleteReason": "awaiting_user_input"} if awaiting_input else {}),
            "goal": prompt,
            "goalStatus": gres.status,
            "goalReason": gres.reason,
            "confidence": gres.confidence,
            "continuations": gres.continuations,
            "attempts": gres.attempts,
            "finalText": gres.final_text,
            "summary": gres.final_text[:1200],
            "exactOutput": is_exact_output_request(prompt),
            "model": model_alias,
            "session": session,
            "goalStatePath": gres.state_path,
            "elapsedSec": round(elapsed, 2),
            "tracePath": (gres.attempts[-1].get("tracePath") if gres.attempts else None),
            "display": {
                "kind": "goal",
                "status": gres.status,
                "reason": gres.reason,
                "statusLabel": (
                    "Awaiting your input · resume available"
                    if awaiting_input
                    else gres.status
                ),
            },
            "candidateOnly": True,
            "canClaimAGI": False,
        }

    # -- Dynamic multi-stage workflow ------------------------------------- #
    def _run_dynamic_workflow(
        self,
        handle: dict,
        prompt: str,
        tee: _TokenTee,
        ctx: Any,
        sink: Callable[[dict], None],
        *,
        configured_mode: str,
        max_stages: int,
        max_agents: int,
        max_steps: int,
        history: "list[dict] | None",
        show_thinking: bool,
        system_extra: str,
        budget: ExecutionBudget,
        raw_prompt: str | None = None,
        max_parallel_tools: int = 1,
        max_continuations: int | None = None,
        response_style: ResponseStyle = "adaptive",
        steering_consumer: Any = None,
        require_live_refresh: bool = False,
        execution: str = "terminal",
        terminal_layout: str = "auto",
        model_alias: str = "mock",
        mode: str = "balanced",
        permission: str = "approve",
        session: str = "code-default",
        root: Path | None = None,
        internal_artifact: bool = False,
        parent_mode: str = "",
        parent_node_id: str = "",
        parent_phase: str = "",
        resume_workflow_run_id: str | None = None,
        workflow_chart_path: str = "",
    ) -> Any:
        """Run Main-planned, barrier-separated parallel A2A stages.

        Main owns every stage transition. Workers never dispatch children or
        revise the workflow, and all workers in one stage are submitted to one
        session-supervisor barrier before Main reviews their combined evidence.
        """
        from agent.a2a_handoff import resolve_dispatch_assignments
        from agent.a2a_orchestration import (
            A2AOrchestrationLedger,
            build_restart_recovery_plan,
            harvest_terminal_worker_receipts,
            overlay_stage_results_from_receipts,
            load_orchestration,
            reconcile_workflow_snapshot,
            should_persist_orchestration,
            strip_workflow_report_bodies,
        )
        from agent.agent_loop import AgentLoopResult, run_agent_loop
        from agent.agent_tools import all_tools
        from agent.dynamic_workflow import (
            MAX_TASKS_PER_STAGE,
            MIN_PARALLEL_TASKS,
            PLUGIN_AUDIT_COVERAGE_KEYS,
            TUI_PARALLEL_BARRIER_COVERAGE_KEYS,
            DIRECT_TEST_EXECUTION_COVERAGE_KEYS,
            WORKFLOW_CRITIC_CONTEXT_MAX_CHARS,
            WorkflowDecision,
            bounded_workflow_planned_stages,
            collect_workflow_source_text,
            infer_workflow_stage_kind,
            known_plugin_audit_stages,
            known_tui_parallel_barrier_smoke_stages,
            known_direct_test_execution_stages,
            parse_workflow_decision,
            workflow_compact_worker_context,
            workflow_board_todo_items,
            workflow_completed_coverage,
            workflow_decision_repair_prompt,
            workflow_deterministic_recovery_decision,
            workflow_filter_completed_tasks,
            workflow_final_synthesis_prompt,
            workflow_planner_system_extra,
            workflow_requires_critic_barrier,
            workflow_referenced_source_ids,
            workflow_result_evidence_complete,
            workflow_result_evidence_gaps,
            workflow_stage_packet_complete,
            workflow_review_prompt,
            workflow_stage_context,
            workflow_task_coverage_keys,
        )
        from agent.flowchart_workflow import (
            CompiledFlowchart,
            FlowchartError,
            FlowchartNode,
            load_flowchart,
        )
        run_id = handle["id"]
        workflow_instance_id = (
            f"{run_id}-{_normalize_session(parent_node_id)}"
            if parent_node_id
            else run_id
        )
        parent_event = {
            "parentMode": parent_mode,
            "parentNodeId": parent_node_id,
            "parentPhase": parent_phase,
            "workflowId": workflow_instance_id,
        }
        cancel: threading.Event = handle["cancel"]
        workspace = (root or Path(ctx.root)).expanduser().resolve()
        selected_chart: CompiledFlowchart | None = None
        chart_error = ""
        if str(workflow_chart_path or "").strip():
            try:
                selected_chart = load_flowchart(
                    str(workflow_chart_path),
                    workspace=workspace,
                )
            except FlowchartError as exc:
                chart_error = str(exc)
        chart_selected = selected_chart is not None
        chart_manifest = (
            selected_chart.to_manifest()
            if selected_chart is not None
            else None
        )
        provider_concurrency_cap, concurrency_reason = (
            _workflow_provider_concurrency(model_alias, budget=budget)
        )
        try:
            from agent import model as model_module

            workflow_provider_kind = str(
                model_module.resolve_config(
                    _model_spec(model_alias)
                ).kind
                or ""
            )
        except Exception:  # noqa: BLE001 - prompt hint must not block routing
            workflow_provider_kind = ""
        stage_task_limit = max(
            MIN_PARALLEL_TASKS,
            min(MAX_TASKS_PER_STAGE, provider_concurrency_cap),
        )
        all_steps: list[dict[str, Any]] = []
        provider_tool_receipts: list[dict[str, Any]] = []
        workflow_stages: list[dict[str, Any]] = []
        flattened_agents: list[dict[str, Any]] = []
        task_signatures: set[str] = set()
        total_agents = 0
        total_requested_agents = 0
        total_unstarted_agents = 0
        last_result: Any = None
        terminal_reason_code = ""
        critic_barrier_required = False
        critic_barrier_satisfied = False
        handle["dynamicWorkflowStages"] = []
        handle["dynamicWorkflowAgents"] = []
        handle["dynamicWorkflowResult"] = {
            "status": "routing",
            "configuredMode": configured_mode,
            "stages": 0,
            "plannedStages": 0,
            "maxStages": max_stages,
            "totalAgents": 0,
            "requestedAgents": 0,
            "unstartedAgents": 0,
            "maxTasksPerStage": stage_task_limit,
            "reasonCode": "",
            "criticBarrier": {
                "required": False,
                "satisfied": False,
            },
            "workflowChart": chart_manifest,
            "candidateOnly": True,
            "canClaimAGI": False,
        }
        handle["dynamicWorkflowChart"] = (
            selected_chart.to_event() if selected_chart is not None else {}
        )
        resume_snapshot: dict[str, Any] | None = None
        resume_plan: dict[str, Any] | None = None
        resume_error = ""
        initial_orchestration: dict[str, Any] | None = None
        if resume_workflow_run_id:
            prior_snapshot = load_orchestration(
                session,
                str(resume_workflow_run_id),
            )
            if prior_snapshot is None:
                resume_error = (
                    "the requested workflow manifest was not found for "
                    f"session={session!r}, run={resume_workflow_run_id!r}"
                )
            else:
                resume_snapshot = harvest_terminal_worker_receipts(
                    prior_snapshot,
                )
                resume_snapshot = reconcile_workflow_snapshot(
                    resume_snapshot,
                    reason="workflow_controller_restart",
                )
                resume_plan = build_restart_recovery_plan(resume_snapshot)
                initial_orchestration = strip_workflow_report_bodies(
                    resume_snapshot,
                )
                initial_orchestration["session"] = session
                initial_orchestration["runId"] = workflow_instance_id
                initial_orchestration["recoveryOf"] = str(
                    resume_workflow_run_id
                )
                initial_orchestration["recoverySourceRunId"] = str(
                    prior_snapshot.get("runId") or resume_workflow_run_id
                )
                initial_orchestration["candidateOnly"] = True
                initial_orchestration["canClaimAGI"] = False
        session_for_persist = str(handle.get("session") or "")
        default_session = str(CODE_DEFAULTS.get("session") or "code-default")
        if not session_for_persist and session and session != default_session:
            session_for_persist = session
        orchestration = A2AOrchestrationLedger(
            session=session,
            run_id=workflow_instance_id,
            mode="workflow",
            persist=should_persist_orchestration(
                session=session_for_persist,
                run_id=str(workflow_instance_id or handle.get("id") or ""),
                resume_run_id=str(resume_workflow_run_id or ""),
                persist_flag=handle.get("persistOrchestration"),
            ),
            initial_state=initial_orchestration,
            source_run_id=str(resume_workflow_run_id or ""),
        )
        handle["a2aOrchestrationPath"] = (
            str(orchestration.path) if orchestration.persist else ""
        )
        dispatch_manifest = self._ensure_dispatch_manifest(
            handle,
            session=session,
            mode="workflow",
            source_run_id=str(resume_workflow_run_id or ""),
        )
        dispatch_manifest.set_status(
            "planning",
            phase="planning",
            main_status="planning",
        )
        if selected_chart is not None:
            dispatch_manifest.set_workflow_chart(chart_manifest)
        self._publish_dispatch_manifest(handle)
        if initial_orchestration is not None:
            workflow_stages = [
                dict(stage)
                for stage in list(
                    (
                        resume_snapshot
                        if resume_snapshot is not None
                        else initial_orchestration
                    ).get("workflowStages") or []
                )
                if isinstance(stage, dict)
            ]
            flattened_agents = [
                dict(agent)
                for stage in workflow_stages
                for agent in list(stage.get("agents") or [])
                if isinstance(agent, dict)
            ]
            total_requested_agents = sum(
                _safe_int(stage.get("requestedAgentCount"), 0)
                for stage in workflow_stages
            )
            total_agents = sum(
                _safe_int(stage.get("startedAgentCount"), 0)
                for stage in workflow_stages
            )
            total_unstarted_agents = sum(
                _safe_int(stage.get("unstartedAgentCount"), 0)
                for stage in workflow_stages
            )
            critic_barrier_required = any(
                bool(stage.get("requiresCritics"))
                for stage in workflow_stages
            )
            critic_barrier_satisfied = any(
                str(stage.get("kind") or "") == "critic"
                and str(stage.get("status") or "") == "succeeded"
                for stage in workflow_stages
            )
            handle["dynamicWorkflowStages"] = list(workflow_stages)
            handle["dynamicWorkflowAgents"] = list(flattened_agents)
            handle["dynamicWorkflowResult"]["recovery"] = dict(
                resume_plan or {}
            )

        last_published_orchestration_version = -1

        def publish_orchestration(
            snapshot: dict[str, Any] | None = None,
        ) -> None:
            nonlocal last_published_orchestration_version
            current = snapshot or orchestration.snapshot()
            version = _safe_int(current.get("version"), 0)
            if version == last_published_orchestration_version:
                return
            last_published_orchestration_version = version
            self.bus.bridge_event(run_id, {
                "type": "a2a_orchestration_snapshot",
                "orchestration": current,
                "candidateOnly": True,
                "canClaimAGI": False,
            })

        plan_task_id = f"{workflow_instance_id}-workflow-plan"
        publish_orchestration(
            orchestration.upsert_agent(
                agent_id="workflow-main",
                name="Main Workflow Controller",
                status="queued",
                source="local",
                protocol="claude-native",
                role="coordinator",
                capabilities={
                    "taskBoard": True,
                    "mailbox": True,
                    "multiStage": True,
                    "adversarialVerification": True,
                },
                connected=True,
                current_task_id=plan_task_id,
            )
        )
        publish_orchestration(
            orchestration.append_message(
                kind="human",
                sender="operator",
                recipient="Main Workflow Controller",
                summary="Operator goal",
                body=raw_prompt or prompt,
                trusted=True,
            )
        )
        publish_orchestration(
            orchestration.upsert_task(
                task_id=plan_task_id,
                subject="Choose workflow route",
                description=(
                    "Decide whether the task benefits from a bounded multi-stage "
                    "parallel workflow and define self-contained worker contracts."
                ),
                state="submitted",
                owner_id="workflow-main",
                done_criteria=(
                    "Select the smallest useful workflow.",
                    "Define independent workers with observable done criteria.",
                    "Keep overlapping writes dependency-ordered or serial.",
                ),
                expected_output="One valid WORKFLOW_DECISION object.",
            )
        )

        inherited_scope = getattr(ctx, "allowed_tools", None)
        workflow_tool_scope = (
            set(all_tools()) if inherited_scope is None else set(inherited_scope)
        )
        workflow_tool_scope.discard("delegate")

        def run_main_pass(
            agent_prompt: str,
            *,
            extra: str,
            task_id: str,
            pass_history: "list[dict] | None" = None,
            raw_turn: str | None = None,
            final_delivery: bool = False,
            enable_tools: bool = False,
            pass_max_steps: int | None = None,
        ) -> Any:
            nonlocal last_result
            if cancel.is_set():
                raise _RunCancelled()
            publish_orchestration(
                orchestration.update_agent_activity(
                    "workflow-main",
                    status="working",
                    current_task_id=task_id,
                    current_tool="",
                )
            )
            publish_orchestration(
                orchestration.set_task_state(task_id, "working")
            )
            prior_scope = getattr(ctx, "allowed_tools", None)
            prior_client = getattr(ctx, "client", None)
            ctx.allowed_tools = workflow_tool_scope
            pass_client = (
                tee
                if final_delivery
                else tee.fork(
                    on_token=lambda _token: None,
                    on_thinking_token=lambda _token: None,
                    share_telemetry=True,
                )
            )
            ctx.client = pass_client
            try:
                def phase_sink(event: dict[str, Any]) -> None:
                    event_type = str(event.get("type") or "")
                    if event_type in {
                        "tool_call",
                        "tool_result",
                        "tool_wait",
                        "provider_wait",
                    }:
                        publish_orchestration(
                            orchestration.update_agent_activity(
                                "workflow-main",
                                status=(
                                    "waiting_input"
                                    if event_type == "tool_wait"
                                    else "working"
                                ),
                                current_task_id=task_id,
                                current_tool=str(
                                    event.get("tool")
                                    or event.get("name")
                                    or (
                                        "provider"
                                        if event_type == "provider_wait"
                                        else ""
                                    )
                                ),
                                summary=event_type.replace("_", " "),
                            )
                        )
                    if not final_delivery and event_type in {
                        "final",
                        "thinking",
                        "model_result",
                    }:
                        return
                    sink(event)

                result = run_agent_loop(
                    agent_prompt,
                    client=pass_client,
                    ctx=ctx,
                    history=pass_history,
                    on_event=phase_sink,
                    max_steps=(
                        max_steps
                        if pass_max_steps is None
                        else max(1, min(max_steps, pass_max_steps))
                    ),
                    system_extra=extra,
                    show_thinking=show_thinking,
                    steering_consumer=(
                        steering_consumer if pass_history is history else None
                    ),
                    budget=budget,
                    max_parallel_tools=max_parallel_tools,
                    post_tool_continuity=True,
                    allow_continuation_nudges=False,
                    max_continuations=0,
                    continue_unfinished_objective=False,
                    raw_user_turn=raw_turn or agent_prompt,
                    current_task=agent_prompt,
                    response_style=response_style,
                    require_live_refresh=(
                        require_live_refresh if pass_history is history else False
                    ),
                    defer_delivery_gate=not final_delivery,
                    enable_tools=enable_tools and not final_delivery,
                    gate_report_context=(
                        {
                            "request": prompt,
                            "authorizedScope": (
                                "Dynamic workflow under native permission="
                                f"{permission}; workers were limited to the "
                                "operator request and the native tool-policy "
                                "intersection."
                            ),
                            "steps": list(all_steps),
                            "providerToolReceipts": list(
                                provider_tool_receipts
                            ),
                            "evidenceCount": (
                                len(all_steps)
                                + len(provider_tool_receipts)
                            ),
                            "allowCautionVerdicts": (
                                _workflow_gate_can_release_caution(
                                    workflow_stages,
                                    critic_required=critic_barrier_required,
                                    critic_satisfied=critic_barrier_satisfied,
                                    native_steps=all_steps,
                                    provider_tool_receipts=(
                                        provider_tool_receipts
                                    ),
                                )
                            ),
                            "laneResults": [
                                {
                                    "stage": stage.get("stage"),
                                    "role": (
                                        result.get("role")
                                        or result.get("name")
                                        or result.get("taskId")
                                        or "workflow worker"
                                    ),
                                    "ok": bool(result.get("ok")),
                                    "status": result.get("status") or "",
                                    "error": (
                                        result.get("error")
                                        or result.get("modelError")
                                        or ""
                                    ),
                                }
                                for stage in workflow_stages
                                if isinstance(stage, dict)
                                for result in list(stage.get("results") or [])
                                if isinstance(result, dict)
                            ],
                            "dynamicWorkflowStages": workflow_stages,
                        }
                        if final_delivery
                        else None
                    ),
                )
            finally:
                ctx.allowed_tools = prior_scope
                ctx.client = prior_client
            last_result = result
            result_ok = bool(getattr(result, "ok", False)) and not str(
                getattr(result, "model_error", "") or ""
            )
            publish_orchestration(
                orchestration.update_agent_activity(
                    "workflow-main",
                    status="idle" if result_ok else "failed",
                    current_task_id="",
                    current_tool="",
                    summary=str(getattr(result, "final_text", "") or "")[:500],
                )
            )
            publish_orchestration(
                orchestration.set_task_state(
                    task_id,
                    "completed" if result_ok else "failed",
                    summary=str(getattr(result, "final_text", "") or "")[:500],
                )
            )
            for step in list(getattr(result, "steps", None) or []):
                all_steps.append(
                    dict(step) if isinstance(step, dict) else step
                )
            return result

        def decision_source(result: Any) -> str:
            return collect_workflow_source_text(
                str(getattr(result, "final_text", "") or ""),
                messages=list(getattr(result, "messages", None) or []),
                steps=list(getattr(result, "steps", None) or []),
            )

        def decision_from(result: Any) -> WorkflowDecision | None:
            return parse_workflow_decision(decision_source(result))

        def repair_decision(
            result: Any,
            *,
            phase: str,
            task_id: str,
        ) -> WorkflowDecision | None:
            repair_prompt = workflow_decision_repair_prompt(
                phase=phase,
                original_goal=prompt,
                invalid_source=decision_source(result),
                stage_ledger=workflow_stages,
            )
            self.bus.bridge_event(run_id, {
                "type": "dynamic_workflow_controller_repair_start",
                "phase": phase,
                "stages": len(workflow_stages),
                "plannedStages": planned_stages,
                "maxStages": max_stages,
                "canClaimAGI": False,
            })
            repair_result = run_main_pass(
                repair_prompt,
                extra=(system_extra or "").strip(),
                task_id=task_id,
                raw_turn=repair_prompt,
                enable_tools=False,
                pass_max_steps=1,
            )
            repaired = (
                decision_from(repair_result)
                if bool(getattr(repair_result, "ok", False))
                and not str(getattr(repair_result, "model_error", "") or "")
                else None
            )
            self.bus.bridge_event(run_id, {
                "type": "dynamic_workflow_controller_repair_end",
                "phase": phase,
                "ok": repaired is not None,
                "action": repaired.action if repaired else "invalid",
                "plannedStages": planned_stages,
                "maxStages": max_stages,
                "canClaimAGI": False,
            })
            return repaired

        chart_limit_error = ""
        if chart_selected and selected_chart is not None:
            if resume_workflow_run_id:
                chart_limit_error = (
                    "a selected flowchart cannot be combined with "
                    "workflow resume"
                )
            elif len(selected_chart.waves) > max_stages:
                chart_limit_error = (
                    f"flowchart has {len(selected_chart.waves)} executable "
                    f"waves but workflowMaxStages is {max_stages}"
                )
            elif len(selected_chart.executable_nodes) > max_agents:
                chart_limit_error = (
                    f"flowchart has {len(selected_chart.executable_nodes)} "
                    f"executable nodes but workflowMaxAgents is {max_agents}"
                )
        if chart_limit_error:
            chart_error = chart_limit_error

        def chart_node_contract(node: FlowchartNode) -> dict[str, Any]:
            """Build one immutable worker contract from a validated chart node."""
            contract: dict[str, Any] = {
                "chartNodeId": node.id,
                "chartNodeKind": node.kind,
                "chartNodeLabel": node.label,
                "chartDependencies": list(node.predecessor_ids),
                "chartSuccessors": list(node.successor_ids),
                "task": node.task,
                "role": node.role or "flowchart-worker",
            }
            if node.done_criteria:
                contract["doneCriteria"] = list(node.done_criteria)
            if node.expected_output:
                contract["expectedOutput"] = node.expected_output
            return contract

        def chart_decision_for_wave(wave_index: int) -> WorkflowDecision:
            assert selected_chart is not None
            node_ids = (
                selected_chart.waves[wave_index]
                if 0 <= wave_index < len(selected_chart.waves)
                else ()
            )
            nodes = tuple(selected_chart.node(node_id) for node_id in node_ids)
            contracts = tuple(chart_node_contract(node) for node in nodes)
            tasks = tuple(node.task for node in nodes)
            return WorkflowDecision(
                action="dispatch",
                pattern=f"flowchart:{selected_chart.chart_id}",
                reason=(
                    f"Dispatch the validated flowchart wave {wave_index + 1}/"
                    f"{len(selected_chart.waves)} from {selected_chart.chart_id}."
                ),
                stage_goal=(
                    "Complete chart nodes: "
                    + ", ".join(node.id for node in nodes)
                ),
                tasks=tasks,
                task_contracts=contracts,
                completion_criteria=(
                    "Every declared chart node in this wave returns a "
                    "usable terminal receipt.",
                    "Do not dispatch a node outside the selected chart.",
                ),
                stage_kind=(
                    "recovery"
                    if any(node.kind == "recovery" for node in nodes)
                    else "specialist"
                ),
                requires_critics=False,
                reason_code="flowchart_wave",
                planned_stages=len(selected_chart.waves),
            )

        def chart_finish_decision() -> WorkflowDecision:
            assert selected_chart is not None
            return WorkflowDecision(
                action="finish",
                pattern=f"flowchart:{selected_chart.chart_id}",
                reason=(
                    "All executable nodes in the selected flowchart completed "
                    "with usable receipts; proceed to bounded synthesis."
                ),
                final_focus=(
                    f"Synthesize the verified receipts for flowchart "
                    f"{selected_chart.chart_id}."
                ),
                requires_critics=False,
                reason_code="flowchart_complete",
                planned_stages=len(selected_chart.waves),
            )

        # A selected file (including a file that fails closed validation) owns
        # the workflow route.  Do not even construct a built-in template for
        # that route: doing so makes an invalid chart look as if it consulted
        # the prompt-driven barrier catalog, and lets future template changes
        # accidentally leak into chart provenance.
        deterministic_stages = []
        deterministic_template_source = ""
        deterministic_coverage_keys = ()
        if not chart_selected and not chart_error:
            deterministic_stages = known_tui_parallel_barrier_smoke_stages(
                prompt,
                profile_context=system_extra,
            )
            if deterministic_stages:
                deterministic_template_source = (
                    "known-tui-parallel-barrier-smoke-template"
                )
                deterministic_coverage_keys = (
                    TUI_PARALLEL_BARRIER_COVERAGE_KEYS
                )
            if not deterministic_stages:
                deterministic_stages = known_direct_test_execution_stages(
                    prompt,
                    profile_context=system_extra,
                )
                if deterministic_stages:
                    deterministic_template_source = (
                        "known-direct-test-execution-template"
                    )
                    deterministic_coverage_keys = (
                        DIRECT_TEST_EXECUTION_COVERAGE_KEYS
                    )
            if not deterministic_stages:
                deterministic_stages = known_plugin_audit_stages(
                    prompt,
                    profile_context=system_extra,
                )
                if deterministic_stages:
                    deterministic_template_source = (
                        "known-plugin-audit-template"
                    )
                    deterministic_coverage_keys = (
                        PLUGIN_AUDIT_COVERAGE_KEYS
                    )
        else:
            deterministic_template_source = "flowchart-file"
        deterministic_template = bool(deterministic_stages)
        known_tui_direct_synthesis = (
            deterministic_template_source.startswith("known-tui")
        )
        if known_tui_direct_synthesis:
            # Grok's default CLI cap is 2. This template's contract is four
            # parallel specialist lanes in one barrier; keep that topology.
            provider_concurrency_cap = max(int(provider_concurrency_cap), 4)
            stage_task_limit = max(
                MIN_PARALLEL_TASKS,
                min(MAX_TASKS_PER_STAGE, provider_concurrency_cap),
            )
        if known_tui_direct_synthesis and workflow_stages:
            # The current known-TUI contract is specialist fan-out followed by
            # direct Main synthesis. Older durable manifests may still carry
            # requiresCritics=true from the retired 4+2 template. Treat the
            # template ID as the authoritative topology, migrate the copied
            # stage records, and do not let stale resume metadata resurrect a
            # critic barrier that this template no longer dispatches.
            for stage in workflow_stages:
                if not bool(stage.get("requiresCritics")):
                    continue
                stage["requiresCritics"] = False
                publish_orchestration(
                    orchestration.upsert_workflow_stage(stage)
                )
            handle["dynamicWorkflowStages"] = list(workflow_stages)
            critic_barrier_required = False
        planned_stages = (
            bounded_workflow_planned_stages(
                len(selected_chart.waves),
                current_stage=0,
                max_stages=max_stages,
                fallback=max_stages,
            )
            if chart_selected and selected_chart is not None
            else (
                bounded_workflow_planned_stages(
                    len(deterministic_stages),
                    current_stage=0,
                    max_stages=max_stages,
                    fallback=max_stages,
                )
                if deterministic_template
                else 0
            )
        )

        def revise_planned_stages(
            next_decision: WorkflowDecision | None,
            *,
            current_stage: int,
        ) -> int:
            if next_decision is None:
                return max(current_stage, planned_stages)
            if chart_selected and selected_chart is not None:
                return bounded_workflow_planned_stages(
                    len(selected_chart.waves),
                    current_stage=current_stage,
                    max_stages=max_stages,
                    fallback=len(selected_chart.waves),
                )
            if deterministic_template:
                return bounded_workflow_planned_stages(
                    len(deterministic_stages),
                    current_stage=current_stage,
                    max_stages=max_stages,
                    fallback=planned_stages,
                )
            if next_decision.action != "dispatch":
                return max(0, current_stage)
            next_stage = max(1, current_stage + 1)
            return bounded_workflow_planned_stages(
                next_decision.planned_stages,
                current_stage=next_stage,
                max_stages=max_stages,
                fallback=max(next_stage, planned_stages),
            )

        def publish_controller_goal(
            next_decision: WorkflowDecision,
            *,
            current_stage: int,
            source: str,
            dedupe_semantic: bool = False,
        ) -> bool:
            nonlocal planned_stages
            planned_stages = revise_planned_stages(
                next_decision,
                current_stage=current_stage,
            )
            if next_decision.action == "dispatch":
                goal_text = (
                    next_decision.stage_goal
                    or f"Complete workflow stage {current_stage + 1}."
                )
            elif next_decision.action == "finish":
                goal_text = (
                    next_decision.final_focus
                    or "Synthesize the verified workflow evidence."
                )
            elif next_decision.action == "awaiting_input":
                goal_text = (
                    next_decision.requested_input
                    or next_decision.reason
                    or "Await operator input required to continue."
                )
            else:
                goal_text = (
                    next_decision.final_focus
                    or next_decision.reason
                    or "Report the bounded workflow outcome."
                )
            summary = _goal_panel_summary(goal_text)
            existing = handle.get("goalPanel")
            if (
                dedupe_semantic
                and isinstance(existing, dict)
                and str(existing.get("goal") or "") == summary
                and _safe_int(existing.get("currentStage"), 0)
                    == max(0, current_stage)
                and _safe_int(existing.get("plannedStages"), 0)
                    == max(0, planned_stages)
                and _safe_int(existing.get("maxStages"), 0)
                    == max(1, max_stages)
            ):
                return False
            self._emit_goal_update(
                handle,
                goal=summary,
                source=source,
                reason=next_decision.reason or next_decision.action,
                current_stage=current_stage,
                planned_stages=(
                    planned_stages
                    if planned_stages > 0
                    else None
                ),
                max_stages=max_stages,
            )
            return True

        self.bus.bridge_event(run_id, {
            "type": "dynamic_workflow_start",
            "configuredMode": configured_mode,
            "execution": execution,
            "terminalLayout": terminal_layout,
            "maxStages": max_stages,
            "plannedStages": planned_stages,
            "maxAgents": max_agents,
            "workflowChart": (
                selected_chart.to_event()
                if selected_chart is not None
                else (
                    {
                        "sourcePath": _normalize_workflow_chart_path(
                            workflow_chart_path
                        ),
                        "error": chart_error,
                    }
                    if chart_error
                    else None
                )
            ),
            "workflowChartSelected": chart_selected,
            **parent_event,
            "maxTasksPerStage": stage_task_limit,
            "providerConcurrencyCap": provider_concurrency_cap,
            "concurrencyReason": concurrency_reason,
            "orchestration": orchestration.snapshot(),
            "candidateOnly": True,
            "canClaimAGI": False,
        })

        planner_result: Any = None
        self.bus.bridge_event(run_id, {
            "type": "dynamic_workflow_controller_start",
            "phase": "plan",
            "stage": 0,
            "plannedStages": planned_stages,
            "maxStages": max_stages,
            "source": (
                "flowchart-file"
                if chart_selected
                else (
                    deterministic_template_source
                    if deterministic_template
                    else "model"
                )
            ),
            "canClaimAGI": False,
        })
        if resume_error:
            decision = None
            planner_ok = False
            planner_result = SimpleNamespace(
                model_error=resume_error,
                final_text="",
            )
        elif chart_error:
            decision = None
            planner_ok = False
            planner_result = SimpleNamespace(
                model_error=chart_error,
                final_text="",
            )
        elif chart_selected:
            decision = chart_decision_for_wave(0)
            planner_ok = True
            planner_result = None
            publish_orchestration(
                orchestration.update_agent_activity(
                    "workflow-main",
                    status="idle",
                    current_task_id="",
                    current_tool="",
                    summary=(
                        "Selected validated flowchart file; Main planning "
                        "was skipped."
                    ),
                )
            )
            publish_orchestration(
                orchestration.set_task_state(
                    plan_task_id,
                    "completed",
                    summary=(
                        "Validated flowchart file supplied the workflow "
                        "topology."
                    ),
                )
            )
        elif resume_plan and str(resume_plan.get("status") or "") == "blocked":
            decision = None
            planner_ok = False
            blocked = ", ".join(
                str(item.get("taskId") or "unknown task")
                for item in list(resume_plan.get("blockedTasks") or [])
                if isinstance(item, dict)
            )
            planner_result = SimpleNamespace(
                model_error=(
                    "restart recovery is blocked because explicit "
                    "retry/idempotency policy is missing for "
                    f"{blocked or 'one or more tasks'}"
                ),
                final_text="",
            )
        elif resume_plan and str(resume_plan.get("status") or "") == "ready":
            recovery_contracts = [
                dict(contract)
                for contract in list(resume_plan.get("tasks") or [])
                if isinstance(contract, dict)
            ]
            recovery_tasks = tuple(
                " ".join(
                    str(contract.get("task") or "").split()
                )
                for contract in recovery_contracts
                if str(contract.get("task") or "").strip()
            )
            decision = WorkflowDecision(
                action="dispatch",
                pattern="durable-restart-recovery",
                reason=(
                    "Resume was explicitly requested. The durable stage "
                    "manifest identified interrupted work; retry only the "
                    "contracts carrying an explicit safe retry policy."
                ),
                stage_goal=(
                    "Recover interrupted workflow coverage from the durable "
                    "manifest without repeating successful receipts."
                ),
                tasks=recovery_tasks,
                task_contracts=tuple(recovery_contracts[: len(recovery_tasks)]),
                completion_criteria=(
                    "Every explicitly retryable interrupted contract has a "
                    "usable terminal receipt.",
                    "No successful prior receipt is dispatched again.",
                ),
                stage_kind="recovery",
                requires_critics=(
                    False
                    if known_tui_direct_synthesis
                    else any(
                        bool(stage.get("requiresCritics"))
                        for stage in workflow_stages
                    )
                ),
                reason_code="restart_recovery_ready",
            )
            planner_ok = bool(recovery_tasks)
            planner_result = None
        elif resume_plan is not None:
            # Explicit resume loaded a durable manifest with nothing left to
            # retry. Do not fall through to deterministic_stages[0] — that
            # would replay specialists that already have receipts.
            resume_status = str(resume_plan.get("status") or "")
            if resume_status == "not_required":
                decision = WorkflowDecision(
                    action="finish",
                    pattern="durable-restart-recovery",
                    reason=(
                        "Resume was explicitly requested. The durable "
                        "manifest has no interrupted contracts that need "
                        "retry; continue from harvested receipts."
                    ),
                    stage_goal=(
                        "Continue from the harvested durable manifest "
                        "without repeating successful receipts."
                    ),
                    reason_code="restart_recovery_not_required",
                    requires_critics=(
                        False
                        if known_tui_direct_synthesis
                        else any(
                            bool(stage.get("requiresCritics"))
                            for stage in workflow_stages
                        )
                    ),
                )
                planner_ok = True
                planner_result = None
            else:
                decision = None
                planner_ok = False
                planner_result = SimpleNamespace(
                    model_error=(
                        "restart recovery returned unsupported status "
                        f"{resume_status!r}"
                    ),
                    final_text="",
                )
        elif deterministic_template:
            decision = deterministic_stages[0]
            planner_ok = True
            publish_orchestration(
                orchestration.update_agent_activity(
                    "workflow-main",
                    status="idle",
                    current_task_id="",
                    current_tool="",
                    summary=(
                        "Selected deterministic known plugin audit template; "
                        "model planning skipped."
                    ),
                )
            )
            publish_orchestration(
                orchestration.set_task_state(
                    plan_task_id,
                    "completed",
                    summary=(
                        "Deterministic known plugin audit template selected."
                    ),
                )
            )
        else:
            planner_extra = (system_extra or "").strip()
            controller_extra = workflow_planner_system_extra(
                configured_mode=configured_mode,
                max_stages=max_stages,
                max_agents=max_agents,
                max_tasks_per_stage=MAX_TASKS_PER_STAGE,
                active_concurrency_limit=stage_task_limit,
                provider_kind=workflow_provider_kind,
            )
            planner_extra = (
                f"{planner_extra}\n\n{controller_extra}".strip()
                if planner_extra
                else controller_extra
            )
            planner_result = run_main_pass(
                prompt,
                extra=planner_extra,
                task_id=plan_task_id,
                pass_history=history,
                raw_turn=raw_prompt or prompt,
                # Routing must be side-effect free. AUTO may legitimately fall
                # back to the ordinary solo loop, so allowing planner tools here
                # could execute a write/command once during routing and again
                # during the actual run.
                enable_tools=False,
            )
            planner_ok = bool(
                getattr(planner_result, "ok", False)
            ) and not str(
                getattr(planner_result, "model_error", "") or ""
            )
            decision = decision_from(planner_result) if planner_ok else None
            if planner_ok and decision is None:
                decision = repair_decision(
                    planner_result,
                    phase="plan",
                    task_id=plan_task_id,
                )
        planned_stages = revise_planned_stages(
            decision,
            current_stage=0,
        )
        critic_barrier_required = (
            False
            if chart_selected or known_tui_direct_synthesis
            else workflow_requires_critic_barrier(
                prompt,
                decision,
            )
        )
        self.bus.bridge_event(run_id, {
            "type": "dynamic_workflow_controller_end",
            "phase": "plan",
            "stage": 0,
            "plannedStages": planned_stages,
            "maxStages": max_stages,
            "ok": bool(planner_ok and decision is not None),
            "source": (
                "flowchart-file"
                if chart_selected or chart_error
                else (
                    deterministic_template_source
                    if deterministic_template
                    else "model"
                )
            ),
            "modelCallSkipped": bool(
                deterministic_template or chart_selected or chart_error
            ),
            "action": decision.action if decision else "invalid",
            "pattern": decision.pattern if decision else "",
            "reason": (
                decision.reason
                if decision
                else str(
                    getattr(planner_result, "model_error", "")
                    or "Main did not emit a valid WORKFLOW_DECISION"
                )
            ),
            "canClaimAGI": False,
        })
        if decision is not None:
            self._emit_goal_update(
                handle,
                goal=decision.stage_goal or prompt,
                source="workflow-plan",
                reason=decision.reason or decision.action,
                current_stage=0,
                planned_stages=(
                    planned_stages
                    if planned_stages > 0
                    else None
                ),
                max_stages=max_stages,
            )
            if decision.action == "dispatch":
                publish_orchestration(
                    orchestration.upsert_workflow_plan({
                        "stage": 1 if not workflow_stages else len(workflow_stages) + 1,
                        "pattern": decision.pattern,
                        "kind": decision.stage_kind or "general",
                        "status": "ready",
                        "goal": decision.stage_goal,
                        "plannedStages": planned_stages,
                        "tasks": list(decision.tasks),
                        "taskContracts": list(decision.task_contracts),
                        "completionCriteria": list(
                            decision.completion_criteria
                        ),
                        "requiresCritics": decision.requires_critics,
                    })
                )

        if chart_error:
            reason = chart_error
            terminal_reason_code = "flowchart_invalid"
            final_text = (
                "Selected flowchart was rejected before worker/provider "
                f"dispatch: {reason}. candidateOnly: true; "
                "canClaimAGI: false."
            )
            handle["dynamicWorkflowResult"] = {
                "status": "failed",
                "configuredMode": configured_mode,
                "pattern": "flowchart-file",
                "reason": reason,
                "reasonCode": terminal_reason_code,
                "stages": 0,
                "plannedStages": 0,
                "maxStages": max_stages,
                "totalAgents": 0,
                "requestedAgents": 0,
                "unstartedAgents": 0,
                "workflowChart": {
                    "sourcePath": _normalize_workflow_chart_path(
                        workflow_chart_path
                    ),
                    "error": reason,
                },
                "criticBarrier": {
                    "required": False,
                    "satisfied": False,
                },
                "candidateOnly": True,
                "canClaimAGI": False,
            }
            self.bus.bridge_event(run_id, {
                "type": "dynamic_workflow_end",
                "selected": True,
                "status": "failed",
                "reason": reason,
                "reasonCode": terminal_reason_code,
                "pattern": "flowchart-file",
                "stages": 0,
                "plannedStages": 0,
                "totalAgents": 0,
                "requestedAgents": 0,
                "unstartedAgents": 0,
                "workflowChartSelected": True,
                "candidateOnly": True,
                "canClaimAGI": False,
            })
            return AgentLoopResult(
                goal=prompt,
                final_text=final_text,
                ok=False,
                steps=all_steps,
                messages=list(history or [])
                + [{"role": "assistant", "content": final_text}],
                model_error=reason,
            )

        if (
            decision is None
            or (
                decision.action == "dispatch"
                and len(decision.tasks) < MIN_PARALLEL_TASKS
                and decision.stage_kind != "recovery"
                and not chart_selected
            )
        ):
            if configured_mode == "auto":
                reason = (
                    "Main workflow routing was invalid; falling back to the "
                    "ordinary solo agent loop"
                )
                self.bus.bridge_event(run_id, {
                    "type": "dynamic_workflow_end",
                    "selected": False,
                    "status": "skipped",
                    "reason": reason,
                    "stages": 0,
                    "plannedStages": 0,
                    "maxStages": max_stages,
                    "totalAgents": 0,
                    "candidateOnly": True,
                    "canClaimAGI": False,
                })
                handle["dynamicWorkflowResult"] = {
                    "status": "skipped",
                    "configuredMode": configured_mode,
                    "reason": reason,
                    "reasonCode": "planner_invalid",
                    "stages": 0,
                    "plannedStages": 0,
                    "maxStages": max_stages,
                    "totalAgents": 0,
                    "requestedAgents": 0,
                    "unstartedAgents": 0,
                    "criticBarrier": {
                        "required": critic_barrier_required,
                        "satisfied": False,
                    },
                    "candidateOnly": True,
                    "canClaimAGI": False,
                }
                handle["runMode"] = "solo"
                return run_agent_loop(
                    prompt,
                    client=tee,
                    ctx=ctx,
                    history=history,
                    on_event=sink,
                    max_steps=max_steps,
                    system_extra=system_extra,
                    show_thinking=show_thinking,
                    steering_consumer=steering_consumer,
                    budget=budget,
                    max_parallel_tools=max_parallel_tools,
                    post_tool_continuity=True,
                    max_continuations=max_continuations,
                    raw_user_turn=raw_prompt or prompt,
                    response_style=response_style,
                    require_live_refresh=require_live_refresh,
                )
            reason = (
                str(getattr(planner_result, "model_error", "") or "")
                or "Main did not emit a valid parallel workflow decision"
            )
            terminal_reason_code = "planner_invalid"
            final_text = (
                "Dynamic workflow stopped before stage 1: "
                f"{reason}. candidateOnly: true; canClaimAGI: false."
            )
            handle["dynamicWorkflowResult"] = {
                "status": "failed",
                "configuredMode": configured_mode,
                "reason": reason,
                "reasonCode": terminal_reason_code,
                "stages": 0,
                "plannedStages": 0,
                "maxStages": max_stages,
                "totalAgents": 0,
                "requestedAgents": 0,
                "unstartedAgents": 0,
                "criticBarrier": {
                    "required": critic_barrier_required,
                    "satisfied": False,
                },
                "candidateOnly": True,
                "canClaimAGI": False,
            }
            return AgentLoopResult(
                goal=prompt,
                final_text=final_text,
                ok=False,
                steps=all_steps,
                messages=list(history or [])
                + [{"role": "assistant", "content": final_text}],
                model_error=reason,
            )

        if decision.action == "skip":
            reason = decision.reason or "Main judged a dynamic workflow unnecessary"
            self.bus.bridge_event(run_id, {
                "type": "dynamic_workflow_end",
                "selected": False,
                "status": "skipped",
                "reason": reason,
                "stages": 0,
                "plannedStages": 0,
                "maxStages": max_stages,
                "totalAgents": 0,
                "candidateOnly": True,
                "canClaimAGI": False,
            })
            handle["dynamicWorkflowResult"] = {
                "status": "skipped",
                "configuredMode": configured_mode,
                "reason": reason,
                "reasonCode": "workflow_skipped",
                "stages": 0,
                "plannedStages": 0,
                "maxStages": max_stages,
                "totalAgents": 0,
                "requestedAgents": 0,
                "unstartedAgents": 0,
                "criticBarrier": {
                    "required": critic_barrier_required,
                    "satisfied": False,
                },
                "candidateOnly": True,
                "canClaimAGI": False,
            }
            handle["runMode"] = "solo"
            return run_agent_loop(
                prompt,
                client=tee,
                ctx=ctx,
                history=history,
                on_event=sink,
                max_steps=max_steps,
                system_extra=system_extra,
                show_thinking=show_thinking,
                steering_consumer=steering_consumer,
                budget=budget,
                max_parallel_tools=max_parallel_tools,
                post_tool_continuity=True,
                max_continuations=max_continuations,
                raw_user_turn=raw_prompt or prompt,
                response_style=response_style,
                require_live_refresh=require_live_refresh,
            )

        def stage_packet_complete(stage: dict[str, Any]) -> bool:
            return workflow_stage_packet_complete(stage)

        def latest_evidence_stage() -> dict[str, Any] | None:
            for stage in reversed(workflow_stages):
                if str(stage.get("kind") or "") in {
                    "general",
                    "specialist",
                    "recovery",
                    "refinement",
                    "implementation_follow_up",
                }:
                    return stage
            return None

        def successful_critic_stage() -> dict[str, Any] | None:
            for stage in reversed(workflow_stages):
                if (
                    str(stage.get("kind") or "") == "critic"
                    and str(stage.get("status") or "") == "succeeded"
                    and stage_packet_complete(stage)
                ):
                    return stage
            return None

        def copy_decision_with_tasks(
            source: WorkflowDecision,
            tasks: tuple[str, ...],
            contracts: tuple[dict[str, Any], ...],
        ) -> WorkflowDecision:
            return WorkflowDecision(
                action=source.action,
                pattern=source.pattern,
                reason=source.reason,
                stage_goal=source.stage_goal,
                tasks=tasks,
                task_contracts=contracts,
                completion_criteria=source.completion_criteria,
                final_focus=source.final_focus,
                requested_input=source.requested_input,
                stage_kind=source.stage_kind,
                requires_critics=source.requires_critics,
                disagreements=source.disagreements,
                reason_code=source.reason_code,
                planned_stages=source.planned_stages,
                raw=source.raw,
            )

        def next_deterministic_template_decision() -> WorkflowDecision:
            completed = workflow_completed_coverage(workflow_stages)
            for planned in deterministic_stages:
                if planned.stage_kind == "critic":
                    continue
                tasks, contracts = workflow_filter_completed_tasks(
                    planned.tasks,
                    planned.task_contracts,
                    completed,
                    planned.stage_kind,
                )
                if tasks:
                    return copy_decision_with_tasks(
                        planned,
                        tasks,
                        contracts,
                    )
            if deterministic_template_source == (
                "known-direct-test-execution-template"
            ):
                return WorkflowDecision(
                    action="finish",
                    pattern="direct-test-execution",
                    reason=(
                        "Both named tests produced persisted bash "
                        "exitCodes; proceed directly to synthesis."
                    ),
                    final_focus=(
                        "Report each command's persisted exitCode and "
                        "pass/fail. Absence of an exitCode is not 0."
                    ),
                    requires_critics=False,
                    reason_code="direct_test_execution_complete",
                )
            if (
                set(deterministic_coverage_keys).issubset(completed)
                and not critic_barrier_satisfied
            ):
                critic_stage = next(
                    (
                        planned
                        for planned in deterministic_stages
                        if planned.stage_kind == "critic"
                    ),
                    None,
                )
                if critic_stage is not None:
                    return critic_stage
                if deterministic_template_source == (
                    "known-direct-test-execution-template"
                ):
                    return WorkflowDecision(
                        action="finish",
                        pattern="direct-test-execution",
                        reason=(
                            "Both named tests produced persisted bash "
                            "exitCodes; proceed directly to synthesis."
                        ),
                        final_focus=(
                            "Report each command's persisted exitCode and "
                            "pass/fail. Absence of an exitCode is not 0."
                        ),
                        requires_critics=False,
                        reason_code="direct_test_execution_complete",
                    )
                if deterministic_template_source.startswith("known-tui"):
                    return WorkflowDecision(
                        action="finish",
                        pattern="tui-parallel-barrier-smoke",
                        reason=(
                            "All specialist lanes completed with usable "
                            "receipts; proceed directly to synthesis."
                        ),
                        final_focus=(
                            "Synthesize the parallel specialist reports and "
                            "issue the bounded evidence report."
                        ),
                        requires_critics=False,
                        reason_code=(
                            "restart_recovery_not_required"
                            if resume_workflow_run_id
                            else "tui_parallel_fanout_complete"
                        ),
                    )
            if critic_barrier_satisfied:
                if deterministic_template_source.startswith("known-tui"):
                    return WorkflowDecision(
                        action="finish",
                        pattern="tui-parallel-barrier-smoke",
                        reason=(
                            "Prior durable parallel specialist coverage is "
                            "complete; proceed to final synthesis."
                        ),
                        final_focus=(
                            "Synthesize the coverage-key verdicts and issue "
                            "the bounded evidence report."
                        ),
                        requires_critics=False,
                        reason_code=(
                            "restart_recovery_not_required"
                            if resume_workflow_run_id
                            else "tui_parallel_barrier_complete"
                        ),
                    )
                return WorkflowDecision(
                    action="finish",
                    pattern="known-plugin-audit",
                    reason=(
                        "All eight specialist coverage keys and both independent "
                        "critic reports completed; proceed directly to final "
                        "delivery-gated synthesis."
                    ),
                    final_focus=(
                        "Reconcile the eight subsystem verdicts and issue the "
                        "bounded beta GO/HOLD recommendation."
                    ),
                    requires_critics=True,
                    reason_code="known_plugin_audit_complete",
                )
            return WorkflowDecision(
                action="fail",
                pattern="known-plugin-audit",
                reason=(
                    "The deterministic audit packet is missing specialist "
                    "coverage required before the critic barrier."
                ),
                final_focus="Report the unresolved audit coverage.",
                requires_critics=True,
                reason_code="known_plugin_audit_coverage_incomplete",
            )

        chart_recovery_waves_used: set[int] = set()

        def next_chart_decision(
            *,
            stage_index: int,
            stage_record: Mapping[str, Any],
            stage_complete: bool,
        ) -> WorkflowDecision:
            """Advance only along the compiled chart, never through a planner."""
            assert selected_chart is not None
            if stage_complete:
                next_wave = stage_index
                if next_wave < len(selected_chart.waves):
                    return chart_decision_for_wave(next_wave)
                return chart_finish_decision()

            failed_node_ids = {
                str(contract.get("chartNodeId") or "").strip()
                for contract in list(stage_record.get("taskContracts") or [])
                if isinstance(contract, Mapping)
                and str(contract.get("chartNodeId") or "").strip()
            }
            completed_node_ids = {
                str(contract.get("chartNodeId") or "").strip()
                for stage in workflow_stages
                if isinstance(stage, Mapping)
                and str(stage.get("status") or "") == "succeeded"
                for contract in list(stage.get("taskContracts") or [])
                if isinstance(contract, Mapping)
                and str(contract.get("chartNodeId") or "").strip()
            }
            for wave_index, wave in enumerate(selected_chart.waves):
                if wave_index in chart_recovery_waves_used:
                    continue
                recovery_nodes = [
                    selected_chart.node(node_id)
                    for node_id in wave
                    if selected_chart.node(node_id).kind == "recovery"
                    and selected_chart.node(node_id).recovery_of in failed_node_ids
                    and node_id not in completed_node_ids
                ]
                if recovery_nodes:
                    chart_recovery_waves_used.add(wave_index)
                    return chart_decision_for_wave(wave_index)
            return WorkflowDecision(
                action="fail",
                pattern=f"flowchart:{selected_chart.chart_id}",
                reason=(
                    "a selected flowchart stage failed or was incomplete and "
                    "declared no unused recovery node for the failed chart "
                    "lane"
                ),
                final_focus="Report the failed flowchart barrier without planner recovery.",
                requires_critics=False,
                reason_code="flowchart_recovery_unavailable",
                planned_stages=len(selected_chart.waves),
            )

        if (
            resume_plan is not None
            and str(resume_plan.get("status") or "") == "not_required"
            and deterministic_template
            and not resume_error
        ):
            decision = next_deterministic_template_decision()
            planned_stages = revise_planned_stages(
                decision,
                current_stage=max(0, len(workflow_stages)),
            )
            if decision.action == "dispatch":
                publish_orchestration(
                    orchestration.upsert_workflow_plan({
                        "stage": max(1, len(workflow_stages) + 1),
                        "pattern": decision.pattern,
                        "kind": decision.stage_kind or "general",
                        "status": "ready",
                        "goal": decision.stage_goal,
                        "plannedStages": planned_stages,
                        "tasks": list(decision.tasks),
                        "taskContracts": list(decision.task_contracts),
                        "completionCriteria": list(
                            decision.completion_criteria
                        ),
                        "requiresCritics": decision.requires_critics,
                    })
                )

        terminal_decision = decision
        stage_start_index = (
            max(1, len(workflow_stages) + 1)
            if resume_workflow_run_id
            else 1
        )
        for stage_index in range(stage_start_index, max_stages + 1):
            if cancel.is_set():
                raise _RunCancelled()
            if terminal_decision.action != "dispatch":
                break
            stage_kind = infer_workflow_stage_kind(
                terminal_decision,
                stage_index=stage_index,
            )
            planned_stages = (
                bounded_workflow_planned_stages(
                    len(selected_chart.waves),
                    current_stage=stage_index,
                    max_stages=max_stages,
                    fallback=planned_stages,
                )
                if chart_selected and selected_chart is not None
                else (
                    bounded_workflow_planned_stages(
                        len(deterministic_stages),
                        current_stage=stage_index,
                        max_stages=max_stages,
                        fallback=planned_stages,
                    )
                    if deterministic_template
                    else bounded_workflow_planned_stages(
                        planned_stages,
                        current_stage=stage_index,
                        max_stages=max_stages,
                        fallback=stage_index,
                    )
                )
            )
            if (
                workflow_stages
                and str(workflow_stages[-1].get("status") or "") != "succeeded"
                and stage_kind != "recovery"
            ):
                terminal_reason_code = "recovery_barrier_required"
                terminal_decision = WorkflowDecision(
                    action="fail",
                    pattern=terminal_decision.pattern,
                    reason=(
                        "a failed or incomplete stage must be repaired by a "
                        "separate recovery barrier before critics or synthesis"
                    ),
                    final_focus="report the missing recovery barrier",
                    reason_code=terminal_reason_code,
                )
                break
            if stage_kind == "critic":
                evidence_stage = latest_evidence_stage()
                if (
                    evidence_stage is None
                    or str(evidence_stage.get("status") or "") != "succeeded"
                    or not stage_packet_complete(evidence_stage)
                ):
                    terminal_reason_code = "critic_barrier_incomplete"
                    terminal_decision = WorkflowDecision(
                        action="fail",
                        pattern=terminal_decision.pattern,
                        reason=(
                            "critic stage requires a complete, successful "
                            "specialist or recovery packet"
                        ),
                        final_focus=(
                            "report the incomplete critic-barrier prerequisite"
                        ),
                        reason_code=terminal_reason_code,
                    )
                    break
            if stage_kind == "tiebreak":
                if (
                    successful_critic_stage() is None
                    or not terminal_decision.disagreements
                ):
                    terminal_reason_code = "tiebreak_precondition_missing"
                    terminal_decision = WorkflowDecision(
                        action="fail",
                        pattern=terminal_decision.pattern,
                        reason=(
                            "tiebreak stage requires a successful critic "
                            "barrier and explicit material disagreements"
                        ),
                        final_focus="report the missing tiebreak prerequisite",
                        reason_code=terminal_reason_code,
                    )
                    break
            remaining_agents = max_agents - total_agents
            if chart_selected:
                filtered_tasks = tuple(terminal_decision.tasks)
                filtered_contracts = tuple(terminal_decision.task_contracts)
            elif deterministic_template:
                completed_before_stage = workflow_completed_coverage(
                    workflow_stages
                )
                filtered_tasks, filtered_contracts = (
                    workflow_filter_completed_tasks(
                        terminal_decision.tasks,
                        terminal_decision.task_contracts,
                        completed_before_stage,
                        stage_kind,
                    )
                )
            else:
                # Coverage keys are a Sophia beta-template protocol. Generic
                # model-planned workflows may legitimately revisit similarly
                # named scopes, so never deduplicate their tasks by inferred
                # plugin-audit phrases.
                filtered_tasks = tuple(terminal_decision.tasks)
                filtered_contracts = tuple(
                    terminal_decision.task_contracts
                )
            controller_requested_task_count = len(filtered_tasks)
            tasks = list(filtered_tasks)[
                : min(remaining_agents, MAX_TASKS_PER_STAGE)
            ]
            task_contracts = list(filtered_contracts)[: len(tasks)]
            deferred_task_count = max(
                0,
                controller_requested_task_count - len(tasks),
            )
            minimum_stage_tasks = (
                1
                if chart_selected or stage_kind == "recovery"
                else MIN_PARALLEL_TASKS
            )
            if len(tasks) < minimum_stage_tasks:
                if (
                    deterministic_template_source
                    == "known-direct-test-execution-template"
                    and workflow_stages
                    and str(workflow_stages[-1].get("status") or "")
                    == "succeeded"
                ):
                    terminal_decision = WorkflowDecision(
                        action="finish",
                        pattern="direct-test-execution",
                        reason=(
                            "Named-test stage succeeded; synthesize instead "
                            "of funding another parallel barrier."
                        ),
                        final_focus=(
                            "Report each command's persisted exitCode and "
                            "pass/fail. Absence of an exitCode is not 0."
                        ),
                        requires_critics=False,
                        reason_code="direct_test_execution_complete",
                    )
                    break
                terminal_reason_code = (
                    "completed_coverage_duplicate"
                    if controller_requested_task_count == 0
                    else "worker_budget_exhausted"
                )
                terminal_decision = WorkflowDecision(
                    action="fail",
                    pattern=terminal_decision.pattern,
                    reason=(
                        (
                            "all proposed specialist coverage is already "
                            "complete; the controller stopped instead of "
                            "dispatching duplicate work"
                        )
                        if controller_requested_task_count == 0
                        else (
                            "workflow worker budget cannot fund the next "
                            f"bounded stage ({total_agents}/{max_agents} "
                            "already used)"
                        )
                    ),
                    final_focus=(
                        "report the completed-coverage deduplication guard"
                        if controller_requested_task_count == 0
                        else "report the bounded workflow budget exhaustion"
                    ),
                    reason_code=terminal_reason_code,
                )
                break
            signature = hashlib.sha256(
                json.dumps(tasks, ensure_ascii=False, sort_keys=True).encode(
                    "utf-8"
                )
            ).hexdigest()
            if signature in task_signatures:
                terminal_reason_code = "repeated_stage"
                terminal_decision = WorkflowDecision(
                    action="fail",
                    pattern=terminal_decision.pattern,
                    reason=(
                        "Main repeated an equivalent worker batch; the bounded "
                        "controller stopped instead of looping"
                    ),
                    final_focus="report the repeated-stage guard",
                    reason_code=terminal_reason_code,
                )
                break
            task_signatures.add(signature)

            assignments = resolve_dispatch_assignments(
                tasks,
                # Main-authored role/skill fields remain authoritative; when
                # an older or malformed planner omits one, the harness still
                # supplies a task-routed persona/skill contract instead of
                # dispatching an uncharacterized generic worker.
                auto_skills=True,
                auto_persona=True,
                tool_scopes=[
                    contract.get("allowedTools")
                    if isinstance(contract, dict)
                    and (
                        bool(contract.get("toolScopeVia"))
                        or bool(contract.get("allowedTools"))
                    )
                    else None
                    for contract in task_contracts
                ],
            )
            if any(assignment.depends_on for assignment in assignments):
                terminal_reason_code = "invalid_stage_dependency"
                terminal_decision = WorkflowDecision(
                    action="fail",
                    pattern=terminal_decision.pattern,
                    reason=(
                        "a workflow stage contained AFTER dependencies; stages "
                        "must contain dependency-independent parallel tasks"
                    ),
                    final_focus="report the invalid parallel-stage dependency",
                    reason_code=terminal_reason_code,
                )
                break

            context_stages: list[dict[str, Any]] = []
            if workflow_stages:
                context_stages = list(workflow_stages)
                if stage_kind == "critic":
                    context_stages = [
                        stage
                        for stage in workflow_stages
                        if str(stage.get("kind") or "") in {
                            "general",
                            "specialist",
                            "recovery",
                        }
                    ]
                elif stage_kind == "tiebreak":
                    critic_stage = successful_critic_stage()
                    context_stages = (
                        [critic_stage] if critic_stage is not None else []
                    )
            try:
                resolved_context_window = max(
                    1,
                    int(handle.get("resolvedContextWindow") or 128_000),
                )
            except (TypeError, ValueError):
                resolved_context_window = 128_000
            focused_context_limit = min(
                WORKFLOW_CRITIC_CONTEXT_MAX_CHARS,
                max(12_000, resolved_context_window),
            )
            task_contexts: list[str] = []
            for index, assignment in enumerate(assignments):
                contract = (
                    task_contracts[index]
                    if index < len(task_contracts)
                    and isinstance(task_contracts[index], dict)
                    else {}
                )
                source_ids = (
                    workflow_referenced_source_ids(assignment.task)
                    if stage_kind in {"critic", "tiebreak"}
                    else ()
                )
                context_limit = (
                    focused_context_limit if source_ids else 4600
                )
                task_contexts.append(
                    workflow_compact_worker_context(
                        "",
                        stage_goal=terminal_decision.stage_goal,
                        rationale=terminal_decision.reason,
                        coverage_keys=workflow_task_coverage_keys(contract),
                        stage_ledger=context_stages,
                        source_ids=source_ids,
                        max_chars=context_limit,
                    )
                )
            worker_context = (
                task_contexts[0]
                if task_contexts
                else workflow_compact_worker_context(
                    "",
                    stage_goal=terminal_decision.stage_goal,
                    rationale=terminal_decision.reason,
                    stage_ledger=context_stages,
                    max_chars=4600,
                )
            )
            compact_original_goal = " ".join(prompt.split())
            if len(compact_original_goal) > 1800:
                compact_original_goal = (
                    f"{compact_original_goal[:1799]}…"
                )

            self._emit_goal_update(
                handle,
                goal=(
                    terminal_decision.stage_goal
                    or f"Complete workflow stage {stage_index}."
                ),
                source="workflow-stage",
                reason=terminal_decision.reason or stage_kind,
                current_stage=stage_index,
                planned_stages=planned_stages,
                max_stages=max_stages,
            )
            self._emit_workflow_todo_board(
                handle,
                workflow_stages,
                pending_contracts=list(task_contracts),
            )
            stage_record = self._run_dynamic_workflow_stage(
                handle,
                original_goal=compact_original_goal,
                stage_index=stage_index,
                pattern=terminal_decision.pattern or "adaptive",
                stage_kind=stage_kind,
                stage_goal=terminal_decision.stage_goal,
                assignments=assignments,
                task_contracts=task_contracts,
                completion_criteria=list(terminal_decision.completion_criteria),
                requires_critics=terminal_decision.requires_critics,
                main_context=worker_context,
                task_contexts=task_contexts,
                system_extra=system_extra,
                model_alias=model_alias,
                mode=mode,
                permission=permission,
                session=session,
                workspace=workspace,
                max_steps=max_steps,
                show_thinking=show_thinking,
                response_style=response_style,
                execution=execution,
                terminal_layout=terminal_layout,
                budget=budget,
                cancel=cancel,
                orchestration=orchestration,
                publish_orchestration=publish_orchestration,
                workflow_id=workflow_instance_id,
                parent_mode=parent_mode,
                parent_node_id=parent_node_id,
                parent_phase=parent_phase,
                provider_concurrency_cap=provider_concurrency_cap,
                concurrency_reason=concurrency_reason,
                conscience_mode=getattr(ctx, "conscience_mode", None),
                controller_requested_task_count=(
                    controller_requested_task_count
                ),
                deferred_task_count=deferred_task_count,
                planned_stages=planned_stages,
                dispatch_manifest=dispatch_manifest,
                worker_model_authority=prompt,
            )
            workflow_stages.append(stage_record)
            self._emit_workflow_todo_board(handle, workflow_stages)
            dispatch_manifest.set_status(
                "verifying",
                phase="verifying",
                main_status="verifying",
            )
            self._publish_dispatch_manifest(handle)
            agents = list(stage_record.get("agents") or [])
            flattened_agents.extend(agents)
            requested_agents = _safe_int(
                stage_record.get("requestedAgentCount"),
                len(agents),
            )
            started_agents = _safe_int(
                stage_record.get("startedAgentCount"),
                len(agents),
            )
            unstarted_agents = _safe_int(
                stage_record.get("unstartedAgentCount"),
                max(0, requested_agents - started_agents),
            )
            total_requested_agents += requested_agents
            total_agents += started_agents
            total_unstarted_agents += unstarted_agents
            if (
                stage_kind == "critic"
                and str(stage_record.get("status") or "") == "succeeded"
                and stage_packet_complete(stage_record)
            ):
                critic_barrier_satisfied = True
            for result in list(stage_record.get("results") or []):
                for step in list(result.get("steps") or []):
                    all_steps.append(
                        dict(step) if isinstance(step, dict) else step
                    )
                for receipt in list(
                    result.get("providerToolReceipts") or []
                ):
                    if isinstance(receipt, dict):
                        provider_tool_receipts.append(dict(receipt))
            handle["dynamicWorkflowStages"] = list(workflow_stages)
            handle["dynamicWorkflowAgents"] = list(flattened_agents)

            stage_results = [
                result
                for result in list(stage_record.get("results") or [])
                if isinstance(result, dict)
            ]
            stage_contracts = [
                contract
                for contract in list(stage_record.get("taskContracts") or [])
                if isinstance(contract, dict)
            ]
            usable_stage_results = [
                result
                for index, result in enumerate(stage_results)
                if workflow_result_evidence_complete(
                    result,
                    (
                        stage_contracts[index]
                        if index < len(stage_contracts)
                        else {}
                    ),
                )
            ]
            stage_complete = (
                str(stage_record.get("status") or "") == "succeeded"
                and stage_packet_complete(stage_record)
            )
            if chart_selected:
                terminal_decision = next_chart_decision(
                    stage_index=stage_index,
                    stage_record=stage_record,
                    stage_complete=stage_complete,
                )
                if terminal_decision.action == "fail":
                    terminal_reason_code = terminal_decision.reason_code
                stage_record["review"] = {
                    **terminal_decision.to_dict(),
                    "source": "flowchart-file",
                    "modelCallSkipped": True,
                }
                publish_controller_goal(
                    terminal_decision,
                    current_stage=stage_index,
                    source="flowchart-review",
                )
                self.bus.bridge_event(run_id, {
                    "type": "dynamic_workflow_controller_end",
                    "phase": "review",
                    "stage": stage_index,
                    "plannedStages": planned_stages,
                    "maxStages": max_stages,
                    "ok": terminal_decision.action != "fail",
                    "source": "flowchart-file",
                    "modelCallSkipped": True,
                    "action": terminal_decision.action,
                    "pattern": terminal_decision.pattern,
                    "reason": terminal_decision.reason,
                    "reasonCode": terminal_decision.reason_code,
                    "nextTaskCount": len(terminal_decision.tasks),
                    "chartNodeIds": [
                        str(contract.get("chartNodeId") or "")
                        for contract in stage_contracts
                        if str(contract.get("chartNodeId") or "")
                    ],
                    "canClaimAGI": False,
                })
                if terminal_decision.action == "fail":
                    break
                continue

            if deterministic_template and not stage_complete:
                recovery_decision = workflow_deterministic_recovery_decision(
                    stage_record,
                    workflow_completed_coverage(workflow_stages),
                )
                if recovery_decision is None:
                    completed_now = workflow_completed_coverage(workflow_stages)
                    if (
                        deterministic_coverage_keys
                        and set(deterministic_coverage_keys).issubset(
                            completed_now
                        )
                    ):
                        terminal_decision = (
                            next_deterministic_template_decision()
                        )
                        critic_barrier_required = (
                            critic_barrier_required
                            or terminal_decision.requires_critics
                        )
                        stage_record["review"] = {
                            **terminal_decision.to_dict(),
                            "source": "deterministic-coverage-complete",
                            "modelCallSkipped": True,
                        }
                        publish_controller_goal(
                            terminal_decision,
                            current_stage=stage_index,
                            source="workflow-review",
                        )
                        self.bus.bridge_event(run_id, {
                            "type": "dynamic_workflow_controller_end",
                            "phase": "review",
                            "stage": stage_index,
                            "plannedStages": planned_stages,
                            "maxStages": max_stages,
                            "ok": True,
                            "source": "deterministic-coverage-complete",
                            "modelCallSkipped": True,
                            "action": terminal_decision.action,
                            "pattern": terminal_decision.pattern,
                            "reason": terminal_decision.reason,
                            "reasonCode": terminal_decision.reason_code,
                            "nextTaskCount": len(terminal_decision.tasks),
                            "canClaimAGI": False,
                        })
                        continue
                    terminal_reason_code = (
                        "stage_no_usable_reports"
                        if not usable_stage_results
                        else "deterministic_recovery_unavailable"
                    )
                    terminal_decision = WorkflowDecision(
                        action="fail",
                        pattern=terminal_decision.pattern,
                        reason=(
                            f"workflow stage {stage_index} produced no usable "
                            "worker reports; controller review was skipped"
                            if not usable_stage_results
                            else (
                                "The failed stage had no unresolved task scope "
                                "that could be recovered without duplicating "
                                "successful coverage."
                            )
                        ),
                        final_focus=(
                            "report the worker failures, exclusions, and "
                            "queue-aware timeout receipts without claiming a "
                            "reviewed synthesis"
                            if not usable_stage_results
                            else "Report the unrecoverable failed barrier."
                        ),
                        requires_critics=critic_barrier_required,
                        reason_code=terminal_reason_code,
                    )
                else:
                    terminal_decision = recovery_decision
                    critic_barrier_required = (
                        critic_barrier_required
                        or recovery_decision.requires_critics
                    )
                stage_record["review"] = {
                    **terminal_decision.to_dict(),
                    "source": "deterministic-failed-coverage-recovery",
                    "modelCallSkipped": True,
                    "skipped": recovery_decision is None,
                }
                publish_controller_goal(
                    terminal_decision,
                    current_stage=stage_index,
                    source="workflow-review",
                )
                self.bus.bridge_event(run_id, {
                    "type": "dynamic_workflow_controller_end",
                    "phase": "review",
                    "stage": stage_index,
                    "plannedStages": planned_stages,
                    "maxStages": max_stages,
                    "ok": recovery_decision is not None,
                    "source": "deterministic-failed-coverage-recovery",
                    "modelCallSkipped": True,
                    "skipped": recovery_decision is None,
                    "action": terminal_decision.action,
                    "pattern": terminal_decision.pattern,
                    "reason": terminal_decision.reason,
                    "reasonCode": terminal_decision.reason_code,
                    "nextTaskCount": len(terminal_decision.tasks),
                    "canClaimAGI": False,
                })
                if recovery_decision is None:
                    break
                continue

            if not usable_stage_results:
                # A model review cannot repair a completely empty evidence
                # barrier.  Calling the provider here only adds another full
                # timeout and obscures the actual worker failure behind
                # ``controller_review_invalid``.
                terminal_reason_code = "stage_no_usable_reports"
                terminal_decision = WorkflowDecision(
                    action="fail",
                    pattern=terminal_decision.pattern,
                    reason=(
                        f"workflow stage {stage_index} produced no usable worker "
                        "reports; controller review was skipped"
                    ),
                    final_focus=(
                        "report the worker failures, exclusions, and queue-aware "
                        "timeout receipts without claiming a reviewed synthesis"
                    ),
                    reason_code=terminal_reason_code,
                )
                stage_record["review"] = {
                    **terminal_decision.to_dict(),
                    "skipped": True,
                }
                publish_controller_goal(
                    terminal_decision,
                    current_stage=stage_index,
                    source="workflow-review",
                )
                self.bus.bridge_event(run_id, {
                    "type": "dynamic_workflow_controller_end",
                    "phase": "review",
                    "stage": stage_index,
                    "plannedStages": planned_stages,
                    "maxStages": max_stages,
                    "ok": False,
                    "skipped": True,
                    "action": terminal_decision.action,
                    "pattern": terminal_decision.pattern,
                    "reason": terminal_decision.reason,
                    "reasonCode": terminal_reason_code,
                    "nextTaskCount": 0,
                    "canClaimAGI": False,
                })
                break

            if deterministic_template:
                terminal_decision = next_deterministic_template_decision()
                critic_barrier_required = (
                    critic_barrier_required
                    or terminal_decision.requires_critics
                )
                stage_record["review"] = {
                    **terminal_decision.to_dict(),
                    "source": deterministic_template_source,
                    "modelCallSkipped": True,
                }
                publish_controller_goal(
                    terminal_decision,
                    current_stage=stage_index,
                    source="workflow-review",
                )
                self.bus.bridge_event(run_id, {
                    "type": "dynamic_workflow_controller_end",
                    "phase": "review",
                    "stage": stage_index,
                    "plannedStages": planned_stages,
                    "maxStages": max_stages,
                    "ok": terminal_decision.action != "fail",
                    "source": deterministic_template_source,
                    "modelCallSkipped": True,
                    "action": terminal_decision.action,
                    "pattern": terminal_decision.pattern,
                    "reason": terminal_decision.reason,
                    "reasonCode": terminal_decision.reason_code,
                    "nextTaskCount": len(terminal_decision.tasks),
                    "canClaimAGI": False,
                })
                continue

            review_prompt = workflow_review_prompt(
                original_goal=prompt,
                configured_mode=configured_mode,
                stage_index=stage_index,
                max_stages=max_stages,
                total_agents=total_agents,
                max_agents=max_agents,
                stage_ledger=workflow_stages,
                max_tasks_per_stage=MAX_TASKS_PER_STAGE,
                active_concurrency_limit=stage_task_limit,
                provider_kind=workflow_provider_kind,
            )
            review_task_id = (
                f"{workflow_instance_id}-workflow-review-{stage_index}"
            )
            publish_orchestration(
                orchestration.upsert_task(
                    task_id=review_task_id,
                    subject=f"Review workflow stage {stage_index}",
                    description=(
                        "Adversarially verify the completed barrier and decide "
                        "whether to dispatch another stage, finish, fail, or ask "
                        "the operator."
                    ),
                    state="queued",
                    owner_id="workflow-main",
                    blocked_by=[
                        str(item.get("taskId") or "")
                        for item in list(stage_record.get("results") or [])
                        if str(item.get("taskId") or "")
                    ],
                    done_criteria=(
                        "Check every worker contract and terminal receipt.",
                        "Preserve disagreements and excluded evidence.",
                        "Never rubber-stamp a stage because workers self-reported success.",
                    ),
                    expected_output="One valid WORKFLOW_DECISION object.",
                    stage=stage_index,
                )
            )
            self.bus.bridge_event(run_id, {
                "type": "dynamic_workflow_controller_start",
                "phase": "review",
                "stage": stage_index,
                "plannedStages": planned_stages,
                "maxStages": max_stages,
                "toolsEnabled": False,
                "controllerMaxSteps": min(max_steps, 2),
                "canClaimAGI": False,
            })
            review_result = run_main_pass(
                review_prompt,
                extra=(system_extra or "").strip(),
                task_id=review_task_id,
                raw_turn=review_prompt,
                enable_tools=False,
                pass_max_steps=2,
            )
            review_ok = bool(getattr(review_result, "ok", False)) and not str(
                getattr(review_result, "model_error", "") or ""
            )
            next_decision = decision_from(review_result) if review_ok else None
            if review_ok and next_decision is None:
                next_decision = repair_decision(
                    review_result,
                    phase=f"review-{stage_index}",
                    task_id=review_task_id,
                )
            if next_decision is None:
                terminal_reason_code = "controller_review_invalid"
                terminal_decision = WorkflowDecision(
                    action="fail",
                    pattern=terminal_decision.pattern,
                    reason=(
                        str(getattr(review_result, "model_error", "") or "")
                        or "Main review did not emit a valid WORKFLOW_DECISION"
                    ),
                    final_focus="report the controller review failure",
                    reason_code=terminal_reason_code,
                )
            else:
                terminal_decision = next_decision
                critic_barrier_required = (
                    critic_barrier_required
                    or next_decision.requires_critics
                )
            stage_record["review"] = terminal_decision.to_dict()
            publish_controller_goal(
                terminal_decision,
                current_stage=stage_index,
                source="workflow-review",
            )
            self.bus.bridge_event(run_id, {
                "type": "dynamic_workflow_controller_end",
                "phase": "review",
                "stage": stage_index,
                "plannedStages": planned_stages,
                "maxStages": max_stages,
                "ok": next_decision is not None,
                "action": terminal_decision.action,
                "pattern": terminal_decision.pattern,
                "reason": terminal_decision.reason,
                "reasonCode": terminal_decision.reason_code,
                "nextTaskCount": len(terminal_decision.tasks),
                "canClaimAGI": False,
            })

        if terminal_decision.action == "dispatch":
            terminal_reason_code = "stage_limit"
            terminal_decision = WorkflowDecision(
                action="fail",
                pattern=terminal_decision.pattern,
                reason=(
                    f"workflow reached the configured {max_stages}-stage bound "
                    "before Main declared completion"
                ),
                final_focus="report the bounded stage limit",
                reason_code=terminal_reason_code,
            )

        if terminal_decision.action == "finish" and workflow_stages:
            latest_stage = workflow_stages[-1]
            if (
                str(latest_stage.get("status") or "") != "succeeded"
                or not stage_packet_complete(latest_stage)
            ):
                terminal_reason_code = "stage_packet_incomplete"
                terminal_decision = WorkflowDecision(
                    action="fail",
                    pattern=terminal_decision.pattern,
                    reason=(
                        "Main attempted to finish with an incomplete or failed "
                        "latest stage packet"
                    ),
                    final_focus="report the incomplete workflow packet",
                    reason_code=terminal_reason_code,
                )

        if (
            terminal_decision.action == "finish"
            and critic_barrier_required
            and not critic_barrier_satisfied
        ):
            terminal_reason_code = "critic_barrier_incomplete"
            terminal_decision = WorkflowDecision(
                action="fail",
                pattern=terminal_decision.pattern,
                reason=(
                    "the operator-required separate critic barrier did not "
                    "complete successfully"
                ),
                final_focus="report the incomplete critic barrier",
                reason_code=terminal_reason_code,
            )

        publish_controller_goal(
            terminal_decision,
            current_stage=len(workflow_stages),
            source="workflow-synthesis",
            dedupe_semantic=True,
        )
        final_task_id = f"{workflow_instance_id}-workflow-final"
        deterministic_empty_barrier = (
            terminal_reason_code == "stage_no_usable_reports"
        )
        if deterministic_empty_barrier:
            failed_stage = workflow_stages[-1] if workflow_stages else {}
            failed_stage_index = _safe_int(
                failed_stage.get("stage"),
                len(workflow_stages),
            )
            failed_stage_kind = str(
                failed_stage.get("kind") or "general"
            )
            retained_usable_reports = [
                result
                for stage in workflow_stages[:-1]
                for result in list(stage.get("results") or [])
                if isinstance(result, dict)
                and bool(result.get("ok"))
                and bool(str(result.get("finalText") or "").strip())
            ]
            self.bus.bridge_event(run_id, {
                "type": "dynamic_workflow_synthesis_skipped",
                "stages": len(workflow_stages),
                "plannedStages": planned_stages,
                "maxStages": max_stages,
                "totalAgents": total_agents,
                "terminalAction": terminal_decision.action,
                "reason": terminal_decision.reason,
                "reasonCode": terminal_reason_code,
                "failedStage": failed_stage_index,
                "failedStageKind": failed_stage_kind,
                "retainedUsableReportCount": len(retained_usable_reports),
                **parent_event,
                "candidateOnly": True,
                "canClaimAGI": False,
            })
            excluded = [
                {
                    "name": str(result.get("name") or result.get("taskId") or ""),
                    "status": str(result.get("status") or "failed"),
                    "reasonCode": str(
                        result.get("reasonCode")
                        or "worker_failed"
                    ),
                    "error": _safe_diagnostic_text(
                        result.get("error")
                        or result.get("modelError")
                        or "",
                        limit=800,
                    ),
                }
                for result in list(failed_stage.get("results") or [])
                if isinstance(result, dict)
            ]
            rendered_exclusions = "\n".join(
                f"- {item['name'] or 'worker'}: {item['status']} "
                f"({item['reasonCode']})"
                f"{f': {item['error']}' if item['error'] else ''}"
                for item in excluded
            ) or "- no worker result receipt was available"
            retained_summary = (
                f"{len(retained_usable_reports)} usable report"
                f"{'' if len(retained_usable_reports) == 1 else 's'} from "
                f"{max(0, len(workflow_stages) - 1)} earlier stage"
                f"{'' if len(workflow_stages) == 2 else 's'}"
                if retained_usable_reports
                else "no usable reports from earlier stages"
            )
            final_text = (
                f"Dynamic workflow stopped because required stage "
                f"{failed_stage_index} ({failed_stage_kind}) returned no usable "
                "worker reports. Main review and synthesis were skipped so "
                "another provider call could not hide the latest-stage worker "
                "failures.\n\n"
                f"Retained prior evidence: {retained_summary}. It was not "
                "presented as a completed answer because the required barrier "
                "did not finish.\n\n"
                "Failed or excluded latest-stage receipts:\n"
                f"{rendered_exclusions}\n\n"
                "candidateOnly: true; canClaimAGI: false."
            )
            final_result = AgentLoopResult(
                goal=prompt,
                final_text=final_text,
                ok=False,
                messages=[{"role": "assistant", "content": final_text}],
                model_error=terminal_decision.reason,
            )
        else:
            final_prompt = workflow_final_synthesis_prompt(
                original_goal=prompt,
                stage_ledger=workflow_stages,
                final_decision=terminal_decision,
            )
            publish_orchestration(
                orchestration.upsert_task(
                    task_id=final_task_id,
                    subject="Final workflow synthesis",
                    description=(
                        "Synthesize only verified stage evidence into the "
                        "single operator-facing answer."
                    ),
                    state="queued",
                    owner_id="workflow-main",
                    blocked_by=[
                        str(item.get("taskId") or "")
                        for stage in workflow_stages
                        for item in list(stage.get("results") or [])
                        if str(item.get("taskId") or "")
                    ],
                    done_criteria=(
                        "Separate received, excluded, disputed, and unresolved evidence.",
                        "State the bounded recommendation without unsupported claims.",
                    ),
                    expected_output="Operator answer with WORKFLOW_LOG.",
                )
            )
            self.bus.bridge_event(run_id, {
                "type": "dynamic_workflow_synthesis_start",
                "stages": len(workflow_stages),
                "plannedStages": planned_stages,
                "maxStages": max_stages,
                "totalAgents": total_agents,
                "terminalAction": terminal_decision.action,
                "workflowChart": chart_manifest,
                **parent_event,
                "canClaimAGI": False,
            })
            handle["dynamicWorkflowResult"] = {
                "status": "synthesizing",
                "configuredMode": configured_mode,
                "pattern": terminal_decision.pattern,
                "reason": terminal_decision.reason,
                "reasonCode": (
                    terminal_decision.reason_code or terminal_reason_code
                ),
                "requestedInput": terminal_decision.requested_input,
                "stages": len(workflow_stages),
                "plannedStages": planned_stages,
                "maxStages": max_stages,
                "totalAgents": total_agents,
                "requestedAgents": total_requested_agents,
                "unstartedAgents": total_unstarted_agents,
                "maxTasksPerStage": stage_task_limit,
                "criticBarrier": {
                    "required": critic_barrier_required,
                    "satisfied": critic_barrier_satisfied,
                },
                "workflowChart": chart_manifest,
                "recovery": dict(resume_plan or {}),
                "candidateOnly": True,
                "canClaimAGI": False,
            }
            final_result = run_main_pass(
                final_prompt,
                extra=(system_extra or "").strip(),
                task_id=final_task_id,
                raw_turn=final_prompt,
                final_delivery=not internal_artifact,
            )
        final_text = str(getattr(final_result, "final_text", "") or "").strip()
        final_ok = (
            terminal_decision.action == "finish"
            and bool(getattr(final_result, "ok", False))
            and not str(getattr(final_result, "model_error", "") or "")
            and bool(final_text)
        )
        if terminal_decision.action == "awaiting_input":
            terminal_reason_code = "awaiting_input"
        elif terminal_decision.action == "fail":
            terminal_reason_code = (
                terminal_decision.reason_code
                or terminal_reason_code
                or "workflow_failed"
            )
        elif not final_ok:
            if bool(getattr(final_result, "gated", False)):
                terminal_reason_code = "delivery_gate_blocked"
            else:
                terminal_reason_code = (
                    terminal_decision.reason_code
                    or terminal_reason_code
                    or "final_synthesis_failed"
                )
        else:
            terminal_reason_code = "verified"
        workflow_status = (
            "succeeded"
            if final_ok
            else (
                "awaiting_input"
                if terminal_decision.action == "awaiting_input"
                else "failed"
            )
        )
        handle["dynamicWorkflowResult"] = {
            "status": workflow_status,
            "configuredMode": configured_mode,
            "pattern": terminal_decision.pattern,
            "reason": terminal_decision.reason,
            "reasonCode": terminal_reason_code,
            "requestedInput": terminal_decision.requested_input,
            "stages": len(workflow_stages),
            "plannedStages": planned_stages,
            "maxStages": max_stages,
            "totalAgents": total_agents,
            "requestedAgents": total_requested_agents,
            "unstartedAgents": total_unstarted_agents,
            "maxTasksPerStage": stage_task_limit,
            "criticBarrier": {
                "required": critic_barrier_required,
                "satisfied": critic_barrier_satisfied,
            },
            "workflowChart": chart_manifest,
            "recovery": dict(resume_plan or {}),
            "deliveryGate": {
                "gated": bool(getattr(final_result, "gated", False)),
                "epistemic": dict(
                    getattr(final_result, "epistemic", None) or {}
                ),
            },
            "candidateOnly": True,
            "canClaimAGI": False,
        }
        if not final_text:
            final_text = (
                "Dynamic workflow did not produce a delivery-gated final "
                "synthesis. Internal stage artifacts remain in the run trace."
            )
        publish_orchestration(
            orchestration.append_message(
                kind="coordinator",
                sender="Main Workflow Controller",
                recipient="operator",
                summary=f"Workflow {workflow_status}",
                body=final_text,
                task_id=final_task_id,
                trusted=True,
            )
        )
        self.bus.bridge_event(run_id, {
            "type": "dynamic_workflow_end",
            "selected": True,
            "status": (
                workflow_status
            ),
            "reason": terminal_decision.reason,
            "reasonCode": terminal_reason_code,
            "pattern": terminal_decision.pattern,
            "stages": len(workflow_stages),
            "plannedStages": planned_stages,
            "maxStages": max_stages,
            "totalAgents": total_agents,
            "requestedAgents": total_requested_agents,
            "unstartedAgents": total_unstarted_agents,
            "maxTasksPerStage": stage_task_limit,
            "criticBarrier": {
                "required": critic_barrier_required,
                "satisfied": critic_barrier_satisfied,
            },
            "workflowChart": chart_manifest,
            "orchestration": orchestration.snapshot(),
            **parent_event,
            "candidateOnly": True,
            "canClaimAGI": False,
        })
        final_result.goal = prompt
        final_result.final_text = final_text
        final_result.ok = final_ok
        final_result.steps = all_steps
        final_result.messages = list(history or [])
        user_turn = raw_prompt or prompt
        if not (
            final_result.messages
            and final_result.messages[-1].get("role") == "user"
            and final_result.messages[-1].get("content") == user_turn
        ):
            final_result.messages.append({"role": "user", "content": user_turn})
        final_result.messages.append({
            "role": "assistant",
            "content": final_text,
        })
        if not final_ok:
            final_result.model_error = (
                str(getattr(final_result, "model_error", "") or "")
                or terminal_decision.reason
                or f"workflow ended with action {terminal_decision.action}"
            )
        if terminal_decision.action == "awaiting_input":
            final_result.incomplete = True
            final_result.incomplete_reason = (
                terminal_decision.requested_input
                or terminal_decision.reason
                or "workflow requires operator input"
            )
        return final_result

    def _run_dynamic_workflow_stage(
        self,
        handle: dict,
        *,
        original_goal: str,
        stage_index: int,
        pattern: str,
        stage_kind: str,
        stage_goal: str,
        assignments: list[Any],
        main_context: str,
        system_extra: str,
        model_alias: str,
        mode: str,
        permission: str,
        session: str,
        workspace: Path,
        max_steps: int,
        show_thinking: bool,
        response_style: ResponseStyle,
        execution: str,
        terminal_layout: str,
        budget: ExecutionBudget,
        cancel: threading.Event,
        task_contexts: list[str] | None = None,
        task_contracts: list[dict[str, Any]] | None = None,
        completion_criteria: list[str] | None = None,
        requires_critics: bool = False,
        orchestration: Any = None,
        publish_orchestration: Callable[[dict[str, Any] | None], None] | None = None,
        workflow_id: str = "",
        parent_mode: str = "",
        parent_node_id: str = "",
        parent_phase: str = "",
        provider_concurrency_cap: int | None = None,
        concurrency_reason: str | None = None,
        controller_requested_task_count: int | None = None,
        deferred_task_count: int = 0,
        planned_stages: int | None = None,
        conscience_mode: str | None = None,
        dispatch_manifest: Any = None,
        worker_model_authority: str = "",
    ) -> dict[str, Any]:
        """Submit and barrier-wait one dependency-independent workflow stage."""
        from agent.a2a_handoff import build_sub_agent_prompt
        from agent.agent_tools import all_tools
        from agent.a2a_orchestration import (
            A2AOrchestrationLedger,
            overlay_stage_results_from_receipts,
            should_persist_orchestration,
        )
        from agent.context_manager import estimate_tokens
        from agent.dynamic_workflow import (
            workflow_result_evidence_gaps,
            workflow_stage_packet_complete,
            workflow_task_coverage_keys,
            worker_report_status,
        )
        from agent.session_supervisor import (
            SessionSupervisorClient,
            _atomic_json as _write_supervised_json,
        )
        from agent.worker_reuse import (
            CompatibilityFingerprint,
            LeaseState,
            LogicalAgentIdentity,
            ReuseDecision,
            ReusePolicyConfig,
            ReuseRequest,
            RuntimeState,
            WorkerLease,
            WorkerRuntime,
            decide_worker_reuse,
            eviction_event_payload,
            select_lru_evictions,
        )

        run_id = handle["id"]
        worker_conscience_mode = _normalize_conscience_mode(
            conscience_mode
            if conscience_mode is not None
            else CODE_DEFAULTS["conscienceMode"]
        )
        task_contracts = list(task_contracts or [])
        task_contexts = list(task_contexts or [])
        completion_criteria = list(completion_criteria or [])

        def contract_at(index: int) -> Mapping[str, Any]:
            """Return a safe contract view for every assignment path."""
            if 0 <= index < len(task_contracts):
                value = task_contracts[index]
                if isinstance(value, Mapping):
                    return value
            return {}

        if orchestration is None:
            orchestration = A2AOrchestrationLedger(
                session=session,
                run_id=run_id,
                mode="workflow",
                persist=should_persist_orchestration(
                    session=session,
                    run_id=run_id,
                    persist_flag=handle.get("persistOrchestration"),
                ),
                state_dir=workspace,
            )
        if publish_orchestration is None:
            publish_orchestration = lambda _snapshot=None: None
        if dispatch_manifest is None:
            dispatch_manifest = self._ensure_dispatch_manifest(
                handle,
                session=session,
                mode="workflow",
            )
        parent_scope = getattr(handle.get("_ctx"), "allowed_tools", None)
        stage_parent_scope = (
            set(all_tools()) if parent_scope is None else set(parent_scope)
        )
        stage_parent_scope.discard("delegate")
        if str(permission or "").lower() == "readonly":
            stage_parent_scope.intersection_update(
                _READ_ONLY_REPOSITORY_REVIEW_TOOLS
            )
        assignment_scopes = [
            set(assignment.allowed_tools) & stage_parent_scope
            for assignment in assignments
        ]
        dispatch_manifest.set_status(
            "dispatching",
            phase="dispatching",
            source="workflow",
            main_status="dispatching",
        )
        self._publish_dispatch_manifest(handle)
        client = SessionSupervisorClient()
        hello = client.ensure_running()
        workflow_id = workflow_id or run_id
        parent_event = {
            "parentMode": parent_mode,
            "parentNodeId": parent_node_id,
            "parentPhase": parent_phase,
            "workflowId": workflow_id,
        }
        planned_stage_count = max(
            stage_index,
            _safe_int(planned_stages, stage_index),
        )
        supervisor_run_id = (
            f"{workflow_id}-workflow-s{stage_index}-{uuid.uuid4().hex[:8]}"
        )
        task_ids: list[str] = []
        submitted_tasks: list[dict[str, Any]] = []
        agents: list[dict[str, Any]] = []
        reuse_meta_by_task: dict[str, dict[str, Any]] = {}
        reserved_lease_ids: set[str] = set()
        warm_leases: list[WorkerLease] = list(
            handle.setdefault("_workflowWorkerLeases", [])
        )
        def _reuse_env_float(name: str, default: float) -> float:
            try:
                value = float(os.environ.get(name, str(default)))
            except (TypeError, ValueError, OverflowError):
                return default
            return value if math.isfinite(value) else default

        def _reuse_env_int(name: str, default: int) -> int:
            try:
                return int(os.environ.get(name, str(default)))
            except (TypeError, ValueError, OverflowError):
                return default

        reuse_config = ReusePolicyConfig(
            ttl_seconds=max(
                30.0,
                _reuse_env_float("SOPHIA_WORKFLOW_WORKER_TTL_SEC", 180.0),
            ),
            max_warm_per_workflow=max(
                0,
                _reuse_env_int("SOPHIA_WORKFLOW_MAX_WARM_WORKERS", 2),
            ),
            max_warm_per_provider=max(
                0,
                _reuse_env_int("SOPHIA_WORKFLOW_MAX_WARM_PER_PROVIDER", 2),
            ),
            max_reuses=max(
                0,
                _reuse_env_int("SOPHIA_WORKFLOW_MAX_WORKER_REUSES", 2),
            ),
            max_context_fraction=min(
                1.0,
                max(
                    0.1,
                    _reuse_env_float(
                        "SOPHIA_WORKFLOW_MAX_CONTEXT_FRACTION",
                        0.65,
                    ),
                ),
            ),
        )
        workspace_revision = str(
            dict(handle.get("runtimeSource") or {}).get(
                "workspaceSourceSha256"
            )
            or dict(handle.get("runtimeSource") or {}).get(
                "runtimeSourceSha256"
            )
            or f"workflow-run:{run_id}"
        )
        try:
            context_window_tokens = max(
                1,
                int(handle.get("resolvedContextWindow") or 128_000),
            )
        except (TypeError, ValueError):
            context_window_tokens = 128_000

        from agent import model as model_module
        from agent.model import (
            GROK_CLI_WORKER_READ_ONLY_COMPATIBLE_TOOLS,
            grok_cli_worker_unavailable_tools,
        )

        provider_kind = ""
        workflow_cfg = None
        try:
            workflow_cfg = model_module.resolve_config(
                _model_spec(model_alias)
            )
            provider_kind = str(workflow_cfg.kind or "")
        except Exception:  # noqa: BLE001 - worker routing fails closed below
            provider_kind = ""
        controller_provider = str(
            getattr(workflow_cfg, "label", "")
            or provider_kind
            or _model_spec(model_alias).partition(":")[0]
        )
        controller_model = str(
            getattr(workflow_cfg, "model", "")
            or model_alias
        )
        dispatch_manifest.set_main_agent_runtime(
            provider=controller_provider,
            model=controller_model,
        )
        self._publish_dispatch_manifest(handle)

        authority_text = worker_model_authority or original_goal
        worker_routes: list[dict[str, Any]] = []
        for index, assignment in enumerate(assignments):
            contract = contract_at(index)
            explicit_worker_model = " ".join(
                str(contract.get("workerModel") or "").split()
            )[:180]
            requested_worker_model = explicit_worker_model or model_alias
            routing_source = (
                "task_contract_explicit"
                if explicit_worker_model
                else "controller_inherited"
            )
            resolved_provider = ""
            resolved_model = ""
            resolved_kind = ""
            route_error_code = ""
            route_error = ""
            try:
                worker_cfg = model_module.resolve_config(
                    _model_spec(requested_worker_model)
                )
                resolved_kind = str(worker_cfg.kind or "")
                resolved_provider = str(
                    getattr(worker_cfg, "label", "")
                    or resolved_kind
                    or _model_spec(requested_worker_model).partition(":")[0]
                )
                resolved_model = str(
                    getattr(worker_cfg, "model", "")
                    or requested_worker_model
                )
            except Exception as exc:  # noqa: BLE001 - fail-closed route contract
                route_error_code = "worker_model_unavailable"
                route_error = (
                    f"worker model {requested_worker_model!r} could not be "
                    f"resolved: {type(exc).__name__}: {exc}"
                )
            if (
                not route_error_code
                and explicit_worker_model
                and explicit_worker_model.casefold()
                != str(model_alias or "").strip().casefold()
                and not _workflow_worker_model_authorized(
                    authority_text,
                    explicit_worker_model,
                )
            ):
                route_error_code = "worker_model_unauthorized"
                route_error = (
                    f"cross-provider worker model {explicit_worker_model!r} "
                    "was not explicitly named in the operator request"
                )
            expected = (
                contract.get("expectedEvidence")
                if isinstance(contract.get("expectedEvidence"), dict)
                else {}
            )
            harness_owned_tools = (
                ("bash",)
                if expected.get("requiresNamedTestExitCode")
                else ()
            )
            unavailable_tools: tuple[str, ...] = ()
            if not route_error_code and resolved_kind == "grok":
                if assignment.tool_scope_via == "default_read_only":
                    assignment_scopes[index] = (
                        set(GROK_CLI_WORKER_READ_ONLY_COMPATIBLE_TOOLS)
                        & stage_parent_scope
                    )
                unavailable_tools = grok_cli_worker_unavailable_tools(
                    tuple(assignment_scopes[index]),
                    harness_owned_tools=harness_owned_tools,
                )
                if unavailable_tools:
                    route_error_code = "worker_tool_scope_unavailable"
                    route_error = (
                        "Grok CLI workflow workers are read-only provider "
                        "inspectors; unavailable native tool scope: "
                        + ", ".join(unavailable_tools)
                    )
            worker_routes.append({
                "requestedModel": requested_worker_model,
                "resolvedProvider": resolved_provider,
                "resolvedModel": resolved_model,
                "providerKind": resolved_kind,
                "routingSource": routing_source,
                "providerToolMode": (
                    "read_only_cli"
                    if resolved_kind == "grok"
                    else "sophia_native_tools"
                ),
                "unavailableTools": unavailable_tools,
                "errorCode": route_error_code,
                "error": route_error,
            })

        valid_route_caps: list[tuple[int, str]] = []
        if all(not route.get("errorCode") for route in worker_routes):
            for route in worker_routes:
                valid_route_caps.append(
                    _workflow_provider_concurrency(
                        str(route.get("requestedModel") or model_alias),
                        budget=budget,
                    )
                )
        if valid_route_caps:
            provider_concurrency_cap = min(
                cap for cap, _reason in valid_route_caps
            )
            route_reasons = list(dict.fromkeys(
                reason for _cap, reason in valid_route_caps
            ))
            concurrency_reason = (
                route_reasons[0]
                if len(route_reasons) == 1
                and all(
                    route.get("routingSource") == "controller_inherited"
                    for route in worker_routes
                )
                else "worker-route concurrency: " + "; ".join(route_reasons)
            )
        elif provider_concurrency_cap is None:
            provider_concurrency_cap, resolved_reason = (
                _workflow_provider_concurrency(model_alias, budget=budget)
            )
            concurrency_reason = concurrency_reason or resolved_reason
        provider_concurrency_cap = max(1, int(provider_concurrency_cap or 1))
        concurrency_reason = (
            concurrency_reason
            or (
                "provider classification unavailable"
                if not provider_kind
                else "provider concurrency cap"
            )
        )
        configured_concurrency = max(
            1,
            min(provider_concurrency_cap, len(assignments)),
        )
        if budget.max_concurrency is not None:
            configured_concurrency = max(
                1,
                min(configured_concurrency, int(budget.max_concurrency)),
            )

        route_failure_codes = list(dict.fromkeys(
            str(route.get("errorCode") or "")
            for route in worker_routes
            if route.get("errorCode")
        ))
        if route_failure_codes:
            reason = "; ".join(
                str(route.get("error") or "")
                for route in worker_routes
                if route.get("error")
            )
            preflight_agents: list[dict[str, Any]] = []
            preflight_results: list[dict[str, Any]] = []
            for index, assignment in enumerate(assignments, start=1):
                route = worker_routes[index - 1]
                name = f"Stage {stage_index} · Sub Agent {index}"
                task_id = f"{supervisor_run_id}-capability-sub-{index}"
                agent_id = (
                    f"{_normalize_session(workflow_id)}"
                    f"-s{stage_index}-sub-{index}"
                )
                row_error_code = str(route.get("errorCode") or "")
                row_status = "failed" if row_error_code else "skipped"
                row_reason_code = row_error_code or "barrier_not_started"
                row_reason = (
                    str(route.get("error") or "")
                    if row_error_code
                    else (
                        "not started because another assignment in the same "
                        "all-of barrier failed worker route validation"
                    )
                )
                unavailable = list(route.get("unavailableTools") or [])
                dispatch_manifest.register_assignment(
                    assignment_id=task_id,
                    agent_id=agent_id,
                    task_id=task_id,
                    name=name,
                    task=assignment.task,
                    phase="dispatching",
                    status=row_status,
                    persona_id=assignment.persona_id,
                    persona_name=assignment.persona_name,
                    persona_discipline=assignment.persona_discipline,
                    persona_via=assignment.persona_via,
                    skills=assignment.skill_names,
                    skill_via=assignment.skill_via,
                    allowed_tools=assignment_scopes[index - 1],
                    tool_scope_via=assignment.tool_scope_via,
                    permission=permission,
                    execution=execution,
                    provider=str(route.get("resolvedProvider") or ""),
                    model=str(route.get("resolvedModel") or ""),
                    stage=stage_index,
                    coverage_keys=workflow_task_coverage_keys(
                        contract_at(index - 1)
                    ),
                    chart_node_id=str(contract_at(index - 1).get("chartNodeId") or ""),
                    source="dynamic_workflow",
                    provider_tool_mode=str(
                        route.get("providerToolMode") or ""
                    ),
                    unavailable_tools=unavailable,
                    requested_worker_model=str(
                        route.get("requestedModel") or ""
                    ),
                    resolved_worker_provider=str(
                        route.get("resolvedProvider") or ""
                    ),
                    resolved_worker_model=str(
                        route.get("resolvedModel") or ""
                    ),
                    routing_source=str(route.get("routingSource") or ""),
                    started=False,
                    reason_code=row_reason_code,
                )
                publish_orchestration(
                    orchestration.upsert_agent(
                        agent_id=agent_id,
                        name=name,
                        status=row_status,
                        source="local",
                        protocol="claude-native",
                        role=assignment.persona_id or "worker",
                        skills=list(assignment.skill_names),
                        capabilities={
                            "streaming": True,
                            "recursiveDelegation": False,
                            "workflowStage": stage_index,
                            "providerToolMode": str(
                                route.get("providerToolMode") or ""
                            ),
                            "requestedWorkerModel": str(
                                route.get("requestedModel") or ""
                            ),
                            "resolvedWorkerProvider": str(
                                route.get("resolvedProvider") or ""
                            ),
                            "resolvedWorkerModel": str(
                                route.get("resolvedModel") or ""
                            ),
                        },
                        connected=True,
                        current_task_id="",
                        summary=row_reason,
                    )
                )
                publish_orchestration(
                    orchestration.upsert_task(
                        task_id=task_id,
                        subject=name,
                        description=assignment.task,
                        state=row_status,
                        owner_id=agent_id,
                        summary=row_reason,
                        stage=stage_index,
                    )
                )
                route_payload = {
                    "requestedWorkerModel": str(
                        route.get("requestedModel") or ""
                    ),
                    "resolvedWorkerProvider": str(
                        route.get("resolvedProvider") or ""
                    ),
                    "resolvedWorkerModel": str(
                        route.get("resolvedModel") or ""
                    ),
                    "routingSource": str(route.get("routingSource") or ""),
                    "providerToolMode": str(
                        route.get("providerToolMode") or ""
                    ),
                }
                agent = {
                    "agentId": agent_id,
                    "taskId": task_id,
                    "name": name,
                    "index": index - 1,
                    "stage": stage_index,
                    "pattern": pattern,
                    "kind": stage_kind,
                    "status": row_status,
                    "active": False,
                    "role": "sub",
                    "persona": assignment.persona_id,
                    "skills": list(assignment.skill_names),
                    "skillVia": list(assignment.skill_via),
                    "allowedTools": sorted(
                        assignment_scopes[index - 1]
                    ),
                    "toolScopeVia": assignment.tool_scope_via,
                    **route_payload,
                    "unavailableTools": unavailable,
                    "chartNodeId": str(
                        contract_at(index - 1).get("chartNodeId") or ""
                    ),
                    "chartNodeKind": str(
                        contract_at(index - 1).get("chartNodeKind") or ""
                    ),
                    "chartDependencies": list(
                        contract_at(index - 1).get("chartDependencies") or []
                    ),
                    "summary": row_reason,
                    "started": False,
                    "reasonCode": row_reason_code,
                    "error": row_reason,
                }
                preflight_agents.append(agent)
                preflight_results.append({
                    "taskId": task_id,
                    "name": name,
                    "stage": stage_index,
                    "pattern": pattern,
                    "role": assignment.persona_id or "sub",
                    "skills": list(assignment.skill_names),
                    "allowedTools": sorted(
                        assignment_scopes[index - 1]
                    ),
                    "toolScopeVia": assignment.tool_scope_via,
                    **route_payload,
                    "unavailableTools": unavailable,
                    "status": row_status,
                    "ok": False,
                    "finalText": "",
                    "modelError": row_reason,
                    "error": row_reason,
                    "steps": [],
                    "provider": str(
                        route.get("resolvedProvider") or ""
                    ),
                    "resolvedModel": str(
                        route.get("resolvedModel") or ""
                    ),
                    "fallbackUsed": False,
                    "supervisorStatus": "not_submitted",
                    "started": False,
                    "reasonCode": row_reason_code,
                    "chartNodeId": str(
                        contract_at(index - 1).get("chartNodeId") or ""
                    ),
                    "chartNodeKind": str(
                        contract_at(index - 1).get("chartNodeKind") or ""
                    ),
                    "chartDependencies": list(
                        contract_at(index - 1).get("chartDependencies") or []
                    ),
                })
            stage_record = {
                "stage": stage_index,
                "plannedStages": planned_stage_count,
                "pattern": pattern,
                "kind": stage_kind,
                "goal": stage_goal,
                "status": "failed",
                "supervisorRunId": "",
                "maxConcurrency": configured_concurrency,
                "providerConcurrencyCap": provider_concurrency_cap,
                "concurrencyReason": concurrency_reason,
                "expectedWaves": math.ceil(
                    len(assignments) / configured_concurrency
                ),
                "hardTimeoutSec": 0.0,
                "requestedAgentCount": len(assignments),
                "startedAgentCount": 0,
                "unstartedAgentCount": len(assignments),
                "timedOutAgentCount": 0,
                "failureCodes": route_failure_codes,
                "agents": preflight_agents,
                "results": preflight_results,
            }
            existing_stages = [
                item
                for item in (handle.get("dynamicWorkflowStages") or [])
                if isinstance(item, dict)
                and int(item.get("stage") or 0) != stage_index
            ]
            existing_stages.append(stage_record)
            existing_stages.sort(
                key=lambda item: int(item.get("stage") or 0)
            )
            handle["dynamicWorkflowStages"] = existing_stages
            handle["dynamicWorkflowAgents"] = [
                agent
                for item in existing_stages
                for agent in list(item.get("agents") or [])
                if isinstance(agent, dict)
            ]
            dispatch_manifest.set_status(
                "failed",
                phase="worker",
                main_status="verifying",
            )
            self._publish_dispatch_manifest(handle)
            self.bus.bridge_event(run_id, {
                "type": "dynamic_workflow_stage_end",
                "stage": stage_index,
                "plannedStages": planned_stage_count,
                "pattern": pattern,
                "kind": stage_kind,
                "goal": stage_goal,
                "ok": False,
                "succeeded": 0,
                "failed": len(assignments),
                "requestedAgentCount": len(assignments),
                "startedAgentCount": 0,
                "unstartedAgentCount": len(assignments),
                "failureCodes": route_failure_codes,
                "reason": reason,
                "agents": preflight_agents,
                **parent_event,
                "orchestration": orchestration.snapshot(),
                "candidateOnly": True,
                "canClaimAGI": False,
            })
            return stage_record

        grok_worker_routes = [
            route
            for route in worker_routes
            if route.get("providerKind") == "grok"
        ]
        if grok_worker_routes and len(assignments) > 1:
            from agent.model import grok_preflight_timeout_sec
            from agent.provider_health import probe_provider

            grok_probe_model = str(
                grok_worker_routes[0].get("requestedModel") or model_alias
            )
            provider_health = probe_provider(
                _model_spec(grok_probe_model),
                include_models=True,
                allow_remote_metadata=False,
                # Keep this aligned with the transport's bounded no-spend
                # preflight. On a healthy local Grok CLI the models probe is
                # commonly close to 1.5s, so using that value as the hard
                # deadline creates avoidable false negatives under normal
                # scheduler jitter.
                timeout=grok_preflight_timeout_sec(),
            )
            health_payload = _redact_diagnostic_value(
                provider_health.to_dict()
            )
            self.bus.bridge_event(run_id, {
                "type": "dynamic_workflow_provider_preflight",
                "stage": stage_index,
                "provider": provider_health.provider or "grok",
                "model": provider_health.model or grok_probe_model,
                "ok": bool(provider_health.ok),
                "state": provider_health.state.value,
                "health": health_payload,
                "noSpend": True,
                **parent_event,
                "candidateOnly": True,
                "canClaimAGI": False,
            })
            if not provider_health.ok:
                failed_checks = [
                    check
                    for check in provider_health.checks
                    if check.required and not check.ok
                ]
                reason = _safe_diagnostic_text(
                    (
                        provider_health.error.message
                        if provider_health.error is not None
                        else "; ".join(
                            check.detail for check in failed_checks
                        )
                    )
                    or "required Grok provider health is unavailable",
                    limit=800,
                )
                preflight_agents: list[dict[str, Any]] = []
                preflight_results: list[dict[str, Any]] = []
                for index, assignment in enumerate(assignments, start=1):
                    route = worker_routes[index - 1]
                    name = f"Stage {stage_index} · Sub Agent {index}"
                    task_id = (
                        f"{supervisor_run_id}-preflight-sub-{index}"
                    )
                    agent_id = (
                        f"{_normalize_session(workflow_id)}"
                        f"-s{stage_index}-sub-{index}"
                    )
                    dispatch_manifest.register_assignment(
                        assignment_id=task_id,
                        agent_id=agent_id,
                        task_id=task_id,
                        name=name,
                        task=assignment.task,
                        phase="dispatching",
                        status="skipped",
                        persona_id=assignment.persona_id,
                        persona_name=assignment.persona_name,
                        persona_discipline=assignment.persona_discipline,
                        persona_via=assignment.persona_via,
                        skills=assignment.skill_names,
                        skill_via=assignment.skill_via,
                        allowed_tools=assignment_scopes[index - 1],
                        tool_scope_via=assignment.tool_scope_via,
                        permission=permission,
                        execution=execution,
                        provider=str(route.get("resolvedProvider") or ""),
                        model=str(route.get("resolvedModel") or ""),
                        stage=stage_index,
                        coverage_keys=workflow_task_coverage_keys(
                            contract_at(index - 1)
                        ),
                        chart_node_id=str(
                            contract_at(index - 1).get("chartNodeId") or ""
                        ),
                        source="dynamic_workflow",
                        provider_tool_mode=str(
                            route.get("providerToolMode") or ""
                        ),
                        requested_worker_model=str(
                            route.get("requestedModel") or ""
                        ),
                        resolved_worker_provider=str(
                            route.get("resolvedProvider") or ""
                        ),
                        resolved_worker_model=str(
                            route.get("resolvedModel") or ""
                        ),
                        routing_source=str(
                            route.get("routingSource") or ""
                        ),
                        started=False,
                        reason_code="provider_preflight_unavailable",
                    )
                    publish_orchestration(
                        orchestration.upsert_agent(
                            agent_id=agent_id,
                            name=name,
                            status="skipped",
                            source="local",
                            protocol="claude-native",
                            role=assignment.persona_id or "worker",
                            skills=list(assignment.skill_names),
                            capabilities={
                                "streaming": True,
                                "recursiveDelegation": False,
                                "workflowStage": stage_index,
                                "providerToolMode": str(
                                    route.get("providerToolMode") or ""
                                ),
                                "requestedWorkerModel": str(
                                    route.get("requestedModel") or ""
                                ),
                                "resolvedWorkerProvider": str(
                                    route.get("resolvedProvider") or ""
                                ),
                                "resolvedWorkerModel": str(
                                    route.get("resolvedModel") or ""
                                ),
                            },
                            connected=True,
                            current_task_id="",
                            summary=reason,
                        )
                    )
                    publish_orchestration(
                        orchestration.upsert_task(
                            task_id=task_id,
                            subject=name,
                            description=assignment.task,
                            state="skipped",
                            owner_id=agent_id,
                            summary=reason,
                            stage=stage_index,
                        )
                    )
                    agent = {
                        "agentId": agent_id,
                        "taskId": task_id,
                        "name": name,
                        "index": index - 1,
                        "stage": stage_index,
                        "pattern": pattern,
                        "kind": stage_kind,
                        "status": "skipped",
                        "active": False,
                        "role": "sub",
                        "persona": assignment.persona_id,
                        "skills": list(assignment.skill_names),
                        "skillVia": list(assignment.skill_via),
                        "allowedTools": sorted(assignment_scopes[index - 1]),
                        "toolScopeVia": assignment.tool_scope_via,
                        "requestedWorkerModel": str(
                            route.get("requestedModel") or ""
                        ),
                        "resolvedWorkerProvider": str(
                            route.get("resolvedProvider") or ""
                        ),
                        "resolvedWorkerModel": str(
                            route.get("resolvedModel") or ""
                        ),
                        "routingSource": str(
                            route.get("routingSource") or ""
                        ),
                        "providerToolMode": str(
                            route.get("providerToolMode") or ""
                        ),
                        "chartNodeId": str(
                            contract_at(index - 1).get("chartNodeId") or ""
                        ),
                        "chartNodeKind": str(
                            contract_at(index - 1).get("chartNodeKind") or ""
                        ),
                        "chartDependencies": list(
                            contract_at(index - 1).get("chartDependencies")
                            or []
                        ),
                        "summary": reason,
                        "started": False,
                        "reasonCode": "provider_preflight_unavailable",
                        "error": reason,
                    }
                    preflight_agents.append(agent)
                    preflight_results.append({
                        "taskId": task_id,
                        "name": name,
                        "stage": stage_index,
                        "pattern": pattern,
                        "role": assignment.persona_id or "sub",
                        "skills": list(assignment.skill_names),
                        "allowedTools": sorted(assignment_scopes[index - 1]),
                        "toolScopeVia": assignment.tool_scope_via,
                        "requestedWorkerModel": str(
                            route.get("requestedModel") or ""
                        ),
                        "resolvedWorkerProvider": str(
                            route.get("resolvedProvider") or ""
                        ),
                        "resolvedWorkerModel": str(
                            route.get("resolvedModel") or ""
                        ),
                        "routingSource": str(
                            route.get("routingSource") or ""
                        ),
                        "providerToolMode": str(
                            route.get("providerToolMode") or ""
                        ),
                        "status": "skipped",
                        "ok": False,
                        "finalText": "",
                        "modelError": reason,
                        "error": reason,
                        "steps": [],
                        "provider": str(
                            route.get("resolvedProvider") or ""
                        ),
                        "resolvedModel": str(
                            route.get("resolvedModel") or ""
                        ),
                        "fallbackUsed": False,
                        "supervisorStatus": "not_submitted",
                        "started": False,
                        "reasonCode": "provider_preflight_unavailable",
                        "chartNodeId": str(
                            contract_at(index - 1).get("chartNodeId") or ""
                        ),
                        "chartNodeKind": str(
                            contract_at(index - 1).get("chartNodeKind") or ""
                        ),
                        "chartDependencies": list(
                            contract_at(index - 1).get("chartDependencies")
                            or []
                        ),
                    })
                stage_record = {
                    "stage": stage_index,
                    "plannedStages": planned_stage_count,
                    "pattern": pattern,
                    "kind": stage_kind,
                    "goal": stage_goal,
                    "status": "failed",
                    "supervisorRunId": "",
                    "maxConcurrency": configured_concurrency,
                    "providerConcurrencyCap": provider_concurrency_cap,
                    "concurrencyReason": concurrency_reason,
                    "expectedWaves": math.ceil(
                        len(assignments) / configured_concurrency
                    ),
                    "hardTimeoutSec": 0.0,
                    "requestedAgentCount": len(assignments),
                    "startedAgentCount": 0,
                    "unstartedAgentCount": len(assignments),
                    "timedOutAgentCount": 0,
                    "failureCodes": ["provider_preflight_unavailable"],
                    "providerPreflight": health_payload,
                    "agents": preflight_agents,
                    "results": preflight_results,
                }
                existing_stages = [
                    item
                    for item in (handle.get("dynamicWorkflowStages") or [])
                    if isinstance(item, dict)
                    and int(item.get("stage") or 0) != stage_index
                ]
                existing_stages.append(stage_record)
                existing_stages.sort(
                    key=lambda item: int(item.get("stage") or 0)
                )
                handle["dynamicWorkflowStages"] = existing_stages
                handle["dynamicWorkflowAgents"] = [
                    agent
                    for item in existing_stages
                    for agent in list(item.get("agents") or [])
                    if isinstance(agent, dict)
                ]
                self.bus.bridge_event(run_id, {
                    "type": "dynamic_workflow_stage_end",
                    "stage": stage_index,
                    "plannedStages": planned_stage_count,
                    "pattern": pattern,
                    "kind": stage_kind,
                    "goal": stage_goal,
                    "ok": False,
                    "succeeded": 0,
                    "failed": len(assignments),
                    "requestedAgentCount": len(assignments),
                    "startedAgentCount": 0,
                    "unstartedAgentCount": len(assignments),
                    "failureCodes": ["provider_preflight_unavailable"],
                    "reason": reason,
                    "providerPreflight": health_payload,
                    "agents": preflight_agents,
                    **parent_event,
                    "orchestration": orchestration.snapshot(),
                    "candidateOnly": True,
                    "canClaimAGI": False,
                })
                self._publish_dispatch_manifest(handle)
                return stage_record
        handle["supervisorRunId"] = supervisor_run_id
        run_root = client.state_dir / "runs" / supervisor_run_id
        run_root.mkdir(parents=True, exist_ok=False, mode=0o700)
        os.chmod(run_root, 0o700)
        for index, assignment in enumerate(assignments, start=1):
            route = worker_routes[index - 1]
            task_id = f"{supervisor_run_id}-sub-{index}"
            task_ids.append(task_id)
            name = f"Stage {stage_index} · Sub Agent {index}"
            worker_scope = assignment_scopes[index - 1]
            contract = contract_at(index - 1)
            done_criteria = [
                str(item).strip()
                for item in list(contract.get("doneCriteria") or [])
                if str(item).strip()
            ]
            done_criteria.extend(
                item
                for item in completion_criteria
                if item not in done_criteria
            )
            expected_output = str(contract.get("expectedOutput") or "").strip()
            coverage_keys = list(workflow_task_coverage_keys(contract))
            retry_of = str(contract.get("retryOf") or "").strip()
            agent_id = (
                f"{_normalize_session(workflow_id)}-s{stage_index}-sub-{index}"
            )
            publish_orchestration(
                orchestration.upsert_agent(
                    agent_id=agent_id,
                    name=name,
                    status="queued",
                    source="local",
                    protocol="claude-native",
                    role=assignment.persona_id or "worker",
                    skills=list(assignment.skill_names),
                    capabilities={
                        "streaming": True,
                        "recursiveDelegation": False,
                        "workflowStage": stage_index,
                        "coverageKeys": coverage_keys,
                        "providerToolMode": str(
                            route.get("providerToolMode") or ""
                        ),
                        "requestedWorkerModel": str(
                            route.get("requestedModel") or ""
                        ),
                        "resolvedWorkerProvider": str(
                            route.get("resolvedProvider") or ""
                        ),
                        "resolvedWorkerModel": str(
                            route.get("resolvedModel") or ""
                        ),
                    },
                    connected=True,
                    current_task_id=task_id,
                    summary=assignment.task,
                )
            )
            publish_orchestration(
                orchestration.upsert_task(
                    task_id=task_id,
                    subject=name,
                    description=assignment.task,
                    state="queued",
                    owner_id=agent_id,
                    done_criteria=done_criteria
                    or (
                        "Complete only the assigned workflow scope.",
                        "Return verifiable evidence for Main review.",
                    ),
                    expected_output=expected_output
                    or "Structured WORKER_REPORT for Main stage review.",
                    stage=stage_index,
                )
            )
            publish_orchestration(
                orchestration.append_message(
                    kind="coordinator",
                    sender="Main Workflow Controller",
                    recipient=name,
                    summary=f"Stage {stage_index} assignment",
                    body=assignment.task,
                    task_id=task_id,
                    trusted=True,
                )
            )
            selected_task_context = (
                task_contexts[index - 1]
                if index - 1 < len(task_contexts)
                else main_context
            )
            worker_main_context = (
                f"Workflow pattern: {pattern}\n"
                f"Stage goal: {stage_goal}\n"
                "Main rationale and prior evidence packet:\n"
                f"{selected_task_context}"
            )
            agent_prompt = build_sub_agent_prompt(
                original_goal=original_goal,
                sub_name=name,
                task=assignment.task,
                sub_index=index,
                total_subs=len(assignments),
                main_context=worker_main_context,
                main_context_max_chars=min(
                    64_000,
                    max(4000, len(worker_main_context)),
                ),
                persona_name=assignment.persona_name,
                persona_id=assignment.persona_id,
                skill_names=list(assignment.skill_names),
                done_criteria=done_criteria,
                expected_output=expected_output,
                allow_subagents=bool(contract.get("allowSubagents", False)),
            )
            worker_extra = (system_extra or "").strip()
            if assignment.system_extra:
                worker_extra = (
                    f"{worker_extra}\n\n{assignment.system_extra}".strip()
                    if worker_extra
                    else assignment.system_extra
                )
            if worker_extra:
                if len(worker_extra) > 6000:
                    worker_extra = (
                        f"{worker_extra[:5999]}…"
                    )
                agent_prompt = (
                    f"{agent_prompt}\n\n"
                    "Additional harness constraints for this worker:\n"
                    f"{worker_extra}"
                )
            fingerprint = CompatibilityFingerprint(
                provider=str(route.get("resolvedProvider") or ""),
                model=str(route.get("resolvedModel") or ""),
                transport=execution,
                role=assignment.persona_id or "worker",
                skills=tuple(assignment.skill_names),
                permission_scope=(permission,),
                tool_scope=tuple(sorted(worker_scope)),
                workspace_root=str(workspace),
                workspace_revision=workspace_revision,
            )
            reuse_key = str(contract.get("reuseKey") or "").strip()
            continuation_of = str(
                contract.get("continuationOf") or ""
            ).strip() or None
            available_leases = [
                lease
                for lease in warm_leases
                if lease.lease_id not in reserved_lease_ids
            ]
            matching_by_predecessor = [
                lease
                for lease in available_leases
                if continuation_of
                and lease.last_task_id == continuation_of
            ]
            if reuse_key:
                logical_agent = LogicalAgentIdentity(
                    workflow_id=workflow_id,
                    agent_id=_normalize_session(reuse_key),
                )
            elif len(matching_by_predecessor) == 1:
                logical_agent = matching_by_predecessor[0].logical_agent
            else:
                # Compatibility alone is not authority to inherit history.
                # Reuse requires an explicit stable key or predecessor task so
                # unrelated refinement/recovery work cannot be silently joined
                # to a prior logical agent merely because its model and tools
                # happen to match.
                logical_agent = LogicalAgentIdentity(
                    workflow_id=workflow_id,
                    agent_id=agent_id,
                )
            reuse_request = ReuseRequest(
                logical_agent=logical_agent,
                task_id=task_id,
                stage_kind=stage_kind,
                fingerprint=fingerprint,
                requested_at=time.time(),
                additional_context_tokens=estimate_tokens(agent_prompt),
                predecessor_task_id=continuation_of,
            )
            if bool(contract.get("freshWorker")):
                reuse_decision = ReuseDecision(
                    allowed=False,
                    reason="operator_forced_fresh",
                )
            else:
                reuse_decision = decide_worker_reuse(
                    reuse_request,
                    available_leases,
                    reuse_config,
                )
            selected_lease = next(
                (
                    lease
                    for lease in warm_leases
                    if lease.lease_id == reuse_decision.lease_id
                ),
                None,
            )
            worker_session = (
                selected_lease.runtime.runtime_id
                if reuse_decision.allowed and selected_lease is not None
                else _normalize_session(
                    f"{session}-wf-{run_id[-8:]}-s{stage_index}-{index}"
                )
            )
            if reuse_decision.allowed and reuse_decision.lease_id:
                reserved_lease_ids.add(reuse_decision.lease_id)
            reuse_payload = reuse_decision.to_event_payload(reuse_request)
            reuse_payload.update(
                {
                    "type": "dynamic_workflow_worker_reuse",
                    "stage": stage_index,
                    "index": index - 1,
                    "workerSession": worker_session,
                    "cacheEligible": bool(reuse_decision.allowed),
                    # The supervised worker remains one-shot. Reusing its
                    # durable session/history can preserve a provider prefix
                    # cache, but the bridge never claims an OS process or KV
                    # cache survived.
                    "processReuse": False,
                }
            )
            self.bus.bridge_event(run_id, reuse_payload)
            if parent_mode == "agi":
                self.bus.bridge_event(run_id, {
                    "type": "agi_workflow_worker_lease",
                    "nodeId": parent_node_id,
                    "phase": parent_phase,
                    "workflowId": workflow_id,
                    "stage": stage_index,
                    "allowed": bool(reuse_decision.allowed),
                    "reuseReason": reuse_decision.reason,
                    "worker": {
                        "agentId": logical_agent.agent_id,
                        "logicalAgentId": logical_agent.agent_id,
                        "workerId": worker_session,
                        "name": name,
                        "role": assignment.persona_id or "worker",
                        "skills": list(assignment.skill_names),
                        "status": "leased",
                        "reuseCount": (
                            selected_lease.reuse_count + 1
                            if reuse_decision.allowed
                            and selected_lease is not None
                            else 0
                        ),
                        "reuseReason": reuse_decision.reason,
                    },
                    "candidateOnly": True,
                    "canClaimAGI": False,
                })
            reuse_meta_by_task[task_id] = {
                "request": reuse_request,
                "decision": reuse_decision,
                "fingerprint": fingerprint,
                "workerSession": worker_session,
                "promptTokens": estimate_tokens(agent_prompt),
            }
            task_root = run_root / task_id
            task_root.mkdir(mode=0o700)
            spec_path = task_root / "worker-spec.json"
            result_path = task_root / "result.json"
            worker_spec = {
                "schema": "sophia.supervised-worker-spec.v1",
                "runId": supervisor_run_id,
                "taskId": task_id,
                "name": name,
                "internalArtifact": True,
                "command": {
                    "prompt": agent_prompt,
                    "model": str(route.get("requestedModel") or model_alias),
                    "mode": mode,
                    "permission": permission,
                    "conscienceMode": worker_conscience_mode,
                    "session": worker_session,
                    "cwd": str(workspace),
                    "maxSteps": max_steps,
                    "allowedTools": sorted(worker_scope),
                    # A workflow specialist's bounded report is complete even
                    # when it truthfully lists unresolved product work. The
                    # ordinary interactive monitor/deploy detector remains on
                    # for non-workflow runs.
                    "continueUnfinishedObjective": False,
                    "semanticFallbackPolicy": "off",
                    "semanticFallbackModel": "",
                    "deepThink": show_thinking,
                    "responseStyle": response_style,
                    "sophiaContract": True,
                    "workflowMode": "off",
                    # A chart owns the parent controller's topology.  A
                    # supervised worker is a single chart-node execution and
                    # must not inherit the parent's selected chart from
                    # persisted defaults while also declaring workflow off.
                    "workflowChartPath": "",
                    "agiMode": False,
                    "agiWorkflowMode": "off",
                },
                "expectedEvidence": dict(contract.get("expectedEvidence") or {}),
                "canClaimAGI": False,
            }
            _write_supervised_json(spec_path, worker_spec)
            dispatch_manifest.register_assignment(
                assignment_id=task_id,
                agent_id=agent_id,
                task_id=task_id,
                name=name,
                task=assignment.task,
                phase="dispatching",
                status="queued",
                persona_id=assignment.persona_id,
                persona_name=assignment.persona_name,
                persona_discipline=assignment.persona_discipline,
                persona_via=assignment.persona_via,
                skills=assignment.skill_names,
                skill_via=assignment.skill_via,
                allowed_tools=worker_scope,
                tool_scope_via=assignment.tool_scope_via,
                permission=permission,
                execution=execution,
                provider=str(route.get("resolvedProvider") or ""),
                model=str(route.get("resolvedModel") or ""),
                stage=stage_index,
                coverage_keys=coverage_keys,
                chart_node_id=str(contract.get("chartNodeId") or ""),
                receipt_path=str(result_path),
                receipt_run_id=supervisor_run_id,
                source="dynamic_workflow",
                worker_session=worker_session,
                logical_agent_id=logical_agent.agent_id,
                reuse_allowed=bool(reuse_decision.allowed),
                reuse_reason=reuse_decision.reason,
                cache_eligible=bool(reuse_decision.allowed),
                process_reuse=False,
                provider_tool_mode=str(
                    route.get("providerToolMode") or ""
                ),
                requested_worker_model=str(
                    route.get("requestedModel") or ""
                ),
                resolved_worker_provider=str(
                    route.get("resolvedProvider") or ""
                ),
                resolved_worker_model=str(
                    route.get("resolvedModel") or ""
                ),
                routing_source=str(route.get("routingSource") or ""),
                started=False,
            )
            self._publish_dispatch_manifest(handle)
            inherited_pythonpath = os.environ.get("PYTHONPATH", "")
            explicit_pythonpath = str(_repo_root())
            if inherited_pythonpath:
                explicit_pythonpath += os.pathsep + inherited_pythonpath
            packaged_worker = os.environ.get(
                "SOPHIA_SESSION_WORKER_EXECUTABLE", ""
            ).strip()
            if packaged_worker:
                worker_executable = Path(packaged_worker).expanduser().resolve()
                if (
                    not worker_executable.is_file()
                    or not os.access(worker_executable, os.X_OK)
                ):
                    raise RuntimeError(
                        "SOPHIA_SESSION_WORKER_EXECUTABLE must name an "
                        "executable regular file"
                    )
                worker_argv = [
                    str(worker_executable),
                    "--spec",
                    str(spec_path),
                    "--result",
                    str(result_path),
                ]
                worker_env = _supervised_worker_env({
                    "SOPHIA_MODEL_FALLBACKS": "",
                    "SOPHIA_MODEL_FALLBACK_POLICY": "never",
                    "SOPHIA_FALLBACK_POLICY": "never",
                    # Permit one bounded in-worker retry for typed transient
                    # provider failures (including streamed event:error
                    # overloads). ModelClient still fails closed for malformed
                    # or non-transient protocol/auth errors, and cross-provider
                    # fallbacks remain disabled for workflow workers.
                    "SOPHIA_MODEL_RETRIES": "2",
                })
            else:
                worker_argv = [
                    sys.executable,
                    "-P",
                    "-m",
                    "agent.session_worker",
                    "--spec",
                    str(spec_path),
                    "--result",
                    str(result_path),
                ]
                worker_env = _supervised_worker_env({
                    "PYTHONPATH": explicit_pythonpath,
                    "SOPHIA_MODEL_FALLBACKS": "",
                    "SOPHIA_MODEL_FALLBACK_POLICY": "never",
                    "SOPHIA_FALLBACK_POLICY": "never",
                    "SOPHIA_MODEL_RETRIES": "2",
                })
            submitted_tasks.append({
                "taskId": task_id,
                "name": name,
                "argv": worker_argv,
                "cwd": str(workspace),
                "receiptPath": str(result_path),
                "dependencies": [],
                "surfaceMode": terminal_layout,
                "env": worker_env,
            })
            agent = {
                "agentId": agent_id,
                "taskId": task_id,
                "name": name,
                "index": index - 1,
                "stage": stage_index,
                "pattern": pattern,
                "kind": stage_kind,
                "status": "queued",
                "started": True,
                "active": False,
                "role": "sub",
                "persona": assignment.persona_id,
                "skills": list(assignment.skill_names),
                "skillVia": list(assignment.skill_via),
                "allowedTools": sorted(worker_scope),
                "toolScopeVia": assignment.tool_scope_via,
                "requestedWorkerModel": str(
                    route.get("requestedModel") or ""
                ),
                "resolvedWorkerProvider": str(
                    route.get("resolvedProvider") or ""
                ),
                "resolvedWorkerModel": str(
                    route.get("resolvedModel") or ""
                ),
                "routingSource": str(route.get("routingSource") or ""),
                "providerToolMode": str(
                    route.get("providerToolMode") or ""
                ),
                "coverageKeys": coverage_keys,
                "chartNodeId": str(contract.get("chartNodeId") or ""),
                "chartNodeKind": str(contract.get("chartNodeKind") or ""),
                "chartDependencies": list(
                    contract.get("chartDependencies") or []
                ),
                "retryOf": retry_of,
                "summary": assignment.task[:160],
                "logicalAgentId": logical_agent.agent_id,
                "workerSession": worker_session,
                "reuseAllowed": bool(reuse_decision.allowed),
                "reuseReason": reuse_decision.reason,
                "cacheEligible": bool(reuse_decision.allowed),
                "processReuse": False,
            }
            agents.append(agent)
            self.bus.bridge_event(run_id, {
                "type": "a2a_harness_select",
                "subName": name,
                "index": index,
                "workflowStage": stage_index,
                "workflowPattern": pattern,
                **assignment.to_dict(),
                "allowedTools": sorted(worker_scope),
                "toolScopeVia": assignment.tool_scope_via,
                "requestedWorkerModel": str(
                    route.get("requestedModel") or ""
                ),
                "resolvedWorkerProvider": str(
                    route.get("resolvedProvider") or ""
                ),
                "resolvedWorkerModel": str(
                    route.get("resolvedModel") or ""
                ),
                "routingSource": str(route.get("routingSource") or ""),
                "providerToolMode": str(
                    route.get("providerToolMode") or ""
                ),
            })
            self.bus.bridge_event(run_id, {
                "type": "a2a_handoff",
                "from": "Main Workflow Controller",
                "to": name,
                "workflowStage": stage_index,
                "workflowPattern": pattern,
                "promptChars": len(agent_prompt),
                "promptPreview": assignment.task[:400],
                "personaId": assignment.persona_id,
                "skills": list(assignment.skill_names),
                "allowedTools": sorted(worker_scope),
                "toolScopeVia": assignment.tool_scope_via,
                "requestedWorkerModel": str(
                    route.get("requestedModel") or ""
                ),
                "resolvedWorkerProvider": str(
                    route.get("resolvedProvider") or ""
                ),
                "resolvedWorkerModel": str(
                    route.get("resolvedModel") or ""
                ),
                "routingSource": str(route.get("routingSource") or ""),
                "providerToolMode": str(
                    route.get("providerToolMode") or ""
                ),
                "chartNodeId": str(contract.get("chartNodeId") or ""),
                "chartNodeKind": str(contract.get("chartNodeKind") or ""),
                "chartDependencies": list(
                    contract.get("chartDependencies") or []
                ),
                "execution": execution,
                "orchestration": orchestration.snapshot(),
                "canClaimAGI": False,
            })

        persisted_contracts: list[dict[str, Any]] = []
        for index, raw_contract in enumerate(
            list(task_contracts or [])[: len(submitted_tasks)]
        ):
            contract = dict(raw_contract) if isinstance(raw_contract, dict) else {}
            task_id = task_ids[index] if index < len(task_ids) else ""
            contract["taskId"] = task_id
            contract["contractIndex"] = index
            # The worker writes this receipt before its terminal event. Keep
            # the exact path/run binding in the durable contract so a
            # controller restart can harvest a receipt that exists even when
            # the live stage projection was interrupted.
            if index < len(submitted_tasks):
                contract["receiptPath"] = str(
                    submitted_tasks[index].get("receiptPath") or ""
                )
            contract["receiptRunId"] = supervisor_run_id
            contract["contractId"] = (
                f"{workflow_id}:stage-{stage_index}:contract-"
                f"{hashlib.sha256(json.dumps(contract, sort_keys=True).encode('utf-8')).hexdigest()[:16]}"
            )
            persisted_contracts.append(contract)
            if index < len(agents):
                agents[index]["contractId"] = contract["contractId"]
        task_contracts = persisted_contracts

        live_stage_record: dict[str, Any] = {
            "stage": stage_index,
            "plannedStages": planned_stage_count,
            "pattern": pattern,
            "kind": stage_kind,
            "goal": stage_goal,
            "status": "running",
            "requiresCritics": bool(requires_critics),
            "supervisorRunId": supervisor_run_id,
            "maxConcurrency": None,
            "requestedAgentCount": (
                controller_requested_task_count
                if controller_requested_task_count is not None
                else len(submitted_tasks)
            ),
            "startedAgentCount": len(submitted_tasks),
            "unstartedAgentCount": max(
                0,
                (
                    controller_requested_task_count
                    if controller_requested_task_count is not None
                    else len(submitted_tasks)
                ) - len(submitted_tasks),
            ),
            "taskContracts": [
                dict(contract)
                for contract in list(task_contracts or [])[: len(submitted_tasks)]
                if isinstance(contract, dict)
            ],
            "completionCriteria": [
                str(item)
                for item in list(completion_criteria or [])
                if str(item).strip()
            ],
            "agents": agents,
            "results": [],
        }

        last_disk_stage_key: tuple[Any, ...] | None = None

        def persist_live_stage() -> None:
            from agent.a2a_orchestration import derive_stage_progress_counts

            nonlocal last_disk_stage_key
            progress = dict(live_stage_record)
            progress.pop("startedAgentCount", None)
            progress.pop("unstartedAgentCount", None)
            requested, started, unstarted = derive_stage_progress_counts(progress)
            live_stage_record["requestedAgentCount"] = requested
            live_stage_record["startedAgentCount"] = started
            live_stage_record["unstartedAgentCount"] = unstarted
            stages = [
                dict(item)
                for item in (handle.get("dynamicWorkflowStages") or [])
                if isinstance(item, dict)
                and int(item.get("stage") or 0) != stage_index
            ]
            stages.append(live_stage_record)
            stages.sort(key=lambda item: int(item.get("stage") or 0))
            handle["dynamicWorkflowStages"] = stages
            handle["dynamicWorkflowAgents"] = [
                agent
                for item in stages
                for agent in list(item.get("agents") or [])
                if isinstance(agent, dict)
            ]
            disk_key = (
                live_stage_record.get("status"),
                requested,
                started,
                unstarted,
                tuple(
                    (
                        str(agent.get("taskId") or ""),
                        bool(agent.get("started")),
                        str(agent.get("status") or ""),
                    )
                    for agent in list(live_stage_record.get("agents") or [])
                    if isinstance(agent, dict)
                ),
            )
            if disk_key != last_disk_stage_key:
                try:
                    orchestration.upsert_workflow_stage(live_stage_record)
                    last_disk_stage_key = disk_key
                except Exception as exc:  # noqa: BLE001 - persist must not kill a live stage
                    self.bus.bridge_event(run_id, {
                        "type": "workflow_persist_warning",
                        "stage": stage_index,
                        "error": f"{type(exc).__name__}: {exc}"[:800],
                        "candidateOnly": True,
                        "canClaimAGI": False,
                    })

        handle["a2aMaxConcurrency"] = configured_concurrency
        live_stage_record["maxConcurrency"] = configured_concurrency
        live_stage_record["providerConcurrencyCap"] = provider_concurrency_cap
        live_stage_record["concurrencyReason"] = concurrency_reason
        live_stage_record["controllerRequestedTaskCount"] = (
            controller_requested_task_count
            if controller_requested_task_count is not None
            else len(submitted_tasks)
        )
        live_stage_record["deferredTaskCount"] = max(
            0,
            int(deferred_task_count),
        )
        publish_orchestration(
            orchestration.upsert_workflow_plan({
                "stage": stage_index,
                "pattern": pattern,
                "kind": stage_kind,
                "status": "dispatching",
                "goal": stage_goal,
                "plannedStages": planned_stage_count,
                "tasks": [
                    str(assignment.task)
                    for assignment in assignments
                ],
                "taskContracts": [
                    dict(contract)
                    for contract in task_contracts
                    if isinstance(contract, dict)
                ],
                "completionCriteria": [
                    str(item)
                    for item in list(completion_criteria or [])
                    if str(item).strip()
                ],
                "requiresCritics": bool(requires_critics),
            })
        )
        persist_live_stage()
        orchestration.upsert_workflow_stage(live_stage_record)
        self.bus.bridge_event(run_id, {
            "type": "dynamic_workflow_stage_start",
            "stage": stage_index,
            "plannedStages": planned_stage_count,
            "pattern": pattern,
            "kind": stage_kind,
            "goal": stage_goal,
            "taskCount": len(submitted_tasks),
            "maxConcurrency": configured_concurrency,
            "providerConcurrencyCap": provider_concurrency_cap,
            "concurrencyReason": concurrency_reason,
            "controllerRequestedTaskCount": (
                controller_requested_task_count
                if controller_requested_task_count is not None
                else len(submitted_tasks)
            ),
            "deferredTaskCount": max(0, int(deferred_task_count)),
            "queued": len(submitted_tasks),
            "active": 0,
            "terminal": 0,
            "started": 0,
            "total": len(submitted_tasks),
            "currentWave": 0,
            "totalWaves": max(
                1,
                math.ceil(
                    len(submitted_tasks) / max(1, configured_concurrency)
                ),
            ),
            "agents": agents,
            **parent_event,
            "orchestration": orchestration.snapshot(),
            "candidateOnly": True,
            "canClaimAGI": False,
        })
        if parent_mode == "agi":
            self.bus.bridge_event(run_id, {
                "type": "agi_workflow_workflow_start",
                "nodeId": parent_node_id,
                "phase": parent_phase,
                "workflowId": workflow_id,
                "pattern": pattern,
                "stage": stage_index,
                "plannedStages": planned_stage_count,
                "status": "running",
                "barrier": {
                    "stage": stage_index,
                    "status": "waiting",
                    "completed": 0,
                    "total": len(agents),
                    "label": "waiting for complete stage barrier",
                },
                "agents": agents,
                "candidateOnly": True,
                "canClaimAGI": False,
            })
        dispatch_manifest.set_status(
            "running",
            phase="worker",
            main_status="waiting_workers",
        )
        self._publish_dispatch_manifest(handle)
        client.submit(
            run_id=supervisor_run_id,
            tasks=submitted_tasks,
            max_concurrency=configured_concurrency,
        )
        self.bus.bridge_event(run_id, {
            "type": "a2a_supervisor_start",
            "supervisorRunId": supervisor_run_id,
            "workflowStage": stage_index,
            "workflowPattern": pattern,
            "socketPath": str(client.socket_path),
            "execution": execution,
            "terminalLayout": terminal_layout,
            "maxConcurrency": configured_concurrency,
            "workerContinuity": True,
            "mainVerifierContinuity": False,
            "canClaimAGI": False,
        })

        sequence = int(hello.get("sequence") or 0)
        started_tasks: set[str] = set()
        active_states = {
            "spawning",
            "running",
            "waiting_input",
            "verifying",
        }
        terminal_states = {
            "succeeded",
            "failed",
            "cancelled",
            "timed_out",
            "lost",
            "needs_reconciliation",
        }
        inactivity_timeout = _normalize_drain_timeout(
            handle.get("drainTimeoutSec", self.drain_timeout)
        )
        stage_started = time.monotonic()
        hard_timeout, expected_waves = _workflow_stage_hard_timeout(
            inactivity_timeout,
            task_count=len(submitted_tasks),
            max_concurrency=configured_concurrency,
        )
        allow_active_progress_extensions = (
            inactivity_timeout >= DRAIN_TIMEOUT_DEFAULT_SEC
            and hard_timeout >= DRAIN_TIMEOUT_MAX_SEC
        )
        hard_deadline = stage_started + hard_timeout
        absolute_deadline = stage_started + (
            max(hard_timeout, WORKFLOW_STAGE_ABSOLUTE_TIMEOUT_SEC)
            if allow_active_progress_extensions
            else hard_timeout
        )
        deadline_extension_count = 0
        last_activity: dict[str, float] = {}
        timed_out_tasks: set[str] = set()
        timed_out_after_active_progress: set[str] = set()
        last_progress_age_at_timeout: dict[str, float] = {}
        task_reason_codes: dict[str, str] = {}
        last_heartbeat = stage_started
        terminal_snapshot: dict[str, Any] = {}
        provider_circuit: dict[str, Any] | None = None

        def agent_for_task(task_id: str) -> tuple[int, dict[str, Any]] | None:
            try:
                index = task_ids.index(task_id)
            except ValueError:
                return None
            return index, agents[index]

        def progress_text(worker_event: dict[str, Any]) -> str:
            event_type = str(
                worker_event.get("eventType")
                or worker_event.get("type")
                or "progress"
            )
            if event_type == "provider_wait":
                elapsed = worker_event.get("elapsedSec")
                return (
                    f"provider wait · {elapsed}s"
                    if isinstance(elapsed, (int, float))
                    else "provider wait"
                )
            if event_type in {"tool_call", "tool_result", "tool_wait"}:
                tool = str(worker_event.get("tool") or "").strip()
                return f"{event_type.replace('_', ' ')}{f' · {tool}' if tool else ''}"
            return event_type.replace("_", " ")

        def refresh_agents(
            snapshot: dict[str, Any],
            *,
            supervised_run_id: str,
            observed_at: float | None = None,
        ) -> None:
            observation_time = (
                observed_at if observed_at is not None else time.monotonic()
            )
            run = dict(
                snapshot.get("runs", {}).get(supervised_run_id) or {}
            )
            tasks = dict(run.get("tasks") or {})
            for task_id, task_snapshot_raw in tasks.items():
                found = agent_for_task(str(task_id))
                if found is None:
                    continue
                _, agent = found
                task_snapshot = dict(task_snapshot_raw or {})
                state = str(task_snapshot.get("state") or agent["status"])
                normalized_task_id = str(task_id)
                if (
                    normalized_task_id not in started_tasks
                    and state in active_states
                ):
                    started_tasks.add(normalized_task_id)
                    last_activity[normalized_task_id] = observation_time
                agent["status"] = state
                agent["active"] = state in active_states
                detail = dict(task_snapshot.get("detail") or {})
                last_event = str(detail.get("lastProgressEvent") or "").strip()
                if last_event:
                    agent["progress"] = last_event.replace("_", " ")
                dispatch_manifest.update_assignment(
                    str(task_id),
                    status=(
                        "queued"
                        if state == "queued_for_model"
                        else state
                    ),
                    phase="worker",
                )
            persist_live_stage()
            self._publish_dispatch_manifest(handle)

        def emit_stage_progress(now: float) -> None:
            counts = {
                "queued": 0,
                "active": 0,
                "terminal": 0,
                "succeeded": 0,
                "failed": 0,
            }
            for agent in agents:
                state = str(agent.get("status") or "queued")
                if state in terminal_states:
                    counts["terminal"] += 1
                    if state == "succeeded":
                        counts["succeeded"] += 1
                    else:
                        counts["failed"] += 1
                elif state in {"queued", "queued_for_model"}:
                    counts["queued"] += 1
                else:
                    counts["active"] += 1
            elapsed = max(0.0, now - stage_started)
            total = len(agents)
            started = max(0, total - counts["queued"])
            total_waves = max(
                1,
                math.ceil(total / max(1, configured_concurrency)),
            )
            current_wave = (
                min(
                    total_waves,
                    max(
                        1,
                        math.ceil(started / max(1, configured_concurrency)),
                    ),
                )
                if started
                else 0
            )
            estimated_remaining: float | None = None
            if counts["terminal"] >= total and total:
                estimated_remaining = 0.0
            elif counts["terminal"] > 0:
                observed = (
                    elapsed
                    / counts["terminal"]
                    * max(0, total - counts["terminal"])
                )
                estimated_remaining = min(
                    observed,
                    max(0.0, hard_deadline - now),
                )
            progress_receipt = {
                "elapsedSec": round(elapsed, 1),
                "hardDeadlineRemainingSec": round(
                    max(0.0, hard_deadline - now),
                    1,
                ),
                "absoluteDeadlineRemainingSec": round(
                    max(0.0, absolute_deadline - now),
                    1,
                ),
                "deadlineExtensionCount": deadline_extension_count,
                "estimatedRemainingSec": (
                    round(estimated_remaining, 1)
                    if estimated_remaining is not None
                    else None
                ),
                "etaBasis": (
                    "observed terminal throughput"
                    if counts["terminal"] > 0
                    else "awaiting first completion"
                ),
                "started": started,
                "total": total,
                "currentWave": current_wave,
                "totalWaves": total_waves,
                **counts,
            }
            live_stage_record["progress"] = progress_receipt
            persist_live_stage()
            self.bus.bridge_event(run_id, {
                "type": "dynamic_workflow_stage_progress",
                "stage": stage_index,
                "plannedStages": planned_stage_count,
                "pattern": pattern,
                "inactivityTimeoutSec": inactivity_timeout,
                "hardTimeoutSec": hard_timeout,
                "expectedWaves": expected_waves,
                **progress_receipt,
                "agents": agents,
                **parent_event,
                "candidateOnly": True,
                "canClaimAGI": False,
            })
            if parent_mode == "agi":
                self.bus.bridge_event(run_id, {
                    "type": "agi_workflow_workflow_start",
                    "nodeId": parent_node_id,
                    "phase": parent_phase,
                    "workflowId": workflow_id,
                    "pattern": pattern,
                    "stage": stage_index,
                    "plannedStages": planned_stage_count,
                    "status": "running",
                    "barrier": {
                        "stage": stage_index,
                        "status": "waiting",
                        "completed": counts["terminal"],
                        "total": (
                            counts["terminal"]
                            + counts["active"]
                            + counts["queued"]
                        ),
                        "label": "stage barrier",
                    },
                    "agents": agents,
                    "candidateOnly": True,
                    "canClaimAGI": False,
                })

        def open_common_provider_circuit(
            supervisor_tasks: dict[str, Any],
        ) -> None:
            """Stop queued work after one provider cohort fails identically."""
            nonlocal provider_circuit
            if provider_circuit is not None:
                return
            cohort_size = min(
                configured_concurrency,
                len(submitted_tasks),
            )
            classified: list[tuple[str, str, str, str]] = []
            for task_id, raw_snapshot in supervisor_tasks.items():
                task_snapshot = dict(raw_snapshot or {})
                if str(task_snapshot.get("state") or "") != "failed":
                    continue
                detail = dict(task_snapshot.get("detail") or {})
                task_result = dict(detail.get("result") or {})
                error = str(
                    task_result.get("modelError")
                    or task_result.get("error")
                    or detail.get("reason")
                    or ""
                )
                failure = _workflow_provider_failure(error)
                if failure is None:
                    continue
                reason_code, fingerprint, actionable = failure
                classified.append(
                    (str(task_id), reason_code, fingerprint, actionable)
                )
            if len(classified) < cohort_size:
                return
            cohort = classified[:cohort_size]
            fingerprints = {item[2] for item in cohort}
            if len(fingerprints) != 1:
                return
            actionable = cohort[0][3]
            failed_ids = [item[0] for item in cohort]
            skipped_ids: list[str] = []
            circuit_reason = (
                "not started because the workflow provider circuit opened "
                f"after {len(cohort)} matching failures: {actionable}"
            )
            for task_id, raw_snapshot in supervisor_tasks.items():
                task_snapshot = dict(raw_snapshot or {})
                state = str(task_snapshot.get("state") or "")
                if task_id in failed_ids or state in terminal_states:
                    continue
                if state not in {"queued", "queued_for_model"}:
                    # A scheduler race may already have started this worker.
                    # Cancel it immediately, but retain started=true later.
                    circuit_reason_for_task = (
                        "cancelled because the workflow provider circuit "
                        f"opened after matching failures: {actionable}"
                    )
                else:
                    circuit_reason_for_task = circuit_reason
                    skipped_ids.append(task_id)
                task_reason_codes[task_id] = "provider_circuit_open"
                client.cancel_task(
                    supervisor_run_id,
                    task_id,
                    reason=circuit_reason_for_task,
                    timed_out=False,
                )
                found = agent_for_task(task_id)
                if found is not None:
                    _, agent = found
                    agent["status"] = (
                        "skipped"
                        if task_id in skipped_ids
                        else "cancelling"
                    )
                    agent["active"] = task_id not in skipped_ids
                    agent["started"] = task_id in started_tasks
                    agent["reasonCode"] = "provider_circuit_open"
                    agent["error"] = circuit_reason_for_task
                    agent["summary"] = circuit_reason_for_task
                    publish_orchestration(
                        orchestration.set_task_state(
                            task_id,
                            (
                                "skipped"
                                if task_id in skipped_ids
                                else "canceled"
                            ),
                            summary=circuit_reason_for_task,
                        )
                    )
                    publish_orchestration(
                        orchestration.update_agent_activity(
                            str(agent.get("agentId") or ""),
                            status=(
                                "skipped"
                                if task_id in skipped_ids
                                else "canceled"
                            ),
                            summary=circuit_reason_for_task,
                            current_task_id="",
                            current_tool="",
                        )
                    )
                    dispatch_manifest.update_assignment(
                        task_id,
                        status=(
                            "skipped"
                            if task_id in skipped_ids
                            else "cancelled"
                        ),
                        phase="worker",
                        error=circuit_reason_for_task,
                    )
            provider_circuit = {
                "reasonCode": "provider_circuit_open",
                "providerFailureCode": cohort[0][1],
                "error": actionable,
                "fingerprint": cohort[0][2],
                "failedTaskIds": failed_ids,
                "skippedTaskIds": skipped_ids,
            }
            live_stage_record["providerCircuit"] = dict(provider_circuit)
            persist_live_stage()
            publish_orchestration(
                orchestration.append_message(
                    kind="task_notification",
                    sender="system",
                    recipient="Main Workflow Controller",
                    summary="Workflow provider circuit opened",
                    body=(
                        f"{actionable}\n\n"
                        f"Skipped before start: {', '.join(skipped_ids) or 'none'}"
                    ),
                    trusted=True,
                )
            )
            self.bus.bridge_event(run_id, {
                "type": "dynamic_workflow_provider_circuit_open",
                "stage": stage_index,
                "pattern": pattern,
                **provider_circuit,
                "reason": circuit_reason,
                "agents": agents,
                **parent_event,
                "orchestration": orchestration.snapshot(),
                "candidateOnly": True,
                "canClaimAGI": False,
            })
            self._publish_dispatch_manifest(handle)

        while True:
            if cancel.is_set():
                if str(handle.get("cancelReason") or "") != "backend_exit":
                    try:
                        terminal_snapshot = client.snapshot(supervisor_run_id)
                        refresh_agents(
                            terminal_snapshot,
                            supervised_run_id=supervisor_run_id,
                        )
                    finally:
                        try:
                            client.cancel_run(
                                supervisor_run_id,
                                reason=str(
                                    handle.get("cancelReason")
                                    or "parent workflow cancellation"
                                ),
                            )
                        finally:
                            for agent in agents:
                                if str(agent.get("status") or "") not in terminal_states:
                                    agent["status"] = "cancelled"
                                    agent["active"] = False
                                    agent["progress"] = str(
                                        handle.get("cancelReason")
                                        or "parent workflow cancellation"
                                    )
                                    task_id = str(agent.get("taskId") or "")
                                    if task_id:
                                        orchestration.set_task_state(
                                            task_id,
                                            "canceled",
                                            summary=agent["progress"],
                                        )
                                        dispatch_manifest.update_assignment(
                                            task_id,
                                            status="cancelled",
                                            phase="worker",
                                            error=agent["progress"],
                                        )
                                    agent_id = str(agent.get("agentId") or "")
                                    if agent_id:
                                        orchestration.update_agent_activity(
                                            agent_id,
                                            status="canceled",
                                            summary=agent["progress"],
                                            current_task_id="",
                                            current_tool="",
                                        )
                            orchestration.append_message(
                                kind="task_notification",
                                sender="system",
                                recipient="main",
                                summary=(
                                    f"Workflow stage {stage_index} canceled"
                                ),
                                body=str(
                                    handle.get("cancelReason")
                                    or "parent workflow cancellation"
                                ),
                                trusted=True,
                            )
                            publish_orchestration()
                            live_stage_record["status"] = "cancelled"
                            self._publish_dispatch_manifest(handle)
                            persist_live_stage()
                            orchestration.upsert_workflow_stage(
                                live_stage_record
                            )
                raise _RunCancelled()
            now = time.monotonic()
            for event in client.replay(
                after=sequence, run_id=supervisor_run_id
            ):
                sequence = max(sequence, int(event.get("sequence") or 0))
                event_type = str(event.get("type") or "")
                task_id = str(event.get("taskId") or "")
                if (
                    task_id in task_ids
                    and event_type in {"surface.output", "task.worker_event"}
                ):
                    started_tasks.add(task_id)
                    last_activity[task_id] = now
                if event_type == "surface.created":
                    self.bus.bridge_event(run_id, {
                        "type": "terminal_surface_created",
                        "supervisorRunId": supervisor_run_id,
                        "taskId": task_id,
                        "surfaceId": event.get("surfaceId"),
                        "name": event.get("name"),
                        "state": event.get("state"),
                        "terminalLayout": terminal_layout,
                        "workflowStage": stage_index,
                        "canClaimAGI": False,
                    })
                elif event_type == "surface.output":
                    self.bus.bridge_event(run_id, {
                        "type": "terminal_output",
                        "supervisorRunId": supervisor_run_id,
                        "taskId": task_id,
                        "surfaceId": event.get("surfaceId"),
                        "text": event.get("text") or "",
                        "workflowStage": stage_index,
                        "canClaimAGI": False,
                    })
                elif event_type == "task.worker_event":
                    worker_event = event.get("workerEvent")
                    if isinstance(worker_event, dict):
                        found = agent_for_task(task_id)
                        if found is not None:
                            agent_index, agent = found
                            if worker_event.get("type") == "task.progress":
                                if (
                                    str(worker_event.get("eventType") or "")
                                    == "provider_wait"
                                ):
                                    # Supervised workers report their provider
                                    # waits through sessiond rather than this
                                    # process's TokenTee. Reuse the same root-run
                                    # lock/throttle before projecting progress.
                                    self._refresh_run_eta_on_provider_wait(handle)
                                agent["progress"] = progress_text(worker_event)
                                provider = str(
                                    worker_event.get("provider") or ""
                                ).strip()
                                resolved_model = str(
                                    worker_event.get("resolvedModel")
                                    or worker_event.get("model")
                                    or ""
                                ).strip()
                                if provider:
                                    agent["provider"] = provider
                                if resolved_model:
                                    agent["resolvedModel"] = resolved_model
                                publish_orchestration(
                                    orchestration.update_agent_activity(
                                        str(agent.get("agentId") or ""),
                                        status="working",
                                        current_task_id=task_id,
                                        current_tool=str(
                                            worker_event.get("tool") or ""
                                        ),
                                        summary=agent["progress"],
                                    )
                                )
                                dispatch_manifest.update_assignment(
                                    task_id,
                                    status="running",
                                    phase="worker",
                                    summary=agent["progress"],
                                    provider=provider or None,
                                    model=resolved_model or None,
                                )
                                self._publish_dispatch_manifest(handle)
                                self.bus.bridge_event(run_id, {
                                    "type": "dynamic_workflow_worker_progress",
                                    "stage": stage_index,
                                    "pattern": pattern,
                                    "index": agent_index,
                                    "taskId": task_id,
                                    "progress": agent["progress"],
                                    **(
                                        {"provider": provider}
                                        if provider
                                        else {}
                                    ),
                                    **(
                                        {"resolvedModel": resolved_model}
                                        if resolved_model
                                        else {}
                                    ),
                                    **{
                                        key: worker_event[key]
                                        for key in (
                                            "promptTokens",
                                            "completionTokens",
                                            "cacheTokens",
                                            "modelCalls",
                                            "fallbackUsed",
                                        )
                                        if isinstance(
                                            worker_event.get(key),
                                            (bool, int, float),
                                        )
                                    },
                                    "agents": agents,
                                    **parent_event,
                                    "orchestration": orchestration.snapshot(),
                                    "candidateOnly": True,
                                    "canClaimAGI": False,
                                })
                                if parent_mode == "agi":
                                    self.bus.bridge_event(run_id, {
                                        "type": "agi_workflow_worker_lease",
                                        "nodeId": parent_node_id,
                                        "phase": parent_phase,
                                        "workflowId": workflow_id,
                                        "stage": stage_index,
                                        "worker": {
                                            **agent,
                                            "status": (
                                                str(agent.get("status") or "")
                                                or "running"
                                            ),
                                            "currentTool": str(
                                                worker_event.get("tool") or ""
                                            ),
                                            "currentStatus": str(
                                                agent.get("progress") or ""
                                            ),
                                        },
                                        "candidateOnly": True,
                                        "canClaimAGI": False,
                                    })
                                persist_live_stage()
                    if (
                        isinstance(worker_event, dict)
                        and worker_event.get("type") == "task.waiting_input"
                        and isinstance(worker_event.get("approval"), dict)
                    ):
                        approval = dict(worker_event["approval"])
                        external_id = f"sup-{uuid.uuid4().hex[:10]}"
                        with self.approvals_lock:
                            self.supervisor_approvals[external_id] = {
                                "client": client,
                                "runId": supervisor_run_id,
                                "taskId": task_id,
                                "workerApprovalId": str(
                                    approval.get("id") or ""
                                ),
                            }
                        self.emit({
                            "type": "approval_request",
                            "runId": run_id,
                            "id": external_id,
                            "tool": approval.get("tool")
                            or "supervised workflow worker",
                            "preview": approval.get("preview") or "",
                            "agentTaskId": task_id,
                            "supervisorRunId": supervisor_run_id,
                            "workflowStage": stage_index,
                            "ts": _now_iso(),
                            "canClaimAGI": False,
                        })
                        publish_orchestration(
                            orchestration.set_task_state(
                                task_id,
                                "waiting_input",
                                summary=str(
                                    approval.get("preview")
                                    or "Human approval required"
                                ),
                            )
                        )
                        dispatch_manifest.update_assignment(
                            task_id,
                            status="waiting_input",
                            phase="worker",
                            summary=str(
                                approval.get("preview")
                                or "Human approval required"
                            ),
                        )
                        self._publish_dispatch_manifest(handle)
                        publish_orchestration(
                            orchestration.append_message(
                                kind="task_notification",
                                sender=(
                                    agent_for_task(task_id)[1]["name"]
                                    if agent_for_task(task_id) is not None
                                    else "workflow worker"
                                ),
                                recipient="operator",
                                summary="Approval required",
                                body=str(approval.get("preview") or ""),
                                task_id=task_id,
                                trusted=False,
                            )
                        )
                elif event_type == "task.state_changed":
                    state = str(event.get("state") or "")
                    found = agent_for_task(task_id)
                    if found is None:
                        continue
                    agent_index, agent = found
                    if task_id not in started_tasks and state in active_states:
                        started_tasks.add(task_id)
                        last_activity[task_id] = now
                    agent["status"] = state
                    agent["active"] = state in active_states
                    detail_reason = str(
                        dict(event.get("detail") or {}).get("reason") or ""
                    )
                    dispatch_manifest.update_assignment(
                        task_id,
                        status=(
                            "queued"
                            if state == "queued_for_model"
                            else state
                        ),
                        phase="worker",
                        error=(
                            detail_reason
                            if state
                            in {
                                "failed",
                                "cancelled",
                                "timed_out",
                                "lost",
                                "needs_reconciliation",
                            }
                            else None
                        ),
                    )
                    self._publish_dispatch_manifest(handle)
                    publish_orchestration(
                        orchestration.set_task_state(
                            task_id,
                            state,
                            summary=detail_reason,
                        )
                    )
                    self.bus.bridge_event(run_id, {
                        "type": "a2a_task_state",
                        "index": agent_index,
                        "taskId": task_id,
                        "supervisorRunId": supervisor_run_id,
                        "state": state,
                        "detail": dict(event.get("detail") or {}),
                        "workflowStage": stage_index,
                        "workflowPattern": pattern,
                        "agents": agents,
                        "orchestration": orchestration.snapshot(),
                        "canClaimAGI": False,
                    })
            terminal_snapshot = client.snapshot(supervisor_run_id)
            refresh_agents(
                terminal_snapshot,
                supervised_run_id=supervisor_run_id,
                observed_at=now,
            )
            supervisor_run = dict(
                terminal_snapshot.get("runs", {}).get(supervisor_run_id) or {}
            )
            terminal_tasks = dict(supervisor_run.get("tasks") or {})
            open_common_provider_circuit(terminal_tasks)
            if str(supervisor_run.get("state") or "") in {
                "succeeded",
                "failed",
                "cancelled",
                "timed_out",
                "needs_reconciliation",
            }:
                break
            terminal_tasks = dict(supervisor_run.get("tasks") or {})
            if (
                allow_active_progress_extensions
                and now >= hard_deadline
                and hard_deadline < absolute_deadline
            ):
                recently_active = [
                    str(task_id)
                    for task_id, task_snapshot_raw in terminal_tasks.items()
                    if str(task_id) in started_tasks
                    and str(
                        dict(task_snapshot_raw or {}).get("state") or ""
                    )
                    not in terminal_states
                    and now - last_activity.get(str(task_id), now)
                    < inactivity_timeout
                ]
                if recently_active:
                    prior_deadline = hard_deadline
                    hard_deadline = min(
                        absolute_deadline,
                        hard_deadline + WORKFLOW_STAGE_ACTIVE_EXTENSION_SEC,
                    )
                    deadline_extension_count += 1
                    self.bus.bridge_event(run_id, {
                        "type": "dynamic_workflow_stage_deadline_extended",
                        "stage": stage_index,
                        "plannedStages": planned_stage_count,
                        "pattern": pattern,
                        "reason": "recent worker progress",
                        "activeTaskCount": len(recently_active),
                        "deadlineExtensionCount": deadline_extension_count,
                        "extensionSec": round(
                            hard_deadline - prior_deadline,
                            1,
                        ),
                        "hardDeadlineRemainingSec": round(
                            max(0.0, hard_deadline - now),
                            1,
                        ),
                        "absoluteDeadlineRemainingSec": round(
                            max(0.0, absolute_deadline - now),
                            1,
                        ),
                        "candidateOnly": True,
                        "canClaimAGI": False,
                    })
                    live_stage_record["deadlineExtensionCount"] = (
                        deadline_extension_count
                    )
                    persist_live_stage()
            for task_id, task_snapshot_raw in terminal_tasks.items():
                task_snapshot = dict(task_snapshot_raw or {})
                state = str(task_snapshot.get("state") or "")
                if state in terminal_states or task_id in timed_out_tasks:
                    continue
                hard_expired = now >= hard_deadline
                if not hard_expired and (
                    task_id not in started_tasks
                    or state in {"queued", "queued_for_model"}
                ):
                    continue
                inactivity = now - last_activity.get(task_id, now)
                if inactivity < inactivity_timeout and not hard_expired:
                    continue
                if hard_expired:
                    last_progress_age_at_timeout[task_id] = max(
                        0.0,
                        inactivity,
                    )
                    if inactivity < inactivity_timeout:
                        timed_out_after_active_progress.add(task_id)
                timed_out_tasks.add(task_id)
                queued_at_deadline = (
                    hard_expired
                    and (
                        task_id not in started_tasks
                        or state in {"queued", "queued_for_model"}
                    )
                )
                if queued_at_deadline:
                    reason = (
                        "workflow stage deadline reached before provider "
                        "execution started"
                    )
                    task_reason_codes[task_id] = "stage_queue_deadline"
                elif hard_expired:
                    reason = (
                        f"workflow stage hard timeout after {hard_timeout:.1f}s"
                    )
                    task_reason_codes[task_id] = "stage_hard_timeout"
                else:
                    reason = (
                        "workflow worker inactivity timeout after "
                        f"{inactivity_timeout:.1f}s without progress"
                    )
                    task_reason_codes[task_id] = "worker_inactivity_timeout"
                client.cancel_task(
                    supervisor_run_id,
                    task_id,
                    reason=reason,
                    timed_out=not queued_at_deadline,
                )
                found = agent_for_task(task_id)
                if found is not None:
                    agent_index, agent = found
                    agent["status"] = (
                        "skipped" if queued_at_deadline else "cancelling"
                    )
                    agent["active"] = not queued_at_deadline
                    agent["started"] = task_id in started_tasks
                    agent["reasonCode"] = task_reason_codes[task_id]
                    agent["error"] = reason
                    agent["progress"] = reason
                    dispatch_manifest.update_assignment(
                        task_id,
                        status=(
                            "skipped"
                            if queued_at_deadline
                            else "timed_out"
                        ),
                        phase="worker",
                        error=reason,
                    )
                    self._publish_dispatch_manifest(handle)
                    publish_orchestration(
                        orchestration.set_task_state(
                            task_id,
                            "skipped" if queued_at_deadline else "timed_out",
                            summary=reason,
                        )
                    )
                    self.bus.bridge_event(run_id, {
                        "type": (
                            "dynamic_workflow_worker_unstarted"
                            if queued_at_deadline
                            else "dynamic_workflow_worker_timeout"
                        ),
                        "stage": stage_index,
                        "pattern": pattern,
                        "index": agent_index,
                        "taskId": task_id,
                        "reason": reason,
                        "timedOutAfterActiveProgress": (
                            task_id in timed_out_after_active_progress
                        ),
                        "lastProgressAgeSec": round(
                            last_progress_age_at_timeout.get(
                                task_id,
                                inactivity,
                            ),
                            1,
                        ),
                        "deadlineExtensionCount": deadline_extension_count,
                        "agents": agents,
                        **parent_event,
                        "orchestration": orchestration.snapshot(),
                        "candidateOnly": True,
                        "canClaimAGI": False,
                    })
                    persist_live_stage()
            if now - last_heartbeat >= WORKFLOW_STAGE_HEARTBEAT_SEC:
                emit_stage_progress(now)
                last_heartbeat = now
            time.sleep(0.1)

        supervisor_run = dict(
            terminal_snapshot.get("runs", {}).get(supervisor_run_id) or {}
        )
        terminal_tasks = dict(supervisor_run.get("tasks") or {})
        results: list[dict[str, Any]] = []
        from agent.a2a_orchestration import hash_worker_receipt_file
        for index, task_id in enumerate(task_ids):
            task_snapshot = dict(terminal_tasks.get(task_id) or {})
            supervisor_state = str(task_snapshot.get("state") or "lost")
            detail = dict(task_snapshot.get("detail") or {})
            task_result = dict(detail.get("result") or {})
            final_text = str(task_result.get("finalText") or "").strip()
            report_status = worker_report_status(final_text)
            report_reason_code = (
                f"worker_report_{report_status}"
                if report_status in {"failed", "blocked", "partial"}
                else ""
            )
            fallback_used = bool(task_result.get("fallbackUsed"))
            actionable_error = _safe_diagnostic_text(
                task_result.get("modelError")
                or task_result.get("error")
                or detail.get("reason")
                or "",
                limit=800,
            )
            started = (
                task_id in started_tasks
                or (
                    supervisor_state
                    in {"succeeded", "failed", "lost", "needs_reconciliation"}
                    and detail.get("started") is not False
                )
            )
            state = (
                "failed"
                if supervisor_state == "succeeded" and fallback_used
                else supervisor_state
            )
            report_error = ""
            if supervisor_state == "succeeded" and report_reason_code:
                state = "failed"
                report_error = (
                    f"worker report declared task status {report_status}"
                )
            task_error = actionable_error or report_error
            reason_code = (
                task_reason_codes.get(task_id, "")
                or str(detail.get("reasonCode") or "")
                or str(task_result.get("reasonCode") or "")
                or report_reason_code
            )
            if not reason_code:
                if fallback_used:
                    reason_code = "provider_fallback_excluded"
                elif supervisor_state == "succeeded" and not final_text:
                    # Supervisor completion proves only that the child process
                    # reached a terminal state. A blank report is not usable
                    # evidence and must not release a successful barrier or
                    # seed the warm logical-session pool.
                    state = "failed"
                    reason_code = "empty_worker_report"
                elif supervisor_state == "needs_reconciliation":
                    reason_code = "worker_needs_reconciliation"
                elif supervisor_state == "lost":
                    reason_code = "worker_lost"
                elif supervisor_state == "cancelled":
                    reason_code = "worker_cancelled"
                elif supervisor_state == "timed_out":
                    reason_code = "worker_timed_out"
                elif supervisor_state == "failed":
                    provider_failure = _workflow_provider_failure(
                        actionable_error
                    )
                    reason_code = (
                        provider_failure[0]
                        if provider_failure is not None
                        else "worker_failed"
                    )
                elif supervisor_state == "succeeded":
                    reason_code = "verified"
            if (
                not started
                and reason_code
                in {"provider_circuit_open", "stage_queue_deadline"}
            ):
                state = "skipped"
            elif not started:
                state = "unstarted"
                reason_code = reason_code or "never_started"
            agent = agents[index]
            agent["status"] = state
            agent["supervisorStatus"] = supervisor_state
            agent["fallbackUsed"] = fallback_used
            agent["provider"] = str(task_result.get("provider") or "")
            agent["resolvedModel"] = str(
                task_result.get("resolvedModel") or ""
            )
            agent["started"] = started
            agent["reasonCode"] = reason_code
            agent["workerReportStatus"] = report_status or ""
            agent["error"] = task_error
            agent["provider"] = str(task_result.get("provider") or "")
            agent["resolvedModel"] = str(
                task_result.get("resolvedModel") or ""
            )
            agent["active"] = False
            agent["summary"] = (
                (final_text[:160] + "…")
                if len(final_text) > 160
                else final_text or task_error or state
            )
            agent["progress"] = (
                str(detail.get("lastProgressEvent") or "").replace("_", " ")
                or agent.get("progress")
                or state.replace("_", " ")
            )
            receipt_path = str(task_snapshot.get("receiptPath") or "")
            receipt_sha256 = str(detail.get("receiptSha256") or "")
            if receipt_path and not receipt_sha256:
                receipt_sha256 = hash_worker_receipt_file(receipt_path)
            results.append({
                "taskId": task_id,
                "name": agent["name"],
                "stage": stage_index,
                "pattern": pattern,
                "role": agent["persona"] or "sub",
                "skills": list(agent["skills"]),
                "allowedTools": list(agent.get("allowedTools") or []),
                "toolScopeVia": str(agent.get("toolScopeVia") or ""),
                "requestedWorkerModel": str(
                    agent.get("requestedWorkerModel") or ""
                ),
                "resolvedWorkerProvider": str(
                    agent.get("resolvedWorkerProvider") or ""
                ),
                "resolvedWorkerModel": str(
                    agent.get("resolvedWorkerModel") or ""
                ),
                "routingSource": str(agent.get("routingSource") or ""),
                "providerToolMode": str(
                    agent.get("providerToolMode") or ""
                ),
                "coverageKeys": list(agent.get("coverageKeys") or []),
                "contractId": str(agent.get("contractId") or ""),
                "contractIndex": index,
                "retryOf": str(agent.get("retryOf") or ""),
                "status": state,
                "ok": state == "succeeded" and bool(final_text),
                "finalText": final_text,
                "modelError": actionable_error,
                "error": str(
                    task_error
                    or (
                        "worker used a fallback provider; report excluded from "
                        "the selected-provider workflow evidence"
                        if fallback_used
                        else ""
                    )
                    or ""
                ),
                "steps": list(task_result.get("steps") or []),
                "providerToolReceipts": list(
                    task_result.get("providerToolReceipts") or []
                ),
                "provider": str(task_result.get("provider") or ""),
                "resolvedModel": str(task_result.get("resolvedModel") or ""),
                "fallbackUsed": fallback_used,
                "receiptPath": receipt_path,
                "receiptSha256": receipt_sha256,
                "truncated": bool(task_result.get("truncated")),
                "fullReceiptRef": str(
                    task_result.get("fullReceiptRef") or ""
                ),
                "evidenceRefs": [
                    dict(ref)
                    for ref in list(task_result.get("evidenceRefs") or [])
                    if isinstance(ref, dict)
                ],
                "verification": [
                    str(item)
                    for item in list(task_result.get("verification") or [])
                    if str(item).strip()
                ],
                "limitations": [
                    str(item)
                    for item in list(task_result.get("limitations") or [])
                    if str(item).strip()
                ],
                "filesModified": [
                    str(item)
                    for item in list(task_result.get("filesModified") or [])
                    if str(item).strip()
                ],
                **{
                    key: task_result[key]
                    for key in (
                        "promptTokens",
                        "completionTokens",
                        "cacheTokens",
                        "modelCalls",
                    )
                    if isinstance(task_result.get(key), int)
                    and not isinstance(task_result.get(key), bool)
                    and task_result[key] >= 0
                },
                "supervisorStatus": supervisor_state,
                "started": started,
                "reasonCode": reason_code,
                "workerReportStatus": report_status or "",
            })
            manifest_status = (
                "succeeded"
                if state == "succeeded" and bool(final_text)
                else "skipped"
                if state in {"skipped", "unstarted"}
                else "cancelled"
                if state == "cancelled"
                else "timed_out"
                if state == "timed_out"
                else "failed"
            )
            dispatch_manifest.update_assignment(
                task_id,
                status=manifest_status,
                phase="worker",
                summary=agent["summary"],
                error=task_error if manifest_status != "succeeded" else None,
                receipt_path=receipt_path,
                receipt_run_id=supervisor_run_id,
                provider=str(task_result.get("provider") or "") or None,
                model=str(task_result.get("resolvedModel") or "") or None,
                provider_tool_mode=(
                    str(agent.get("providerToolMode") or "") or None
                ),
                worker_report_status=report_status or None,
            )
            self._publish_dispatch_manifest(handle)
            publish_orchestration(
                orchestration.set_task_state(
                    task_id,
                    state,
                    summary=agent["summary"],
                )
            )
            publish_orchestration(
                orchestration.append_message(
                    kind="worker_result",
                    sender=agent["name"],
                    recipient="Main Workflow Controller",
                    summary=f"{agent['name']} · {state}",
                    body=final_text or actionable_error or state,
                    task_id=task_id,
                    trusted=False,
                )
            )
            with self.approvals_lock:
                stale = [
                    approval_id
                    for approval_id, pending in self.supervisor_approvals.items()
                    if pending.get("taskId") == task_id
                ]
                for approval_id in stale:
                    self.supervisor_approvals.pop(approval_id, None)

        lease_by_id = {lease.lease_id: lease for lease in warm_leases}
        now_wall = time.time()
        for result in results:
            if not bool(result.get("ok")):
                continue
            task_id = str(result.get("taskId") or "")
            reuse_meta = reuse_meta_by_task.get(task_id)
            if not reuse_meta:
                continue
            reuse_request = reuse_meta["request"]
            reuse_decision = reuse_meta["decision"]
            selected_lease = (
                lease_by_id.get(str(reuse_decision.lease_id or ""))
                if reuse_decision.allowed
                else None
            )
            context_tokens = int(reuse_meta["promptTokens"]) + estimate_tokens(
                str(result.get("finalText") or "")
            )
            if selected_lease is not None:
                context_tokens += selected_lease.context_tokens
                lease_id = selected_lease.lease_id
                created_at = selected_lease.created_at
                reuse_count = selected_lease.reuse_count + 1
            else:
                lease_id = f"lease-{uuid.uuid4().hex[:12]}"
                created_at = now_wall
                reuse_count = 0
            replacement = WorkerLease(
                lease_id=lease_id,
                logical_agent=reuse_request.logical_agent,
                runtime=WorkerRuntime(
                    runtime_id=str(reuse_meta["workerSession"]),
                    state=RuntimeState.READY,
                ),
                fingerprint=reuse_meta["fingerprint"],
                lease_state=LeaseState.WARM,
                created_at=created_at,
                last_used_at=now_wall,
                reuse_count=reuse_count,
                context_tokens=min(context_tokens, context_window_tokens),
                context_window_tokens=context_window_tokens,
                last_task_id=task_id,
            )
            lease_by_id[lease_id] = replacement
            result["logicalAgentId"] = reuse_request.logical_agent.agent_id
            result["workerSession"] = str(reuse_meta["workerSession"])
            result["reuseAllowed"] = bool(reuse_decision.allowed)
            result["reuseReason"] = reuse_decision.reason
            result["reuseCount"] = reuse_count
            result["cacheEligible"] = bool(reuse_decision.allowed)
            result["processReuse"] = False

        updated_leases = list(lease_by_id.values())
        evictions = select_lru_evictions(
            updated_leases,
            now=now_wall,
            config=reuse_config,
        )
        evicted_ids = {lease.lease_id for lease in evictions}
        for lease in evictions:
            eviction = eviction_event_payload(
                lease,
                reason=(
                    "ttl_expired"
                    if now_wall - lease.last_used_at
                    >= reuse_config.ttl_seconds
                    else "lru_capacity"
                ),
                evicted_at=now_wall,
            )
            eviction.update(
                {
                    "type": "dynamic_workflow_worker_evicted",
                    "stage": stage_index,
                    **parent_event,
                }
            )
            self.bus.bridge_event(run_id, eviction)
            if parent_mode == "agi":
                self.bus.bridge_event(run_id, {
                    **eviction,
                    "type": "agi_workflow_evicted",
                    "nodeId": parent_node_id,
                    "phase": parent_phase,
                    "workflowId": workflow_id,
                })
        warm_leases = [
            lease
            for lease in updated_leases
            if lease.lease_id not in evicted_ids
        ]
        handle["_workflowWorkerLeases"] = warm_leases
        warm_pool = [
            {
                "leaseId": lease.lease_id,
                "logicalAgentId": lease.logical_agent.agent_id,
                "workerSession": lease.runtime.runtime_id,
                "provider": lease.fingerprint.provider,
                "model": lease.fingerprint.model,
                "role": lease.fingerprint.role,
                "skills": list(lease.fingerprint.skills),
                "lastTaskId": lease.last_task_id,
                "reuseCount": lease.reuse_count,
                "contextFraction": round(lease.context_fraction, 4),
                "expiresAt": datetime.fromtimestamp(
                    lease.last_used_at + reuse_config.ttl_seconds,
                    tz=timezone.utc,
                ).isoformat(),
                "processReuse": False,
                "candidateOnly": True,
                "canClaimAGI": False,
            }
            for lease in warm_leases
        ]
        if parent_mode == "agi":
            self.bus.bridge_event(run_id, {
                "type": "agi_workflow_warm_pool",
                "nodeId": parent_node_id,
                "phase": parent_phase,
                "workflowId": workflow_id,
                "stage": stage_index,
                "size": len(warm_pool),
                "leases": [
                    {
                        **lease,
                        "workerId": lease.get("workerSession"),
                        "status": "warm_idle",
                    }
                    for lease in warm_pool
                ],
                "candidateOnly": True,
                "canClaimAGI": False,
            })

        requested_agent_count = len(task_ids)
        stage_elapsed = max(0.0, time.monotonic() - stage_started)
        started_agent_count = sum(
            1 for result in results if bool(result.get("started"))
        )
        unstarted_agent_count = max(
            0,
            requested_agent_count - started_agent_count,
        )
        failure_codes = sorted({
            str(result.get("reasonCode") or "")
            for result in results
            if not result.get("ok") and result.get("reasonCode")
        })
        stage_contracts = [
            dict(contract)
            for contract in list(task_contracts or [])[:requested_agent_count]
            if isinstance(contract, dict)
        ]
        overlay_stage_results_from_receipts({
            "supervisorRunId": supervisor_run_id,
            "taskContracts": stage_contracts,
            "results": results,
        })
        for index, result in enumerate(results):
            contract = (
                stage_contracts[index]
                if index < len(stage_contracts)
                else {}
            )
            gaps = workflow_result_evidence_gaps(result, contract)
            result["evidenceComplete"] = not gaps
            if gaps:
                result["evidenceGaps"] = list(gaps)
            report_status = worker_report_status(result.get("finalText"))
            report_reason_code = (
                f"worker_report_{report_status}"
                if report_status in {"failed", "blocked", "partial"}
                else ""
            )
            if report_reason_code:
                report_error = (
                    f"worker report declared task status {report_status}"
                )
                result["ok"] = False
                result["status"] = "failed"
                result["reasonCode"] = report_reason_code
                result["workerReportStatus"] = report_status
                result["error"] = str(result.get("error") or report_error)
                found = agent_for_task(str(result.get("taskId") or ""))
                if found is not None:
                    _, agent = found
                    agent["status"] = "failed"
                    agent["reasonCode"] = report_reason_code
                    agent["workerReportStatus"] = report_status
                    agent["error"] = report_error
                    agent["summary"] = report_error
                    publish_orchestration(
                        orchestration.set_task_state(
                            str(result.get("taskId") or ""),
                            "failed",
                            summary=report_error,
                        )
                    )
                    publish_orchestration(
                        orchestration.update_agent_activity(
                            str(agent.get("agentId") or ""),
                            status="failed",
                            summary=report_error,
                            current_task_id="",
                            current_tool="",
                        )
                    )
                dispatch_manifest.update_assignment(
                    str(result.get("taskId") or ""),
                    status="failed",
                    phase="worker",
                    summary=report_error,
                    error=report_error,
                    worker_report_status=report_status,
                    provider_tool_mode=(
                        (
                            str(found[1].get("providerToolMode") or "")
                            if found is not None
                            else ""
                        )
                        or None
                    ),
                )
                self._publish_dispatch_manifest(handle)
            if result.get("ok") is True and result.get("status") == "succeeded":
                found = agent_for_task(str(result.get("taskId") or ""))
                if found is not None:
                    _, agent = found
                    agent["status"] = "succeeded"
                    agent["reasonCode"] = str(result.get("reasonCode") or "verified")
                    agent["error"] = ""
        authoritative_failures = {
            str(result.get("taskId") or "")
            for result in results
            if str(result.get("reasonCode") or "").startswith(
                "worker_report_"
            )
        }
        if authoritative_failures:
            warm_leases = [
                lease
                for lease in list(handle.get("_workflowWorkerLeases") or [])
                if str(getattr(lease, "last_task_id", "") or "")
                not in authoritative_failures
            ]
            handle["_workflowWorkerLeases"] = warm_leases
            warm_pool = [
                lease
                for lease in warm_pool
                if str(lease.get("lastTaskId") or "")
                not in authoritative_failures
            ]
        failure_codes = sorted({
            str(result.get("reasonCode") or "")
            for result in results
            if not result.get("ok") and result.get("reasonCode")
        })
        evidence_complete = workflow_stage_packet_complete({
            "taskContracts": stage_contracts,
            "results": results,
        })
        stage_ok = (
            all(result["ok"] for result in results)
            and evidence_complete
        )
        if (
            all(result["ok"] for result in results)
            and not evidence_complete
            and "evidence_incomplete" not in failure_codes
        ):
            failure_codes = sorted([*failure_codes, "evidence_incomplete"])
        self.bus.bridge_event(run_id, {
            "type": "a2a_supervisor_end",
            "supervisorRunId": supervisor_run_id,
            "workflowStage": stage_index,
            "workflowPattern": pattern,
            "state": supervisor_run.get("state"),
            "sequence": terminal_snapshot.get("sequence"),
            "canClaimAGI": False,
        })
        self.bus.bridge_event(run_id, {
            "type": "dynamic_workflow_stage_end",
            "stage": stage_index,
            "plannedStages": planned_stage_count,
            "pattern": pattern,
            "kind": stage_kind,
            "goal": stage_goal,
            "ok": stage_ok,
            "succeeded": sum(1 for result in results if result["ok"]),
            "failed": sum(1 for result in results if not result["ok"]),
            "fallbackExcluded": sum(
                1 for result in results if result["fallbackUsed"]
            ),
            "requestedAgentCount": requested_agent_count,
            "startedAgentCount": started_agent_count,
            "unstartedAgentCount": unstarted_agent_count,
            "timedOutAgentCount": sum(
                1
                for result in results
                if (
                    result["supervisorStatus"] == "timed_out"
                    or str(result.get("reasonCode") or "")
                    in {
                        "worker_inactivity_timeout",
                        "stage_hard_timeout",
                        "provider_timeout",
                    }
                )
            ),
            "elapsedSec": round(stage_elapsed, 1),
            "deadlineExtensionCount": deadline_extension_count,
            "timedOutAfterActiveProgress": bool(
                timed_out_after_active_progress
            ),
            "lastProgressAgeSec": (
                round(max(last_progress_age_at_timeout.values()), 1)
                if last_progress_age_at_timeout
                else None
            ),
            "totalWaves": max(
                1,
                math.ceil(
                    requested_agent_count / max(1, configured_concurrency)
                ),
            ),
            "failureCodes": failure_codes,
            "warmWorkers": warm_pool,
            "agents": agents,
            **parent_event,
            "orchestration": orchestration.snapshot(),
            "candidateOnly": True,
            "canClaimAGI": False,
        })
        stage_record = {
            "stage": stage_index,
            "plannedStages": planned_stage_count,
            "pattern": pattern,
            "kind": stage_kind,
            "goal": stage_goal,
            "status": "succeeded" if stage_ok else "failed",
            "requiresCritics": bool(requires_critics),
            "supervisorRunId": supervisor_run_id,
            "maxConcurrency": configured_concurrency,
            "providerConcurrencyCap": provider_concurrency_cap,
            "concurrencyReason": concurrency_reason,
            "expectedWaves": expected_waves,
            "hardTimeoutSec": hard_timeout,
            "controllerRequestedTaskCount": (
                controller_requested_task_count
                if controller_requested_task_count is not None
                else requested_agent_count
            ),
            "deferredTaskCount": max(0, int(deferred_task_count)),
            "requestedAgentCount": requested_agent_count,
            "startedAgentCount": started_agent_count,
            "unstartedAgentCount": unstarted_agent_count,
            "elapsedSec": round(stage_elapsed, 1),
            "deadlineExtensionCount": deadline_extension_count,
            "timedOutAfterActiveProgress": bool(
                timed_out_after_active_progress
            ),
            "lastProgressAgeSec": (
                round(max(last_progress_age_at_timeout.values()), 1)
                if last_progress_age_at_timeout
                else None
            ),
            "totalWaves": max(
                1,
                math.ceil(
                    requested_agent_count / max(1, configured_concurrency)
                ),
            ),
            "timedOutAgentCount": sum(
                1
                for result in results
                if (
                    result["supervisorStatus"] == "timed_out"
                    or str(result.get("reasonCode") or "")
                    in {
                        "worker_inactivity_timeout",
                        "stage_hard_timeout",
                        "provider_timeout",
                    }
                )
            ),
            "failureCodes": failure_codes,
            **(
                {"providerCircuit": dict(provider_circuit)}
                if provider_circuit is not None
                else {}
            ),
            "warmWorkers": warm_pool,
            "taskContracts": stage_contracts,
            "completionCriteria": [
                str(item)
                for item in list(completion_criteria or [])
                if str(item).strip()
            ],
            "agents": agents,
            "results": results,
        }
        live_stage_record.clear()
        live_stage_record.update(stage_record)
        persist_live_stage()
        orchestration.upsert_workflow_stage(stage_record)
        if parent_mode == "agi":
            self.bus.bridge_event(run_id, {
                "type": "agi_workflow_workflow_end",
                "nodeId": parent_node_id,
                "phase": parent_phase,
                "workflowId": workflow_id,
                "pattern": pattern,
                "stage": stage_index,
                "status": "succeeded" if stage_ok else "failed",
                "ok": stage_ok,
                "barrier": {
                    "stage": stage_index,
                    "status": "released" if stage_ok else "failed",
                    "completed": len(results),
                    "total": len(results),
                    "label": "stage barrier complete",
                },
                "agents": agents,
                "evidenceSummary": (
                    f"{sum(1 for result in results if result['ok'])}/"
                    f"{len(results)} usable worker reports"
                ),
                "candidateOnly": True,
                "canClaimAGI": False,
            })
        return stage_record

    def _ensure_dispatch_manifest(
        self,
        handle: dict[str, Any],
        *,
        session: str,
        mode: str,
        source_run_id: str = "",
    ) -> Any:
        """Create the mandatory live SMUX dispatch projection for a run.

        The manifest is deliberately independent from the richer A2A ledger:
        it is a compact, secret-free assignment/lifecycle contract that every
        dispatch mode can update.  TUI dispatch must persist it even when a
        caller disabled the legacy orchestration ledger, so this helper never
        consults ``persistOrchestration``.
        """
        existing = handle.get("_dispatchManifest")
        if existing is not None:
            return existing
        from agent.dispatch_manifest import DispatchManifest

        persist_manifest = bool(
            str(handle.get("session") or "").strip()
            or handle.get("persistDispatchManifest") is True
            or str(os.environ.get("SOPHIA_STATE_DIR") or "").strip()
        )
        manifest = DispatchManifest(
            session=session,
            run_id=str(handle.get("id") or ""),
            mode=mode,
            persist=persist_manifest,
            source_run_id=source_run_id,
        )
        handle["_dispatchManifest"] = manifest
        handle["dispatchManifestPath"] = (
            str(manifest.path) if manifest.persist else ""
        )
        manifest.set_status(
            "planning",
            phase="planning",
            source=mode,
            main_status="planning",
        )
        self.bus.bridge_event(
            str(handle.get("id") or ""),
            {
                **manifest.event_payload(),
                "manifestPath": (
                    str(manifest.path) if manifest.persist else ""
                ),
                "dispatchManifestPath": (
                    str(manifest.path) if manifest.persist else ""
                ),
            },
        )
        return manifest

    def _publish_dispatch_manifest(
        self,
        handle: dict[str, Any],
        *,
        snapshot: dict[str, Any] | None = None,
    ) -> None:
        manifest = handle.get("_dispatchManifest")
        if manifest is None:
            return
        payload = manifest.event_payload()
        if snapshot is not None:
            payload["manifestVersion"] = int(
                snapshot.get("version") or payload["manifestVersion"]
            )
            payload["status"] = str(
                snapshot.get("status") or payload["status"]
            )
            payload["phase"] = str(
                snapshot.get("phase") or payload["phase"]
            )
            payload["dispatch"] = dict(snapshot.get("dispatch") or {})
        payload.update(
            {
                "manifestPath": (
                    str(manifest.path) if manifest.persist else ""
                ),
                "dispatchManifestPath": (
                    str(manifest.path) if manifest.persist else ""
                ),
            }
        )
        self.bus.bridge_event(str(handle.get("id") or ""), payload)

    # -- A2A handoff ------------------------------------------------------- #
    def _run_a2a_chain(
        self,
        handle: dict,
        prompt: str,
        tee: _TokenTee,
        ctx: Any,
        sink: Callable[[dict], None],
        *,
        a2a_agents: int,
        max_steps: int,
        history: "list[dict] | None",
        show_thinking: bool,
        system_extra: str,
        budget: ExecutionBudget,
        raw_prompt: str | None = None,
        max_parallel_tools: int = 1,
        max_continuations: int | None = None,
        response_style: ResponseStyle = "adaptive",
        steering_consumer: Any = None,
        require_live_refresh: bool = False,
        execution: str = "embedded",
        terminal_layout: str = "auto",
        model_alias: str = "mock",
        mode: str = "balanced",
        permission: str = "approve",
        session: str = "code-default",
        root: Path | None = None,
        local_model: bool = True,
    ) -> Any:
        """Main plans/dispatches N subs (LLM-chosen), then Main verifies+synthesizes."""
        from agent.a2a_handoff import (
            A2A_AUTO,
            A2AAgentLive,
            DEFAULT_MAIN_NAME,
            DEFAULT_MAIN_VERIFY_NAME,
            MAX_A2A_SUB_AGENTS_SAFETY,
            build_output_contract_repair_prompt,
            build_sub_agent_prompt,
            build_verify_synthesis_prompt,
            initial_main_only,
            collect_dispatch_source_text,
            main_agent_plan_system_extra,
            parse_dispatch_plan,
            resolve_dispatch_assignments,
            sub_agent_name,
        )
        from agent.agent_loop import AgentLoopResult, run_agent_loop
        from agent.agent_tools import all_tools
        from agent.a2a_orchestration import (
            A2AOrchestrationLedger,
            should_persist_orchestration,
        )

        run_id = handle["id"]
        cancel: threading.Event = handle["cancel"]
        handle["a2aExecution"] = execution
        handle["a2aMaxConcurrency"] = 1
        auto = a2a_agents == A2A_AUTO or a2a_agents < 0
        # Fixed legacy: a2a_agents is total Main+subs → max_subs = n-1.
        max_subs = (
            MAX_A2A_SUB_AGENTS_SAFETY
            if auto
            else max(0, min(MAX_A2A_SUB_AGENTS_SAFETY, int(a2a_agents) - 1))
        )
        a2a_session_for_persist = str(handle.get("session") or "")
        default_session = str(CODE_DEFAULTS.get("session") or "code-default")
        if (
            not a2a_session_for_persist
            and session
            and session != default_session
        ):
            a2a_session_for_persist = session
        orchestration = A2AOrchestrationLedger(
            session=session,
            run_id=run_id,
            mode="a2a",
            persist=should_persist_orchestration(
                session=a2a_session_for_persist,
                run_id=str(run_id or ""),
                persist_flag=handle.get("persistOrchestration"),
            ),
        )
        handle["a2aOrchestrationPath"] = (
            str(orchestration.path) if orchestration.persist else ""
        )
        dispatch_manifest = self._ensure_dispatch_manifest(
            handle,
            session=session,
            mode="a2a",
        )
        dispatch_manifest.set_status(
            "planning",
            phase="planning",
            main_status="planning",
        )
        self._publish_dispatch_manifest(handle)

        def _publish_orchestration(snapshot: dict[str, Any] | None = None) -> None:
            self.bus.bridge_event(run_id, {
                "type": "a2a_orchestration_snapshot",
                "orchestration": snapshot or orchestration.snapshot(),
                "canClaimAGI": False,
            })

        _publish_orchestration(
            orchestration.upsert_agent(
                agent_id="main",
                name=DEFAULT_MAIN_NAME,
                status="queued",
                source="local",
                protocol="claude-native",
                role="coordinator",
                capabilities={
                    "taskBoard": True,
                    "mailbox": True,
                    "synthesis": True,
                },
                connected=True,
            )
        )
        _publish_orchestration(
            orchestration.append_message(
                kind="human",
                sender="operator",
                recipient=DEFAULT_MAIN_NAME,
                summary="Operator goal",
                body=raw_prompt or prompt,
                trusted=True,
            )
        )
        _publish_orchestration(
            orchestration.upsert_task(
                task_id=f"{run_id}-main-plan",
                subject="Plan and dispatch",
                description="Decompose the operator goal into self-contained worker contracts.",
                state="submitted",
                owner_id="main",
                done_criteria=(
                    "Choose the smallest useful worker set.",
                    "Emit a parseable DISPATCH block with self-contained tasks.",
                ),
                expected_output="Coordinator DISPATCH plan.",
            )
        )

        live: list[A2AAgentLive] = initial_main_only()
        self.bus.bridge_event(run_id, {
            "type": "a2a_chain_start",
            "mode": "auto" if auto else "fixed",
            "execution": execution,
            "terminalLayout": terminal_layout,
            "agents": [a.to_dict() for a in live],
            "count": len(live),
            "maxSubsSafety": MAX_A2A_SUB_AGENTS_SAFETY,
            "orchestration": orchestration.snapshot(),
            "canClaimAGI": False,
        })
        self._emit_goal_update(
            handle,
            goal="Plan the request and define self-contained sub-agent work.",
            source="a2a-plan",
            reason="Main is deciding whether delegation is useful",
            current_stage=1,
            planned_stages=3,
            max_stages=3,
        )

        all_steps: list[dict[str, Any]] = []
        chain_ok = True
        model_error = ""
        last_res: Any = None
        # A2A is bridge-owned orchestration: Main emits a DISPATCH plan, the
        # bridge runs each sub-agent sequentially, then Main verifies. Exposing
        # the generic delegate tool inside any phase lets a model start a second,
        # nested orchestration path (and in readonly mode it fails before the
        # bridge can parse DISPATCH). Preserve every caller/lane restriction but
        # remove delegate from the A2A surface for all phases.
        inherited_scope = getattr(ctx, "allowed_tools", None)
        a2a_tool_scope = (
            set(all_tools())
            if inherited_scope is None
            else set(inherited_scope)
        )
        a2a_tool_scope.discard("delegate")
        if str(permission or "").lower() == "readonly":
            a2a_tool_scope.intersection_update(
                _READ_ONLY_REPOSITORY_REVIEW_TOOLS
            )

        def _mark_active(idx: int) -> None:
            for j, agent in enumerate(live):
                agent.active = j == idx
                if j == idx:
                    agent.status = "running"

        def _emit_agents(kind: str, **extra: Any) -> None:
            self.bus.bridge_event(run_id, {
                "type": kind,
                "agents": [a.to_dict() for a in live],
                "orchestration": orchestration.snapshot(),
                "canClaimAGI": False,
                **extra,
            })

        def _run_one(
            *,
            name: str,
            agent_prompt: str,
            extra: str,
            agent_history: "list[dict] | None",
            raw_turn: str,
            use_steering: bool,
            use_refresh: bool,
            internal_artifact: bool,
            agent_id: str,
            task_id: str,
            allowed_tools: set[str] | None = None,
            allow_continuation_nudges: bool = True,
            final_event_buffer: list[dict[str, Any]] | None = None,
        ) -> Any:
            nonlocal last_res
            if cancel.is_set():
                raise _RunCancelled()
            self.bus.bridge_event(run_id, {
                "type": "assistant_message",
                "text": f"▶ {name} is now active",
                "ok": True,
                "agent": name,
            })
            _publish_orchestration(
                orchestration.update_agent_activity(
                    agent_id,
                    status="working",
                    current_task_id=task_id,
                    current_tool="",
                )
            )
            _publish_orchestration(
                orchestration.set_task_state(task_id, "working")
            )
            prior_scope = getattr(ctx, "allowed_tools", None)
            ctx.allowed_tools = (
                set(a2a_tool_scope)
                if allowed_tools is None
                else set(allowed_tools) & set(a2a_tool_scope)
            )
            try:
                def phase_sink(event: dict[str, Any]) -> None:
                    event_type = str(event.get("type") or "")
                    if event_type in {
                        "tool_call",
                        "tool_result",
                        "tool_wait",
                        "provider_wait",
                    }:
                        tool = str(
                            event.get("tool")
                            or event.get("name")
                            or (
                                "provider"
                                if event_type == "provider_wait"
                                else ""
                            )
                        )
                        _publish_orchestration(
                            orchestration.update_agent_activity(
                                agent_id,
                                status=(
                                    "waiting_input"
                                    if event_type == "tool_wait"
                                    else "working"
                                ),
                                current_task_id=task_id,
                                current_tool=tool,
                                summary=event_type.replace("_", " "),
                            )
                        )
                    # Internal phase terminal previews are not operator-facing
                    # answers. Keep them in each phase trace, but do not let the
                    # outer bridge publish them alongside the final gated Main
                    # verification result.
                    if (
                        internal_artifact
                        and str(event.get("type") or "") == "final"
                    ):
                        return
                    if (
                        final_event_buffer is not None
                        and str(event.get("type") or "") == "final"
                    ):
                        final_event_buffer.append(dict(event))
                        return
                    sink(event)

                res = run_agent_loop(
                    agent_prompt,
                    client=tee,
                    ctx=ctx,
                    history=agent_history,
                    on_event=phase_sink,
                    max_steps=max_steps,
                    system_extra=extra,
                    show_thinking=show_thinking,
                    steering_consumer=steering_consumer if use_steering else None,
                    budget=budget,
                    max_parallel_tools=max_parallel_tools,
                    post_tool_continuity=True,
                    allow_continuation_nudges=allow_continuation_nudges,
                    max_continuations=max_continuations,
                    raw_user_turn=raw_turn,
                    current_task=agent_prompt,
                    response_style=response_style,
                    require_live_refresh=use_refresh,
                    defer_delivery_gate=internal_artifact,
                )
            finally:
                ctx.allowed_tools = prior_scope
            last_res = res
            result_ok = bool(getattr(res, "ok", False)) and not str(
                getattr(res, "model_error", "") or ""
            )
            token_usage = {
                key: int(value)
                for key, value in {
                    "prompt": getattr(res, "prompt_tokens", None),
                    "completion": getattr(res, "completion_tokens", None),
                }.items()
                if isinstance(value, int)
            }
            _publish_orchestration(
                orchestration.update_agent_activity(
                    agent_id,
                    status="idle" if result_ok else "failed",
                    current_task_id="",
                    current_tool="",
                    token_usage=token_usage,
                    summary=str(getattr(res, "final_text", "") or "")[:500],
                )
            )
            _publish_orchestration(
                orchestration.set_task_state(
                    task_id,
                    "completed" if result_ok else "failed",
                    summary=str(getattr(res, "final_text", "") or "")[:500],
                )
            )
            for step in list(getattr(res, "steps", None) or []):
                all_steps.append(dict(step) if isinstance(step, dict) else step)
            return res

        # ── 1) Main Agent plan + DISPATCH ─────────────────────────────────
        _mark_active(0)
        _emit_agents(
            "a2a_agent_start",
            index=0,
            name=DEFAULT_MAIN_NAME,
            agent=live[0].to_dict(),
            phase="plan",
        )
        plan_extra = (system_extra or "").strip()
        plan_extra = (
            plan_extra + "\n\n" + main_agent_plan_system_extra()
        ).strip() if plan_extra else main_agent_plan_system_extra()
        if not auto and max_subs > 0:
            plan_extra += (
                f"\nPreferred sub-agent count for this run: up to {max_subs} "
                f"(you may use fewer)."
            )
        main_res = _run_one(
            name=DEFAULT_MAIN_NAME,
            agent_prompt=prompt,
            extra=plan_extra,
            agent_history=history,
            raw_turn=raw_prompt or prompt,
            use_steering=True,
            use_refresh=require_live_refresh,
            internal_artifact=True,
            agent_id="main",
            task_id=f"{run_id}-main-plan",
            # The planner's DISPATCH block is a structured terminal artifact.
            # Generic intent nudges mistake words such as "dispatch" and
            # "next" for unfinished prose, which can make a provider repeat
            # the same plan indefinitely instead of handing it to the bridge.
            allow_continuation_nudges=False,
        )
        main_text = str(getattr(main_res, "final_text", "") or "").strip()
        # DISPATCH often appears mid-transcript while final_text is only a short
        # "stopping here" coda. Parse the full Main transcript for the block.
        main_dispatch_src = collect_dispatch_source_text(
            main_text,
            messages=list(getattr(main_res, "messages", None) or []),
            steps=list(getattr(main_res, "steps", None) or []),
        )
        main_ok = bool(getattr(main_res, "ok", False)) and not str(
            getattr(main_res, "model_error", "") or ""
        )
        live[0].status = "succeeded" if main_ok else "failed"
        live[0].active = False
        live[0].summary = (main_text[:160] + "…") if len(main_text) > 160 else main_text
        if not main_ok:
            chain_ok = False
            model_error = str(getattr(main_res, "model_error", "") or "Main Agent failed")
        _emit_agents(
            "a2a_agent_end",
            index=0,
            name=DEFAULT_MAIN_NAME,
            agent=live[0].to_dict(),
            ok=main_ok,
            answerChars=len(main_text),
            phase="plan",
        )

        plan = parse_dispatch_plan(
            main_dispatch_src,
            max_subs=max_subs if max_subs > 0 else MAX_A2A_SUB_AGENTS_SAFETY,
        )
        if plan.sub_count == 0 and main_text and main_dispatch_src != main_text:
            # Last-chance: parse final alone (already tried via collect) — keep event honest.
            pass
        self.bus.bridge_event(run_id, {
            "type": "a2a_dispatch_parse",
            "source": plan.source,
            "subCount": plan.sub_count,
            "finalChars": len(main_text),
            "dispatchSrcChars": len(main_dispatch_src),
            "usedTranscript": main_dispatch_src != main_text,
            "canClaimAGI": False,
        })
        # Safety clamp (product has no advertised limit; this is runaway guard only).
        tasks = list(plan.tasks)[:MAX_A2A_SUB_AGENTS_SAFETY]
        # Resolve persona ROLE + auto-attach SKILLs for each dispatched task.
        assignments = resolve_dispatch_assignments(tasks) if tasks else []
        assignment_scopes = [
            set(asn.allowed_tools) & set(a2a_tool_scope)
            for asn in assignments
        ]
        dispatch_manifest.set_status(
            "dispatching",
            phase="dispatching",
            source="a2a",
            main_status="dispatching",
        )
        self._publish_dispatch_manifest(handle)
        logical_task_ids = [
            f"{run_id}-sub-{index + 1}" for index in range(len(tasks))
        ]
        _publish_orchestration(
            orchestration.append_message(
                kind="coordinator",
                sender=DEFAULT_MAIN_NAME,
                recipient="A2A harness",
                summary=f"Dispatch plan · {len(tasks)} worker(s)",
                body=main_dispatch_src or main_text,
                task_id=f"{run_id}-main-plan",
                trusted=True,
            )
        )
        for index, task in enumerate(tasks):
            asn = assignments[index] if index < len(assignments) else None
            name = sub_agent_name(index + 1)
            agent_id = f"sub-{index + 1}"
            _publish_orchestration(
                orchestration.upsert_agent(
                    agent_id=agent_id,
                    name=name,
                    status="queued",
                    source="local",
                    protocol="claude-native",
                    role=asn.persona_id if asn else "worker",
                    skills=list(asn.skill_names) if asn else (),
                    capabilities={
                        "streaming": True,
                        "recursiveDelegation": False,
                    },
                    connected=True,
                    current_task_id=logical_task_ids[index],
                    summary=asn.task if asn else task,
                )
            )
            dependency_ids = [
                logical_task_ids[item - 1]
                for item in (asn.depends_on if asn else ())
                if 1 <= item <= len(logical_task_ids)
            ]
            _publish_orchestration(
                orchestration.upsert_task(
                    task_id=logical_task_ids[index],
                    subject=name,
                    description=asn.task if asn else task,
                    state="blocked" if dependency_ids else "queued",
                    owner_id=agent_id,
                    blocked_by=dependency_ids,
                    done_criteria=(
                        "Complete only the assigned scope.",
                        "Return native-tool evidence or explicitly state uncertainty.",
                        "Return the required WORKER_REPORT envelope.",
                    ),
                    expected_output="Structured WORKER_REPORT for Main verification.",
                )
            )
            _publish_orchestration(
                orchestration.append_message(
                    kind="coordinator",
                    sender=DEFAULT_MAIN_NAME,
                    recipient=name,
                    summary=f"Assigned · {name}",
                    body=asn.task if asn else task,
                    task_id=logical_task_ids[index],
                    trusted=True,
                )
            )
            if asn is not None:
                dispatch_manifest.register_assignment(
                    assignment_id=logical_task_ids[index],
                    agent_id=agent_id,
                    task_id=logical_task_ids[index],
                    name=name,
                    task=asn.task,
                    phase="dispatching",
                    status="blocked" if dependency_ids else "queued",
                    persona_id=asn.persona_id,
                    persona_name=asn.persona_name,
                    persona_discipline=asn.persona_discipline,
                    persona_via=asn.persona_via,
                    skills=asn.skill_names,
                    skill_via=asn.skill_via,
                    allowed_tools=assignment_scopes[index],
                    tool_scope_via=asn.tool_scope_via,
                    permission=permission,
                    execution=execution,
                    provider=str(model_alias).split(":", 1)[0],
                    model=model_alias,
                    dependencies=dependency_ids,
                )
        self._publish_dispatch_manifest(handle)
        self.bus.bridge_event(run_id, {
            "type": "a2a_dispatch",
            "source": plan.source,
            "subCount": len(tasks),
            "tasks": [
                {
                    "name": sub_agent_name(i + 1),
                    "task": (assignments[i].task if i < len(assignments) else t)[:300],
                    "personaId": assignments[i].persona_id if i < len(assignments) else "",
                    "personaName": assignments[i].persona_name if i < len(assignments) else "",
                    "personaVia": assignments[i].persona_via if i < len(assignments) else "none",
                    "skills": list(assignments[i].skill_names) if i < len(assignments) else [],
                    "skillVia": list(assignments[i].skill_via) if i < len(assignments) else [],
                    "allowedTools": sorted(assignment_scopes[i]) if i < len(assignment_scopes) else [],
                    "toolScopeVia": assignments[i].tool_scope_via if i < len(assignments) else "none",
                    "dependsOn": list(assignments[i].depends_on) if i < len(assignments) else [],
                }
                for i, t in enumerate(tasks)
            ],
            "orchestration": orchestration.snapshot(),
            "canClaimAGI": False,
        })
        if tasks:
            self._emit_goal_update(
                handle,
                goal=(
                    f"Complete {len(tasks)} delegated task"
                    f"{'' if len(tasks) == 1 else 's'} and collect the reports."
                ),
                source="a2a-workers",
                reason=f"Main dispatched {len(tasks)} self-contained task(s)",
                current_stage=2,
                planned_stages=3,
                max_stages=3,
            )
        for i, asn in enumerate(assignments):
            self.bus.bridge_event(run_id, {
                "type": "a2a_harness_select",
                "subName": sub_agent_name(i + 1),
                "index": i + 1,
                **asn.to_dict(),
            })
            for sk_name, sk_via in zip(asn.skill_names, asn.skill_via):
                skill_payload: dict[str, Any] = {
                    "type": "skill",
                    "name": sk_name,
                    "found": True,
                    "via": sk_via,
                    "agent": sub_agent_name(i + 1),
                    "phase": "a2a_sub",
                    "canClaimAGI": False,
                }
                try:
                    from agent import skills as skill_registry
                    sk = skill_registry.get(sk_name)
                    if sk:
                        skill_payload["whenToUse"] = _safe_text(
                            sk.get("whenToUse"), limit=400,
                        )
                        skill_payload["steps"] = len(sk.get("workflow") or [])
                except Exception:  # noqa: BLE001 - chrome only
                    pass
                self.bus.bridge_event(run_id, skill_payload)

        # Extend live agent list with queued subs.
        for i, task in enumerate(tasks):
            asn = assignments[i] if i < len(assignments) else None
            summary = (asn.task if asn else task)[:120]
            if asn and (asn.persona_id or asn.skill_names):
                bits = []
                if asn.persona_id:
                    bits.append(f"role:{asn.persona_id}")
                if asn.skill_names:
                    bits.append("skills:" + ",".join(asn.skill_names))
                summary = f"[{' | '.join(bits)}] {summary}"[:160]
            live.append(
                A2AAgentLive(
                    name=sub_agent_name(i + 1),
                    index=len(live),
                    status="queued",
                    active=False,
                    role="sub",
                    summary=summary,
                    persona=asn.persona_id if asn else "",
                    skills=list(asn.skill_names) if asn else [],
                    skillVia=list(asn.skill_via) if asn else [],
                    allowedTools=(
                        sorted(assignment_scopes[i])
                        if i < len(assignment_scopes)
                        else []
                    ),
                    toolScopeVia=(
                        asn.tool_scope_via if asn is not None else "none"
                    ),
                )
            )
        if tasks:
            _emit_agents("a2a_chain_start", count=len(live), mode="auto" if auto else "fixed")

        # ── 2) Sub agents (Main-chosen tasks) ─────────────────────────────
        sub_results: list[tuple[str, str]] = []
        supervised = execution in {"terminal", "headless"}
        if main_ok and supervised and tasks:
            from agent.session_supervisor import (
                SessionSupervisorClient,
                TERMINAL_STATES as SUPERVISOR_TERMINAL_STATES,
                _atomic_json as _write_supervised_json,
            )

            workspace = (root or Path(ctx.root)).expanduser().resolve()
            client = SessionSupervisorClient()
            hello = client.ensure_running()
            supervisor_run_id = f"{run_id}-a2a-{uuid.uuid4().hex[:8]}"
            handle["supervisorRunId"] = supervisor_run_id
            task_ids = list(logical_task_ids)
            run_root = client.state_dir / "runs" / supervisor_run_id
            run_root.mkdir(parents=True, exist_ok=False, mode=0o700)
            os.chmod(run_root, 0o700)
            submitted_tasks: list[dict[str, Any]] = []
            for i, task in enumerate(tasks):
                name = live[i + 1].name
                asn = assignments[i] if i < len(assignments) else None
                clean_task = asn.task if asn else task
                agent_prompt = build_sub_agent_prompt(
                    original_goal=prompt,
                    sub_name=name,
                    task=clean_task,
                    sub_index=i + 1,
                    total_subs=len(tasks),
                    main_context=main_text,
                    persona_name=asn.persona_name if asn else "",
                    persona_id=asn.persona_id if asn else "",
                    skill_names=list(asn.skill_names) if asn else (),
                    done_criteria=(
                        "Produce evidence that Main can independently verify.",
                        "Return the required WORKER_REPORT envelope.",
                    ),
                    expected_output="Structured WORKER_REPORT for Main verification.",
                )
                sub_extra = (system_extra or "").strip()
                if asn and asn.system_extra:
                    sub_extra = (
                        f"{sub_extra}\n\n{asn.system_extra}".strip()
                        if sub_extra
                        else asn.system_extra
                    )
                if sub_extra:
                    agent_prompt = (
                        f"{agent_prompt}\n\n"
                        "Additional harness constraints for this worker:\n"
                        f"{sub_extra}"
                    )
                self.bus.bridge_event(run_id, {
                    "type": "a2a_handoff",
                    "from": DEFAULT_MAIN_NAME,
                    "to": name,
                    "promptChars": len(agent_prompt),
                    "promptPreview": clean_task[:400],
                    "personaId": asn.persona_id if asn else "",
                    "skills": list(asn.skill_names) if asn else [],
                    "allowedTools": sorted(assignment_scopes[i]) if i < len(assignment_scopes) else [],
                    "toolScopeVia": asn.tool_scope_via if asn else "none",
                    "dependsOn": list(asn.depends_on) if asn else [],
                    "execution": execution,
                    "orchestration": orchestration.snapshot(),
                    "canClaimAGI": False,
                })
                task_id = task_ids[i]
                task_root = run_root / task_id
                task_root.mkdir(mode=0o700)
                spec_path = task_root / "worker-spec.json"
                result_path = task_root / "result.json"
                worker_session = _normalize_session(
                    f"{session}-a2a-{run_id[-8:]}-{i + 1}"
                )
                worker_spec = {
                    "schema": "sophia.supervised-worker-spec.v1",
                    "runId": supervisor_run_id,
                    "taskId": task_id,
                    "name": name,
                    "command": {
                        "prompt": agent_prompt,
                        "model": model_alias,
                        "mode": mode,
                        "permission": permission,
                        "conscienceMode": _normalize_conscience_mode(
                            getattr(ctx, "conscience_mode", None)
                            or CODE_DEFAULTS["conscienceMode"]
                        ),
                        "session": worker_session,
                        "cwd": str(workspace),
                        "maxSteps": max_steps,
                        "allowedTools": (
                            sorted(assignment_scopes[i])
                            if i < len(assignment_scopes)
                            else []
                        ),
                        "deepThink": show_thinking,
                        "responseStyle": response_style,
                        "sophiaContract": True,
                    },
                    "canClaimAGI": False,
                }
                _write_supervised_json(spec_path, worker_spec)
                dispatch_manifest.update_assignment(
                    task_id,
                    status="spawning",
                    phase="dispatching",
                    receipt_path=str(result_path),
                    receipt_run_id=supervisor_run_id,
                )
                self._publish_dispatch_manifest(handle)
                dependencies = [
                    task_ids[item - 1]
                    for item in (asn.depends_on if asn else ())
                    if 1 <= item <= len(task_ids)
                ]
                inherited_pythonpath = os.environ.get("PYTHONPATH", "")
                explicit_pythonpath = str(_repo_root())
                if inherited_pythonpath:
                    explicit_pythonpath += os.pathsep + inherited_pythonpath
                packaged_worker = os.environ.get(
                    "SOPHIA_SESSION_WORKER_EXECUTABLE", ""
                ).strip()
                if packaged_worker:
                    worker_executable = Path(packaged_worker).expanduser().resolve()
                    if (
                        not worker_executable.is_file()
                        or not os.access(worker_executable, os.X_OK)
                    ):
                        raise RuntimeError(
                            "SOPHIA_SESSION_WORKER_EXECUTABLE must name an "
                            "executable regular file"
                        )
                    worker_argv = [
                        str(worker_executable),
                        "--spec",
                        str(spec_path),
                        "--result",
                        str(result_path),
                    ]
                    worker_env = _supervised_worker_env()
                else:
                    worker_argv = [
                        sys.executable,
                        "-P",
                        "-m",
                        "agent.session_worker",
                        "--spec",
                        str(spec_path),
                        "--result",
                        str(result_path),
                    ]
                    worker_env = _supervised_worker_env({
                        "PYTHONPATH": explicit_pythonpath,
                    })
                submitted_tasks.append(
                    {
                        "taskId": task_id,
                        "name": name,
                        "argv": worker_argv,
                        "cwd": str(workspace),
                        "receiptPath": str(result_path),
                        "dependencies": dependencies,
                        "surfaceMode": terminal_layout,
                        "env": worker_env,
                    }
                )

            configured_concurrency = (
                1
                if local_model
                else min(4, len(submitted_tasks))
            )
            if local_model:
                configured_concurrency = max(
                    1,
                    min(
                        len(submitted_tasks),
                        _safe_int(
                            os.environ.get("SOPHIA_LOCAL_AGENT_CONCURRENCY"),
                            1,
                        ),
                    ),
                )
            if budget.max_concurrency is not None:
                configured_concurrency = max(
                    1,
                    min(configured_concurrency, int(budget.max_concurrency)),
                )
            handle["a2aMaxConcurrency"] = configured_concurrency
            client.submit(
                run_id=supervisor_run_id,
                tasks=submitted_tasks,
                max_concurrency=configured_concurrency,
            )
            self.bus.bridge_event(run_id, {
                "type": "a2a_supervisor_start",
                "supervisorRunId": supervisor_run_id,
                "socketPath": str(client.socket_path),
                "execution": execution,
                "terminalLayout": terminal_layout,
                "maxConcurrency": configured_concurrency,
                "workerContinuity": True,
                "mainVerifierContinuity": False,
                "canClaimAGI": False,
            })
            sequence = int(hello.get("sequence") or 0)
            started_tasks: set[str] = set()
            terminal_snapshot: dict[str, Any] = {}
            while True:
                if cancel.is_set():
                    if str(handle.get("cancelReason") or "") != "backend_exit":
                        client.cancel_run(supervisor_run_id)
                    else:
                        self.bus.bridge_event(run_id, {
                            "type": "a2a_supervisor_detached",
                            "supervisorRunId": supervisor_run_id,
                            "reason": "bridge exited; workers continue headlessly",
                            "mainVerifierPending": True,
                            "canClaimAGI": False,
                        })
                    raise _RunCancelled()
                for event in client.replay(after=sequence, run_id=supervisor_run_id):
                    sequence = max(sequence, int(event.get("sequence") or 0))
                    event_type = str(event.get("type") or "")
                    task_id = str(event.get("taskId") or "")
                    if event_type == "surface.created":
                        self.bus.bridge_event(run_id, {
                            "type": "terminal_surface_created",
                            "supervisorRunId": supervisor_run_id,
                            "taskId": task_id,
                            "surfaceId": event.get("surfaceId"),
                            "name": event.get("name"),
                            "state": event.get("state"),
                            "terminalLayout": terminal_layout,
                            "canClaimAGI": False,
                        })
                    elif event_type == "surface.output":
                        self.bus.bridge_event(run_id, {
                            "type": "terminal_output",
                            "supervisorRunId": supervisor_run_id,
                            "taskId": task_id,
                            "surfaceId": event.get("surfaceId"),
                            "text": event.get("text") or "",
                            "canClaimAGI": False,
                        })
                    elif event_type == "task.worker_event":
                        worker_event = event.get("workerEvent")
                        try:
                            worker_index = task_ids.index(task_id)
                        except ValueError:
                            worker_index = -1
                        if isinstance(worker_event, dict) and worker_index >= 0:
                            worker_type = str(worker_event.get("type") or "")
                            if (
                                worker_type == "task.progress"
                                and str(worker_event.get("eventType") or "")
                                == "provider_wait"
                            ):
                                # A2A supervised workers also bypass the root
                                # TokenTee while they run under sessiond.
                                self._refresh_run_eta_on_provider_wait(handle)
                            _publish_orchestration(
                                orchestration.update_agent_activity(
                                    f"sub-{worker_index + 1}",
                                    status=(
                                        "waiting_input"
                                        if worker_type == "task.waiting_input"
                                        else "working"
                                    ),
                                    current_task_id=task_id,
                                    current_tool=str(
                                        worker_event.get("tool")
                                        or worker_event.get("name")
                                        or ""
                                    ),
                                    summary=worker_type.replace("_", " "),
                                )
                            )
                        if (
                            isinstance(worker_event, dict)
                            and worker_event.get("type") == "task.waiting_input"
                            and isinstance(worker_event.get("approval"), dict)
                        ):
                            approval = dict(worker_event["approval"])
                            worker_approval_id = str(approval.get("id") or "")
                            external_id = (
                                f"sup-{uuid.uuid4().hex[:10]}"
                            )
                            with self.approvals_lock:
                                self.supervisor_approvals[external_id] = {
                                    "client": client,
                                    "runId": supervisor_run_id,
                                    "taskId": task_id,
                                    "workerApprovalId": worker_approval_id,
                                }
                            self.emit({
                                "type": "approval_request",
                                "runId": run_id,
                                "id": external_id,
                                "tool": approval.get("tool") or "supervised worker",
                                "preview": approval.get("preview") or "",
                                "agentTaskId": task_id,
                                "supervisorRunId": supervisor_run_id,
                                "ts": _now_iso(),
                                "canClaimAGI": False,
                            })
                            _publish_orchestration(
                                orchestration.set_task_state(
                                    task_id,
                                    "waiting_input",
                                    summary=str(
                                        approval.get("preview")
                                        or "Human approval required"
                                    ),
                                )
                            )
                            _publish_orchestration(
                                orchestration.append_message(
                                    kind="task_notification",
                                    sender=(
                                        live[worker_index + 1].name
                                        if worker_index >= 0
                                        else "worker"
                                    ),
                                    recipient="operator",
                                    summary="Approval required",
                                    body=str(approval.get("preview") or ""),
                                    task_id=task_id,
                                    trusted=False,
                                )
                            )
                    elif event_type == "task.state_changed":
                        state = str(event.get("state") or "")
                        try:
                            sub_index = task_ids.index(task_id) + 1
                        except ValueError:
                            continue
                        if task_id not in started_tasks and state in {
                            "spawning", "running", "waiting_input", "verifying"
                        }:
                            started_tasks.add(task_id)
                            _emit_agents(
                                "a2a_agent_start",
                                index=sub_index,
                                name=live[sub_index].name,
                                agent=live[sub_index].to_dict(),
                                phase="sub",
                                execution=execution,
                            )
                        live[sub_index].status = state
                        live[sub_index].active = state in {
                            "spawning", "running", "waiting_input", "verifying"
                        }
                        dispatch_manifest.update_assignment(
                            task_id,
                            status=state,
                            phase="worker",
                        )
                        self._publish_dispatch_manifest(handle)
                        _publish_orchestration(
                            orchestration.set_task_state(
                                task_id,
                                state,
                                summary=str(
                                    dict(event.get("detail") or {}).get("reason")
                                    or ""
                                ),
                            )
                        )
                        _emit_agents(
                            "a2a_task_state",
                            index=sub_index,
                            taskId=task_id,
                            supervisorRunId=supervisor_run_id,
                            state=state,
                            detail=dict(event.get("detail") or {}),
                        )
                terminal_snapshot = client.snapshot(supervisor_run_id)
                supervisor_run = dict(
                    terminal_snapshot.get("runs", {}).get(supervisor_run_id) or {}
                )
                if str(supervisor_run.get("state") or "") in {
                    "succeeded", "failed", "cancelled", "needs_reconciliation"
                }:
                    break
                time.sleep(0.1)

            supervisor_run = dict(
                terminal_snapshot.get("runs", {}).get(supervisor_run_id) or {}
            )
            terminal_tasks = dict(supervisor_run.get("tasks") or {})
            for i, task_id in enumerate(task_ids):
                sub_idx = i + 1
                name = live[sub_idx].name
                task_snapshot = dict(terminal_tasks.get(task_id) or {})
                state = str(task_snapshot.get("state") or "lost")
                detail = dict(task_snapshot.get("detail") or {})
                task_result = dict(detail.get("result") or {})
                sub_text = str(task_result.get("finalText") or "").strip()
                sub_results.append((name, sub_text))
                for step in list(task_result.get("steps") or []):
                    all_steps.append(dict(step) if isinstance(step, dict) else step)
                sub_ok = state == "succeeded"
                live[sub_idx].status = state
                live[sub_idx].active = False
                live[sub_idx].summary = (
                    (sub_text[:160] + "…") if len(sub_text) > 160
                    else sub_text or str(detail.get("reason") or state)
                )
                dispatch_manifest.update_assignment(
                    task_id,
                    status=(
                        "succeeded"
                        if sub_ok
                        else (
                            "cancelled"
                            if state == "cancelled"
                            else "timed_out"
                            if state == "timed_out"
                            else "failed"
                        )
                    ),
                    phase="worker",
                    summary=live[sub_idx].summary,
                    error=(
                        str(
                            task_result.get("modelError")
                            or detail.get("reason")
                            or ""
                        )
                        if not sub_ok
                        else None
                    ),
                    receipt_path=str(
                        (
                            submitted_tasks[i].get("receiptPath")
                            if i < len(submitted_tasks)
                            else ""
                        )
                        or ""
                    ),
                    receipt_run_id=supervisor_run_id,
                )
                self._publish_dispatch_manifest(handle)
                if not sub_ok:
                    chain_ok = False
                    model_error = str(
                        task_result.get("modelError")
                        or detail.get("reason")
                        or f"{name} ended {state}"
                    )
                _publish_orchestration(
                    orchestration.set_task_state(
                        task_id,
                        state,
                        summary=live[sub_idx].summary,
                    )
                )
                _publish_orchestration(
                    orchestration.append_message(
                        kind="worker_result",
                        sender=name,
                        recipient=DEFAULT_MAIN_VERIFY_NAME,
                        summary=f"{name} · {state}",
                        body=sub_text or str(detail.get("reason") or state),
                        task_id=task_id,
                        trusted=False,
                    )
                )
                _emit_agents(
                    "a2a_agent_end",
                    index=sub_idx,
                    name=name,
                    taskId=task_id,
                    supervisorRunId=supervisor_run_id,
                    agent=live[sub_idx].to_dict(),
                    ok=sub_ok,
                    state=state,
                    answerChars=len(sub_text),
                    phase="sub",
                    execution=execution,
                )
                with self.approvals_lock:
                    stale = [
                        approval_id
                        for approval_id, pending in self.supervisor_approvals.items()
                        if pending.get("taskId") == task_id
                    ]
                    for approval_id in stale:
                        self.supervisor_approvals.pop(approval_id, None)
            self.bus.bridge_event(run_id, {
                "type": "a2a_supervisor_end",
                "supervisorRunId": supervisor_run_id,
                "state": supervisor_run.get("state"),
                "sequence": terminal_snapshot.get("sequence"),
                "canClaimAGI": False,
            })
        elif main_ok:
            for i, task in enumerate(tasks):
                if cancel.is_set():
                    raise _RunCancelled()
                sub_idx = i + 1  # live[0] is Main
                name = live[sub_idx].name
                asn = assignments[i] if i < len(assignments) else None
                clean_task = asn.task if asn else task
                _mark_active(sub_idx)
                _emit_agents(
                    "a2a_agent_start",
                    index=sub_idx,
                    name=name,
                    agent=live[sub_idx].to_dict(),
                    phase="sub",
                    persona=live[sub_idx].persona,
                    skills=list(live[sub_idx].skills),
                )
                dispatch_manifest.update_assignment(
                    logical_task_ids[i],
                    status="running",
                    phase="worker",
                )
                self._publish_dispatch_manifest(handle)
                agent_prompt = build_sub_agent_prompt(
                    original_goal=prompt,
                    sub_name=name,
                    task=clean_task,
                    sub_index=i + 1,
                    total_subs=len(tasks),
                    main_context=main_text,
                    persona_name=asn.persona_name if asn else "",
                    persona_id=asn.persona_id if asn else "",
                    skill_names=list(asn.skill_names) if asn else (),
                    done_criteria=(
                        "Produce evidence that Main can independently verify.",
                        "Return the required WORKER_REPORT envelope.",
                    ),
                    expected_output="Structured WORKER_REPORT for Main verification.",
                )
                sub_extra = (system_extra or "").strip()
                if asn and asn.system_extra:
                    sub_extra = (
                        f"{sub_extra}\n\n{asn.system_extra}".strip()
                        if sub_extra
                        else asn.system_extra
                    )
                self.bus.bridge_event(run_id, {
                    "type": "a2a_handoff",
                    "from": DEFAULT_MAIN_NAME,
                    "to": name,
                    "promptChars": len(agent_prompt),
                    "promptPreview": (clean_task[:400] if clean_task else agent_prompt[:400]),
                    "personaId": asn.persona_id if asn else "",
                    "skills": list(asn.skill_names) if asn else [],
                    "allowedTools": sorted(assignment_scopes[i]) if i < len(assignment_scopes) else [],
                    "toolScopeVia": asn.tool_scope_via if asn else "none",
                    "orchestration": orchestration.snapshot(),
                    "canClaimAGI": False,
                })
                sub_res = _run_one(
                    name=name,
                    agent_prompt=agent_prompt,
                    extra=sub_extra,
                    agent_history=None,
                    raw_turn=agent_prompt,
                    use_steering=False,
                    use_refresh=False,
                    internal_artifact=True,
                    agent_id=f"sub-{i + 1}",
                    task_id=logical_task_ids[i],
                    allowed_tools=(
                        assignment_scopes[i]
                        if i < len(assignment_scopes)
                        else set()
                    ),
                )
                sub_text = str(getattr(sub_res, "final_text", "") or "").strip()
                sub_results.append((name, sub_text))
                sub_ok = bool(getattr(sub_res, "ok", False)) and not str(
                    getattr(sub_res, "model_error", "") or ""
                )
                live[sub_idx].status = "succeeded" if sub_ok else "failed"
                live[sub_idx].active = False
                live[sub_idx].summary = (
                    (sub_text[:160] + "…") if len(sub_text) > 160 else sub_text
                )
                dispatch_manifest.update_assignment(
                    logical_task_ids[i],
                    status="succeeded" if sub_ok else "failed",
                    phase="worker",
                    summary=live[sub_idx].summary,
                    error=(
                        str(getattr(sub_res, "model_error", "") or "")
                        if not sub_ok
                        else None
                    ),
                )
                self._publish_dispatch_manifest(handle)
                if not sub_ok:
                    chain_ok = False
                    model_error = str(
                        getattr(sub_res, "model_error", "") or f"{name} failed"
                    )
                _publish_orchestration(
                    orchestration.append_message(
                        kind="worker_result",
                        sender=name,
                        recipient=DEFAULT_MAIN_VERIFY_NAME,
                        summary=f"{name} · {'completed' if sub_ok else 'failed'}",
                        body=sub_text
                        or str(getattr(sub_res, "model_error", "") or ""),
                        task_id=logical_task_ids[i],
                        trusted=False,
                    )
                )
                _emit_agents(
                    "a2a_agent_end",
                    index=sub_idx,
                    name=name,
                    agent=live[sub_idx].to_dict(),
                    ok=sub_ok,
                    answerChars=len(sub_text),
                    phase="sub",
                )
                # Continue remaining subs even if one fails — Main will verify.

        # ── 3) Empty DISPATCH collapses to one delivery-gated solo worker ─
        collapsed_to_solo = False
        synthesis_text = ""
        verify_ok = False
        verify_task_id = ""
        authoritative_final_events: list[dict[str, Any]] | None = None
        if main_ok and not tasks:
            collapsed_to_solo = True
            handle["observedRoute"] = "solo"
            self._emit_goal_update(
                handle,
                goal="Complete the request in the verified solo fallback.",
                source="a2a-solo-fallback",
                reason="Main found no independently useful subtask",
                current_stage=2,
                planned_stages=2,
                max_stages=2,
            )
            self.bus.bridge_event(run_id, {
                "type": "a2a_route_collapsed",
                "from": "a2a",
                "to": "solo",
                "reason": "no independently useful subtask",
                "subCount": 0,
                "canClaimAGI": False,
            })
            _emit_agents(
                "a2a_route_collapsed",
                fromRoute="a2a",
                to="solo",
                reason="no independently useful subtask",
                subCount=0,
            )
            solo_res = _run_one(
                name=DEFAULT_MAIN_NAME,
                agent_prompt=prompt,
                extra=(system_extra or "").strip(),
                agent_history=history,
                raw_turn=raw_prompt or prompt,
                use_steering=True,
                use_refresh=require_live_refresh,
                internal_artifact=False,
                agent_id="main",
                task_id=f"{run_id}-main-plan",
            )
            last_res = solo_res
            synthesis_text = str(getattr(solo_res, "final_text", "") or "").strip()
            solo_ok = bool(getattr(solo_res, "ok", False)) and not str(
                getattr(solo_res, "model_error", "") or ""
            )
            if not solo_ok:
                chain_ok = False
                model_error = str(
                    getattr(solo_res, "model_error", "") or "solo collapse failed"
                )

        # ── 4) Main Agent verify + synthesize (only when subs actually ran) ─
        if main_ok and not collapsed_to_solo:
            dispatch_manifest.set_status(
                "verifying",
                phase="verifying",
                main_status="verifying",
            )
            self._publish_dispatch_manifest(handle)
            self._emit_goal_update(
                handle,
                goal="Verify and synthesize every sub-agent report.",
                source="a2a-verify",
                reason="all dispatched tasks reached the verification barrier",
                current_stage=3,
                planned_stages=3,
                max_stages=3,
            )
            verify_task_id = f"{run_id}-main-verify"
            verify_final_events: list[dict[str, Any]] = []
            _publish_orchestration(
                orchestration.upsert_agent(
                    agent_id="main-verify",
                    name=DEFAULT_MAIN_VERIFY_NAME,
                    status="queued",
                    source="local",
                    protocol="claude-native",
                    role="coordinator-verify",
                    capabilities={
                        "synthesis": True,
                        "adversarialVerification": True,
                    },
                    connected=True,
                    current_task_id=verify_task_id,
                )
            )
            _publish_orchestration(
                orchestration.upsert_task(
                    task_id=verify_task_id,
                    subject="Verify and synthesize",
                    description=(
                        "Adversarially verify every worker report and produce the "
                        "only operator-facing answer."
                    ),
                    state="blocked" if logical_task_ids else "queued",
                    owner_id="main-verify",
                    blocked_by=logical_task_ids,
                    done_criteria=(
                        "Check every worker against its dispatch contract.",
                        "Resolve disagreements or explicitly preserve uncertainty.",
                        "Never rubber-stamp worker completion.",
                    ),
                    expected_output="Operator answer followed by HARNESS_LOG.",
                )
            )
            verify = A2AAgentLive(
                name=DEFAULT_MAIN_VERIFY_NAME,
                index=len(live),
                status="queued",
                active=False,
                role="verify",
            )
            live.append(verify)
            _mark_active(len(live) - 1)
            _emit_agents(
                "a2a_agent_start",
                index=len(live) - 1,
                name=DEFAULT_MAIN_VERIFY_NAME,
                agent=live[-1].to_dict(),
                phase="verify",
            )
            verify_prompt = build_verify_synthesis_prompt(
                original_goal=prompt,
                main_plan_output=main_dispatch_src or main_text,
                sub_results=sub_results,
            )
            self.bus.bridge_event(run_id, {
                "type": "a2a_handoff",
                "from": "sub-agents",
                "to": DEFAULT_MAIN_VERIFY_NAME,
                "promptChars": len(verify_prompt),
                "promptPreview": "verify + synthesize all sub-agent outputs",
                "orchestration": orchestration.snapshot(),
                "canClaimAGI": False,
            })
            verify_res = _run_one(
                name=DEFAULT_MAIN_VERIFY_NAME,
                agent_prompt=verify_prompt,
                extra=(system_extra or "").strip(),
                agent_history=None,
                raw_turn=verify_prompt,
                use_steering=False,
                use_refresh=False,
                internal_artifact=False,
                agent_id="main-verify",
                task_id=verify_task_id,
                # Verification is another structured orchestration pass. Its
                # final report is consumed by the bridge's delivery gate, not
                # by the generic tool-continuation heuristic.
                allow_continuation_nudges=False,
                final_event_buffer=verify_final_events,
            )
            authoritative_final_events = verify_final_events
            synthesis_text = str(getattr(verify_res, "final_text", "") or "").strip()
            verify_ok = bool(getattr(verify_res, "ok", False)) and not str(
                getattr(verify_res, "model_error", "") or ""
            )
            live[-1].status = "succeeded" if verify_ok else "failed"
            live[-1].active = False
            live[-1].summary = (
                (synthesis_text[:160] + "…") if len(synthesis_text) > 160 else synthesis_text
            )
            if not verify_ok:
                chain_ok = False
                model_error = str(
                    getattr(verify_res, "model_error", "") or "Main Agent verify failed"
                )
            _publish_orchestration(
                orchestration.append_message(
                    kind="coordinator",
                    sender=DEFAULT_MAIN_VERIFY_NAME,
                    recipient="operator",
                    summary=(
                        "Verified synthesis" if verify_ok else "Synthesis failed"
                    ),
                    body=synthesis_text
                    or str(getattr(verify_res, "model_error", "") or ""),
                    task_id=verify_task_id,
                    trusted=True,
                )
            )
            _emit_agents(
                "a2a_agent_end",
                index=len(live) - 1,
                name=DEFAULT_MAIN_VERIFY_NAME,
                agent=live[-1].to_dict(),
                ok=verify_ok,
                answerChars=len(synthesis_text),
                phase="verify",
            )

        # Internal Main-plan and sub-agent artifacts deliberately defer their
        # delivery gates. They may be used as evidence by Main verify, but must
        # never become a direct fallback answer. Fail closed unless the final,
        # normally gated Main verification pass produced a deliverable body.
        if synthesis_text.strip():
            operator_final = synthesis_text.strip()
        elif not main_ok:
            operator_final = (
                "A2A stopped before dispatch because the internal "
                "Main planning phase failed. No internal planning text was "
                "delivered."
            )
        else:
            operator_final = (
                "A2A did not produce a delivery-gated Main "
                "verification report. Internal plan and sub-agent artifacts "
                "were retained in the trace but were not delivered."
            )
        from agent.completion_gate import (
            decide_completion,
            finalize_completion_markers,
            apply_decision_to_result,
        )
        operator_final, a2a_predicates = finalize_completion_markers(
            operator_final,
            prompt=prompt,
        )
        failed_output_predicates = tuple(
            name for name, passed in a2a_predicates.items() if not passed
        )
        if (
            main_ok
            and not collapsed_to_solo
            and bool(tasks)
            and verify_ok
            and failed_output_predicates
        ):
            repair_task_id = f"{run_id}-main-output-repair"
            repair_prompt = build_output_contract_repair_prompt(
                original_goal=prompt,
                prior_answer=synthesis_text,
                failed_predicates=failed_output_predicates,
            )
            dispatch_manifest.set_status(
                "verifying",
                phase="output_contract_repair",
                main_status="repairing_output_contract",
            )
            self._publish_dispatch_manifest(handle)
            _publish_orchestration(
                orchestration.upsert_task(
                    task_id=repair_task_id,
                    subject="Repair output contract",
                    description=(
                        "Perform one tools-free formatting repair of the verified "
                        "operator answer."
                    ),
                    state="queued",
                    owner_id="main-verify",
                    blocked_by=(verify_task_id,),
                    done_criteria=(
                        "Preserve verified claims and limitations.",
                        "Add no new facts or evidence.",
                        "Repair only failed deterministic output syntax.",
                    ),
                    expected_output="Complete corrected operator answer.",
                )
            )
            self.bus.bridge_event(run_id, {
                "type": "a2a_output_contract_repair_start",
                "attempt": 1,
                "maxAttempts": 1,
                "failedPredicates": list(failed_output_predicates),
                "allowedTools": [],
                "allowContinuationNudges": False,
                "orchestration": orchestration.snapshot(),
                "candidateOnly": True,
                "canClaimAGI": False,
            })
            repair_final_events: list[dict[str, Any]] = []
            prior_last_res = last_res
            repair_res = _run_one(
                name=DEFAULT_MAIN_VERIFY_NAME,
                agent_prompt=repair_prompt,
                extra="",
                agent_history=None,
                raw_turn=repair_prompt,
                use_steering=False,
                use_refresh=False,
                internal_artifact=False,
                agent_id="main-verify",
                task_id=repair_task_id,
                allowed_tools=set(),
                allow_continuation_nudges=False,
                final_event_buffer=repair_final_events,
            )
            repair_text = str(
                getattr(repair_res, "final_text", "") or ""
            ).strip()
            repair_ok = (
                bool(getattr(repair_res, "ok", False))
                and not str(getattr(repair_res, "model_error", "") or "")
                and bool(repair_text)
            )
            repair_adopted = False
            if repair_ok:
                synthesis_text = repair_text
                operator_final, a2a_predicates = finalize_completion_markers(
                    synthesis_text,
                    prompt=prompt,
                )
                authoritative_final_events = repair_final_events
                repair_adopted = True
            else:
                last_res = prior_last_res
            remaining_failed = [
                name for name, passed in a2a_predicates.items() if not passed
            ]
            predicates_passed = not remaining_failed
            self.bus.bridge_event(run_id, {
                "type": "a2a_output_contract_repair_end",
                "attempt": 1,
                "maxAttempts": 1,
                "ok": repair_ok,
                "adopted": repair_adopted,
                "predicatesPassed": predicates_passed,
                "failedPredicates": remaining_failed,
                "answerChars": len(repair_text),
                "orchestration": orchestration.snapshot(),
                "candidateOnly": True,
                "canClaimAGI": False,
            })
        if not handle.get("observedRoute"):
            handle["observedRoute"] = "solo" if collapsed_to_solo else "serial"

        self.bus.bridge_event(run_id, {
            "type": "a2a_chain_end",
            "agents": [a.to_dict() for a in live],
            "ok": chain_ok,
            "subCount": len(tasks),
            "execution": execution,
            "terminalLayout": terminal_layout,
            "supervisorRunId": handle.get("supervisorRunId"),
            "collapsedToSolo": collapsed_to_solo,
            "observedRoute": handle.get("observedRoute") or "",
            "orchestration": orchestration.snapshot(),
            "canClaimAGI": False,
        })
        # Persist the authoritative terminal ledger before any return path,
        # including the no-result failure path.  ``run_finished`` is assembled
        # later, after Main verify has either completed or been skipped.
        handle["a2aAgents"] = [a.to_dict() for a in live]
        if last_res is None:
            return AgentLoopResult(
                goal=prompt,
                final_text=operator_final,
                ok=False,
                steps=[],
                messages=[{"role": "assistant", "content": operator_final}],
                model_error=model_error or "a2a chain produced no agent result",
            )
        last_res.final_text = operator_final
        last_res.ok = chain_ok and bool(getattr(last_res, "ok", False))
        last_res.steps = all_steps
        last_res.messages = list(getattr(last_res, "messages", None) or [])
        if last_res.messages and last_res.messages[-1].get("role") == "assistant":
            last_res.messages[-1] = {**last_res.messages[-1], "content": operator_final}
        else:
            last_res.messages.append({"role": "assistant", "content": operator_final})
        if model_error and not chain_ok:
            last_res.model_error = model_error
        a2a_decision = decide_completion(
            controller_status="achieved" if last_res.ok else "candidate_complete",
            output_predicates_pass=(
                all(a2a_predicates.values()) if a2a_predicates else True
            ),
            reason="" if last_res.ok else (model_error or "a2a incomplete"),
        )
        apply_decision_to_result(last_res, a2a_decision)
        if authoritative_final_events is not None:
            final_event = (
                dict(authoritative_final_events[-1])
                if authoritative_final_events
                else {"type": "final"}
            )
            final_event.update(
                {
                    "type": "final",
                    "text": operator_final,
                    "ok": bool(last_res.ok),
                }
            )
            sink(final_event)
        return last_res

    # -- team mode --------------------------------------------------------- #
    def _run_team(self, handle: dict, prompt: str, tee: _TokenTee, ctx: Any,
                  sink: Callable[[dict], None], *, team: int, max_steps: int,
                  history: "list[dict] | None", show_thinking: bool,
                  system_extra: str, lane_results: list[dict[str, Any]], budget: ExecutionBudget,
                  raw_prompt: str | None = None, post_tool_continuity: bool = False,
                  max_continuations: int | None = None,
                  max_parallel_tools: int = 1,
                  require_live_refresh: bool = False,
                  response_style: ResponseStyle = "adaptive",
                  worker_tee: _TokenTee | None = None,
                  worker_model: str | None = None) -> Any:
        """Fan the goal out to K parallel worker lanes, then synthesize.

        Lane roles come from :func:`_resolve_team_lanes` (an explicit operator
        task partition first, SwarmRouter otherwise, then TEAM_ROLES fallback).
        Each lane is an independent tool loop that inherits the parent's
        ``permission`` and ``approver`` — never the unapproved harness path —
        and may carry a least-privilege ``allowed_tools`` set. Events flow into
        the same bus tagged with their lane id so the app can draw one column
        per agent. The coordinator then runs a read-only synthesis pass over
        the lane outputs (tools disabled — answer only).
        """
        from agent.agent_loop import (
            AgentLoopResult,
            _claims_tools_are_unavailable,
            run_agent_loop,
        )
        from agent.agent_tools import ToolContext, all_tools

        run_id = handle["id"]
        cancel: threading.Event = handle["cancel"]
        from agent.continuation import build_continuation_context
        lane_history = build_continuation_context(
            history or [], effective_request=prompt)
        routing_client = (worker_tee or tee).raw_client
        resolver_parameters = inspect.signature(_resolve_team_lanes).parameters
        if "llm_client" in resolver_parameters:
            lanes, routing = _resolve_team_lanes(
                prompt,
                team,
                llm_client=routing_client,
            )
        else:
            # Test/extension compatibility for an injected legacy two-argument
            # resolver. Production always takes the explicit routing client.
            lanes, routing = _resolve_team_lanes(prompt, team)
        lanes = _finalize_team_lane_contracts(list(lanes))
        n_lanes = len(lanes)
        dispatch_manifest = self._ensure_dispatch_manifest(
            handle,
            session=str(handle.get("session") or "code-default"),
            mode="team",
        )
        dispatch_manifest.set_status(
            "dispatching",
            phase="dispatching",
            source="team",
            main_status="dispatching",
        )
        self._publish_dispatch_manifest(handle)
        require_read_only_evidence = _requires_read_only_repository_evidence(prompt)
        runtime_source = dict(
            handle.get("runtimeSource")
            or _runtime_source_provenance(Path(ctx.root))
        )
        runtime_source_matches_workspace = runtime_source.get(
            "runtimeSourceMatchesWorkspace"
        )
        self.bus.bridge_event(run_id, {
            "type": "team_start",
            "team": n_lanes,
            "roles": [lane.role for lane in lanes],
            "assignments": [
                {
                    "role": lane.role,
                    "personaId": lane.persona_id,
                    "personaName": lane.persona_name,
                    "personaVia": lane.persona_via,
                    "skills": list(lane.skills),
                    "skillVia": list(lane.skill_via),
                    "allowedTools": sorted(lane.allowed_tools or ()),
                    "toolScopeVia": lane.tool_scope_via,
                    "source": lane.source,
                    "division": lane.division,
                }
                for lane in lanes
            ],
            "routing": routing,
            **runtime_source,
            **({"workerModel": worker_model} if worker_model else {}),
        })
        self._emit_goal_update(
            handle,
            goal=(
                f"Run {n_lanes} parallel evidence lane"
                f"{'' if n_lanes == 1 else 's'} to cover the request."
            ),
            source="team-lanes",
            reason="parallel team routing completed",
            current_stage=1,
            planned_stages=2,
            max_stages=2,
        )
        # Discover the shared registry once before lane inactivity clocks start.
        # Cold plugin imports inside competing worker threads can otherwise make
        # a diagnostic sub-second drain expire before the first model/tool event,
        # and the registry cache is process-wide rather than lane-specific.
        all_tools()

        results: "queue.Queue[tuple[int, Any]]" = queue.Queue()
        # Reserve ids in router order before threads start. Thread scheduling can
        # then change execution order without changing which durable lane node a
        # timeout/completion event targets.
        lane_ids = [self.bus.reserve("lane") for _ in range(n_lanes)]
        team_task_ids = [
            f"{run_id}-team-lane-{index + 1}"
            for index in range(n_lanes)
        ]
        for index, lane in enumerate(lanes):
            dispatch_manifest.register_assignment(
                assignment_id=lane_ids[index],
                agent_id=lane_ids[index],
                task_id=team_task_ids[index],
                name=f"{lane.role} #{index + 1}",
                task=lane.goal,
                phase="dispatching",
                status="queued",
                persona_id=lane.persona_id,
                persona_name=lane.persona_name,
                persona_discipline=lane.persona_discipline,
                persona_via=lane.persona_via,
                skills=lane.skills,
                skill_via=lane.skill_via,
                allowed_tools=lane.allowed_tools or (),
                tool_scope_via=lane.tool_scope_via,
                permission=str(getattr(ctx, "permission", "") or ""),
                execution="embedded",
                provider="",
                model=worker_model or "",
                source=lane.source,
                division=lane.division,
            )
        self._publish_dispatch_manifest(handle)
        # Each lane needs its own cancellation boundary. The parent budget must
        # remain live for coordinator synthesis, but a lane abandoned at the drain
        # timeout must not keep spending or emitting under an already-terminal run.
        # A child inherits the parent's limits/deadline while allowing the drain
        # path to cancel only that lane at its next model/tool boundary.
        parent_usd_cap = budget.snapshot().limits.usd

        def lane_budget_for(lane: TeamLane) -> ExecutionBudget:
            # Swarm-router lane price estimates are useful only when the
            # operator supplied an actual parent USD budget. Adding an
            # artificial finite cap beneath an unlimited parent fails closed
            # before the first call for provider aliases whose prices are not
            # registered locally (for example 020s). The parent still owns all
            # cancellation, deadline, call, and concurrency limits.
            if parent_usd_cap is None or lane.budget_usd is None:
                return budget.child()
            return budget.child(Limits(usd=min(parent_usd_cap, lane.budget_usd)))

        lane_budgets = [lane_budget_for(lane) for lane in lanes]
        lane_source = worker_tee or tee
        lane_clients = [lane_source.fork() for _ in range(n_lanes)]
        # The inactivity clock is armed only after every worker has reached its
        # launch barrier. Starting it while Python is still scheduling sibling
        # threads makes an explicit sub-second diagnostic timeout race thread
        # startup: one lane can be cancelled before it ever enters its first
        # model call. The barrier action sets the shared epoch before releasing
        # any participant, so normal and diagnostic drains measure lane
        # inactivity rather than host scheduling delay.
        drain_started = 0.0
        base_drain_timeout = float(
            handle.get("drainTimeoutSec", self.drain_timeout)
        )
        drain_state = {
            "deadlines": [
                float("inf")
                for _ in range(n_lanes)
            ],
            "extendedLanes": set(),
            "finalReportLanes": set(),
            "lastProgressAt": [0.0 for _ in range(n_lanes)],
            "lastProgressEvent": ["lane_start" for _ in range(n_lanes)],
        }
        drain_state_lock = threading.Lock()

        def arm_team_drain() -> None:
            nonlocal drain_started
            drain_started = time.monotonic()
            with drain_state_lock:
                drain_state["deadlines"] = [
                    drain_started + base_drain_timeout
                    for _ in range(n_lanes)
                ]
                drain_state["lastProgressAt"] = [
                    drain_started for _ in range(n_lanes)
                ]

        lane_start_barrier = threading.Barrier(
            n_lanes + 1,
            action=arm_team_drain,
            timeout=max(10.0, min(DRAIN_TIMEOUT_DEFAULT_SEC, 30.0)),
        )

        def lane_model_call_limit(effective_steps: int) -> int:
            """Allow one bounded final report after a multi-tool lane.

            Router ``max_steps`` bounds the tool-work slice. A lane that uses
            every allowed turn still needs one answer-only model call to turn
            its verified tool results into a report the coordinator can
            synthesize. Preserve the established one-turn contract unchanged.
            """
            return effective_steps if effective_steps <= 1 else effective_steps + 1

        def lane_failure_detail(res: Any) -> str:
            """Return a factual terminal reason without erasing completed tools."""
            if isinstance(res, Exception):
                return f"{type(res).__name__}: {res}"
            if res is None:
                return "lane returned no result"
            model_error = str(getattr(res, "model_error", "") or "")
            steps = list(getattr(res, "steps", []) or [])
            if bool(getattr(res, "incomplete", False)) and steps:
                native_count = sum(1 for step in steps if step.get("native"))
                tool_count = len(steps)
                count_text = (
                    f"{native_count} native tool call(s)"
                    if native_count else f"{tool_count} tool call(s)"
                )
                reason = str(getattr(res, "incomplete_reason", "") or "")
                detail = model_error or reason or "execution slice ended before a final report"
                return f"{detail} after {count_text}"
            return model_error or _summary(getattr(res, "final_text", "")) or "lane did not complete"

        def worker(idx: int) -> None:
            lane = lanes[idx]
            lane_budget = lane_budgets[idx]
            lane_client = lane_clients[idx]
            effective_steps = min(max_steps, lane.max_steps or max_steps)
            lane_id = self.bus.push(
                "lane", f"{lane.role} #{idx + 1}", frame_id=lane_ids[idx])

            def lane_sink(event: dict) -> None:
                # An in-flight provider may keep streaming after the coordinator's
                # drain timeout. Cancellation cannot interrupt that HTTP call, but
                # it can close its protocol lane immediately so abandoned output
                # never races coordinator synthesis or lands after the run result.
                if not lane_budget.snapshot().cancelled:
                    event_type = str(event.get("type") or "")
                    if (
                        event_type in TEAM_LANE_PROGRESS_EVENTS
                        and base_drain_timeout >= DRAIN_TIMEOUT_DEFAULT_SEC
                    ):
                        now = time.monotonic()
                        hard_deadline = drain_started + DRAIN_TIMEOUT_MAX_SEC
                        with drain_state_lock:
                            final_report_active = (
                                event_type == "final_call_reserved"
                                or idx in drain_state["finalReportLanes"]
                            )
                        activity_window = (
                            TEAM_FINAL_REPORT_GRACE_SEC
                            if final_report_active
                            else base_drain_timeout
                        )
                        proposed_deadline = min(
                            hard_deadline,
                            now + activity_window,
                        )
                        extension_event: dict[str, Any] | None = None
                        with drain_state_lock:
                            deadlines = drain_state["deadlines"]
                            previous_deadline = float(deadlines[idx])
                            drain_state["lastProgressAt"][idx] = now
                            drain_state["lastProgressEvent"][idx] = event_type
                            if proposed_deadline > previous_deadline:
                                deadlines[idx] = proposed_deadline
                                drain_state["extendedLanes"].add(idx)
                            if (
                                event_type == "final_call_reserved"
                                and idx not in drain_state["finalReportLanes"]
                            ):
                                drain_state["finalReportLanes"].add(idx)
                                extension_event = {
                                    "type": "team_drain_extended",
                                    "lane": lane_id,
                                    "role": lane.role,
                                    "reason": "reserved final report call",
                                    "baseDrainTimeoutSec": base_drain_timeout,
                                    "finalReportGraceSec": TEAM_FINAL_REPORT_GRACE_SEC,
                                    "effectiveDrainSec": round(
                                        proposed_deadline - drain_started, 3
                                    ),
                                }
                        if extension_event is not None:
                            self.bus.bridge_event(run_id, extension_event)
                    sink(event)

            # ``_TokenTee.fork`` normally inherits the parent provider-wait
            # callback, whose notifier runs on a separate thread and therefore
            # cannot recover this lane's thread-local event-bus path. Route the
            # heartbeat through the lane sink explicitly: the TUI gets the lane
            # identity and the inactivity deadline is renewed while a legitimate
            # provider call is still pending.
            def on_lane_provider_wait(
                sequence: int,
                elapsed_sec: float,
                max_wait_sec: float,
            ) -> None:
                # Team lanes replace the inherited wait callback to restore
                # lane-local event-bus identity. Keep the root-run ETA refresh
                # as well; its per-handle lock/throttle collapses simultaneous
                # lane heartbeats into one bounded recalibration.
                self._refresh_run_eta_on_provider_wait(handle)
                lane_sink({
                    "type": "provider_wait",
                    "lane": lane_id,
                    "role": lane.role,
                    "sequence": sequence,
                    "elapsedSec": round(elapsed_sec, 3),
                    "maxWaitSec": round(max_wait_sec, 3),
                })

            lane_client._on_wait = on_lane_provider_wait

            try:
                # Do not arm any lane's inactivity budget until all sibling
                # workers have been scheduled and completed their lane-local
                # callback setup. This makes the drain independent of Python
                # thread-start order on loaded CI and local hosts.
                lane_start_barrier.wait()
                # Start the inactivity window when this worker actually begins,
                # not when the coordinator finished constructing the team. On a
                # loaded host, thread scheduling alone can consume a small
                # diagnostic drain window and abandon a lane before its first
                # model/tool event. Keep the existing team-wide hard ceiling.
                lane_started_at = time.monotonic()
                with drain_state_lock:
                    drain_state["deadlines"][idx] = min(
                        drain_started + DRAIN_TIMEOUT_MAX_SEC,
                        lane_started_at + base_drain_timeout,
                    )
                    drain_state["lastProgressAt"][idx] = lane_started_at
                    drain_state["lastProgressEvent"][idx] = "lane_start"
                lane_title = (
                    f"{lane.role} ({lane.division}) #{idx + 1}"
                    if lane.division
                    else f"{lane.role} #{idx + 1}"
                )
                # TeamLane.source is a string in production. Some legacy tests
                # construct the dataclass positionally with the pre-source
                # field order, however, so fail closed by omitting malformed
                # metadata rather than making the whole bridge event
                # non-serializable.
                lane_source = lane.source if isinstance(lane.source, str) else ""
                self.bus.bridge_event(run_id, {
                    "type": "lane_start",
                    "lane": lane_id,
                    "role": lane.role,
                    "title": lane_title,
                    "personaId": lane.persona_id,
                    "personaName": lane.persona_name,
                    "personaVia": lane.persona_via,
                    "skillVia": list(lane.skill_via),
                    "allowedTools": sorted(lane.allowed_tools or ()),
                    "toolScopeVia": lane.tool_scope_via,
                    # Preserve the legacy lane_start wire exactly when agency
                    # routing is disabled or falls back.
                    **(
                        {"source": lane_source}
                        if lane_source == "agency_router"
                        else {}
                    ),
                    **({"division": lane.division} if lane.division else {}),
                    **({"skills": list(lane.skills)} if lane.skills else {}),
                })
                # Inherit the parent's permission + approver. Do NOT route through
                # agent.subagent / harness: that lineage has no approver parameter
                # and would arm RISK_WRITE/EXEC under parent manual.
                lane_tools = set(lane.allowed_tools) if lane.allowed_tools is not None else None
                parent_tools = (
                    set(all_tools())
                    if getattr(ctx, "allowed_tools", None) is None
                    else set(getattr(ctx, "allowed_tools", set()) or ())
                )
                if str(getattr(ctx, "permission", "") or "").lower() == "readonly":
                    parent_tools.intersection_update(
                        _READ_ONLY_REPOSITORY_REVIEW_TOOLS
                    )
                lane_tools = (
                    parent_tools
                    if lane_tools is None
                    else lane_tools & parent_tools
                )
                if require_read_only_evidence:
                    lane_tools = (
                        set(_READ_ONLY_REPOSITORY_REVIEW_TOOLS)
                        if lane_tools is None
                        else lane_tools & _READ_ONLY_REPOSITORY_REVIEW_TOOLS
                    )
                    # Runtime-source tools are safe, read-only, and necessary
                    # whenever a bundled release is reviewing a different
                    # workspace checkout. Router scopes predate these tools, so
                    # add them explicitly rather than silently forcing the lane
                    # back onto a stale workspace backend file.
                    lane_tools.update({"read_runtime_file", "grep_runtime"})
                parent_worker_tools = getattr(ctx, "subagent_allowed_tools", None)
                if worker_tee is not None and parent_worker_tools is not None:
                    lane_tools = lane_tools & set(parent_worker_tools)
                dispatch_manifest.update_assignment(
                    lane_id,
                    status="running",
                    phase="worker",
                    allowed_tools=lane_tools,
                    tool_scope_via=(
                        f"{lane.tool_scope_via}+parent_intersection"
                    ),
                )
                self._publish_dispatch_manifest(handle)
                lane_ctx = ToolContext(
                    root=ctx.root,
                    permission=ctx.permission,
                    approver=ctx.approver,
                    max_output=(
                        max(
                            int(getattr(ctx, "max_output", 6000) or 6000),
                            _READ_ONLY_REPOSITORY_REVIEW_MAX_OUTPUT,
                        )
                        if require_read_only_evidence
                        else int(getattr(ctx, "max_output", 6000) or 6000)
                    ),
                    client=lane_client,
                    subagent_client=lane_client,
                    budget=lane_budget,
                    sandbox=getattr(ctx, "sandbox", None),
                    conscience_strict=getattr(ctx, "conscience_strict", None),
                    conscience_mode=getattr(ctx, "conscience_mode", None),
                    allowed_tools=lane_tools,
                    subagent_allowed_tools=lane_tools,
                    # A team lane runs the same tool registry under the same
                    # workspace root — a PreToolUse rule the operator wrote must
                    # hold for a lane's tool calls too, not only the parent's.
                    hook_config=getattr(ctx, "hook_config", None),
                    hook_sink=getattr(ctx, "hook_sink", None),
                )
                lane_ctx.code_bridge_sink = lane_sink  # type: ignore[attr-defined]
                res = run_agent_loop(
                    lane.goal,
                    client=lane_client,
                    ctx=lane_ctx,
                    history=lane_history,
                    raw_user_turn=lane.goal,
                    current_task=lane.goal,
                    response_style="concise",  # internal evidence, not user presentation
                    on_event=lane_sink,
                    max_steps=effective_steps,
                    max_model_calls=lane_model_call_limit(effective_steps),
                    reserve_final_model_call=effective_steps > 1,
                    tool_feedback_cap=(
                        _READ_ONLY_REPOSITORY_REVIEW_MAX_OUTPUT
                        if require_read_only_evidence else None
                    ),
                    system_extra=(
                        (
                            _team_lane_specialist_guidance(lane) + "\n\n"
                            if lane.agent_md or lane.skills
                            else ""
                        )
                        +
                        f"You are the {lane.role} on a {n_lanes}-agent team. {lane.brief} "
                        f"You are already dispatched as worker {idx + 1} of {n_lanes}; "
                        "the coordinator exclusively owns the overall routing decision, "
                        "team size, other-lane progress, and final synthesis. Never claim "
                        "that the overall execution is solo and never choose or revise "
                        "the lane count. Stay in your lane's role and be concise."
                        + (
                            " This is an explicit read-only repository review: begin "
                            "with a native read-only tool call, cite the exact files "
                            "you inspected, and do not modify files. For a named "
                            "Python symbol, use a narrow grep with glob/path set "
                            "to the named file, then read_file around the returned "
                            "lines in chunks of at most 120 lines. Do not spend a "
                            "turn on outline when the operator already named the "
                            "file and symbol. Never batch more than two read_file "
                            "requests at once; larger batches can hide later results "
                            "behind the feedback cap. Do "
                            "not stop after imports, comments, or a function "
                            "signature: read the executable implementation branches "
                            "needed by the assigned question. The runtime reserves "
                            "one answer-only call after the bounded tool phase; use "
                            "the evidence already collected to produce a complete "
                            "report on that call, and state only genuine remaining "
                            "uncertainty rather than labelling the lane incomplete "
                            "merely because its tool budget ended."
                            if require_read_only_evidence else ""
                        )
                        + (
                            " Runtime provenance warning: the workspace checkout's "
                            "agent/code_bridge.py differs from the Python source "
                            "currently executing Sophia. For live backend behavior, "
                            "use grep_runtime and read_runtime_file, and cite it as "
                            "runtime:agent/code_bridge.py:<line>. Use ordinary "
                            "repository tools for workspace/TUI source. Never present "
                            "the stale workspace backend copy as the executing runtime."
                            if runtime_source_matches_workspace is False else ""
                        )
                    ) + system_extra,
                    show_thinking=show_thinking,
                    budget=lane_budget,
                    max_parallel_tools=max_parallel_tools,
                    post_tool_continuity=post_tool_continuity,
                    max_continuations=(
                        0
                        if lane.source in {
                            "agency_router",
                            "swarm_router",
                            "operator_partition",
                        }
                        else max_continuations
                    ),
                    require_live_refresh=require_live_refresh,
                    require_initial_tool=bool(require_read_only_evidence and lane_tools),
                )
                lane_provenance = _lane_provenance(
                    lane_client,
                    lane_budget,
                )
                lane_summary = _summary(res.final_text)
                dispatch_manifest.update_assignment(
                    lane_id,
                    status="succeeded" if bool(res.ok) else "failed",
                    phase="worker",
                    summary=lane_summary,
                    error=(
                        lane_failure_detail(res)
                        if not bool(res.ok)
                        else None
                    ),
                    provider=str(lane_provenance.get("provider") or "") or None,
                    model=str(lane_provenance.get("resolvedModel") or "") or None,
                )
                self._publish_dispatch_manifest(handle)
                self.bus.bridge_event(run_id, {
                    "type": "lane_end",
                    "lane": lane_id,
                    "ok": bool(res.ok),
                    **_lane_tool_receipt(res),
                    **lane_provenance,
                })
                results.put((idx, res))
            except Exception as exc:  # noqa: BLE001 - a lane failure must not sink the team
                dispatch_manifest.update_assignment(
                    lane_id,
                    status="failed",
                    phase="worker",
                    error=f"{type(exc).__name__}: {exc}",
                )
                self._publish_dispatch_manifest(handle)
                self.bus.bridge_event(run_id, {
                    "type": "lane_end",
                    "lane": lane_id,
                    "ok": False,
                    "error": f"{type(exc).__name__}: {exc}",
                    **_lane_provenance(lane_client, lane_budget),
                })
                results.put((idx, exc))
            finally:
                self.bus.pop("lane")

        threads = [
            threading.Thread(target=worker, args=(idx,), name=f"team-lane-{idx + 1}", daemon=True)
            for idx in range(n_lanes)
        ]
        for thread in threads:
            thread.start()
        try:
            lane_start_barrier.wait()
        except threading.BrokenBarrierError as exc:
            for lane_budget in lane_budgets:
                lane_budget.cancel()
            raise RuntimeError(
                "team workers did not reach the launch barrier"
            ) from exc
        abandoned: set[int] = set()
        while not cancel.is_set():
            live_indexes = [
                idx for idx, thread in enumerate(threads)
                if idx not in abandoned and thread.is_alive()
            ]
            if not live_indexes:
                break
            now = time.monotonic()
            with drain_state_lock:
                deadlines = list(drain_state["deadlines"])
            expired_indexes = [
                idx for idx in live_indexes
                if float(deadlines[idx]) <= now
            ]
            if expired_indexes:
                # Expire lanes independently. A quiet/stuck worker must not
                # discard a different worker that is still returning evidence.
                for idx in expired_indexes:
                    abandoned.add(idx)
                    lane_budgets[idx].cancel()
                    dispatch_manifest.update_assignment(
                        lane_ids[idx],
                        status="timed_out",
                        phase="worker",
                        error="lane abandoned at drain timeout",
                    )
                    self._publish_dispatch_manifest(handle)
                    self.bus.bridge_event(run_id, {
                        "type": "lane_end",
                        "lane": lane_ids[idx],
                        "ok": False,
                        "error": "lane abandoned at drain timeout",
                        **_lane_provenance(lane_clients[idx], lane_budgets[idx]),
                    })
                    lane_results.append({
                        "lane": lane_ids[idx],
                        "role": lanes[idx].role,
                        "skills": list(lanes[idx].skills),
                        "ok": False,
                        "error": "lane abandoned at drain timeout",
                        **_lane_provenance(lane_clients[idx], lane_budgets[idx]),
                    })
                continue
            next_deadline = min(float(deadlines[idx]) for idx in live_indexes)
            cancel.wait(timeout=min(0.05, max(0.0, next_deadline - now)))

        lingering_indexes = sorted(abandoned)
        lingering = [threads[idx].name for idx in lingering_indexes]
        if lingering:
            with drain_state_lock:
                lane_deadlines_sec = [
                    round(float(deadline) - drain_started, 3)
                    for deadline in drain_state["deadlines"]
                ]
                effective_drain_sec = round(
                    max(float(deadline) for deadline in drain_state["deadlines"])
                    - drain_started,
                    3,
                )
                extended_lane_indexes = sorted(drain_state["extendedLanes"])
                final_report_lane_indexes = sorted(drain_state["finalReportLanes"])
                last_progress_events = list(drain_state["lastProgressEvent"])
            handle.setdefault("diagnostics", []).append({
                "type": "lingering_lanes",
                "lanes": lingering,
                "baseDrainTimeoutSec": base_drain_timeout,
                "effectiveDrainSec": effective_drain_sec,
                "laneDeadlinesSec": lane_deadlines_sec,
                "progressExtendedLanes": extended_lane_indexes,
                "finalReportGraceLanes": final_report_lane_indexes,
                "lastProgressEvents": last_progress_events,
            })
            # An abandoned lane is not a footnote: its work is dropped, the
            # synthesis silently falls back to "(no lane produced an answer)",
            # and the run still reports ok=True with every agent node drawn. So
            # say it on the wire, where the operator can see it, rather than
            # only in a diagnostics dict nothing renders.
            self.bus.bridge_event(run_id, {
                "type": "lanes_abandoned", "lanes": lingering,
                "drainTimeoutSec": base_drain_timeout,
                "effectiveDrainSec": effective_drain_sec,
                "laneDeadlinesSec": lane_deadlines_sec,
                "progressExtendedLanes": extended_lane_indexes,
                "finalReportGraceLanes": final_report_lane_indexes,
                "lastProgressEvents": last_progress_events,
                "detail": (
                    f"{len(lingering)} lane(s) made no progress within the bounded "
                    "inactivity/final-report window; their output is NOT in the final answer."
                ),
            })
        handle["completionThreads"] = [
            thread for thread in threads if thread.is_alive()
        ]
        # All lanes have been joined/drained before a cancelled team becomes
        # terminal from the connector's perspective.  A provider call that
        # cannot be interrupted may outlive the answer/result event, so the
        # central finalizer waits for these threads before ``run_finished``.
        if cancel.is_set():
            raise _RunCancelled()

        collected: list[Any] = [None] * n_lanes
        while not results.empty():
            idx, res = results.get()
            collected[idx] = res
        for idx, res in enumerate(collected):
            if idx in abandoned:
                continue
            role = lanes[idx].role
            if isinstance(res, Exception):
                lane_results.append({"lane": lane_ids[idx], "role": role, "ok": False,
                                     "skills": list(lanes[idx].skills),
                                     "error": f"{type(res).__name__}: {res}",
                                     **_lane_provenance(lane_clients[idx], lane_budgets[idx])})
            elif res is not None:
                lane_results.append({"lane": lane_ids[idx], "role": role, "ok": bool(res.ok),
                                     "skills": list(lanes[idx].skills),
                                     "summary": _summary(res.final_text),
                                     **_lane_tool_receipt(res),
                                     **_lane_provenance(lane_clients[idx], lane_budgets[idx])})
                if not res.ok:
                    lane_results[-1]["error"] = lane_failure_detail(res)
                lane_results[-1]["finalText"] = res.final_text

        # Synthesis pass: coordinator merges lane outputs, answer-only.
        if cancel.is_set():
            raise _RunCancelled()
        usable_evidence = [
            (i, res) for i, res in enumerate(collected)
            if (i not in abandoned
                and res is not None
                and not isinstance(res, Exception)
                and not str(getattr(res, "model_error", "") or "")
                and (res.final_text or "").strip()
                and not str(res.final_text).lstrip().startswith("(reached "))
        ]
        team_degraded = not usable_evidence
        if usable_evidence:
            briefs = "\n\n".join(
                f"[{lanes[i].role} lane"
                + (" — resumable checkpoint" if getattr(res, "incomplete", False) else "")
                + f"]\nAuthoritative dispatch metadata: worker "
                f"{i + 1}/{n_lanes}; role={lanes[i].role}. Lane-local routing "
                f"or team-size claims are non-authoritative.\n"
                f"Authoritative tool receipt: {_lane_tool_receipt_text(res)}.\n"
                f"{res.final_text}"
                for i, res in usable_evidence
            )
        else:
            failure_lines: list[str] = []
            for index, res in enumerate(collected):
                if index in abandoned:
                    detail = "lane abandoned at drain timeout"
                else:
                    detail = lane_failure_detail(res)
                failure_lines.append(f"- {lanes[index].role}: {_summary(detail)}")
            final_text = (
                "Team execution did not complete a usable review report.\n\n"
                + "\n".join(failure_lines)
                + "\n\nNo synthesis was generated because no teammate lane returned "
                  "a usable final report. This does not imply that repository tools "
                  "were unavailable."
            )
            handle["teamDegraded"] = True
            return AgentLoopResult(
                goal=prompt,
                final_text=final_text,
                ok=False,
                messages=list(history or []) + [{"role": "assistant", "content": final_text}],
                model_error="team execution produced no usable lane evidence",
            )
        handle["teamDegraded"] = team_degraded
        dispatch_manifest.set_status(
            "verifying",
            phase="synthesis",
            main_status="synthesizing",
        )
        self._publish_dispatch_manifest(handle)
        self._emit_goal_update(
            handle,
            goal=(
                f"Reconcile and synthesize {len(usable_evidence)} usable "
                f"lane report{'' if len(usable_evidence) == 1 else 's'}."
            ),
            source="team-synthesis",
            reason="parallel lane barrier completed",
            current_stage=2,
            planned_stages=2,
            max_stages=2,
        )
        self.bus.bridge_event(run_id, {
            "type": "synthesis_start", "lanes": n_lanes,
            "completedLanes": len(usable_evidence), "teamDegraded": team_degraded,
        })
        authoritative_roles = ", ".join(
            f"{index + 1}={lane.role}" for index, lane in enumerate(lanes)
        )
        synthesis_goal = (
            f"Original goal: {prompt}\n\n"
            f"Authoritative dispatch receipt: exactly {n_lanes} workers were "
            f"dispatched; roles: {authoritative_roles}. Routing and lane count "
            "are coordinator-owned facts. Ignore and correct any lane-local "
            "claim that it selected a different team size, ran solo, or knows "
            "another lane's state.\n\n"
            f"{n_lanes} teammate agents produced the following lane outputs. "
            "Synthesize them into one final answer for the operator: reconcile "
            "disagreements, keep the strongest evidence, and state the combined plan.\n\n"
            f"{briefs}"
        )
        synthesis = run_agent_loop(
            synthesis_goal,
            client=tee,
            ctx=ctx,
            # Coordinator context must be isolated from the operator transcript:
            # passing the original prompt as raw_user_turn caused run_agent_loop
            # to append only that prompt, while the synthesis goal containing all
            # lane reports was never model-visible. The coordinator then correctly
            # (but disastrously) said no teammate evidence had been supplied.
            history=None,
            raw_user_turn=synthesis_goal,
            current_task=None,
            response_style=response_style,
            on_event=sink,
            max_steps=max(2, max_steps // 2),
            system_extra=(
                "You are an answer-only coordinator. Native tools are intentionally "
                "disabled for this synthesis pass, but that does NOT mean the teammate "
                "lanes lacked native tools. Never claim that the original run had no "
                "tools; report only the supplied lane evidence and any explicit lane "
                "failure. "
            ) + system_extra,
            show_thinking=show_thinking,
            enable_tools=False,
            budget=budget,
            gate_report_context={
                "request": prompt,
                "laneResults": lane_results,
            },
        )

        def operator_conversation(final_text: str) -> list[dict[str, Any]]:
            """Persist the operator exchange, never the synthetic coordinator goal."""
            messages = [dict(message) for message in (history or [])]
            user_turn = raw_prompt or prompt
            if not (
                messages
                and messages[-1].get("role") == "user"
                and messages[-1].get("content") == user_turn
            ):
                messages.append({"role": "user", "content": user_turn})
            messages.append({"role": "assistant", "content": final_text})
            return messages

        if _denies_supplied_team_evidence(synthesis.final_text):
            final_text = (
                "The coordinator contradicted teammate evidence that it was given. "
                "Its synthesis was withheld; the completed lane reports are preserved "
                "below instead.\n\n"
                + briefs
            )
            return AgentLoopResult(
                goal=prompt,
                final_text=final_text,
                ok=False,
                messages=operator_conversation(final_text),
                model_error="team synthesis contradicted supplied lane evidence",
            )
        synthesis.goal = prompt
        synthesis.messages = operator_conversation(synthesis.final_text)
        return synthesis

    # -- deep think (second-stage creative→logical answer review) ----------- #
    def _run_deep_think(self, handle: dict, prompt: str, tee: "_TokenTee",
                        ctx: Any, res: Any, *, continuation_context: str = "",
                        response_style: ResponseStyle = "adaptive",
                        lane_results: list[dict[str, Any]] | None = None) -> dict[str, Any]:
        """Creative→logical review over the run's transcript + final-answer edit.

        Runs at high/ultra effort (always — no per-effort episode count). Three
        tools-free passes review the primary answer: a divergent/creative pass
        proposes candidate edits, a logical/thesis pass rejects unsupported ones,
        and a final editor returns a natural user-facing answer (which the caller
        substitutes for the primary answer). Each pass is pushed onto the event bus
        so token streams land on the right node in the app."""
        from agent import code_bridge_deepthink as dt
        from agent.agent_loop import run_agent_loop

        run_id = handle["id"]
        cancel: threading.Event = handle["cancel"]
        budget: ExecutionBudget = handle["budget"]
        digest = dt.run_digest(
            effective_request=prompt,
            continuation_context=continuation_context,
            steps=res.steps or [],
            final_text=res.final_text,
        )
        self.bus.bridge_event(run_id, {"type": "deep_think_start", "stages": list(dt.STAGES)})

        no_tools = ("You are deliberating over a completed run, not coding. "
                    "Do not call tools; answer in prose only.")

        def _pass(stage: str, user_prompt: str) -> str:
            """One tools-free debate leg; returns its clipped text ('' on failure)."""
            if cancel.is_set():
                raise _RunCancelled()
            frame = self.bus.push(stage, stage)
            self.bus.bridge_event(run_id, {"type": "deep_think_stage_start", "stage": stage, "node": frame})
            text = ""
            try:
                leg = run_agent_loop(
                    user_prompt,
                    client=tee,
                    ctx=ctx,
                    history=None,
                    on_event=None,  # debate passes stream tokens only; no kernel nodes
                    max_steps=2,
                    system_extra=no_tools,
                    show_thinking=True,
                    enable_tools=False,
                    budget=budget,
                )
                if not (getattr(leg, "model_error", None) or not getattr(leg, "ok", True)):
                    text = leg.final_text or ""
            except _RunCancelled:
                self.bus.pop(stage)
                raise
            except Exception:  # noqa: BLE001 - one leg must not sink the debate
                text = ""
            self.bus.bridge_event(run_id, {"type": "deep_think_stage_done", "stage": stage,
                                           "node": frame, "chars": len(text)})
            self.bus.pop(stage)
            return dt.clip_leg(text)

        candidates = _pass("creative", dt.creative_prompt(
            effective_request=prompt, digest=digest,
            continuation_context=continuation_context))
        critique = _pass("logical", dt.logical_prompt(
            effective_request=prompt, digest=digest, candidates=candidates,
            continuation_context=continuation_context))

        frame = self.bus.push("converge", "converge")
        self.bus.bridge_event(run_id, {"type": "conclusion_start", "node": frame})
        conclusion_error = ""
        conclusion = ""
        try:
            con_res = run_agent_loop(
                dt.converge_prompt(
                    effective_request=prompt,
                    digest=digest,
                    candidates=candidates,
                    critique=critique,
                    response_style=response_style,
                    exact_output=is_exact_output_request(prompt),
                    continuation_context=continuation_context,
                ),
                client=tee,
                ctx=ctx,
                history=None,
                on_event=None,
                max_steps=2,
                system_extra=(
                    "You are editing the completed run's final answer, not coding. "
                    "Do not call tools. Return only the natural user-facing answer; "
                    "never add harness labels or describe the editorial review."
                ),
                show_thinking=True,
                enable_tools=False,
                budget=budget,
                gate_report_context={
                    "request": prompt,
                    "laneResults": list(lane_results or []),
                },
            )
            conclusion = con_res.final_text or ""
            if getattr(con_res, "model_error", None) or not getattr(con_res, "ok", True):
                conclusion_error = str(getattr(con_res, "model_error", None) or "convergence pass failed")
                conclusion = ""
        except _RunCancelled:
            self.bus.pop("converge")
            raise
        except Exception as exc:  # preserve the primary answer with diagnostics
            conclusion = ""
            conclusion_error = f"{type(exc).__name__}: {exc}"
        self.bus.pop("converge")
        review = {
            "schema": "sophia.code_deep_think.v1",
            "stages": list(dt.STAGES),
            "creative": candidates,
            "critique": critique,
            "conclusion": conclusion,
            "confidence": dt.extract_confidence(conclusion),
            "partial": bool(conclusion_error),
            "diagnostics": {"conclusionError": conclusion_error} if conclusion_error else {},
            "canClaimAGI": False,
        }
        self.bus.bridge_event(run_id, {"type": "deep_think_done", **review})
        return review

    def _skill_brief(self, run_id: str, skill_name: str) -> str:
        try:
            from agent import skills as skill_registry

            skill = skill_registry.get(skill_name)
        except Exception:  # noqa: BLE001 - skills are optional chrome
            skill = None
        if not skill:
            self.bus.bridge_event(run_id, {"type": "skill", "name": skill_name, "found": False})
            return ""
        workflow = skill.get("workflow") or []
        steps_text = "\n".join(f"{i + 1}. {step}" for i, step in enumerate(workflow)) or "(no steps)"
        verification = skill.get("verification") or ""
        brief = (
            f"\nActive skill: {skill.get('name')}\n"
            f"Workflow:\n{steps_text}\n"
            f"Verification: {verification}\n"
        )
        self.bus.bridge_event(run_id, {
            "type": "skill",
            "name": str(skill.get("name")),
            "whenToUse": _safe_text(skill.get("whenToUse"), limit=400),
            "steps": len(workflow),
            "found": True,
        })
        return brief

    # -- config / sessions payloads ---------------------------------------- #
    def config_payload(self, cwd: str | Path | None = None) -> dict[str, Any]:
        from agent import cli as terminal_cli
        from agent import runtime_config
        from agent.agent_tools import all_tools
        from agent.image_provider import available_image_providers, image_provider_manifest
        from agent.model import provider_capability_manifest, resolve_config_with_live_context_window

        status = runtime_config.detect_status()
        state, warning = _load_state()
        public_state = _public_state(state, warning=warning)
        defaults = public_state["defaults"]
        profile_name = (
            os.environ.get("SOPHIA_PROVIDER_PROFILE")
            or os.environ.get("SOPHIA_RUNTIME_PROFILE")
            or "public"
        )
        try:
            profile = runtime_config.provider_profile(profile_name, status=status).to_dict()
        except ValueError:
            profile = runtime_config.provider_profile("public", status=status).to_dict()
        try:
            local_engines = [
                engine.to_dict()
                for engine in runtime_config.detect_local_engines(status)
            ]
        except Exception:  # noqa: BLE001 - discovery must not block startup
            local_engines = []
        try:
            provider_capabilities = provider_capability_manifest(
                _model_spec(str(defaults.get("model") or "mock"))
            )
        except Exception:  # noqa: BLE001 - invalid saved models belong in doctor
            provider_capabilities = None
        try:
            # detect_context_window() is fully built and unit-tested but
            # resolve_config() itself stays probe-free (it re-resolves on
            # essentially every model call) — this is the one place designed
            # to pay that live-probe cost: once per config fetch, not once per
            # turn. A no-op for cloud/mock/already-declared-window presets
            # (see resolve_config_with_live_context_window's own scoping).
            model_context_window = resolve_config_with_live_context_window(
                _model_spec(str(defaults.get("model") or "mock"))
            ).context_window
        except Exception:  # noqa: BLE001 - an unresolvable saved model just means "unknown window"
            model_context_window = None
        custom_model_options: list[dict[str, Any]] = []
        try:
            from agent import provider_profiles

            for custom_profile in provider_profiles.list_profiles():
                spec = f"profile:{custom_profile.name}"
                custom_model_options.append({
                    "alias": spec,
                    "spec": spec,
                    "label": (
                        f"Custom endpoint · "
                        f"{dict(custom_profile.metadata).get('display_name') or custom_profile.name}"
                    ),
                    "setup": (
                        "Saved custom endpoint profile; use /model connections "
                        "to inspect or re-check it."
                    ),
                    "group": (
                        "gateway"
                        if custom_profile.endpoint_scope in {"local", "private"}
                        else "cloud"
                    ),
                })
        except Exception:
            custom_model_options = []
        try:
            image_provider = image_provider_manifest(
                str(defaults.get("imageProvider") or "none"),
                profile=profile_name,
            )
        except Exception as exc:  # noqa: BLE001 - report without blocking startup
            image_provider = {
                "schema": "sophia.image-provider.v1",
                "name": str(defaults.get("imageProvider") or "none"),
                "health": {
                    "ready": False,
                    "detail": _safe_text(str(exc), limit=300),
                },
                "candidateOnly": True,
                "canClaimAGI": False,
            }
        onboarding_state = (
            public_state.get("onboarding")
            if isinstance(public_state.get("onboarding"), dict)
            else {}
        )
        persisted_before = bool(public_state.get("updatedAt"))
        configured_model, _ = _config_model_override()
        configured_tui, _ = _config_tui_overrides()
        onboarding_required = {
            "provider": not (
                bool(onboarding_state.get("providerConfirmed"))
                or persisted_before
                or bool(configured_model)
            ),
            "permission": not (
                bool(onboarding_state.get("permissionConfirmed"))
                or persisted_before
                or "permission" in configured_tui
            ),
            # Automatic team mode is an explicit opt-in. A fresh install is
            # already safely configured OFF and must not interrupt onboarding
            # to ask for an agent-count/auto-dispatch choice.
            "autoDispatch": False,
        }
        mlx_models = _local_mlx_models()
        try:
            vllm_specs = terminal_cli._discover_vllm_specs()
        except Exception:  # noqa: BLE001 - local discovery is optional
            vllm_specs = []
        try:
            ds4_specs = terminal_cli._discover_ds4_specs()
        except Exception:  # noqa: BLE001 - local discovery is optional
            ds4_specs = []
        models = [
            {"alias": k, **v} for k, v in terminal_cli.MODEL_CHOICES.items()
        ] + _cloud_model_options() + _engine_model_options(local_engines) + custom_model_options + _external_gateway_model_options() + [
            {"alias": spec, "spec": spec,
             "label": "Local vLLM model",
             "setup": "Detected from live OpenAI-compatible /v1/models on this machine."}
            for spec in vllm_specs
        ] + [
            {"alias": spec, "spec": spec,
             "label": "Local DeepSeek V4 Flash via DwarfStar",
             "setup": "Detected from live ds4-server /v1/models on this machine.",
             "group": "ds4"}
            for spec in ds4_specs
        ] + [
            {"alias": f"ollama:{model}", "spec": f"ollama:{model}",
             "label": "Local Ollama model", "setup": "Detected from ollama list"}
            for model in status.ollama_models
        ] + [
            {"alias": f"mlx:{model}", "spec": f"mlx:{model}",
             "label": "Local MLX cache model",
             "setup": "Detected in local MLX/Hugging Face cache; requires mlx-lm."}
            for model in mlx_models
        ]
        seen: set[str] = set()
        deduped = []
        for option in models:
            alias = str(option.get("alias") or "")
            if alias and alias not in seen:
                seen.add(alias)
                deduped.append(option)
        try:
            from agent import skills as skill_registry

            skills = skill_registry.list_skills()
        except Exception:  # noqa: BLE001
            skills = []
        try:
            from agent.plugin_host import PluginHost

            configured_workspace = _normalize_workspace_root(
                cwd or defaults.get("cwd") or Path.cwd()
            )
            plugin_host = PluginHost(configured_workspace)
            try:
                plugins = plugin_host.summary()
            finally:
                plugin_host.close()
        except Exception as exc:  # noqa: BLE001 - startup remains usable without plugins
            plugins = {
                "schema": "sophia.plugin-host/v1",
                "safeMode": True,
                "plugins": [],
                "issues": [
                    {
                        "path": "",
                        "error": (
                            "plugin discovery unavailable: "
                            f"{type(exc).__name__}"
                        ),
                    }
                ],
                "selections": {},
                "candidateOnly": True,
                "canClaimAGI": False,
            }
        tools = [
            {"name": spec.name, "risk": spec.risk, "description": spec.description}
            for spec in all_tools().values()
        ]
        try:
            from agent.a2a_orchestration import load_latest_orchestration

            a2a_orchestration = load_latest_orchestration(
                str(defaults.get("session") or "")
            )
        except Exception:  # noqa: BLE001 - recovery metadata is best-effort
            a2a_orchestration = None
        return {
            "app": APP_NAME,
            "protocol": PROTOCOL_VERSION,
            "protocolInfo": {
                "version": PROTOCOL_VERSION,
                "minimum": PROTOCOL_MIN_VERSION,
                "bridgeInstanceId": self.instance_id,
                "features": [
                    "stable-event-metadata",
                    "queue-next",
                    "diagnostic-snapshot",
                    "mcp-health",
                    "provider-health",
                    "model-connections-v1",
                    "startup-routing-v1",
                    "plugin-host-v1",
                    "plugin-workflow-proposals-v1",
                    "plugin-runtime-quarantine-v1",
                    "typed-errors",
                ],
            },
            "canClaimAGI": False,
            "generatedAt": _now_iso(),
            "settingsPath": str(_state_path()),
            "repoRoot": str(_repo_root()),
            "defaults": defaults,
            "state": public_state,
            "a2aOrchestration": a2a_orchestration,
            "startupRouting": _startup_routing_payload(mlx_models),
            "models": deduped,
            "modes": [{"name": name, **settings}
                      for name, settings in terminal_cli.MODE_PRESETS.items()],
            "permissions": ["auto", "manual", "readonly"],
            "permissionOptions": [
                {"name": "auto", "label": "Auto",
                 "description": "Permit kernel tool calls without app prompts.",
                 "terminalFlag": "--auto"},
                {"name": "manual", "label": "Manual approval",
                 "description": "The app asks before write/bash/function-call execution.",
                 "terminalFlag": "--approve"},
                {"name": "readonly", "label": "Read-only",
                 "description": "Block write and exec tools.",
                 "terminalFlag": "--readonly"},
            ],
            "tools": tools,
            "skills": skills,
            "plugins": plugins,
            "teamRoles": [{"role": role, "brief": brief} for role, brief in TEAM_ROLES],
            "autoTeam": {
                "value": defaults.get("autoTeam"),
                "state": public_state["autoTeamState"],
                "publicDefault": False,
                "configKeys": ["code.auto_team", "code.autoTeam"],
                "explicitTeamWins": True,
            },
            "onboarding": {
                "required": onboarding_required,
                "state": dict(onboarding_state),
                "providerSelectionPersists": True,
                "permissionSelectionRequired": True,
                "autoDispatchAskFirst": True,
            },
            "providerProfile": profile,
            "localEngines": local_engines,
            "providerCapabilities": provider_capabilities,
            "providerHealth": {
                "status": "not_probed",
                "startupProbe": False,
                "command": "provider_health",
                "paidProbeMade": False,
            },
            "imageProvider": image_provider,
            "imageProviders": list(available_image_providers()),
            "mcp": {
                "startupProbe": False,
                "healthCommand": "mcp_health",
                "timeoutsCommand": "mcp_timeouts",
                "timeouts": dict(self.mcp_timeouts),
            },
            "deepThink": {
                "available": True,
                "kernelNative": any(k in terminal_cli.MODE_PRESETS for k in DEEP_MODE_KEYS),
                "description": "Extended-reasoning profile: high reasoning effort + visible thinking.",
            },
            "runtime": {
                "os_name": status.os_name,
                "machine": status.machine,
                "python": status.python,
                "is_apple_silicon": status.is_apple_silicon,
                "has_nvidia": status.has_nvidia,
                "ollama_models": list(status.ollama_models),
                "local_mlx_models": mlx_models,
                "local_ds4_models": list(status.local_ds4_models),
            },
            "runtimeRecommendation": runtime_config.recommended_backend(status),
            # The currently-selected default model's real context window,
            # live-probed for a local endpoint with none declared (None when
            # unresolvable or genuinely unknown — never a guessed number).
            "modelContextWindow": model_context_window,
            "history": {
                "defaultSession": defaults["session"],
                "supportsJSON": True,
                "supportsMarkdown": True,
                "supportsOKF": True,
                "supportsRAG": True,
            },
        }

    def sessions_payload(self, *, limit: int = 50) -> dict[str, Any]:
        from agent import cli as terminal_cli

        # Single source of truth: runs persist through _conversation_path, so the
        # listing must resolve the same directory. Reading RUNS_DIR directly made
        # /session list show a different directory than the one just written to
        # whenever SOPHIA_CONVERSATIONS_DIR was set.
        conv_dir = terminal_cli._conversation_path("session-probe").parent
        sessions: list[dict[str, Any]] = []
        paths: list[Path] = []
        if conv_dir.is_dir():
            paths = sorted(conv_dir.glob("*.json"), key=lambda p: p.stat().st_mtime, reverse=True)
        for path in paths[: max(0, limit)]:
            turns = terminal_cli._load_conversation(path) or []
            last_text = ""
            for item in turns:
                content = str(item.get("content") or "")
                if content.strip():
                    last_text = content
            try:
                updated = path.stat().st_mtime
            except OSError:
                updated = 0
            sessions.append({
                "id": path.stem,
                "name": path.stem,
                "title": path.stem.replace("_", " "),
                "jsonPath": str(path),
                "markdownPath": str(path.with_suffix(".md")),
                "turns": len(turns),
                "lastTextPreview": _summary(last_text, limit=300),
                "updatedAt": updated,
                "updatedAtISO": datetime.fromtimestamp(updated, timezone.utc)
                .isoformat(timespec="seconds").replace("+00:00", "Z") if updated else None,
                "hasMarkdown": path.with_suffix(".md").exists(),
            })
        return {
            "ok": True,
            "sessions": sessions,
            "refresh": {"generatedAt": _now_iso(), "count": len(sessions), "limit": limit},
            "canClaimAGI": False,
        }


def _tbench_render_table(rows: list[dict]) -> str:
    """Markdown scorecard for the in-chat ``tbench_result`` bubble.

    Mirrors ``agent.model_bench.render_table``'s shape (sorted, with a totals
    row) so the TUI renders it with the same code path. Module-level (not a
    CodeBridge method) because it is a pure renderer with no ``self`` state.
    """
    if not rows:
        return "_(no tasks ran)_"
    scored = [r for r in rows if r.get("passed") is not None]
    passed = sum(1 for r in scored if r.get("passed") is True)
    failed = sum(1 for r in scored if r.get("passed") is False)
    deferred = sum(1 for r in rows if r.get("deferred"))
    rate = f"{passed}/{len(scored)} ({100*passed/len(scored):.0f}%)" if scored else "n/a"
    header = "| task | category | diff | result | latency | reason |"
    sep = "|---|---|---|---|---|---|"
    body = []
    for r in rows:
        mark = "✓" if r.get("passed") is True else ("✗" if r.get("passed") is False else "·")
        reason = str(r.get("reason") or "").replace("|", "/")
        body.append(f"| {r['name']} | {r.get('category','?')} | {r.get('difficulty','?')} | "
                    f"{mark} | {r.get('latency_s','?')}s | {reason[:60]} |")
    summary = (f"\n\n**pass@1 (host-best-effort):** {rate} · "
               f"{failed} failed · {deferred} deferred to Docker")
    return "\n".join([header, sep, *body]) + summary


def _tbench_write_report(rows: list[dict], *, model_alias: str, mode: str,
                         comparability: str) -> str:
    """Write a ``candidate.json`` report under agi-proof/benchmark-results/tbench/.

    candidateOnly:true · canClaimAGI:false · validated:false. The comparability
    caveat is embedded so the report can never be read as a capability claim.
    Module-level: pure writer with no ``self`` state.
    """
    from agent.runtime_paths import artifact_dir

    scored = [r for r in rows if r.get("passed") is not None]
    passed = sum(1 for r in scored if r.get("passed") is True)
    out_dir = artifact_dir() / "benchmark-results" / "tbench"
    out_dir.mkdir(parents=True, exist_ok=True)
    ts = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    slug = model_alias.replace("/", "_").replace(":", "-")
    path = out_dir / f"{slug}-{mode}-{ts}.candidate.json"
    report = {
        "schema": "sophia.tbench_report.v1",
        "benchmark": "terminal-bench 2.1 (host-best-effort subset)",
        "model": model_alias,
        "mode": mode,
        "candidateOnly": True,
        "validated": False,
        "canClaimAGI": False,
        "claimBoundary": "host-best-effort scorer; NOT Docker-faithful; not AGI proof",
        "comparability": comparability,
        "n": len(rows),
        "scored": len(scored),
        "passed": passed,
        "passAt1": (passed / len(scored)) if scored else None,
        "deferred": sum(1 for r in rows if r.get("deferred")),
        "rows": rows,
        "ts": ts,
    }
    try:
        path.write_text(json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8")
        return str(path)
    except OSError:
        return f"(report not written)"


def _repo_root() -> Path:
    from agent.config import ROOT

    return Path(ROOT)


# --------------------------------------------------------------------------- #
# Line protocol entrypoint
# --------------------------------------------------------------------------- #
def main(argv: "list[str] | None" = None, *, inp: TextIO | None = None,
         out: TextIO | None = None) -> int:
    inp = inp or sys.stdin
    out = out or sys.stdout
    bridge = CodeBridge(out)
    # Send the FULL ready payload (with resolved defaults + state), not a
    # minimal stub. The TUI's ready handler adopts defaults.model from this
    # event — a stub here meant it fell back to the TUI's own startup default
    # (props.model), then pushed THAT back via setSettings, clobbering the
    # operator's config.toml model choice. The full payload carries the
    # config.toml-resolved model (via _load_state's override) so the TUI picks
    # it up on the very first event. config_payload() builds exactly this dict
    # (it already calls _load_state and includes state/defaults/models/...).
    try:
        ready_payload = bridge.config_payload()
    except Exception:  # noqa: BLE001 - never block startup on payload assembly
        ready_payload = {}
    bridge.emit({
        **ready_payload,
        "type": "ready",
        "app": APP_NAME,
        "protocol": PROTOCOL_VERSION,
        "ts": _now_iso(),
        "canClaimAGI": False,
    })
    for line in inp:
        if bridge.shutdown.is_set():
            break
        line = line.strip()
        if len(line.encode("utf-8")) > MAX_COMMAND_BYTES:
            bridge.error("command exceeds protocol size limit", error_type="CommandTooLarge")
            continue
        if not line:
            continue
        try:
            cmd = json.loads(line)
        except json.JSONDecodeError:
            bridge.error("invalid JSON command line", error_type="CommandParseError")
            continue
        if not isinstance(cmd, dict):
            bridge.error("command must be a JSON object", error_type="CommandShapeError")
            continue
        bridge.handle(cmd)
    # stdin closed (app went away or pipe ended): cancel and drain any active run.
    # Record the cause, but do NOT acknowledge — the reader is already gone.
    if not bridge.shutdown.is_set():
        bridge._handle_cancel({"reason": "backend_exit"}, ack=False)
        bridge._wait_active()
        bridge.close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
